Object.assign(window.verseCommentary, {
  "Matthew 6:3": { title: "Give Without Seeking Praise", text: "Jesus says generosity should be so sincere that the giver does not perform it for recognition. The image of the left hand not knowing what the right hand does emphasizes unshowy giving.", refs: ["Matthew 6:1–2","2 Corinthians 9:7"] },
  "Matthew 6:4": { title: "The Father Sees Secret Giving", text: "Giving done privately is seen by the Father. Jesus redirects the giver from human applause to sincere devotion before God.", refs: ["Matthew 6:1–4","Hebrews 4:13"] },
  "Matthew 6:5": { title: "Do Not Pray to Be Seen", text: "Jesus warns against praying for public admiration. Prayer is not wrong when others hear it; the condemned motive is performing devotion to gain status.", refs: ["Luke 18:10–14","Matthew 23:5"] },
  "Matthew 6:6": { title: "Pray to the Father in Secret", text: "Jesus teaches His disciples to seek God in private, away from an audience. The Father sees what is hidden, so prayer can be sincere rather than theatrical.", refs: ["Psalm 91:1","Matthew 6:6"] },
  "Matthew 6:7": { title: "Avoid Empty Repetition", text: "Jesus condemns empty, mechanical repetition as if many words could force God to answer. This does not forbid persistent prayer, which Scripture also commends.", refs: ["1 Kings 18:26–29","Luke 18:1–8"] },
  "Matthew 6:8": { title: "The Father Knows Your Needs", text: "God knows what His children need before they ask. Prayer is not informing an unaware God but expressing dependence, trust, and relationship.", refs: ["Psalm 139:1–4","Romans 8:26–27"] },
  "Matthew 6:9": { title: "Our Father in Heaven", text: "Jesus begins the model prayer by addressing God as Father. The Bible’s confession remains that God is one; Jesus teaches His disciples to approach the one God with reverence and trust.", refs: ["Deuteronomy 6:4","Isaiah 64:8"] },
  "Matthew 6:10": { title: "Hallowed Be Thy Name", text: "God’s name is holy and must be treated with reverence. Prayer begins by honoring God, not merely listing personal requests.", refs: ["Leviticus 22:32","Ezekiel 36:23"] },
  "Matthew 6:11": { title: "Thy Kingdom Come", text: "The disciple asks for God’s reign and purposes to be manifested. Prayer looks beyond personal interests toward God’s will on earth.", refs: ["Matthew 4:17","Revelation 11:15"] },
  "Matthew 6:12": { title: "Thy Will Be Done", text: "Jesus teaches surrender to the Father’s will. His own prayer in Gethsemane later demonstrates obedience even in the face of suffering.", refs: ["Matthew 26:39","1 John 5:14"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 10:1": { title: "Jesus Calls the Twelve", text: "Jesus calls His twelve disciples and gives them a distinct assignment. Their number recalls Israel’s twelve tribes and signals a renewed mission to God’s people.", refs: ["Mark 3:13–19","Luke 6:12–16"] },
  "Matthew 10:2": { title: "The Names of the Twelve", text: "Matthew records the names of the apostles, including Peter, Andrew, James, John, and Judas Iscariot. They are real, diverse people entrusted with a mission, not a collection of flawless heroes.", refs: ["Luke 6:14–16","Acts 1:13"] },
  "Matthew 10:3": { title: "Jesus Sends Them to Israel", text: "Jesus sends the twelve first to the lost sheep of Israel. This is a specific stage in the mission; after His resurrection the commission extends to all nations.", refs: ["Matthew 15:24","Matthew 28:19"] },
  "Matthew 10:4": { title: "Preach That the Kingdom Is Near", text: "The disciples are to announce that the kingdom of heaven is at hand. Their message continues Jesus’ call to repentance and readiness for God’s reign.", refs: ["Matthew 4:17","Luke 9:2"] },
  "Matthew 10:5": { title: "Heal and Deliver Freely", text: "Jesus gives the disciples authority for healing and deliverance and commands them to give freely because they received freely. God’s gifts must not be exploited for profit.", refs: ["Acts 8:18–23","2 Kings 5:15–16"] },
  "Matthew 10:6": { title: "Travel Without Stockpiling", text: "The disciples are instructed not to take extra provisions for this mission, depending on hospitality as they go. This specific commission should not be turned into a universal ban on prudent preparation.", refs: ["Luke 9:3","Luke 22:35–36"] },
  "Matthew 10:7": { title: "Seek Worthy Hospitality", text: "The disciples should seek a receptive household and remain there rather than use the mission to chase comfort. Their conduct is to be stable and honorable.", refs: ["Luke 10:5–8","1 Timothy 5:18"] },
  "Matthew 10:8": { title: "Bless the House of Peace", text: "The disciples are to greet the household with peace. Where that peace is received, it rests there; where rejected, the messengers move on without coercion.", refs: ["Luke 10:5–6"] },
  "Matthew 10:9": { title: "Shake Off the Dust", text: "If a town refuses their message, the disciples are to shake off its dust as a testimony. The act signifies accountability and does not authorize revenge.", refs: ["Acts 13:50–51","Luke 9:5"] },
  "Matthew 10:10": { title: "Judgment for Rejection", text: "Jesus warns that rejecting the message brings serious accountability, comparing such a town with Sodom and Gomorrah. Greater revelation carries greater responsibility.", refs: ["Genesis 19:24–28","Luke 10:12–15"] },
  "Matthew 10:11": { title: "Sheep among Wolves", text: "Jesus sends His disciples into danger and tells them to be wise as serpents and harmless as doves. Courage must be joined with prudence and integrity.", refs: ["Luke 10:3","Romans 16:19"] },
  "Matthew 10:12": { title: "Beware of Human Opposition", text: "Jesus warns that disciples will face courts and punishment. Their mission does not promise safety from persecution.", refs: ["John 16:2","Acts 5:40"] },
  "Matthew 10:13": { title: "The Spirit Helps in Testimony", text: "When brought before authorities, disciples should not be consumed with anxious rehearsal; the Spirit will help them speak. This promise concerns the specific setting of witness under persecution, not a rejection of preparation in every context.", refs: ["Luke 12:11–12","Acts 4:8"] },
  "Matthew 10:14": { title: "Families May Be Divided", text: "Jesus warns that loyalty to Him can divide households when some reject the gospel. The passage describes the painful cost of allegiance, not a command to seek family conflict.", refs: ["Micah 7:6","Luke 12:51–53"] },
  "Matthew 10:15": { title: "Hated for His Name", text: "Disciples will be hated for Jesus’ name, but those who endure faithfully will be saved. Endurance is steadfast loyalty to God amid opposition.", refs: ["Daniel 12:12","Matthew 24:13"] },
  "Matthew 10:16": { title: "Flee Persecution Wisely", text: "When persecuted in one city, the disciples may flee to another. Jesus does not require needless martyrdom; the mission continues through prudent movement.", refs: ["Acts 8:1–4","Acts 14:5–7"] },
  "Matthew 10:17": { title: "The Disciple Is Not Above the Master", text: "Jesus says His followers should not expect better treatment than He receives. If the Master is opposed, His servants may also face hostility.", refs: ["John 13:16","John 15:20"] },
  "Matthew 10:18": { title: "Called Beelzebub", text: "If people insult Jesus as Beelzebub, His household should not expect to escape slander. Disciples must remain faithful rather than be surprised by false accusations.", refs: ["Matthew 12:24","John 8:48"] },
  "Matthew 10:19": { title: "Fear God Rather Than People", text: "What is hidden will be revealed, and Jesus tells His followers to fear God above human threats. Human beings can harm the body, but God is the final judge.", refs: ["Luke 12:4–5","Ecclesiastes 12:13–14"] },
  "Matthew 10:20": { title: "Speak the Gospel Openly", text: "What Jesus teaches privately is to be proclaimed openly. The gospel is not meant to remain secret out of fear of opposition.", refs: ["Acts 4:19–20","Ephesians 6:19–20"] },
  "Matthew 10:21": { title: "God Knows the Sparrows", text: "Not even a sparrow falls without the Father’s knowledge, and the disciples are more valuable than many sparrows. This gives courage without promising that believers will never suffer.", refs: ["Luke 12:6–7","Psalm 56:8"] },
  "Matthew 10:22": { title: "Confess Jesus Before People", text: "Those who confess Jesus before people are acknowledged by Him before the Father. The call is to public faithfulness, not merely private admiration.", refs: ["Romans 10:9–10","Revelation 3:5"] },
  "Matthew 10:23": { title: "Denying Jesus Has Consequences", text: "Jesus warns that denying Him before people has consequences before the Father. The warning calls for steadfast confession, especially under pressure.", refs: ["2 Timothy 2:12","Luke 12:9"] },
  "Matthew 10:24": { title: "Not Peace but a Sword", text: "Jesus describes the division His message can bring, using the sword as an image of conflict. He is not commanding His followers to take up violence; His gospel can expose loyalties and provoke opposition.", refs: ["Luke 12:51","John 18:36"] },
  "Matthew 10:25": { title: "Love Jesus Above All", text: "Disciples must love Jesus more than even their closest family ties when loyalties conflict. This does not cancel the command to honor and care for family; it establishes the highest allegiance.", refs: ["Deuteronomy 6:5","Luke 14:26","1 Timothy 5:8"] },
  "Matthew 10:26": { title: "Take Up the Cross", text: "Following Jesus may require self-denial, suffering, and willingness to lose worldly security. The cross here is not merely a minor inconvenience but the cost of discipleship.", refs: ["Matthew 16:24","Galatians 2:20"] },
  "Matthew 10:27": { title: "Find Life by Losing It", text: "A person who makes self-preservation the highest goal may lose true life, while one who gives their life for Jesus finds it. Jesus reverses worldly measures of success.", refs: ["John 12:25","Philippians 3:7–8"] },
  "Matthew 10:28": { title: "The Worth of a Soul", text: "The whole world cannot compensate for the loss of a soul. Jesus urges disciples to value eternal life above wealth and worldly gain.", refs: ["Psalm 49:6–8","Mark 8:36–37"] },
  "Matthew 10:29": { title: "The Son of Man Will Come in Glory", text: "Jesus speaks of the Son of man coming in the glory of His Father with angels to judge and reward. The language echoes Daniel’s vision and points to divine authority exercised through the Messiah.", refs: ["Daniel 7:13–14","Matthew 25:31–32"] },
  "Matthew 10:30": { title: "Some Will See the Kingdom’s Coming", text: "Jesus says some standing there will see the Son of man coming in His kingdom before they die. Interpreters relate this to the transfiguration and/or the kingdom’s powerful advance; the next chapter’s transfiguration provides an immediate narrative connection.", refs: ["Matthew 17:1–9","Mark 9:1"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 10:1": { title: "Jesus Gives Authority to the Twelve", text: "Jesus gives the twelve authority over unclean spirits and to heal disease. Their mission is delegated authority under Jesus, not independent power or a license for personal gain.", refs: ["Mark 3:13–15","Luke 9:1"] },
  "Matthew 10:2": { title: "The Names of the Apostles", text: "Matthew names the twelve apostles, beginning with Simon Peter and Andrew, and James and John. The title apostle means one sent with a commission.", refs: ["Luke 6:13–16","Acts 1:13"] },
  "Matthew 10:3": { title: "Philip, Bartholomew, Thomas, and Matthew", text: "The list continues with Philip, Bartholomew, Thomas, and Matthew the publican. Jesus calls people with different backgrounds into a shared mission.", refs: ["Mark 3:18","Luke 6:15"] },
  "Matthew 10:4": { title: "James, Lebbaeus, Simon, and Judas", text: "Matthew completes the list, including Simon the Canaanite and Judas Iscariot, who betrayed Jesus. The inclusion of Judas shows that outward proximity to Jesus does not guarantee faithful character.", refs: ["Luke 6:15–16","John 6:70–71"] },
  "Matthew 10:5": { title: "Jesus Sends the Twelve", text: "Jesus sends the twelve and gives specific instructions for this stage of their mission. These directions must be read in their immediate context and alongside the later commission to all nations.", refs: ["Matthew 28:19–20","Luke 9:2"] },
  "Matthew 10:6": { title: "Go to Israel’s Lost Sheep", text: "The disciples are first directed to Israel’s lost sheep. This is the initial focus of Jesus’ earthly ministry, not a permanent exclusion of the Gentiles.", refs: ["Matthew 15:24","Romans 1:16"] },
  "Matthew 10:7": { title: "Preach the Kingdom Is Near", text: "The disciples announce that the kingdom of heaven is at hand, continuing Jesus’ call to repentance and readiness for God’s reign.", refs: ["Matthew 4:17","Luke 9:2"] },
  "Matthew 10:8": { title: "Heal and Give Freely", text: "The disciples are commissioned to heal, cleanse, raise the dead, and cast out devils; they must give freely because they received freely. God’s gifts must not be exploited for profit.", refs: ["Acts 8:18–23","2 Kings 5:15–16"] },
  "Matthew 10:9": { title: "Take No Extra Provision", text: "For this particular mission, the disciples are told not to stockpile travel provisions. They are to depend on God and the hospitality provided; this is not a universal ban on prudent preparation.", refs: ["Luke 9:3","Luke 22:35–36"] },
  "Matthew 10:10": { title: "Seek Worthy Hospitality", text: "The disciples are to seek a worthy household and remain there rather than move from house to house seeking better comfort. Their conduct should be stable and honorable.", refs: ["Luke 10:5–8","1 Timothy 5:18"] },
  "Matthew 10:11": { title: "Greet the House with Peace", text: "The disciples are to greet the household with peace. If the household receives the greeting, peace rests there; if not, it returns to the messengers.", refs: ["Luke 10:5–6"] },
  "Matthew 10:12": { title: "Shake Off the Dust", text: "If a town refuses to receive them or hear their words, the disciples are to shake off its dust as a testimony. This is a sign of accountability, not permission for revenge.", refs: ["Acts 13:50–51","Luke 9:5"] },
  "Matthew 10:13": { title: "Judgment for Rejecting the Message", text: "Jesus says the judgment will be more tolerable for Sodom and Gomorrah than for a town that rejects the disciples’ message. Greater revelation brings greater responsibility.", refs: ["Genesis 19:24–28","Luke 10:12–15"] },
  "Matthew 10:14": { title: "Sheep among Wolves", text: "Jesus sends His disciples into danger and tells them to be wise as serpents and harmless as doves. Prudence must be joined with innocence and integrity.", refs: ["Luke 10:3","Romans 16:19"] },
  "Matthew 10:15": { title: "Beware of Human Courts", text: "Jesus warns that people will deliver His followers to councils and scourge them in synagogues. Discipleship does not promise freedom from persecution.", refs: ["John 16:2","Acts 5:40"] },
  "Matthew 10:16": { title: "Witness Before Rulers", text: "The disciples will be brought before governors and kings as witnesses to them and the Gentiles. Even persecution can become an occasion to testify to the gospel.", refs: ["Acts 24:10–21","Acts 26:1–3"] },
  "Matthew 10:17": { title: "The Spirit Helps Them Speak", text: "When brought before authorities, disciples should not be consumed by anxiety over their testimony; the Spirit will help them speak. This promise concerns witness under persecution, not a rejection of preparation in every setting.", refs: ["Luke 12:11–12","Acts 4:8"] },
  "Matthew 10:18": { title: "Family Division", text: "Jesus warns that family members may betray one another because of the conflict caused by the gospel. He describes the painful cost of allegiance, not a command to create conflict.", refs: ["Micah 7:6","Luke 12:51–53"] },
  "Matthew 10:19": { title: "Hated for Jesus’ Name", text: "The disciples will be hated for Jesus’ name, but the one who endures to the end will be saved. Endurance means remaining faithful through opposition.", refs: ["Daniel 12:12","Matthew 24:13"] },
  "Matthew 10:20": { title: "Flee to Another City", text: "When persecuted in one city, the disciples may flee to another. Jesus does not demand needless exposure to danger; the mission can continue through prudent movement.", refs: ["Acts 8:1–4","Acts 14:5–7"] },
  "Matthew 10:21": { title: "The Disciple Is Not Above the Master", text: "Jesus says His followers should not expect better treatment than He receives. If the Master is opposed, His servants may also face hostility.", refs: ["John 13:16","John 15:20"] },
  "Matthew 10:22": { title: "Called Beelzebub", text: "If people call the master of the house Beelzebub, they will slander His household even more. Disciples should not be surprised by false accusations when Jesus Himself was maligned.", refs: ["Matthew 12:24","John 8:48"] },
  "Matthew 10:23": { title: "Fear God, Not People", text: "Jesus tells the disciples not to fear those who can kill the body but cannot kill the soul. Their ultimate reverence belongs to God, the final judge.", refs: ["Luke 12:4–5","Ecclesiastes 12:13–14"] },
  "Matthew 10:24": { title: "Proclaim What Is Hidden", text: "What Jesus teaches privately is to be proclaimed openly. The gospel must not remain hidden merely because its messengers fear opposition.", refs: ["Acts 4:19–20","Ephesians 6:19–20"] },
  "Matthew 10:25": { title: "Speak the Message Openly", text: "Jesus repeats that His disciples should declare openly what they have heard. Faithful witness requires courage and clarity.", refs: ["Acts 20:20","Acts 20:27"] },
  "Matthew 10:26": { title: "God Knows the Sparrows", text: "Sparrows are sold for little, yet none falls without the Father’s knowledge. Jesus uses this to assure the disciples of God’s care amid danger.", refs: ["Luke 12:6–7","Psalm 56:8"] },
  "Matthew 10:27": { title: "The Hairs of Your Head Are Numbered", text: "God’s knowledge of the disciples is intimate and complete. They are more valuable than many sparrows, giving them reason to resist fear.", refs: ["Luke 12:7","Isaiah 43:1"] },
  "Matthew 10:28": { title: "Confess Jesus Before People", text: "Whoever confesses Jesus before people will be acknowledged by Him before the Father. Jesus calls for open faithfulness, not merely private admiration.", refs: ["Romans 10:9–10","Revelation 3:5"] },
  "Matthew 10:29": { title: "Denying Jesus Has Consequences", text: "Jesus warns that whoever denies Him before people will be denied before the Father. The warning calls for steadfast confession under pressure.", refs: ["2 Timothy 2:12","Luke 12:9"] },
  "Matthew 10:30": { title: "Not Peace but a Sword", text: "Jesus describes the division His message can bring, using the sword as an image of conflict. He is not commanding His followers to commit violence; the gospel exposes loyalties and can provoke opposition.", refs: ["Luke 12:51","John 18:36"] },
  "Matthew 10:31": { title: "Love Jesus Above Family", text: "Disciples must love Jesus more than even their closest family ties when loyalties conflict. This does not cancel biblical duties to honor and care for family; it establishes the highest allegiance.", refs: ["Deuteronomy 6:5","Luke 14:26","1 Timothy 5:8"] },
  "Matthew 10:32": { title: "Take Up the Cross", text: "Whoever does not take up their cross and follow Jesus is not worthy of Him. Discipleship includes self-denial and willingness to suffer rather than abandon Christ.", refs: ["Matthew 16:24","Galatians 2:20"] },
  "Matthew 10:33": { title: "Lose Life to Find It", text: "The person who preserves life at any cost will lose it, while the one who loses life for Jesus’ sake will find it. Jesus reverses worldly measures of success.", refs: ["John 12:25","Philippians 3:7–8"] },
  "Matthew 10:34": { title: "Receive Jesus’ Representatives", text: "Receiving Jesus’ disciples because they belong to Him is a way of receiving Jesus Himself. The verse stresses the importance of hospitality toward faithful messengers.", refs: ["Matthew 25:40","John 13:20"] },
  "Matthew 10:35": { title: "Receive a Prophet as a Prophet", text: "Whoever receives a prophet because he is a prophet will receive a prophet’s reward. God values support for those who faithfully speak His word.", refs: ["1 Kings 17:9–16","2 Kings 4:8–10"] },
  "Matthew 10:36": { title: "Receive a Righteous Person", text: "Whoever receives a righteous person because he is righteous will receive a righteous person’s reward. The verse encourages honor and practical support for those who live faithfully.", refs: ["Psalm 41:1","Hebrews 6:10"] },
  "Matthew 10:37": { title: "Even a Cup of Cold Water", text: "Even a cup of cold water given to one of Jesus’ little ones because they are His disciple will not lose its reward. God notices small acts of genuine kindness and service.", refs: ["Mark 9:41","Hebrews 6:10"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 10:1": { title: "Authority over Unclean Spirits", text: "Jesus gives the twelve authority over unclean spirits and to heal disease. Their authority is delegated by Jesus, not independent power or permission for personal gain.", refs: ["Mark 3:13–15","Luke 9:1"] },
  "Matthew 10:2": { title: "The First Apostles Named", text: "Matthew names Simon Peter and Andrew, and James and John. These men are called to serve as commissioned witnesses of Jesus.", refs: ["Luke 6:13–16","Acts 1:13"] },
  "Matthew 10:3": { title: "Four More Apostles", text: "Philip, Bartholomew, Thomas, and Matthew the publican are named. Jesus calls people from varied backgrounds into a shared mission.", refs: ["Mark 3:18","Luke 6:15"] },
  "Matthew 10:4": { title: "The Last Four Named", text: "James the son of Alphaeus, Lebbaeus, Simon the Canaanite, and Judas Iscariot complete the list. Judas’ inclusion warns that outward closeness to Jesus does not guarantee faithfulness.", refs: ["Luke 6:15–16","John 6:70–71"] },
  "Matthew 10:5": { title: "The Twelve Are Sent", text: "Jesus sends the twelve with specific instructions for this stage of their mission. These directions belong to the immediate context and must be read alongside the later commission to all nations.", refs: ["Matthew 28:19–20","Luke 9:2"] },
  "Matthew 10:6": { title: "Israel’s Lost Sheep", text: "The disciples are first directed to Israel’s lost sheep. This is the initial focus of Jesus’ earthly ministry, not a permanent exclusion of the Gentiles.", refs: ["Matthew 15:24","Romans 1:16"] },
  "Matthew 10:7": { title: "Preach the Kingdom", text: "The disciples announce that the kingdom of heaven is at hand, continuing Jesus’ call to repentance and readiness for God’s reign.", refs: ["Matthew 4:17","Luke 9:2"] },
  "Matthew 10:8": { title: "Heal and Give Freely", text: "The disciples are commissioned to heal, cleanse, raise the dead, and cast out devils; they must give freely because they received freely. God’s gifts must not be exploited for profit.", refs: ["Acts 8:18–23","2 Kings 5:15–16"] },
  "Matthew 10:9": { title: "Take No Gold or Silver", text: "For this particular mission, the disciples are told not to carry gold, silver, or brass in their purses. They are to depend on God and the hospitality provided, not turn ministry into a business.", refs: ["Luke 9:3","1 Timothy 6:5"] },
  "Matthew 10:10": { title: "Take No Extra Travel Supplies", text: "Jesus instructs them not to stockpile provisions for this journey. This specific commission should not be turned into a universal ban on prudent preparation, as later instructions differ.", refs: ["Luke 22:35–36","Mark 6:8–9"] },
  "Matthew 10:11": { title: "Seek a Worthy Household", text: "The disciples should seek a worthy household and remain there rather than move from house to house seeking better comfort. Their conduct should be stable and honorable.", refs: ["Luke 10:5–8","1 Timothy 5:18"] },
  "Matthew 10:12": { title: "Greet the House", text: "The disciples are to greet the household with peace. Their arrival should be marked by a sincere desire for peace, not conflict.", refs: ["Luke 10:5–6"] },
  "Matthew 10:13": { title: "Peace Rests on the House", text: "If the household is worthy, the disciples’ peace will rest upon it; if not, the peace returns to them. The mission’s welcome cannot be forced.", refs: ["Luke 10:6"] },
  "Matthew 10:14": { title: "Shake Off the Dust", text: "If a town refuses to receive them or hear their words, the disciples are to shake off its dust as a testimony. This is a sign of accountability, not permission for revenge.", refs: ["Acts 13:50–51","Luke 9:5"] },
  "Matthew 10:15": { title: "Judgment for Rejection", text: "Jesus says judgment will be more tolerable for Sodom and Gomorrah than for a town that rejects the disciples’ message. Greater revelation brings greater responsibility.", refs: ["Genesis 19:24–28","Luke 10:12–15"] },
  "Matthew 10:16": { title: "Wise as Serpents, Harmless as Doves", text: "Jesus sends His disciples as sheep among wolves and calls them to combine prudence with innocence. Wisdom must not become deceit, and harmlessness must not become foolishness.", refs: ["Luke 10:3","Romans 16:19"] },
  "Matthew 10:17": { title: "Beware of Men", text: "Jesus warns that people will deliver His followers to councils and scourge them in synagogues. Discipleship does not promise freedom from persecution.", refs: ["John 16:2","Acts 5:40"] },
  "Matthew 10:18": { title: "Witness Before Rulers", text: "The disciples will be brought before governors and kings as witnesses to them and the Gentiles. Even persecution can become an occasion to testify to the gospel.", refs: ["Acts 24:10–21","Acts 26:1–3"] },
  "Matthew 10:19": { title: "Do Not Be Anxious About Your Words", text: "When brought before authorities, disciples should not be consumed by anxiety over how to answer. Jesus gives this assurance for that moment of testimony, not as a rejection of preparation in every setting.", refs: ["Luke 12:11–12","Acts 4:8"] },
  "Matthew 10:20": { title: "The Spirit Will Help You Speak", text: "Jesus says the Spirit of the Father will speak through them in that hour. The promise encourages faithful witness under pressure and dependence on God.", refs: ["Mark 13:11","Acts 6:10"] },
  "Matthew 10:21": { title: "Family Members May Betray One Another", text: "Jesus warns that the gospel may bring division even within families, and that some will betray relatives to death. He describes the painful cost of allegiance, not a command to create conflict.", refs: ["Micah 7:6","Luke 12:51–53"] },
  "Matthew 10:22": { title: "Hated for Jesus’ Name", text: "The disciples will be hated for Jesus’ name, but the one who endures to the end will be saved. Endurance means remaining faithful through opposition.", refs: ["Daniel 12:12","Matthew 24:13"] },
  "Matthew 10:23": { title: "Flee to Another City", text: "When persecuted in one city, the disciples may flee to another. Jesus does not demand needless exposure to danger; the mission can continue through prudent movement.", refs: ["Acts 8:1–4","Acts 14:5–7"] },
  "Matthew 10:24": { title: "The Disciple Is Not Above the Master", text: "Jesus says His followers should not expect better treatment than He receives. If the Master is opposed, His servants may also face hostility.", refs: ["John 13:16","John 15:20"] },
  "Matthew 10:25": { title: "Called Beelzebub", text: "If people call the master of the house Beelzebub, they will slander His household even more. Disciples should not be surprised by false accusations when Jesus Himself was maligned.", refs: ["Matthew 12:24","John 8:48"] },
  "Matthew 10:26": { title: "Fear God, Not People", text: "Jesus says not to fear those who can kill the body but cannot kill the soul. Ultimate reverence belongs to God, the final judge.", refs: ["Luke 12:4–5","Ecclesiastes 12:13–14"] },
  "Matthew 10:27": { title: "Proclaim What Is Hidden", text: "What Jesus teaches privately is to be proclaimed openly. The gospel must not remain hidden merely because its messengers fear opposition.", refs: ["Acts 4:19–20","Ephesians 6:19–20"] },
  "Matthew 10:28": { title: "Speak the Message Openly", text: "Jesus repeats that His disciples should declare openly what they have heard. Faithful witness requires courage and clarity.", refs: ["Acts 20:20","Acts 20:27"] },
  "Matthew 10:29": { title: "God Knows the Sparrows", text: "Not even a sparrow falls without the Father’s knowledge. Jesus uses this to assure the disciples of God’s care amid danger.", refs: ["Luke 12:6–7","Psalm 56:8"] },
  "Matthew 10:30": { title: "The Hairs of Your Head Are Numbered", text: "God’s knowledge of the disciples is intimate and complete. They are more valuable than many sparrows, giving them reason to resist fear.", refs: ["Luke 12:7","Isaiah 43:1"] },
  "Matthew 10:31": { title: "You Are of More Value Than Sparrows", text: "Jesus repeats that the disciples are precious to God. This assurance does not mean they will never suffer, but that they are never forgotten by the Father.", refs: ["Luke 12:6–7","Psalm 8:4–5"] },
  "Matthew 10:32": { title: "Confess Jesus Before People", text: "Whoever confesses Jesus before people will be acknowledged by Him before the Father. Jesus calls for open faithfulness, not merely private admiration.", refs: ["Romans 10:9–10","Revelation 3:5"] },
  "Matthew 10:33": { title: "Denying Jesus Has Consequences", text: "Jesus warns that whoever denies Him before people will be denied before the Father. The warning calls for steadfast confession under pressure.", refs: ["2 Timothy 2:12","Luke 12:9"] },
  "Matthew 10:34": { title: "Not Peace but a Sword", text: "Jesus describes the division His message can bring, using the sword as an image of conflict. He is not commanding His followers to commit violence; the gospel exposes loyalties and can provoke opposition.", refs: ["Luke 12:51","John 18:36"] },
  "Matthew 10:35": { title: "Family Division Through the Gospel", text: "Jesus quotes the prophet to show that a person’s own household may become opponents. The division is a tragic response to the message, not a reason to hate family members.", refs: ["Micah 7:6","Luke 12:53"] },
  "Matthew 10:36": { title: "Love Jesus Above Family", text: "Disciples must love Jesus more than even their closest family ties when loyalties conflict. This does not cancel biblical duties to honor and care for family; it establishes the highest allegiance.", refs: ["Deuteronomy 6:5","Luke 14:26","1 Timothy 5:8"] },
  "Matthew 10:37": { title: "Take Up the Cross", text: "Whoever does not take up their cross and follow Jesus is not worthy of Him. Discipleship includes self-denial and willingness to suffer rather than abandon Christ.", refs: ["Matthew 16:24","Galatians 2:20"] },
  "Matthew 10:38": { title: "Lose Life to Find It", text: "The person who preserves life at any cost will lose it, while the one who loses life for Jesus’ sake will find it. Jesus reverses worldly measures of success.", refs: ["John 12:25","Philippians 3:7–8"] },
  "Matthew 10:39": { title: "Receive Jesus’ Representatives", text: "Receiving Jesus’ disciples because they belong to Him is a way of receiving Jesus Himself. The verse stresses the importance of hospitality toward faithful messengers.", refs: ["Matthew 25:40","John 13:20"] },
  "Matthew 10:40": { title: "Receive the One Who Sent Jesus", text: "Receiving Jesus means receiving the Father who sent Him. In a Oneness reading, the Father’s saving mission is revealed through the Son; Jesus is the visible manifestation of the invisible God.", refs: ["John 12:44–45","John 14:9–10","2 Corinthians 5:19"] },
  "Matthew 10:41": { title: "Receive a Prophet as a Prophet", text: "Whoever receives a prophet because he is a prophet will receive a prophet’s reward. God values support for those who faithfully speak His word.", refs: ["1 Kings 17:9–16","2 Kings 4:8–10"] },
  "Matthew 10:42": { title: "Receive a Righteous Person", text: "Whoever receives a righteous person because he is righteous will receive a righteous person’s reward. The verse encourages honor and practical support for those who live faithfully.", refs: ["Psalm 41:1","Hebrews 6:10"] },
  "Matthew 10:43": { title: "A Cup of Cold Water Is Remembered", text: "Even a cup of cold water given to one of Jesus’ little ones because they are His disciple will not lose its reward. God notices small acts of genuine kindness and service.", refs: ["Mark 9:41","Hebrews 6:10"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 10:34": { title: "Not Peace but a Sword", text: "Jesus describes the division His message can bring, using the sword as an image of conflict. He is not commanding His followers to commit violence; the gospel exposes loyalties and can provoke opposition.", refs: ["Luke 12:51","John 18:36"] },
  "Matthew 10:35": { title: "Family Division Through the Gospel", text: "Jesus says His coming will expose deep divisions, even between close family members. This is a description of painful responses to His message, not a command to create conflict.", refs: ["Micah 7:6","Luke 12:52–53"] },
  "Matthew 10:36": { title: "A Person’s Enemies May Be in Their Own House", text: "Jesus quotes the prophet to warn that even household members may oppose a disciple. Faithfulness can bring painful rejection, but disciples are still commanded to act in love.", refs: ["Micah 7:6","Matthew 5:44"] },
  "Matthew 10:37": { title: "Love Jesus Above Family", text: "Disciples must love Jesus more than even their closest family ties when loyalties conflict. This does not cancel biblical duties to honor and care for family; it establishes the highest allegiance.", refs: ["Deuteronomy 6:5","Luke 14:26","1 Timothy 5:8"] },
  "Matthew 10:38": { title: "Take Up the Cross", text: "Whoever does not take up their cross and follow Jesus is not worthy of Him. Discipleship includes self-denial and willingness to suffer rather than abandon Christ.", refs: ["Matthew 16:24","Galatians 2:20"] },
  "Matthew 10:39": { title: "Lose Life to Find It", text: "The person who preserves life at any cost will lose it, while the one who loses life for Jesus’ sake will find it. Jesus reverses worldly measures of success.", refs: ["John 12:25","Philippians 3:7–8"] },
  "Matthew 10:40": { title: "Receive Jesus’ Disciples and the One Who Sent Him", text: "Jesus says receiving His disciples is receiving Him, and receiving Him is receiving the One who sent Him. In a Oneness reading, the Father’s saving mission is revealed through the Son; Jesus makes the invisible God known.", refs: ["Matthew 25:40","John 12:44–45","John 14:9–10","2 Corinthians 5:19"] },
  "Matthew 10:41": { title: "Receive a Prophet as a Prophet", text: "Whoever receives a prophet because he is a prophet will receive a prophet’s reward. God values support for those who faithfully speak His word.", refs: ["1 Kings 17:9–16","2 Kings 4:8–10"] },
  "Matthew 10:42": { title: "Receive a Righteous Person", text: "Whoever receives a righteous person because he is righteous will receive a righteous person’s reward. The verse encourages honor and practical support for those who live faithfully.", refs: ["Psalm 41:1","Hebrews 6:10"] },
  "Matthew 10:43": { title: "A Cup of Cold Water Is Remembered", text: "Even a cup of cold water given to one of Jesus’ little ones because they are His disciple will not lose its reward. God notices small acts of genuine kindness and service.", refs: ["Mark 9:41","Hebrews 6:10"] }
});
delete window.verseCommentary["Matthew 10:43"];

Object.assign(window.verseCommentary, {
  "Matthew 11:1": { title: "Jesus Finishes Instructing the Twelve", text: "After giving the twelve their mission instructions, Jesus continues teaching and preaching in the cities. The work of the kingdom continues beyond the disciples’ first assignment.", refs: ["Matthew 10:5–15","Luke 9:1–6"] },
  "Matthew 11:2": { title: "John Hears of Christ’s Works", text: "John the Baptist, now in prison, hears about Jesus’ works and sends disciples to ask Him a question. His confinement does not end his concern for God’s promised deliverance.", refs: ["Matthew 14:3–5","Luke 7:18–20"] },
  "Matthew 11:3": { title: "Are You the Coming One?", text: "John’s disciples ask whether Jesus is the expected One or whether they should look for another. The question invites Jesus to identify His mission through Scripture-fulfilling works.", refs: ["Malachi 3:1","Luke 7:19"] },
  "Matthew 11:4": { title: "Jesus Points to His Works", text: "Jesus tells them to report what they see and hear: the blind see, the lame walk, lepers are cleansed, the deaf hear, the dead are raised, and the poor receive the gospel. These works fulfill prophetic signs of restoration.", refs: ["Isaiah 35:5–6","Isaiah 61:1","Luke 4:18"] },
  "Matthew 11:5": { title: "Blessed Is the One Not Offended in Jesus", text: "Jesus blesses the person who is not offended by Him. His mission may differ from expectations, but His works reveal God’s promised salvation.", refs: ["Isaiah 8:14","1 Peter 2:6–8"] },
  "Matthew 11:6": { title: "Jesus Asks About John", text: "As John’s messengers leave, Jesus asks the crowd what they went into the wilderness to see. He leads them to recognize John’s prophetic role.", refs: ["Luke 7:24–26"] },
  "Matthew 11:7": { title: "Not a Reed Shaken by Wind", text: "John was not a weak or easily swayed person. His prophetic message was firm, even though it led to imprisonment.", refs: ["Matthew 3:1–4","Ephesians 4:14"] },
  "Matthew 11:8": { title: "Not a Man in Soft Clothing", text: "John was not a courtly figure dressed in luxury; those who wear such clothing live in kings’ houses. His prophetic authority did not come from worldly status.", refs: ["Matthew 3:4","Mark 1:6"] },
  "Matthew 11:9": { title: "More Than a Prophet", text: "Jesus declares John more than a prophet because he is the messenger who prepares the way. John has a unique place in the unfolding plan of God.", refs: ["Malachi 3:1","Luke 1:76"] },
  "Matthew 11:10": { title: "The Messenger Who Prepares the Way", text: "Jesus applies the prophecy of the messenger to John. John prepares the people for the Lord’s coming, and the New Testament presents Jesus as the center of that arrival.", refs: ["Isaiah 40:3","Malachi 3:1","Matthew 3:3"] },
  "Matthew 11:11": { title: "None Greater Among Those Born of Women", text: "Jesus honors John as the greatest among those born of women, yet says the least in the kingdom of heaven is greater. The contrast concerns the privilege of the kingdom age, not a denial of John’s faithfulness.", refs: ["Luke 7:28","Hebrews 11:39–40"] },
  "Matthew 11:12": { title: "The Kingdom Suffers Violence", text: "The wording describes violent opposition or forceful struggle surrounding the kingdom; the precise nuance is debated. The context emphasizes the intense conflict accompanying God’s kingdom proclamation.", refs: ["Luke 16:16","Ephesians 6:12"] },
  "Matthew 11:13": { title: "The Law and Prophets Until John", text: "The Law and the Prophets prophesied until John, whose ministry marks a transition toward the announced kingdom. Jesus does not dismiss Scripture; He brings its promises toward fulfillment.", refs: ["Luke 16:16","Matthew 5:17"] },
  "Matthew 11:14": { title: "John as Elijah Who Was to Come", text: "If the hearers are willing to receive it, John fulfills the promised Elijah-like forerunner. This is a prophetic role and ministry, not a claim that John is literally the ancient Elijah returned as the same person.", refs: ["Malachi 4:5–6","Luke 1:17","John 1:21"] },
  "Matthew 11:15": { title: "He That Has Ears, Let Him Hear", text: "Jesus calls the hearers to understand the spiritual significance of what He has said. Hearing physically is not the same as receiving the message with faith.", refs: ["Mark 4:9","Revelation 2:7"] },
  "Matthew 11:16": { title: "This Generation Like Children in the Marketplace", text: "Jesus compares the generation to children who complain when others will not play their chosen game. The image exposes people who reject both John’s seriousness and Jesus’ gracious approach.", refs: ["Luke 7:31–32"] },
  "Matthew 11:17": { title: "John Is Accused of Having a Devil", text: "John’s austere life is criticized as demonic. The charge shows how people can discredit a messenger rather than honestly consider the message.", refs: ["Matthew 3:4","Luke 7:33"] },
  "Matthew 11:18": { title: "The Son of Man Is Called a Glutton", text: "Jesus’ ordinary fellowship with people is misrepresented as excess and moral compromise. People who refuse God’s call can find fault with opposite styles of ministry.", refs: ["Luke 7:34","Matthew 9:10–13"] },
  "Matthew 11:19": { title: "Wisdom Is Justified by Her Children", text: "God’s wisdom is shown to be right by its results and fruit. The responses to John and Jesus do not invalidate the wisdom of God’s different ministries.", refs: ["Luke 7:35","Proverbs 8:1–8"] },
  "Matthew 11:20": { title: "Woe to Chorazin and Bethsaida", text: "Jesus pronounces woe on cities that saw mighty works but did not repent. Greater exposure to God’s work increases responsibility to respond.", refs: ["Luke 10:13–14","Jonah 3:5–10"] },
  "Matthew 11:21": { title: "Capernaum Will Be Brought Down", text: "Capernaum’s exalted position will not protect it from judgment because it failed to repent. Privilege without response brings accountability.", refs: ["Isaiah 14:13–15","Luke 10:15"] },
  "Matthew 11:22": { title: "Judgment More Tolerable for Sodom", text: "Jesus says judgment will be more tolerable for Sodom than for a city that rejected His works. The warning emphasizes the seriousness of refusing clear revelation.", refs: ["Genesis 19:24–28","Matthew 10:15"] },
  "Matthew 11:23": { title: "Jesus Thanks the Father", text: "Jesus thanks the Father, Lord of heaven and earth, for revealing truth to the humble rather than those who trust in their own wisdom. The passage emphasizes God’s sovereign revelation.", refs: ["Luke 10:21","1 Corinthians 1:26–29"] },
  "Matthew 11:24": { title: "The Father and the Son", text: "Jesus says all things are delivered to Him by the Father, and that the Father is known through the Son. In a Oneness reading, God is made known in Christ; the passage describes their relationship in the saving mission without requiring two separate Gods.", refs: ["John 1:18","John 14:9–10","Colossians 2:9"] },
  "Matthew 11:25": { title: "The Son Reveals the Father", text: "No one fully knows the Father except the Son and those to whom the Son reveals Him. Jesus is the definitive revelation of the invisible God.", refs: ["John 1:18","Hebrews 1:1–3"] },
  "Matthew 11:26": { title: "Come to Me, All Who Labour", text: "Jesus invites the weary and burdened to come to Him for rest. His invitation is personal and compassionate, reaching those exhausted by burdens they cannot carry alone.", refs: ["Isaiah 55:1–3","John 7:37"] },
  "Matthew 11:27": { title: "I Will Give You Rest", text: "Jesus promises rest to those who come to Him. This rest includes relief for the soul and a new relationship with God, not a guarantee of a trouble-free life.", refs: ["Jeremiah 6:16","Hebrews 4:9–11"] },
  "Matthew 11:28": { title: "Take My Yoke upon You", text: "Jesus calls disciples to take His yoke and learn from Him. A yoke implies guidance and service; His way is shaped by His own meekness and humility.", refs: ["Jeremiah 6:16","John 13:15"] },
  "Matthew 11:29": { title: "Learn of Me, for I Am Meek", text: "Jesus describes Himself as meek and lowly in heart. His authority is not harsh domination; He leads with humility and compassion.", refs: ["Zechariah 9:9","Philippians 2:5–8"] },
  "Matthew 11:30": { title: "His Yoke Is Easy and His Burden Light", text: "Jesus’ yoke is easy and His burden light compared with crushing burdens. He does not promise the absence of sacrifice, but offers a faithful way of life under His gracious leadership.", refs: ["1 John 5:3","Matthew 23:4"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 12:1": { title: "Disciples Pluck Grain on the Sabbath", text: "Jesus’ disciples pluck grain because they are hungry as they walk through the fields on the Sabbath. Their action raises a dispute about how Sabbath law should be applied.", refs: ["Mark 2:23–24","Luke 6:1–2"] },
  "Matthew 12:2": { title: "The Pharisees Object", text: "The Pharisees accuse the disciples of doing what is not lawful on the Sabbath. Their interpretation focuses on the action without considering need and the scriptural precedents Jesus will cite.", refs: ["Exodus 20:8–10","Deuteronomy 23:25"] },
  "Matthew 12:3": { title: "David Eats the Shewbread", text: "Jesus reminds them that David and his companions ate the consecrated bread when they were hungry. Scripture itself records an exceptional act in a time of need.", refs: ["1 Samuel 21:1–6","Mark 2:25–26"] },
  "Matthew 12:4": { title: "The Priests and Sabbath Service", text: "Jesus notes that priests perform temple duties on the Sabbath and are blameless. The law itself makes room for service and need, so the Pharisees’ accusation is incomplete.", refs: ["Numbers 28:9–10","John 7:22–23"] },
  "Matthew 12:5": { title: "One Greater Than the Temple", text: "Jesus declares that something greater than the temple is present. His authority and mission exceed the temple’s symbolic role in Israel’s worship.", refs: ["Matthew 12:41–42","Colossians 2:9"] },
  "Matthew 12:6": { title: "Mercy, Not Sacrifice", text: "Jesus quotes Hosea to teach that God desires mercy rather than empty ritual. The disciples’ hunger should be met with compassion, not condemned through a harsh interpretation.", refs: ["Hosea 6:6","Matthew 9:13"] },
  "Matthew 12:7": { title: "The Son of Man Is Lord of the Sabbath", text: "Jesus declares the Son of man Lord even of the Sabbath. His authority determines the right understanding of Sabbath purpose; the Sabbath was not intended as a weapon against mercy.", refs: ["Mark 2:27–28","Luke 6:5"] },
  "Matthew 12:8": { title: "Jesus Enters the Synagogue", text: "Jesus enters a synagogue where a man with a withered hand is present. The setting creates a second Sabbath controversy about doing good.", refs: ["Mark 3:1","Luke 6:6"] },
  "Matthew 12:9": { title: "They Ask to Accuse Him", text: "The question about healing on the Sabbath is asked to find grounds for accusation, not sincerely to learn. The passage warns against using religious debate as a trap.", refs: ["Mark 3:2","Luke 14:1"] },
  "Matthew 12:10": { title: "A Sheep in a Pit", text: "Jesus asks who would not rescue a sheep that fell into a pit on the Sabbath. Their ordinary compassion for an animal exposes the inconsistency of opposing mercy to a suffering person.", refs: ["Luke 14:5","Deuteronomy 22:4"] },
  "Matthew 12:11": { title: "A Man Is Worth More Than a Sheep", text: "Jesus concludes that it is lawful to do well on the Sabbath. Human need matters, and Sabbath observance should be consistent with God’s mercy.", refs: ["Mark 3:4","Luke 6:9"] },
  "Matthew 12:12": { title: "Jesus Heals the Withered Hand", text: "Jesus tells the man to stretch out his hand, and it is restored whole. The healing demonstrates Jesus’ authority and the goodness of doing good on the Sabbath.", refs: ["Mark 3:5","Luke 6:10"] },
  "Matthew 12:13": { title: "The Pharisees Plot Against Jesus", text: "The Pharisees leave and take counsel to destroy Jesus. Their response to a healing exposes how religious hostility can become more committed to power than to mercy.", refs: ["Mark 3:6","John 11:53"] },
  "Matthew 12:14": { title: "Jesus Withdraws from Them", text: "Jesus knows of the plot and withdraws, while many people follow Him. His withdrawal is prudent, and His ministry of healing continues.", refs: ["Matthew 10:23","Mark 3:7–10"] },
  "Matthew 12:15": { title: "Jesus Heals and Warns Them", text: "Jesus heals the people and charges them not to make Him known. His mission is not driven by sensational publicity; Matthew sees this restraint as prophetic fulfillment.", refs: ["Mark 1:43–45","Matthew 8:4"] },
  "Matthew 12:16": { title: "The Servant Chosen by God", text: "Matthew quotes Isaiah’s description of God’s chosen servant, beloved and pleasing to Him. The passage presents Jesus’ Spirit-empowered mission and gentle manner.", refs: ["Isaiah 42:1","Matthew 3:17"] },
  "Matthew 12:17": { title: "He Will Declare Judgment to the Gentiles", text: "Jesus’ mission carries God’s judgment and justice beyond Israel to the nations. The Messiah’s work has a global horizon.", refs: ["Isaiah 42:1","Matthew 28:19"] },
  "Matthew 12:18": { title: "He Will Not Strive or Cry Out", text: "The servant does not advance by loud self-promotion or violent struggle. Jesus’ gentleness contrasts with worldly displays of power.", refs: ["Isaiah 42:2","1 Peter 2:23"] },
  "Matthew 12:19": { title: "A Bruised Reed He Will Not Break", text: "Jesus treats the weak with patience rather than crushing them. The image portrays compassionate care for people who are wounded or nearly overwhelmed.", refs: ["Isaiah 42:3","Matthew 11:28–30"] },
  "Matthew 12:20": { title: "Until He Sends Forth Judgment to Victory", text: "Jesus persists until God’s justice is brought to victory. His gentleness is not weakness; He faithfully completes the mission God gave Him.", refs: ["Isaiah 42:3–4","Revelation 19:11"] },
  "Matthew 12:21": { title: "In His Name the Gentiles Trust", text: "The nations will place their hope in Jesus. Matthew’s quotation points beyond Israel to the worldwide reach of God’s saving purpose.", refs: ["Isaiah 42:4","Romans 15:12"] },
  "Matthew 12:22": { title: "A Blind and Dumb Man Is Healed", text: "A demon-possessed man who is blind and unable to speak is brought to Jesus, and Jesus heals him. The miracle displays authority over both affliction and demonic oppression.", refs: ["Matthew 9:32–33","Luke 11:14"] },
  "Matthew 12:23": { title: "The People Ask If He Is the Son of David", text: "The crowds wonder whether Jesus is the promised Son of David. His works lead them to consider His messianic identity.", refs: ["Matthew 9:27","John 7:31"] },
  "Matthew 12:24": { title: "The Pharisees Attribute His Power to Beelzebub", text: "The Pharisees claim Jesus casts out devils by Beelzebub, the prince of devils. They try to explain away the evidence rather than receive it as God’s work.", refs: ["Matthew 9:34","Mark 3:22"] },
  "Matthew 12:25": { title: "A Kingdom Divided Cannot Stand", text: "Jesus argues that Satan would be undermining his own kingdom if Satan were casting out Satan. The accusation is internally inconsistent.", refs: ["Mark 3:23–26","Luke 11:17–18"] },
  "Matthew 12:26": { title: "Satan’s House Divided", text: "Jesus continues that a divided kingdom or house cannot stand. His reasoning exposes the absurdity of attributing deliverance from Satan to Satan’s own power.", refs: ["Luke 11:17–18"] },
  "Matthew 12:27": { title: "By Whom Do Your Children Cast Them Out?", text: "Jesus asks by whose power the accusers’ own followers cast out devils; they will be their judges. Their double standard exposes the weakness of their charge.", refs: ["Acts 19:13–16","Luke 11:19"] },
  "Matthew 12:28": { title: "The Spirit of God Casts Out Devils", text: "Jesus says that if He casts out devils by the Spirit of God, then God’s kingdom has come upon them. The deliverance is evidence that God’s reign is breaking in through Jesus.", refs: ["Luke 11:20","Acts 10:38"] },
  "Matthew 12:29": { title: "The Strong Man Is Bound", text: "A person must bind a strong man before plundering his house. Jesus’ deliverance of the oppressed shows that He is overcoming the power that held them captive.", refs: ["Isaiah 49:24–25","Luke 11:21–22"] },
  "Matthew 12:30": { title: "The Strong Man’s House Is Spoiled", text: "Jesus depicts Himself as stronger than the oppressor, able to rescue those held in bondage. The image supports His claim that God’s kingdom is active in His ministry.", refs: ["Luke 11:22","1 John 3:8"] },
  "Matthew 12:31": { title: "Whoever Is Not with Me", text: "Jesus says those who are not with Him are against Him, and those who do not gather with Him scatter. His mission demands a response; neutrality toward His saving work is not lasting discipleship.", refs: ["Luke 11:23","Joshua 24:15"] },
  "Matthew 12:32": { title: "Blasphemy Against the Holy Ghost", text: "Jesus warns that blasphemy against the Holy Ghost will not be forgiven. In context, the warning concerns knowingly attributing God’s liberating work to an evil source; it should not be used to torment tender consciences over unwanted thoughts.", refs: ["Mark 3:28–30","Luke 12:10"] },
  "Matthew 12:33": { title: "A Word Against the Son of Man", text: "Jesus distinguishes speaking against the Son of man from blasphemy against the Holy Ghost. The verse recognizes that people may misunderstand Jesus’ humble human appearance, while deliberate rejection of God’s Spirit-work is far more serious.", refs: ["Luke 12:10","John 7:12"] },
  "Matthew 12:34": { title: "Blasphemy Against the Holy Ghost Will Not Be Forgiven", text: "Jesus repeats the warning that blasphemy against the Holy Ghost will not be forgiven in this age or the age to come. The context is a hardened accusation against the Spirit’s work, not a casual mistake or a fearful intrusive thought.", refs: ["Mark 3:29–30","Hebrews 10:26–29"] },
  "Matthew 12:35": { title: "A Tree Is Known by Its Fruit", text: "Jesus says a tree is known by its fruit. The Pharisees’ words reveal their hearts, just as a tree’s fruit reveals its nature.", refs: ["Matthew 7:16–20","Luke 6:43–45"] },
  "Matthew 12:36": { title: "Out of the Heart the Mouth Speaks", text: "Words reveal what fills the heart. Jesus calls people to examine not only outward behavior but also the inner source of speech.", refs: ["Luke 6:45","James 3:8–12"] },
  "Matthew 12:37": { title: "Words Will Be Judged", text: "People will give account for careless words on the day of judgment. Speech matters because it reveals the heart and can harm or help others.", refs: ["Ecclesiastes 12:14","James 3:1–10"] },
  "Matthew 12:38": { title: "By Your Words You Are Justified", text: "Words can testify to faithfulness or expose guilt. Jesus does not teach salvation by speech alone; He warns that our words are evidence of the heart’s condition.", refs: ["Romans 10:9–10","James 2:17–18"] },
  "Matthew 12:39": { title: "The Scribes and Pharisees Ask for a Sign", text: "The religious leaders ask Jesus for a sign even after witnessing His works. Their demand reflects unbelief rather than an honest lack of evidence.", refs: ["Matthew 16:1–4","John 2:18"] },
  "Matthew 12:40": { title: "The Sign of the Prophet Jonah", text: "Jesus says the sign of Jonah will be given. Jonah’s three days in the great fish foreshadow Jesus’ death and resurrection.", refs: ["Jonah 1:17","Matthew 16:4"] },
  "Matthew 12:41": { title: "The Son of Man Three Days and Nights", text: "Jesus compares His coming burial and resurrection to Jonah’s time in the fish. The expression is a Jewish way of describing the period and should be read with the Gospel’s chronology.", refs: ["Jonah 1:17","1 Corinthians 15:4"] },
  "Matthew 12:42": { title: "Nineveh Will Rise in Judgment", text: "The people of Nineveh repented at Jonah’s preaching, while Jesus’ hearers rejected one greater than Jonah. Greater light brings greater accountability.", refs: ["Jonah 3:5–10","Luke 11:32"] },
  "Matthew 12:43": { title: "The Queen of the South Will Rise", text: "The queen of the south travelled to hear Solomon’s wisdom, yet Jesus is greater than Solomon. Her example exposes the refusal of people who have a greater revelation before them.", refs: ["1 Kings 10:1–10","2 Chronicles 9:1–8"] },
  "Matthew 12:44": { title: "Something Greater Than Solomon Is Here", text: "Jesus declares that one greater than Solomon is present. His wisdom and messianic authority surpass Israel’s greatest royal sage.", refs: ["1 Kings 3:12","Colossians 2:3"] },
  "Matthew 12:45": { title: "The Unclean Spirit Returns", text: "Jesus describes an unclean spirit leaving a person and later returning with others when the person is left spiritually empty. The warning emphasizes the need for genuine, lasting transformation.", refs: ["Luke 11:24–26","2 Peter 2:20"] },
  "Matthew 12:46": { title: "An Empty House Is Not Enough", text: "The spirit finds the house empty, swept, and garnished. External reform without a new allegiance to God leaves a person vulnerable to a worse condition.", refs: ["John 5:14","Romans 6:11–14"] },
  "Matthew 12:47": { title: "The Last State Is Worse", text: "The final state of the person becomes worse than the first. Jesus warns against temporary reform that does not lead to a lasting response to God.", refs: ["2 Peter 2:20–22","Hebrews 6:4–6"] },
  "Matthew 12:48": { title: "A Woman Calls Mary Blessed", text: "A woman in the crowd blesses the womb that bore Jesus and the breasts that nursed Him. Jesus responds by emphasizing obedience to God’s word rather than biological relationship alone.", refs: ["Luke 11:27–28"] },
  "Matthew 12:49": { title: "Hear and Keep God’s Word", text: "Jesus says those who hear and keep God’s word are blessed. The emphasis is not disrespect for His mother but on faithful obedience as the mark of true discipleship.", refs: ["Luke 8:21","James 1:22–25"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 12:46": { title: "Jesus’ Mother and Brethren Stand Outside", text: "While Jesus speaks to the multitude, His mother and brethren stand outside and seek to speak with Him. The scene sets up Jesus’ teaching about spiritual kinship.", refs: ["Mark 3:31–32","Luke 8:19"] },
  "Matthew 12:47": { title: "Someone Tells Jesus His Family Is Waiting", text: "A person informs Jesus that His mother and brethren are outside wishing to speak with Him. Jesus uses the moment to teach rather than dismiss the importance of family care.", refs: ["Mark 3:32","Luke 8:20"] },
  "Matthew 12:48": { title: "Who Is My Mother?", text: "Jesus asks who His mother and brethren are, preparing to identify His spiritual family. His question does not deny His human family; it highlights a deeper relationship formed by obedience to God.", refs: ["Mark 3:33","John 2:4"] },
  "Matthew 12:49": { title: "Jesus Points to His Disciples", text: "Jesus stretches His hand toward His disciples and identifies them as His family in this spiritual sense. Those who follow Him belong to a community defined by doing God’s will.", refs: ["Mark 3:34","Hebrews 2:11–12"] },
  "Matthew 12:50": { title: "Whoever Does the Father’s Will Is Family", text: "Jesus says whoever does the will of His Father in heaven is His brother, sister, and mother. True spiritual kinship is marked by obedience to God, not merely by biological connection.", refs: ["Luke 8:21","John 14:15","James 1:22"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 13:1": { title: "The Sower Goes Out", text: "Jesus begins a parable about a sower scattering seed. The seed will encounter different conditions, illustrating varied responses to God’s word.", refs: ["Mark 4:1–9","Luke 8:4–8"] },
  "Matthew 13:2": { title: "The Crowds Gather", text: "A great multitude gathers, so Jesus enters a ship while the people stand on the shore. He teaches through parables that invite listeners to consider the condition of their hearts.", refs: ["Mark 4:1–2"] },
  "Matthew 13:3": { title: "Seed by the Wayside", text: "Some seed falls by the wayside, where birds devour it. The image begins to show how the word may be heard without taking root.", refs: ["Luke 8:5, 12"] },
  "Matthew 13:4": { title: "Seed on Stony Places", text: "Some seed falls on shallow, stony ground and springs up quickly because the soil is thin. Initial enthusiasm without depth cannot endure hardship.", refs: ["Mark 4:5–6","Luke 8:6"] },
  "Matthew 13:5": { title: "Seed among Thorns", text: "Some seed falls among thorns, which grow up and choke it. Competing desires can prevent God’s word from bearing fruit.", refs: ["Luke 8:7, 14"] },
  "Matthew 13:6": { title: "Good Ground Bears Fruit", text: "Other seed falls on good ground and produces a harvest. The parable emphasizes receptive hearts that hear and respond fruitfully.", refs: ["Luke 8:8, 15"] },
  "Matthew 13:7": { title: "He That Has Ears, Let Him Hear", text: "Jesus calls listeners to pay close attention. Parables require more than hearing the story; they call for spiritual understanding and response.", refs: ["Mark 4:9","Revelation 2:7"] },
  "Matthew 13:8": { title: "The Disciples Ask Why Parables", text: "The disciples ask why Jesus speaks to the multitude in parables. Jesus explains that understanding is granted to receptive disciples, while others remain unmoved by what they hear.", refs: ["Mark 4:10–12"] },
  "Matthew 13:9": { title: "Knowledge of the Kingdom Given", text: "Jesus tells His disciples that they are given to know the mysteries of the kingdom. This knowledge is a gift that brings responsibility to respond faithfully.", refs: ["1 Corinthians 2:10–12","Ephesians 1:9"] },
  "Matthew 13:10": { title: "More Will Be Given to the Receptive", text: "Those who receive and use the truth they have will be given more understanding; those who reject it lose even what they think they have. The principle concerns spiritual responsiveness.", refs: ["Luke 8:18","Mark 4:24–25"] },
  "Matthew 13:11": { title: "Seeing Without Perceiving", text: "Jesus explains that some see the works and hear the teaching without truly perceiving their meaning. Spiritual blindness is not merely a lack of information.", refs: ["Isaiah 6:9–10","John 12:40"] },
  "Matthew 13:12": { title: "The Heart Has Grown Dull", text: "Jesus quotes Isaiah about people whose hearts are dull and whose ears are slow to hear. Persistent refusal can harden a person against truth.", refs: ["Isaiah 6:10","Acts 28:26–27"] },
  "Matthew 13:13": { title: "Turning and Being Healed", text: "The prophecy speaks of people who might turn and be healed. God’s truth calls for repentance and restoration, but the hearer must not harden the heart against it.", refs: ["Isaiah 6:10","James 5:19–20"] },
  "Matthew 13:14": { title: "Blessed Are Your Eyes", text: "Jesus tells the disciples their eyes are blessed because they see what prophets and righteous people longed to see. They witness the Messiah’s ministry and the kingdom’s arrival.", refs: ["Luke 10:23–24","Hebrews 11:13"] },
  "Matthew 13:15": { title: "Prophets Desired to See This Day", text: "The prophets and righteous people desired to see and hear what the disciples experience. Their privilege calls for gratitude and faithful response.", refs: ["1 Peter 1:10–12","Hebrews 11:39–40"] },
  "Matthew 13:16": { title: "The Sower Parable Explained", text: "Jesus explains that the seed is the word of the kingdom. The wayside hearer does not understand, and the evil one takes away what was sown in the heart.", refs: ["Luke 8:11–12","Mark 4:14–15"] },
  "Matthew 13:17": { title: "The Stony-Ground Hearer", text: "The stony-ground hearer receives the word quickly and joyfully but has no root. When tribulation or persecution comes because of the word, the person falls away.", refs: ["Mark 4:16–17","James 1:2–4"] },
  "Matthew 13:18": { title: "The Thorny-Ground Hearer", text: "The thorny-ground hearer hears the word, but worldly care and the deceitfulness of riches choke it. A crowded heart cannot produce mature spiritual fruit.", refs: ["Luke 8:14","1 Timothy 6:9–10"] },
  "Matthew 13:19": { title: "The Good-Ground Hearer", text: "The good-ground hearer understands and bears fruit, some thirtyfold, some sixtyfold, and some an hundredfold. Fruitfulness varies, but genuine reception produces a harvest.", refs: ["Luke 8:15","John 15:5"] },
  "Matthew 13:20": { title: "The Wheat and Tares", text: "Jesus gives another parable: a man sows good seed, but an enemy later sows tares among the wheat. Good and evil appear together in the present world until the harvest.", refs: ["Matthew 13:36–43"] },
  "Matthew 13:21": { title: "The Enemy Sows Tares", text: "The enemy sows tares while people sleep and departs. The parable portrays opposition to God’s work without suggesting that servants can always identify evil perfectly at first.", refs: ["Matthew 13:38–39","2 Corinthians 11:13–15"] },
  "Matthew 13:22": { title: "The Wheat Appears with Tares", text: "When the plants grow, the tares also become visible. The coexistence of good and evil creates a question about how the servants should respond.", refs: ["Matthew 13:27–28"] },
  "Matthew 13:23": { title: "The Servants Ask About the Tares", text: "The servants ask whether the enemy’s weeds should be pulled out. Their question represents the desire to remove evil immediately, but Jesus will warn of the danger of harming the wheat.", refs: ["Matthew 13:28–29"] },
  "Matthew 13:24": { title: "The Enemy Has Done This", text: "The householder identifies an enemy as the source of the tares. Jesus recognizes opposition to the kingdom while directing His servants away from rash judgment.", refs: ["Matthew 13:39","John 8:44"] },
  "Matthew 13:25": { title: "Let Both Grow Until Harvest", text: "The householder says to let both grow until harvest, lest pulling up tares damage the wheat. Final separation belongs to God’s appointed judgment, not human vengeance.", refs: ["Matthew 13:30","Romans 12:19"] },
  "Matthew 13:26": { title: "The Mustard Seed", text: "Jesus compares the kingdom of heaven to a mustard seed that is very small when sown but grows into a large plant. God’s kingdom may begin in an unimpressive way yet grow greatly.", refs: ["Mark 4:30–32","Luke 13:18–19"] },
  "Matthew 13:27": { title: "The Kingdom Grows from Small Beginnings", text: "The mustard seed’s growth illustrates the surprising expansion of God’s kingdom. The parable encourages trust in God’s work even when its beginning seems small.", refs: ["Zechariah 4:10","Acts 1:8"] },
  "Matthew 13:28": { title: "The Leaven in the Meal", text: "Jesus compares the kingdom to leaven that a woman hides in flour until all is leavened. The image emphasizes pervasive influence working through the whole measure.", refs: ["Luke 13:20–21","1 Corinthians 5:6"] },
  "Matthew 13:29": { title: "Jesus Teaches in Parables", text: "Jesus speaks to the multitude in parables, fulfilling the prophetic pattern of revealing truth through figures. His teaching both reveals and calls for attentive understanding.", refs: ["Psalm 78:2","Mark 4:33–34"] },
  "Matthew 13:30": { title: "The Prophetic Use of Parables", text: "Matthew connects Jesus’ parables with the prophetic Scriptures. The kingdom’s truth is communicated in a form that calls hearers to seek and understand.", refs: ["Psalm 78:2","Romans 15:4"] },
  "Matthew 13:31": { title: "Jesus Sends the Crowd Away", text: "Jesus sends the multitude away and enters the house. The disciples then ask for a fuller explanation of the parable of the tares.", refs: ["Matthew 13:36"] },
  "Matthew 13:32": { title: "Explain the Tares", text: "The disciples ask Jesus to explain the parable of the tares. Their request models seeking understanding rather than pretending to know.", refs: ["Proverbs 2:3–5","James 1:5"] },
  "Matthew 13:33": { title: "The Sower of Good Seed Is the Son of Man", text: "Jesus identifies the one who sows good seed as the Son of man. The parable centers on His authority and the kingdom work He carries out.", refs: ["Matthew 8:20","Matthew 16:13"] },
  "Matthew 13:34": { title: "The Field Is the World", text: "Jesus identifies the field as the world. The parable’s scope reaches beyond a local congregation to the world in which the kingdom’s people live.", refs: ["Matthew 28:19","John 3:16"] },
  "Matthew 13:35": { title: "The Good Seed Are the Children of the Kingdom", text: "The good seed represents the children of the kingdom. Their identity should be seen in relation to God’s reign and the fruit of faithful living.", refs: ["Matthew 5:14–16","Romans 8:14"] },
  "Matthew 13:36": { title: "The Tares Are the Children of the Wicked One", text: "The tares represent those aligned with evil. Jesus’ imagery is about spiritual allegiance and final judgment, not permission to label disliked people as enemies.", refs: ["John 8:44","1 John 3:10"] },
  "Matthew 13:37": { title: "The Enemy Is the Devil", text: "Jesus identifies the enemy who sows tares as the devil. Scripture presents evil as opposing God’s work, while affirming that God will finally judge it.", refs: ["Genesis 3:1–15","1 Peter 5:8"] },
  "Matthew 13:38": { title: "The Harvest Is the End of the World", text: "The harvest represents the end of the age, when the present mixture will be brought to judgment. The parable directs hope toward God’s final justice.", refs: ["Matthew 24:3","Revelation 14:14–16"] },
  "Matthew 13:39": { title: "The Reapers Are the Angels", text: "Jesus identifies the reapers as angels. The final separation is assigned to God’s agents, not to human attempts at violent purification.", refs: ["Matthew 24:31","Hebrews 1:14"] },
  "Matthew 13:40": { title: "The Tares Are Gathered for Burning", text: "As tares are gathered and burned, so evil will face judgment at the end of the age. The image is a serious warning against continuing in lawlessness.", refs: ["Matthew 13:40–42","Revelation 20:11–15"] },
  "Matthew 13:41": { title: "The Son of Man Sends His Angels", text: "Jesus describes the Son of man sending angels to gather out of His kingdom those who cause sin and practice lawlessness. The passage portrays the Messiah’s authority in final judgment.", refs: ["Matthew 24:30–31","2 Thessalonians 1:7–9"] },
  "Matthew 13:42": { title: "A Furnace of Fire", text: "The image of a furnace of fire conveys the severity of final judgment and the anguish of those rejected. Jesus calls hearers to take righteousness and repentance seriously.", refs: ["Matthew 25:41","Revelation 20:15"] },
  "Matthew 13:43": { title: "The Righteous Shine Forth", text: "The righteous shine as the sun in their Father’s kingdom. After judgment, God’s people share in the glory of His righteous reign.", refs: ["Daniel 12:3","Philippians 2:15"] },
  "Matthew 13:44": { title: "He That Has Ears, Let Him Hear", text: "Jesus again calls for careful hearing. The teaching about judgment is meant to awaken faithful response, not mere curiosity about the future.", refs: ["Mark 4:9","Revelation 2:7"] },
  "Matthew 13:45": { title: "Treasure Hidden in a Field", text: "The kingdom is like treasure hidden in a field, which a man finds and hides again before joyfully selling all he has to buy the field. The parable stresses the kingdom’s surpassing worth.", refs: ["Philippians 3:7–8","Matthew 19:21"] },
  "Matthew 13:46": { title: "The Joy of Finding the Kingdom", text: "The man’s joy leads him to give up everything for the treasure. Following God’s kingdom is not merely loss; it is a joyful response to a value greater than all else.", refs: ["Psalm 16:11","Luke 14:33"] },
  "Matthew 13:47": { title: "The Pearl of Great Price", text: "A merchant seeking fine pearls finds one of great value and sells all to obtain it. The kingdom is worth more than any competing possession or ambition.", refs: ["Proverbs 3:13–15","Philippians 3:8"] },
  "Matthew 13:48": { title: "The Merchant Gives All for the Pearl", text: "The merchant’s decisive action shows that the kingdom requires wholehearted commitment. The point is not purchasing salvation with money but recognizing the kingdom’s supreme worth.", refs: ["Luke 14:28–33","Ephesians 2:8–10"] },
  "Matthew 13:49": { title: "The Net Cast into the Sea", text: "The kingdom is like a net gathering fish of every kind. The image anticipates a final separation among those gathered in the present age.", refs: ["Matthew 22:10","Luke 5:4–7"] },
  "Matthew 13:50": { title: "The Net Is Drawn to Shore", text: "When the net is full, the fish are brought ashore and sorted. The parable teaches that gathering now does not mean every person will receive the same final outcome.", refs: ["Matthew 25:31–32"] },
  "Matthew 13:51": { title: "The Good Are Gathered", text: "The good fish are gathered into vessels. The image points to preservation and blessing for those who belong to God’s kingdom.", refs: ["Matthew 25:34","John 5:29"] },
  "Matthew 13:52": { title: "The Bad Are Cast Away", text: "The bad fish are cast away, illustrating the coming separation of the wicked from the righteous. Jesus calls hearers to respond before the final judgment.", refs: ["Matthew 13:49–50","John 5:29"] },
  "Matthew 13:53": { title: "The End of the Age", text: "Jesus explains that at the end of the age angels will separate the wicked from among the just. Final judgment belongs to God and will be righteous.", refs: ["Matthew 25:31–32","Revelation 20:11–15"] },
  "Matthew 13:54": { title: "The Wicked Are Cast into the Furnace", text: "The passage warns that the wicked face judgment and anguish. Jesus’ warning should be taken seriously as a call to repentance and faithful living.", refs: ["Matthew 13:42","Revelation 20:15"] },
  "Matthew 13:55": { title: "The Disciples Understand", text: "Jesus asks whether the disciples understand these things, and they answer yes. Understanding the kingdom’s teaching brings responsibility to live by it.", refs: ["James 1:22","Matthew 7:24"] },
  "Matthew 13:56": { title: "A Scribe Trained for the Kingdom", text: "Jesus compares a scribe instructed in the kingdom to a householder who brings out treasures new and old. A faithful teacher draws from Scripture while recognizing the new revelation of the kingdom in Jesus.", refs: ["Matthew 5:17","2 Timothy 3:16–17"] },
  "Matthew 13:57": { title: "Jesus Leaves That Place", text: "After teaching these parables, Jesus departs. The narrative moves from instruction to the response of people in His hometown.", refs: ["Mark 6:1"] },
  "Matthew 13:58": { title: "Jesus Teaches in His Hometown", text: "Jesus comes to His own country and teaches in the synagogue. The people are astonished, but familiarity soon becomes an obstacle to faith.", refs: ["Mark 6:2","Luke 4:16–22"] },
  "Matthew 13:59": { title: "Where Did He Get This Wisdom?", text: "The people wonder where Jesus received His wisdom and mighty works. Their question acknowledges His extraordinary teaching but turns toward doubt.", refs: ["John 7:15","Mark 6:2"] },
  "Matthew 13:60": { title: "Is This Not the Carpenter’s Son?", text: "The people identify Jesus by His family and ordinary background. Familiarity with His earthly circumstances leads them to underestimate His divine mission.", refs: ["Mark 6:3","John 1:10–11"] },
  "Matthew 13:61": { title: "His Family Is Known to Them", text: "The people name Jesus’ mother, brethren, and sisters, stumbling over what they think they know about Him. Their familiarity becomes a barrier to recognizing God’s work through Him.", refs: ["Mark 6:3","Galatians 4:4"] },
  "Matthew 13:62": { title: "A Prophet Without Honour", text: "Jesus says a prophet is not without honour except in his own country and house. Those closest to a messenger may fail to recognize the truth because of familiarity or prejudice.", refs: ["Luke 4:24","John 4:44"] },
  "Matthew 13:63": { title: "Their Unbelief Limits the Works Seen", text: "Jesus does not many mighty works there because of their unbelief, though He heals a few sick people. The passage emphasizes their resistance, not a lack of power in Jesus.", refs: ["Mark 6:5–6","Hebrews 3:12"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 13:1": { title: "The Sower Goes Out", text: "Jesus begins a parable about a sower scattering seed. The seed encounters different conditions, illustrating varied responses to God’s word.", refs: ["Mark 4:1–9","Luke 8:4–8"] },
  "Matthew 13:2": { title: "Jesus Teaches from a Ship", text: "A great multitude gathers, so Jesus enters a ship while the people stand on the shore. He teaches through parables that invite hearers to examine their hearts.", refs: ["Mark 4:1–2"] },
  "Matthew 13:3": { title: "Seed by the Wayside", text: "Some seed falls by the wayside, where birds devour it. The image shows how the word may be heard without taking root.", refs: ["Luke 8:5, 12"] },
  "Matthew 13:4": { title: "Seed on Stony Ground", text: "Some seed falls on shallow, stony ground and springs up quickly because the soil is thin. Initial enthusiasm without depth cannot endure hardship.", refs: ["Mark 4:5–6","Luke 8:6"] },
  "Matthew 13:5": { title: "Seed among Thorns", text: "Some seed falls among thorns, which grow up and choke it. Competing desires can prevent God’s word from bearing fruit.", refs: ["Luke 8:7, 14"] },
  "Matthew 13:6": { title: "Seed on Good Ground", text: "Other seed falls on good ground and produces a harvest. The parable emphasizes receptive hearts that hear and respond fruitfully.", refs: ["Luke 8:8, 15"] },
  "Matthew 13:7": { title: "He That Has Ears, Let Him Hear", text: "Jesus calls listeners to pay close attention. Hearing the story is not enough; they must receive its spiritual meaning.", refs: ["Mark 4:9","Revelation 2:7"] },
  "Matthew 13:8": { title: "The Disciples Ask About Parables", text: "The disciples ask why Jesus speaks to the multitude in parables. Jesus explains that understanding is granted to receptive disciples, while others remain unmoved.", refs: ["Mark 4:10–12"] },
  "Matthew 13:9": { title: "Knowledge of the Kingdom Is Given", text: "Jesus tells His disciples they are given to know the mysteries of the kingdom. This knowledge is a gift and brings responsibility to respond faithfully.", refs: ["1 Corinthians 2:10–12","Ephesians 1:9"] },
  "Matthew 13:10": { title: "More Is Given to the Receptive", text: "Those who receive and use the truth they have will be given more understanding; those who reject it lose even what they think they have. The principle concerns spiritual responsiveness.", refs: ["Luke 8:18","Mark 4:24–25"] },
  "Matthew 13:11": { title: "Seeing Without Perceiving", text: "Some see Jesus’ works and hear His teaching without truly perceiving their meaning. Spiritual blindness is not merely a lack of information.", refs: ["Isaiah 6:9–10","John 12:40"] },
  "Matthew 13:12": { title: "The Heart Has Grown Dull", text: "Jesus quotes Isaiah about people whose hearts are dull and whose ears are slow to hear. Persistent refusal can harden a person against truth.", refs: ["Isaiah 6:10","Acts 28:26–27"] },
  "Matthew 13:13": { title: "Turning and Being Healed", text: "The prophecy speaks of people who might turn and be healed. God’s truth calls for repentance and restoration, but the hearer must not harden the heart against it.", refs: ["Isaiah 6:10","James 5:19–20"] },
  "Matthew 13:14": { title: "Blessed Are Your Eyes", text: "Jesus tells the disciples their eyes are blessed because they see what prophets and righteous people longed to see. They witness the Messiah’s ministry and the kingdom’s arrival.", refs: ["Luke 10:23–24","Hebrews 11:13"] },
  "Matthew 13:15": { title: "Prophets Desired to See This Day", text: "The prophets and righteous people desired to see and hear what the disciples experience. Their privilege calls for gratitude and faithful response.", refs: ["1 Peter 1:10–12","Hebrews 11:39–40"] },
  "Matthew 13:16": { title: "The Sower Parable Explained", text: "Jesus explains that the seed is the word of the kingdom. The wayside hearer does not understand, and the evil one takes away what was sown in the heart.", refs: ["Luke 8:11–12","Mark 4:14–15"] },
  "Matthew 13:17": { title: "The Stony-Ground Hearer", text: "The stony-ground hearer receives the word quickly and joyfully but has no root. When tribulation or persecution comes because of the word, the person falls away.", refs: ["Mark 4:16–17","James 1:2–4"] },
  "Matthew 13:18": { title: "The Thorny-Ground Hearer", text: "The thorny-ground hearer hears the word, but worldly care and the deceitfulness of riches choke it. A crowded heart cannot produce mature spiritual fruit.", refs: ["Luke 8:14","1 Timothy 6:9–10"] },
  "Matthew 13:19": { title: "The Good-Ground Hearer", text: "The good-ground hearer understands and bears fruit, some thirtyfold, some sixtyfold, and some an hundredfold. Fruitfulness varies, but genuine reception produces a harvest.", refs: ["Luke 8:15","John 15:5"] },
  "Matthew 13:20": { title: "The Wheat and Tares", text: "Jesus compares the kingdom to a man who sows good seed in his field. This parable considers the coexistence of faithful and wicked people until the harvest.", refs: ["Matthew 13:36–43"] },
  "Matthew 13:21": { title: "The Enemy Sows Tares", text: "An enemy sows tares among the wheat while people sleep. The parable portrays opposition to God’s work, even when evil is not immediately obvious.", refs: ["Matthew 13:38–39","2 Corinthians 11:13–15"] },
  "Matthew 13:22": { title: "Both Grow Together", text: "When the plants appear, the tares also become visible. The coexistence of good and evil creates the question of how servants should respond.", refs: ["Matthew 13:27–28"] },
  "Matthew 13:23": { title: "The Servants Ask About the Weeds", text: "The servants ask whether they should pull out the tares. Their question represents the desire to remove evil immediately, but Jesus will warn of the danger of harming the wheat.", refs: ["Matthew 13:28–29"] },
  "Matthew 13:24": { title: "The Enemy Has Done This", text: "The householder identifies an enemy as the source of the tares. Jesus recognizes opposition to the kingdom while directing His servants away from rash judgment.", refs: ["Matthew 13:39","John 8:44"] },
  "Matthew 13:25": { title: "Let Both Grow Until Harvest", text: "The householder says to let both grow until harvest, lest pulling up tares damage the wheat. Final separation belongs to God’s appointed judgment, not human vengeance.", refs: ["Matthew 13:30","Romans 12:19"] },
  "Matthew 13:26": { title: "The Mustard Seed", text: "Jesus compares the kingdom to a mustard seed that is very small when sown but grows into a large plant. God’s kingdom may begin in an unimpressive way yet grow greatly.", refs: ["Mark 4:30–32","Luke 13:18–19"] },
  "Matthew 13:27": { title: "The Leaven", text: "Jesus compares the kingdom to leaven hidden in flour until all is leavened. The image emphasizes a pervasive influence working through the whole measure.", refs: ["Luke 13:20–21","1 Corinthians 5:6"] },
  "Matthew 13:28": { title: "Jesus Teaches in Parables", text: "Jesus speaks to the multitude in parables, fulfilling the prophetic pattern of revealing truth through figures. His teaching calls hearers to seek and understand.", refs: ["Psalm 78:2","Mark 4:33–34"] },
  "Matthew 13:29": { title: "The Prophetic Use of Parables", text: "Matthew connects Jesus’ parables with the prophetic Scriptures. The kingdom’s truth is communicated in a form that calls hearers to attentive understanding.", refs: ["Psalm 78:2","Romans 15:4"] },
  "Matthew 13:30": { title: "Jesus Sends the Crowd Away", text: "Jesus sends the multitude away and enters the house. The disciples then ask for a fuller explanation of the tares parable.", refs: ["Matthew 13:36"] },
  "Matthew 13:31": { title: "Explain the Tares", text: "The disciples ask Jesus to explain the parable of the tares. Their request models seeking understanding rather than pretending to know.", refs: ["Proverbs 2:3–5","James 1:5"] },
  "Matthew 13:32": { title: "The Sower of Good Seed", text: "Jesus identifies the sower of good seed as the Son of man. The parable centers on His authority and kingdom work.", refs: ["Matthew 8:20","Matthew 16:13"] },
  "Matthew 13:33": { title: "The Field Is the World", text: "Jesus identifies the field as the world. The parable’s scope reaches beyond a local congregation to the world in which God’s people live.", refs: ["Matthew 28:19","John 3:16"] },
  "Matthew 13:34": { title: "The Good Seed", text: "The good seed represents the children of the kingdom. Their identity should be seen in relation to God’s reign and the fruit of faithful living.", refs: ["Matthew 5:14–16","Romans 8:14"] },
  "Matthew 13:35": { title: "The Tares", text: "The tares represent the children of the wicked one. The image concerns spiritual allegiance and final judgment, not permission to label disliked people as enemies.", refs: ["John 8:44","1 John 3:10"] },
  "Matthew 13:36": { title: "The Enemy Is the Devil", text: "Jesus identifies the enemy who sows tares as the devil. Scripture presents evil as opposing God’s work, while affirming that God will finally judge it.", refs: ["Genesis 3:1–15","1 Peter 5:8"] },
  "Matthew 13:37": { title: "The Harvest Is the End of the Age", text: "The harvest represents the end of the age, when the present mixture will be brought to judgment. The parable directs hope toward God’s final justice.", refs: ["Matthew 24:3","Revelation 14:14–16"] },
  "Matthew 13:38": { title: "The Reapers Are Angels", text: "Jesus identifies the reapers as angels. The final separation is assigned to God’s agents, not to human attempts at violent purification.", refs: ["Matthew 24:31","Hebrews 1:14"] },
  "Matthew 13:39": { title: "The Tares Are Gathered for Burning", text: "As tares are gathered and burned, so evil will face judgment at the end of the age. The image warns against continuing in lawlessness.", refs: ["Matthew 13:40–42","Revelation 20:11–15"] },
  "Matthew 13:40": { title: "The Son of Man Sends His Angels", text: "Jesus describes the Son of man sending angels to gather out of His kingdom those who cause sin and practice lawlessness. The passage portrays the Messiah’s authority in final judgment.", refs: ["Matthew 24:30–31","2 Thessalonians 1:7–9"] },
  "Matthew 13:41": { title: "A Furnace of Fire", text: "The image of a furnace of fire conveys the severity of final judgment and the anguish of those rejected. Jesus calls hearers to take righteousness and repentance seriously.", refs: ["Matthew 13:42","Revelation 20:15"] },
  "Matthew 13:42": { title: "The Righteous Shine Forth", text: "The righteous shine as the sun in their Father’s kingdom. After judgment, God’s people share in the glory of His righteous reign.", refs: ["Daniel 12:3","Philippians 2:15"] },
  "Matthew 13:43": { title: "He That Has Ears, Let Him Hear", text: "Jesus calls for careful hearing. The teaching about judgment is meant to awaken faithful response, not mere curiosity about the future.", refs: ["Mark 4:9","Revelation 2:7"] },
  "Matthew 13:44": { title: "Treasure Hidden in a Field", text: "The kingdom is like treasure hidden in a field, which a man finds and joyfully sells all he has to buy the field. The parable stresses the kingdom’s surpassing worth.", refs: ["Philippians 3:7–8","Matthew 19:21"] },
  "Matthew 13:45": { title: "The Pearl of Great Price", text: "A merchant seeking fine pearls finds one of great value and sells all to obtain it. The kingdom is worth more than any competing possession or ambition.", refs: ["Proverbs 3:13–15","Philippians 3:8"] },
  "Matthew 13:46": { title: "The Net Cast into the Sea", text: "The kingdom is like a net gathering fish of every kind. The image anticipates a final separation among those gathered in the present age.", refs: ["Matthew 22:10","Luke 5:4–7"] },
  "Matthew 13:47": { title: "The Net Is Drawn to Shore", text: "When the net is full, it is brought ashore and the fish are sorted. The parable teaches that gathering now does not mean every person will receive the same final outcome.", refs: ["Matthew 25:31–32"] },
  "Matthew 13:48": { title: "The Good Fish Are Gathered", text: "The good fish are gathered into vessels. The image points to preservation and blessing for those who belong to God’s kingdom.", refs: ["Matthew 25:34","John 5:29"] },
  "Matthew 13:49": { title: "The Bad Fish Are Cast Away", text: "The bad fish are cast away, illustrating the coming separation of the wicked from the righteous. Jesus calls hearers to respond before the final judgment.", refs: ["Matthew 13:49–50","John 5:29"] },
  "Matthew 13:50": { title: "The End of the Age", text: "At the end of the age, angels will separate the wicked from among the just. Final judgment belongs to God and will be righteous.", refs: ["Matthew 25:31–32","Revelation 20:11–15"] },
  "Matthew 13:51": { title: "The Wicked Face Judgment", text: "The passage warns that the wicked face judgment and anguish. Jesus’ warning is a call to repentance and faithful living.", refs: ["Matthew 13:42","Revelation 20:15"] },
  "Matthew 13:52": { title: "Do the Disciples Understand?", text: "Jesus asks whether the disciples understand these things, and they answer yes. Understanding the kingdom’s teaching brings responsibility to live by it.", refs: ["James 1:22","Matthew 7:24"] },
  "Matthew 13:53": { title: "A Scribe Trained for the Kingdom", text: "Jesus compares a scribe instructed in the kingdom to a householder who brings out treasures new and old. A faithful teacher draws from Scripture while recognizing God’s work revealed in Jesus.", refs: ["Matthew 5:17","2 Timothy 3:16–17"] },
  "Matthew 13:54": { title: "Jesus Leaves That Place", text: "After teaching these parables, Jesus departs. The narrative moves from instruction to the response of people in His hometown.", refs: ["Mark 6:1"] },
  "Matthew 13:55": { title: "Jesus Teaches in His Hometown", text: "Jesus comes to His own country and teaches in the synagogue. The people are astonished, but familiarity soon becomes an obstacle to faith.", refs: ["Mark 6:2","Luke 4:16–22"] },
  "Matthew 13:56": { title: "Where Did He Get This Wisdom?", text: "The people wonder where Jesus received His wisdom and mighty works. Their question acknowledges His extraordinary teaching but turns toward doubt.", refs: ["John 7:15","Mark 6:2"] },
  "Matthew 13:57": { title: "Is This Not the Carpenter’s Son?", text: "The people identify Jesus by His family and ordinary background. Familiarity with His earthly circumstances leads them to underestimate His divine mission.", refs: ["Mark 6:3","John 1:10–11"] },
  "Matthew 13:58": { title: "His Family Is Known to Them", text: "The people name Jesus’ mother, brethren, and sisters, stumbling over what they think they know about Him. Their familiarity becomes a barrier to recognizing God’s work through Him.", refs: ["Mark 6:3","Galatians 4:4"] },
  "Matthew 13:59": { title: "A Prophet Without Honour", text: "Jesus says a prophet is not without honour except in his own country and house. Those closest to a messenger may fail to recognize the truth because of familiarity or prejudice.", refs: ["Luke 4:24","John 4:44"] },
  "Matthew 13:60": { title: "Unbelief in Nazareth", text: "Jesus does not many mighty works there because of their unbelief, though He heals a few sick people. The passage emphasizes their resistance, not a lack of power in Jesus.", refs: ["Mark 6:5–6","Hebrews 3:12"] }
});
delete window.verseCommentary["Matthew 13:59"];
delete window.verseCommentary["Matthew 13:60"];
delete window.verseCommentary["Matthew 13:61"];
delete window.verseCommentary["Matthew 13:62"];
delete window.verseCommentary["Matthew 13:63"];

Object.assign(window.verseCommentary, {
  "Matthew 14:1": { title: "Herod Hears of Jesus", text: "Herod the tetrarch hears reports about Jesus and becomes troubled by what people are saying. The account shows that Jesus’ ministry had become widely known.", refs: ["Matthew 4:24","Luke 9:7–9"] },
  "Matthew 14:2": { title: "Herod’s Fearful Conclusion", text: "Herod supposes that John the Baptist has risen from the dead and that miraculous power is working in him. His conclusion reflects guilt and fear after John’s execution.", refs: ["Matthew 16:14","Mark 6:14–16"] },
  "Matthew 14:3": { title: "John Imprisoned", text: "Matthew explains that Herod had arrested John because of Herodias, his unlawful relationship with his brother Philip’s wife. John’s imprisonment followed his bold witness to righteousness.", refs: ["Matthew 11:2","Mark 6:17–18"] },
  "Matthew 14:4": { title: "John Rebukes Herod", text: "John plainly tells Herod that his relationship with Herodias is unlawful. A servant of God must not change the truth merely to please a ruler.", refs: ["Leviticus 18:16","Leviticus 20:21","Ephesians 5:11"] },
  "Matthew 14:5": { title: "Herod Fears the People", text: "Herod wants John dead but fears the crowd, which regards John as a prophet. Political pressure restrains him for a time, but it does not produce repentance.", refs: ["Matthew 21:26","Mark 6:20"] },
  "Matthew 14:6": { title: "A Birthday Celebration", text: "At Herod’s birthday celebration, Herodias’s daughter dances before the guests. The setting prepares for a rash promise that will lead to a righteous man’s death.", refs: ["Mark 6:21–22","Proverbs 29:11"] },
  "Matthew 14:7": { title: "A Rash Oath", text: "Herod promises with an oath to give the girl whatever she asks. Scripture warns against careless speech and vows made without wisdom.", refs: ["Ecclesiastes 5:2","Matthew 5:33–37"] },
  "Matthew 14:8": { title: "Herodias’s Request", text: "Prompted by her mother, the girl asks for John’s head on a platter. The demand reveals Herodias’s hostility toward the prophet who exposed her sin.", refs: ["Mark 6:24–25","1 Kings 19:2"] },
  "Matthew 14:9": { title: "Herod’s Sorrow", text: "Herod is sorry, yet his concern for his oath and his guests outweighs the right course of action. Sorrow that refuses to obey truth cannot undo wrongdoing.", refs: ["Mark 6:26","2 Corinthians 7:10"] },
  "Matthew 14:10": { title: "John Is Beheaded", text: "Herod orders John’s execution in prison. John’s death shows the cost of faithful witness in a sinful and powerful world, not the failure of God’s word.", refs: ["Matthew 11:11","Revelation 6:9–11"] },
  "Matthew 14:11": { title: "John’s Head Is Delivered", text: "John’s head is brought on a platter and given to the girl, who carries it to her mother. The grim account exposes the cruelty that can follow pride, resentment, and reckless promises.", refs: ["Mark 6:27–28","Proverbs 27:4"] },
  "Matthew 14:12": { title: "John’s Disciples Bury Him", text: "John’s disciples take his body, bury it, and tell Jesus. They honor their teacher, and their report connects John’s death with Jesus’ continuing ministry.", refs: ["Matthew 11:2–6","Mark 6:29"] },
  "Matthew 14:13": { title: "Jesus Withdraws to a Desert Place", text: "Jesus withdraws by boat to a solitary place after hearing the news. When the crowds follow, He does not turn them away; His compassion directs what happens next.", refs: ["Matthew 9:36","Mark 6:31–32"] },
  "Matthew 14:14": { title: "Jesus Has Compassion", text: "Jesus sees the great multitude, is moved with compassion, and heals their sick. His authority is joined with mercy; God’s work through Jesus brings help to people in need.", refs: ["Matthew 9:35–36","Isaiah 35:5–6"] },
  "Matthew 14:15": { title: "The Disciples See the Need", text: "As evening comes, the disciples ask Jesus to send the crowd away to buy food. They recognize the practical problem but have not yet grasped what Jesus will provide.", refs: ["Mark 6:35–36","John 6:5–6"] },
  "Matthew 14:16": { title: "Give Them to Eat", text: "Jesus tells the disciples that the people need not depart and commands them to give the crowd food. The command invites them to bring their limited resources under His direction.", refs: ["2 Kings 4:42–44","John 6:8–11"] },
  "Matthew 14:17": { title: "Five Loaves and Two Fishes", text: "The disciples report that they have only five loaves and two fish. Their small supply emphasizes that the coming provision will be the work of Jesus, not human abundance.", refs: ["Matthew 16:9","John 6:9"] },
  "Matthew 14:18": { title: "Bring the Food to Jesus", text: "Jesus tells them to bring the food to Him. In ministry, what seems insufficient can still be placed in the Lord’s hands and used according to His purpose.", refs: ["Matthew 14:19","2 Corinthians 12:9"] },
  "Matthew 14:19": { title: "Jesus Blesses and Breaks the Loaves", text: "Jesus seats the people, takes the loaves and fish, looks to heaven, blesses, breaks, and gives the food to the disciples to distribute. The miracle displays divine provision through Jesus and thankful dependence upon God.", refs: ["Matthew 15:36","John 6:11"] },
  "Matthew 14:20": { title: "All Are Filled", text: "Everyone eats and is satisfied, and the disciples gather twelve baskets of leftovers. The abundance shows that Jesus’ provision fully meets the need rather than barely supplying it.", refs: ["2 Kings 4:43–44","John 6:12–13"] },
  "Matthew 14:21": { title: "Five Thousand Men Fed", text: "About five thousand men eat, besides women and children. The crowd’s size underlines the scale of the miracle and the sufficiency of Jesus’ provision.", refs: ["Matthew 16:9–10","Mark 6:44"] },
  "Matthew 14:22": { title: "Jesus Sends the Disciples Ahead", text: "Jesus directs the disciples to cross the sea while He dismisses the crowd. His actions are deliberate: He remains in control even as the disciples face a difficult crossing.", refs: ["Mark 6:45–46","John 6:15–17"] },
  "Matthew 14:23": { title: "Jesus Prays Alone", text: "Jesus goes up a mountain by Himself to pray. His solitary prayer shows His genuine human life and dependence in prayer; it does not require the conclusion that He is a second God.", refs: ["Luke 5:16","John 17:1–5"] },
  "Matthew 14:24": { title: "The Boat Is Tossed by Waves", text: "The boat is far from land and battered by contrary wind. The disciples are in real danger, but the storm does not place them beyond Jesus’ reach.", refs: ["Mark 6:47–48","Psalm 107:23–30"] },
  "Matthew 14:25": { title: "Jesus Walks on the Sea", text: "In the fourth watch of the night, Jesus comes to the disciples walking on the sea. The act displays authority over creation, a power Scripture associates with the Lord.", refs: ["Job 9:8","Psalm 77:19","John 6:19"] },
  "Matthew 14:26": { title: "The Disciples Are Afraid", text: "The disciples mistake Jesus for a spirit and cry out in fear. Their reaction is understandable in the darkness and storm, but they do not yet recognize the One approaching them.", refs: ["Mark 6:49–50","Luke 24:37"] },
  "Matthew 14:27": { title: "Be of Good Cheer", text: "Jesus immediately tells them to be of good courage, identifies Himself, and commands them not to fear. His presence answers their terror before the storm has passed.", refs: ["Isaiah 41:10","John 6:20"] },
  "Matthew 14:28": { title: "Peter Asks to Come", text: "Peter asks Jesus to command him to come across the water. He looks to Jesus for the word that would make the impossible step possible.", refs: ["Matthew 14:29","John 21:7"] },
  "Matthew 14:29": { title: "Peter Walks on the Water", text: "At Jesus’ command, Peter leaves the boat and walks on the water toward Him. His action is possible only because Jesus calls him; courage is not independence from the Lord.", refs: ["Matthew 14:28","Hebrews 11:29"] },
  "Matthew 14:30": { title: "Peter Begins to Sink", text: "Seeing the wind, Peter becomes afraid and begins to sink, crying for the Lord to save him. The scene shows how fear can overwhelm faith and how prayer turns urgently to Jesus.", refs: ["Psalm 69:1–2","Matthew 8:25"] },
  "Matthew 14:31": { title: "Jesus Immediately Helps Peter", text: "Jesus catches Peter and rebukes his little faith and doubt. The Lord both rescues and teaches him, revealing compassion without pretending that doubt is harmless.", refs: ["Matthew 6:30","Jude 22"] },
  "Matthew 14:32": { title: "The Wind Ceases", text: "When Jesus and Peter enter the boat, the wind stops. The sudden calm confirms Jesus’ authority over the forces threatening the disciples.", refs: ["Psalm 89:9","Mark 4:39"] },
  "Matthew 14:33": { title: "The Disciples Worship Jesus", text: "Those in the boat worship Jesus and confess that He truly is the Son of God. Matthew presents worship and confession in response to the authority Jesus has displayed.", refs: ["Matthew 16:16","John 20:28–31"] },
  "Matthew 14:34": { title: "They Reach Gennesaret", text: "The boat reaches the land of Gennesaret. The narrative moves from danger at sea to a region where people will seek Jesus for healing.", refs: ["Mark 6:53","John 6:21"] },
  "Matthew 14:35": { title: "The People Bring the Sick", text: "The people recognize Jesus and spread the news throughout the surrounding area, bringing all who are sick to Him. His ministry is marked by public compassion and healing.", refs: ["Matthew 4:24","Matthew 9:35"] },
  "Matthew 14:36": { title: "Those Who Touch His Garment Are Healed", text: "The sick beg merely to touch the hem of Jesus’ garment, and those who touch it are made whole. Their faith looks to Jesus as the source of healing, not to the garment as an independent power.", refs: ["Matthew 9:20–22","Mark 6:56"] },

  "Matthew 15:1": { title: "Religious Leaders Question Jesus", text: "Scribes and Pharisees from Jerusalem ask Jesus why His disciples do not follow the elders’ tradition concerning handwashing. The dispute concerns human tradition, not a commandment given by God in the law.", refs: ["Mark 7:1–5","Colossians 2:8"] },
  "Matthew 15:2": { title: "Tradition of the Elders", text: "The leaders accuse the disciples of eating with unwashed hands according to their ceremonial tradition. The issue is not ordinary hygiene but treating an inherited rule as a religious obligation.", refs: ["Mark 7:3–4","Isaiah 29:13"] },
  "Matthew 15:3": { title: "Jesus Exposes Their Tradition", text: "Jesus asks why they transgress God’s commandment by their tradition. Human customs must be tested against God’s word rather than allowed to displace it.", refs: ["Deuteronomy 4:2","Mark 7:8–9"] },
  "Matthew 15:4": { title: "Honor Father and Mother", text: "Jesus recalls God’s command to honor parents and the serious penalty attached to cursing them. He establishes God’s command as the standard by which religious practice must be judged.", refs: ["Exodus 20:12","Exodus 21:17","Ephesians 6:2"] },
  "Matthew 15:5": { title: "A Tradition That Evades Duty", text: "The leaders allow a person to claim that support owed to parents has been dedicated as a gift to God. Their rule can excuse a person from the very responsibility God commanded.", refs: ["Mark 7:11–12","1 Timothy 5:4"] },
  "Matthew 15:6": { title: "God’s Word Made Void", text: "By their tradition, they make God’s command ineffective in practice. Religious sincerity does not justify a rule that contradicts the clear duty taught by Scripture.", refs: ["Matthew 23:23","Titus 1:14"] },
  "Matthew 15:7": { title: "Hypocrisy Exposed", text: "Jesus calls the leaders hypocrites and introduces Isaiah’s rebuke. Outward religious appearance cannot conceal a heart that resists God’s authority.", refs: ["Isaiah 29:13","Matthew 23:27–28"] },
  "Matthew 15:8": { title: "Lips Near, Heart Far", text: "The people honor God with their lips while their heart remains far from Him. True worship requires inward devotion and obedience, not words alone.", refs: ["Isaiah 29:13","Ezekiel 33:31"] },
  "Matthew 15:9": { title: "Vain Worship by Human Commandments", text: "Jesus says worship becomes vain when human commandments are taught as doctrines. Scripture must govern teaching; tradition cannot claim God’s authority merely because it is old.", refs: ["Mark 7:7","Colossians 2:20–23"] },
  "Matthew 15:10": { title: "Jesus Calls the Crowd", text: "Jesus calls the multitude to hear and understand. He brings the issue beyond a private dispute and teaches a principle that concerns everyone’s spiritual life.", refs: ["Mark 7:14","Proverbs 2:2"] },
  "Matthew 15:11": { title: "What Defiles a Person", text: "Jesus teaches that what enters the mouth does not by itself defile the person; what comes out of the mouth reveals the heart. He is confronting the defilement issue under discussion, not declaring that evil speech and conduct are unimportant.", refs: ["Matthew 12:34–37","Mark 7:18–23"] },
  "Matthew 15:12": { title: "The Pharisees Are Offended", text: "The disciples report that the Pharisees were offended by Jesus’ words. Offense from those whose traditions are challenged does not prove that the teaching is false.", refs: ["Galatians 4:16","John 6:60–61"] },
  "Matthew 15:13": { title: "Every Plant Not Planted by the Father", text: "Jesus says every plant not planted by His heavenly Father will be rooted up. A religious system lacking God’s approval cannot endure merely because influential people defend it.", refs: ["Isaiah 60:21","John 15:1–2"] },
  "Matthew 15:14": { title: "Blind Guides", text: "Jesus describes the leaders as blind guides: both guide and follower may fall into a ditch. Spiritual leadership requires truth and discernment, not merely status or confidence.", refs: ["Luke 6:39","Romans 2:19–21"] },
  "Matthew 15:15": { title: "Peter Asks for an Explanation", text: "Peter asks Jesus to explain the parable. The disciples do not understand everything immediately, and the passage encourages seeking clarification rather than pretending to understand.", refs: ["Mark 7:17","James 1:5"] },
  "Matthew 15:16": { title: "Understanding Still Lacking", text: "Jesus asks whether the disciples also lack understanding. Being close to Jesus does not remove the need to listen carefully and learn His teaching.", refs: ["Matthew 16:9","John 14:26"] },
  "Matthew 15:17": { title: "The Path of Food", text: "Jesus describes food entering the mouth and passing through the body. This ordinary process helps distinguish physical food from the moral source of defilement.", refs: ["Mark 7:18–19","1 Corinthians 6:13"] },
  "Matthew 15:18": { title: "The Heart Produces Words", text: "Words that come from the mouth proceed from the heart, and these defile the person. Speech can expose inner motives and moral condition.", refs: ["Proverbs 4:23","Luke 6:45"] },
  "Matthew 15:19": { title: "Evil Proceeds from Within", text: "Jesus lists evil thoughts, murders, adultery, sexual immorality, theft, false witness, and blasphemy as coming from the heart. The answer to sin must address the inward person, not only outward ritual.", refs: ["Jeremiah 17:9","Galatians 5:19–21"] },
  "Matthew 15:20": { title: "Defilement and Unwashed Hands", text: "Jesus summarizes that these evils defile a person, while eating with unwashed hands does not make one morally unclean in the way the leaders alleged. He is correcting their misplaced priority, not dismissing holiness.", refs: ["Mark 7:20–23","Psalm 24:3–4"] },
  "Matthew 15:21": { title: "Jesus Goes to the Coasts of Tyre and Sidon", text: "Jesus withdraws into the region of Tyre and Sidon. The following encounter shows faith reaching toward Him beyond the immediate Jewish setting of His ministry.", refs: ["Mark 7:24","Isaiah 42:6"] },
  "Matthew 15:22": { title: "A Canaanite Woman Cries for Mercy", text: "A Canaanite woman calls Jesus the Son of David and pleads for her demon-oppressed daughter. She recognizes His messianic identity and appeals to His mercy.", refs: ["Matthew 9:27","Matthew 20:30–31"] },
  "Matthew 15:23": { title: "The Disciples Ask Jesus to Send Her Away", text: "Jesus initially gives no answer, and the disciples urge Him to send the woman away because she keeps crying after them. The tension in the scene prepares for a deeper revelation of persistent faith.", refs: ["Matthew 15:24–28","Luke 18:1–8"] },
  "Matthew 15:24": { title: "Jesus Describes His Mission to Israel", text: "Jesus says He was sent to the lost sheep of the house of Israel, reflecting the covenant order of His earthly ministry. The wider New Testament later shows the gospel going to all nations.", refs: ["Matthew 10:5–6","Romans 1:16","Acts 1:8"] },
  "Matthew 15:25": { title: "The Woman Worships and Pleads", text: "The woman comes nearer, worships Jesus, and asks Him to help her. Her persistence is joined with humility and confidence in His ability to deliver her daughter.", refs: ["Matthew 8:2","Hebrews 11:6"] },
  "Matthew 15:26": { title: "The Children’s Bread", text: "Jesus uses the image of children’s bread and little dogs to express the priority of His mission to Israel. The exchange tests and brings to light the woman’s understanding and faith.", refs: ["Mark 7:27","Romans 9:4–5"] },
  "Matthew 15:27": { title: "Even the Dogs Eat the Crumbs", text: "The woman accepts the image but points out that even little dogs eat crumbs from their masters’ table. She does not demand status; she trusts that even a portion of Jesus’ mercy is sufficient.", refs: ["Luke 7:6–9","Ephesians 2:12–13"] },
  "Matthew 15:28": { title: "Great Faith and Healing", text: "Jesus commends the woman’s great faith and grants her request; her daughter is healed that very hour. The passage shows that faith in Jesus’ mercy crosses social boundaries.", refs: ["Matthew 8:10–13","Galatians 3:28–29"] },
  "Matthew 15:29": { title: "Jesus Returns to the Sea of Galilee", text: "Jesus comes near the Sea of Galilee and sits on a mountain. The setting leads to another scene of healing and provision for the gathered people.", refs: ["Mark 7:31","Matthew 14:23"] },
  "Matthew 15:30": { title: "Many Are Healed", text: "Great multitudes bring people with varied disabilities and illnesses and lay them at Jesus’ feet, and He heals them. His compassion reaches people whose conditions had limited their lives.", refs: ["Isaiah 35:5–6","Matthew 11:4–5"] },
  "Matthew 15:31": { title: "The Multitude Glorifies the God of Israel", text: "The people see the healed speaking, walking, and made whole, and they glorify the God of Israel. Jesus’ works lead observers to praise God, showing God’s saving power active through Him.", refs: ["Matthew 9:8","Luke 7:16"] },
  "Matthew 15:32": { title: "Jesus Has Compassion on the Hungry Crowd", text: "Jesus says He has compassion on the multitude because they have stayed with Him three days and have no food. He is unwilling to send them away fainting, displaying practical care as well as spiritual teaching.", refs: ["Matthew 14:14–16","Mark 8:1–3"] },
  "Matthew 15:33": { title: "The Disciples See No Supply", text: "The disciples ask where enough bread could be found in the wilderness to feed so many. They focus on the scarcity around them, despite having already witnessed Jesus multiply food.", refs: ["Matthew 14:17","Matthew 16:9–10"] },
  "Matthew 15:34": { title: "Seven Loaves and a Few Small Fish", text: "Jesus asks what food they have, and they report seven loaves and a few small fish. As before, the miracle begins with an honest accounting of what is available.", refs: ["Matthew 14:17–18","Mark 8:5–7"] },
  "Matthew 15:35": { title: "The People Sit Down", text: "Jesus commands the multitude to sit on the ground. The ordered setting prepares for the distribution and shows that the meal is provided deliberately, not through confusion.", refs: ["Matthew 14:19","Mark 8:6"] },
  "Matthew 15:36": { title: "Jesus Gives Thanks and Breaks the Food", text: "Jesus takes the seven loaves and fish, gives thanks, breaks them, and gives them to His disciples. Thanksgiving precedes distribution, and the disciples serve as instruments through whom the crowd receives provision.", refs: ["Matthew 14:19","1 Timothy 4:4–5"] },
  "Matthew 15:37": { title: "Four Thousand Are Filled", text: "The people eat and are filled, and seven baskets of fragments remain. The abundance again demonstrates Jesus’ power to provide beyond the immediate need.", refs: ["Matthew 14:20","Mark 8:8"] },
  "Matthew 15:38": { title: "Four Thousand Men", text: "About four thousand men are counted, besides women and children. Matthew records the scale of the second feeding, distinct from the earlier feeding of the five thousand.", refs: ["Matthew 14:21","Mark 8:9"] },
  "Matthew 15:39": { title: "Jesus Departs by Ship", text: "After sending the multitude away, Jesus enters a ship and comes to the coasts of Magdala. The account closes the feeding episode and moves the narrative onward.", refs: ["Mark 8:10","Matthew 16:1"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 16:1": { title: "A Sign Demanded from Heaven", text: "The Pharisees and Sadducees test Jesus by demanding a sign from heaven. Their request is not honest inquiry; they have already seen works that testify to His authority.", refs: ["Matthew 12:38–40","Mark 8:11–12"] },
  "Matthew 16:2": { title: "Reading the Sky", text: "Jesus describes how people interpret the evening sky. Their ability to observe natural signs contrasts with their refusal to consider the spiritual significance of what God is doing.", refs: ["Luke 12:54–56","Jeremiah 8:7"] },
  "Matthew 16:3": { title: "Discerning the Times", text: "They can judge the weather but fail to discern the signs of their time. Religious knowledge is incomplete when it refuses to recognize God’s work before them.", refs: ["Matthew 11:4–6","Luke 19:44"] },
  "Matthew 16:4": { title: "The Sign of Jonah", text: "Jesus calls the generation wicked and adulterous and points to the sign of Jonah rather than satisfying their demand. Jonah’s experience foreshadows Jesus’ death and resurrection.", refs: ["Jonah 1:17","Matthew 12:39–40"] },
  "Matthew 16:5": { title: "The Disciples Forget Bread", text: "The disciples cross the sea and realize they have forgotten to bring bread. Their immediate concern sets up Jesus’ warning about a more dangerous kind of leaven.", refs: ["Mark 8:14","Matthew 15:34–36"] },
  "Matthew 16:6": { title: "Beware the Leaven", text: "Jesus warns them to beware the leaven of the Pharisees and Sadducees. The image points to the corrupting influence of their teaching and unbelief, not merely to physical bread.", refs: ["Luke 12:1","1 Corinthians 5:6–8"] },
  "Matthew 16:7": { title: "The Disciples Misunderstand", text: "The disciples assume Jesus is speaking because they brought no bread. They remain focused on the literal situation and miss the spiritual meaning of His warning.", refs: ["Matthew 15:16","Mark 8:17"] },
  "Matthew 16:8": { title: "Little Faith", text: "Jesus challenges their lack of faith and understanding. Their anxiety about bread overlooks the provision they have already witnessed.", refs: ["Matthew 6:30–32","Matthew 14:19–21"] },
  "Matthew 16:9": { title: "Remember the Five Thousand", text: "Jesus reminds them of the five loaves and the twelve baskets left over. Remembering God’s past provision should strengthen trust in present need.", refs: ["Matthew 14:17–21","Psalm 77:11–12"] },
  "Matthew 16:10": { title: "Remember the Four Thousand", text: "Jesus also recalls the seven loaves and seven baskets from the feeding of the four thousand. The repeated miracle should have taught the disciples that He is not limited by scarcity.", refs: ["Matthew 15:34–38","Mark 8:19–20"] },
  "Matthew 16:11": { title: "Understand the Warning", text: "Jesus clarifies that He was not warning them about literal bread but about the leaven of the Pharisees and Sadducees. Spiritual discernment requires hearing the intended meaning of His words.", refs: ["Matthew 16:6","Mark 8:21"] },
  "Matthew 16:12": { title: "The Doctrine of the Pharisees", text: "The disciples finally understand that Jesus means their doctrine. Teaching can spread through a community like leaven, so believers must examine it against God’s word.", refs: ["Acts 17:11","Colossians 2:8"] },
  "Matthew 16:13": { title: "Who Do People Say the Son of Man Is?", text: "Jesus asks His disciples who people say the Son of man is. The question moves from public opinion toward the personal confession that will define their understanding of Him.", refs: ["Daniel 7:13–14","Matthew 8:20"] },
  "Matthew 16:14": { title: "Many Opinions About Jesus", text: "The disciples report that some identify Jesus with John the Baptist, Elijah, Jeremiah, or another prophet. Respectful opinions are not enough; the decisive question is who Jesus truly is.", refs: ["Matthew 14:2","Malachi 4:5","Deuteronomy 18:15"] },
  "Matthew 16:15": { title: "Who Do You Say I Am?", text: "Jesus turns the question directly to the disciples. Faith cannot rest only on what others say; each hearer must respond to the truth revealed about Jesus.", refs: ["John 6:67–69","Romans 10:9–10"] },
  "Matthew 16:16": { title: "Peter Confesses the Christ", text: "Peter declares Jesus to be the Christ, the Son of the living God. This confession identifies Him as the promised Messiah and God's Son; the Gospel also teaches that the fullness of deity dwells bodily in Christ.", refs: ["John 20:31","Colossians 2:9","Matthew 1:23"] },
  "Matthew 16:17": { title: "Revelation from the Father", text: "Jesus says Peter did not arrive at this confession by human reasoning alone; the Father in heaven revealed it. True recognition of Jesus is a gift of divine revelation.", refs: ["Matthew 11:25–27","John 6:44–45"] },
  "Matthew 16:18": { title: "Christ Builds His Church", text: "Jesus declares that He will build His church upon this foundational confession, and the gates of hell will not prevail against it. The church belongs to Christ and rests on the truth of His identity, not on human power.", refs: ["1 Corinthians 3:11","Ephesians 2:20","Acts 2:41–42"] },
  "Matthew 16:19": { title: "The Keys of the Kingdom", text: "Jesus gives Peter the keys of the kingdom and speaks of binding and loosing. In the apostolic mission, the gospel announces the terms of entry into the kingdom; Acts records the apostles preaching repentance, baptism in Jesus’ name, and the gift of the Spirit.", refs: ["Matthew 18:18","Acts 2:38","Acts 10:44–48"] },
  "Matthew 16:20": { title: "Jesus Commands Silence for a Time", text: "Jesus charges the disciples not to announce yet that He is the Christ. His messianic mission must be understood in light of the cross and resurrection, not reduced to popular political expectations.", refs: ["Matthew 17:9","Mark 9:9"] },
  "Matthew 16:21": { title: "Jesus Foretells His Death and Resurrection", text: "Jesus begins to explain that He must go to Jerusalem, suffer, be killed, and rise again. The cross is not an accident but central to the saving mission He willingly fulfills.", refs: ["Isaiah 53:3–12","Luke 24:6–7"] },
  "Matthew 16:22": { title: "Peter Rebukes Jesus", text: "Peter objects that these things must not happen to Jesus. His affection is real, but he is thinking in human terms and resisting the very purpose Jesus has come to accomplish.", refs: ["John 12:27","Matthew 26:51–54"] },
  "Matthew 16:23": { title: "Get Behind Me, Satan", text: "Jesus sharply rebukes Peter because his words oppose God’s saving purpose. Peter is not literally identified as Satan; he has become an obstacle by thinking about glory without the cross.", refs: ["Isaiah 55:8–9","Matthew 4:8–10"] },
  "Matthew 16:24": { title: "Deny Yourself and Follow Jesus", text: "Jesus calls anyone who would follow Him to deny self, take up the cross, and follow. Discipleship means surrendering self-rule and remaining faithful even when obedience is costly.", refs: ["Luke 9:23","Galatians 2:20"] },
  "Matthew 16:25": { title: "Losing Life to Save It", text: "Whoever tries to save life at any cost will lose it, while whoever loses life for Jesus’ sake will find it. Faithfulness to Christ is worth more than preserving earthly security.", refs: ["John 12:25","Philippians 1:21"] },
  "Matthew 16:26": { title: "The Value of the Soul", text: "The whole world cannot compensate for the loss of one’s soul. Earthly gain is temporary, while a person’s standing before God has eternal significance.", refs: ["Psalm 49:7–8","Mark 8:36–37"] },
  "Matthew 16:27": { title: "The Son of Man Comes in Glory", text: "The Son of man will come in the glory of His Father with His angels and reward each according to works. Jesus speaks of divine judgment and the accountability of every person before Him.", refs: ["Daniel 7:13–14","Romans 2:6–8","Revelation 22:12"] },
  "Matthew 16:28": { title: "Some Will See the Kingdom Coming", text: "Jesus says some standing there will not taste death before seeing the Son of man coming in His kingdom. The next chapter’s transfiguration offers a foretaste of His majesty, while the saying has also been discussed in connection with the kingdom’s powerful arrival.", refs: ["Matthew 17:1–8","Mark 9:1","2 Peter 1:16–18"] },

  "Matthew 17:1": { title: "The Transfiguration", text: "Six days later Jesus takes Peter, James, and John up a high mountain. The private setting prepares these witnesses to see a revelation of Jesus’ glory.", refs: ["Mark 9:2","Luke 9:28"] },
  "Matthew 17:2": { title: "Jesus’ Face Shines", text: "Jesus is transfigured before them, His face shining like the sun and His clothes becoming white as light. The scene reveals heavenly glory through Jesus and anticipates His exaltation.", refs: ["Exodus 34:29–35","John 1:14","2 Peter 1:16–18"] },
  "Matthew 17:3": { title: "Moses and Elijah Appear", text: "Moses and Elijah appear and speak with Jesus. Their presence can be understood as bearing witness from the Law and the Prophets to the mission Jesus fulfills.", refs: ["Luke 9:30–31","Luke 24:27"] },
  "Matthew 17:4": { title: "Peter Offers to Build Tabernacles", text: "Peter proposes making three tabernacles for Jesus, Moses, and Elijah. His words show awe and confusion, and the heavenly voice will direct the disciples to hear Jesus above all.", refs: ["Mark 9:5–6","Deuteronomy 18:15"] },
  "Matthew 17:5": { title: "The Father Identifies His Beloved Son", text: "A bright cloud overshadows them, and a voice declares Jesus to be the beloved Son in whom God is well pleased, commanding the disciples to hear Him. The distinction between the heavenly voice and Jesus’ human life does not by itself require three divine persons; the passage identifies Jesus as the uniquely appointed Son.", refs: ["Matthew 3:17","Deuteronomy 18:15","2 Peter 1:17"] },
  "Matthew 17:6": { title: "The Disciples Fall on Their Faces", text: "The disciples fall down in great fear when they hear the voice. Encountering God’s majesty produces reverence and humility.", refs: ["Exodus 20:18–19","Daniel 10:8–9"] },
  "Matthew 17:7": { title: "Jesus Touches Them", text: "Jesus comes, touches the disciples, and tells them to rise and not be afraid. His reassuring presence meets them in their fear.", refs: ["Matthew 14:27","Daniel 10:10–12"] },
  "Matthew 17:8": { title: "They See Jesus Only", text: "When they look up, they see no one but Jesus. Moses and Elijah’s appearance was temporary; the disciples are directed to the Son whom the Father commanded them to hear.", refs: ["Hebrews 1:1–2","Luke 9:36"] },
  "Matthew 17:9": { title: "Tell the Vision After the Resurrection", text: "Jesus commands them not to tell the vision until the Son of man rises from the dead. The resurrection will provide the proper context for understanding His glory and messianic mission.", refs: ["Matthew 16:20–21","Mark 9:9–10"] },
  "Matthew 17:10": { title: "The Question About Elijah", text: "The disciples ask why the scribes say Elijah must come first. They are trying to reconcile the prophetic expectation with what they have just witnessed.", refs: ["Malachi 4:5–6","John 1:21"] },
  "Matthew 17:11": { title: "Elijah Restores All Things", text: "Jesus affirms that Elijah comes and restores all things. The prophecy establishes a preparatory ministry before the day of the Lord.", refs: ["Malachi 3:1","Malachi 4:5–6"] },
  "Matthew 17:12": { title: "Elijah Has Already Come", text: "Jesus explains that Elijah has already come, but people did not recognize him and mistreated him; Jesus likewise will suffer. The statement points to John the Baptist’s preparatory role.", refs: ["Matthew 11:13–14","Luke 1:17"] },
  "Matthew 17:13": { title: "The Disciples Understand John’s Role", text: "The disciples understand that Jesus is speaking about John the Baptist. John came in the spirit and power of Elijah, preparing people for the Lord.", refs: ["Luke 1:16–17","John 1:23"] },
  "Matthew 17:14": { title: "A Father Kneels Before Jesus", text: "A man comes to Jesus and kneels, bringing the desperate need of his afflicted son. The father approaches Jesus because he needs help beyond his own ability.", refs: ["Mark 9:17–18","Luke 9:38"] },
  "Matthew 17:15": { title: "The Son Suffers Terribly", text: "The father describes his son’s severe suffering and dangerous episodes. The account portrays a real family crisis and calls forth Jesus’ compassion and authority.", refs: ["Mark 9:20–22","Luke 9:39"] },
  "Matthew 17:16": { title: "The Disciples Cannot Heal Him", text: "The father says he brought the boy to Jesus’ disciples, but they could not cure him. Their inability prepares for Jesus’ correction about faith and dependence upon God.", refs: ["Matthew 10:1","Mark 9:18"] },
  "Matthew 17:17": { title: "Jesus Rebukes the Unbelieving Generation", text: "Jesus laments the unbelieving and perverse generation and asks how long He must be with them. His words expose persistent unbelief, not a lack of willingness to help the suffering boy.", refs: ["Deuteronomy 32:5","Mark 9:19"] },
  "Matthew 17:18": { title: "The Devil Leaves the Boy", text: "Jesus rebukes the devil, and it departs; the boy is healed from that hour. Jesus’ authority over evil is decisive and brings deliverance.", refs: ["Luke 4:35–36","Acts 10:38"] },
  "Matthew 17:19": { title: "The Disciples Ask Privately", text: "The disciples ask Jesus why they could not cast the devil out. They seek an explanation for their failure rather than hiding it.", refs: ["Mark 9:28","James 1:5"] },
  "Matthew 17:20": { title: "Faith as a Grain of Mustard Seed", text: "Jesus points to their little faith and says faith as a mustard seed can move a mountain. The image teaches confidence in God’s power, not a magical formula or a guarantee that every personal wish will occur.", refs: ["Matthew 21:21","Luke 17:6"] },
  "Matthew 17:21": { title: "Prayer and Fasting", text: "Some later manuscript traditions include a verse about this kind not going out except by prayer and fasting, while many modern editions omit it or place it in a note. The related teaching about prayer and fasting appears in Mark’s account.", refs: ["Mark 9:29","Acts 13:2–3"] },
  "Matthew 17:22": { title: "The Son of Man Will Be Betrayed", text: "Jesus tells the disciples again that the Son of man will be delivered into human hands. His coming suffering is part of the mission He knowingly continues.", refs: ["Matthew 16:21","Matthew 20:18–19"] },
  "Matthew 17:23": { title: "Death and Resurrection Foretold", text: "Jesus says He will be killed and raised the third day, and the disciples are exceedingly sorry. Their grief shows they hear the prediction’s pain but have not yet embraced the hope of resurrection.", refs: ["Matthew 12:40","Luke 24:6–8"] },
  "Matthew 17:24": { title: "The Temple Tribute", text: "Collectors of the half-shekel temple tribute ask Peter whether Jesus pays it. The question concerns the temple tax, not the Roman tribute imposed by Caesar.", refs: ["Exodus 30:13–16","Mark 12:17"] },
  "Matthew 17:25": { title: "Children Are Free", text: "Jesus asks Peter whether kings collect taxes from their own children or from strangers. The illustration leads to a point about the Son’s relationship to the temple and the freedom of God’s children.", refs: ["Romans 8:15–17","Galatians 4:4–7"] },
  "Matthew 17:26": { title: "The Sons Are Free", text: "Peter answers that tribute is collected from strangers, and Jesus concludes that the children are free. Jesus is not submitting because He lacks authority; He is explaining His status and the principle behind the next action.", refs: ["Matthew 12:6","John 2:19–21"] },
  "Matthew 17:27": { title: "The Coin in the Fish’s Mouth", text: "To avoid needless offense, Jesus tells Peter to catch a fish and use the coin found in its mouth to pay for both of them. Jesus exercises knowledge and authority while choosing a peaceful course in a matter that does not compromise truth.", refs: ["Romans 14:13","1 Corinthians 9:19–23"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 18:1": { title: "Who Is Greatest in the Kingdom?", text: "The disciples ask who is greatest in the kingdom of heaven. Their question exposes the temptation to measure kingdom life by rank rather than humility and service.", refs: ["Mark 9:33–34","Luke 22:24–26"] },
  "Matthew 18:2": { title: "Jesus Sets a Child Among Them", text: "Jesus calls a little child and sets the child in their midst. He uses the child as a living lesson about the humble posture required of kingdom citizens.", refs: ["Mark 9:36","Luke 9:47"] },
  "Matthew 18:3": { title: "Become as Little Children", text: "Jesus says they must be converted and become as little children to enter the kingdom. He calls for a changed disposition marked by humility and dependence, not childish ignorance.", refs: ["Matthew 5:3","1 Peter 2:2"] },
  "Matthew 18:4": { title: "Humility Is Greatness", text: "Whoever humbles himself like this child is greatest in the kingdom. God’s measure of greatness differs from worldly ambition and self-promotion.", refs: ["Matthew 23:11–12","James 4:6"] },
  "Matthew 18:5": { title: "Receiving a Child in Jesus’ Name", text: "Receiving a child in Jesus’ name is treated as receiving Jesus Himself. How people treat the vulnerable matters to the Lord.", refs: ["Matthew 10:40–42","Mark 9:37"] },
  "Matthew 18:6": { title: "Do Not Cause Little Ones to Stumble", text: "Jesus gives a severe warning against causing a believer who is little in faith to stumble. Spiritual influence carries serious responsibility, especially toward the vulnerable.", refs: ["Luke 17:1–2","Romans 14:13"] },
  "Matthew 18:7": { title: "Woe to the World Because of Offences", text: "Jesus acknowledges that stumbling blocks will come but pronounces woe on the person through whom they come. The presence of evil in the world does not excuse anyone who chooses to cause harm.", refs: ["Luke 17:1","Romans 1:32"] },
  "Matthew 18:8": { title: "Remove What Leads You to Sin", text: "Jesus uses strong imagery about cutting off a hand or foot rather than being cast into everlasting fire. The language stresses decisive action against sin, not self-mutilation.", refs: ["Matthew 5:29–30","Colossians 3:5"] },
  "Matthew 18:9": { title: "Guard the Eye", text: "The warning about plucking out an eye likewise calls for radical resistance to sin. Nothing in this teaching makes bodily injury the remedy; Jesus emphasizes the eternal seriousness of sin.", refs: ["Matthew 5:29","Romans 6:12–13"] },
  "Matthew 18:10": { title: "Do Not Despise Little Ones", text: "Jesus warns against despising these little ones and speaks of their angels beholding the Father’s face. Heaven is not indifferent to those whom the world may overlook.", refs: ["Psalm 91:11","Hebrews 1:14"] },
  "Matthew 18:11": { title: "The Son of Man Saves the Lost", text: "Some later manuscript traditions include a verse stating that the Son of man came to save the lost, while many modern editions omit it or place it in a note. The teaching itself is clearly affirmed elsewhere in the Gospels.", refs: ["Luke 19:10","Matthew 9:13"] },
  "Matthew 18:12": { title: "The Lost Sheep", text: "Jesus asks whether a shepherd would leave ninety-nine sheep to seek one that has gone astray. The illustration reveals the value of the wandering one and the seeking heart of God.", refs: ["Luke 15:4–7","Ezekiel 34:11–16"] },
  "Matthew 18:13": { title: "Joy over the Found Sheep", text: "The shepherd rejoices more over the recovered sheep than over those that never strayed. Heaven rejoices when the lost are restored.", refs: ["Luke 15:7","Zephaniah 3:17"] },
  "Matthew 18:14": { title: "The Father’s Will for Little Ones", text: "Jesus says it is not the Father’s will that one of these little ones should perish. This underscores God’s concern for the vulnerable and those in danger of wandering.", refs: ["John 6:39","2 Peter 3:9"] },
  "Matthew 18:15": { title: "Go to a Brother Who Sins", text: "Jesus instructs a believer to address a sinning brother privately first. The aim is to gain the brother, not to shame him publicly or spread the matter unnecessarily.", refs: ["Leviticus 19:17","Galatians 6:1"] },
  "Matthew 18:16": { title: "Take One or Two Witnesses", text: "If the brother will not hear, take one or two others so that the matter may be established by witnesses. This protects fairness and follows the scriptural principle of reliable testimony.", refs: ["Deuteronomy 19:15","2 Corinthians 13:1"] },
  "Matthew 18:17": { title: "Tell It to the Church", text: "If he refuses to hear the witnesses, the matter is brought to the church; continued refusal affects fellowship. The process is serious but restorative in purpose, and discipline must follow truth and justice.", refs: ["1 Corinthians 5:1–5","2 Thessalonians 3:14–15"] },
  "Matthew 18:18": { title: "Binding and Loosing", text: "Jesus speaks of binding and loosing in the context of the church’s handling of sin and reconciliation. Such authority must be exercised under His teaching, not as personal power to contradict God’s will.", refs: ["Matthew 16:19","John 20:23"] },
  "Matthew 18:19": { title: "Agreement in Prayer", text: "Jesus teaches that when two agree in prayer concerning a matter, the Father hears. The promise encourages united, God-directed prayer; it is not a guarantee that every selfish request will be granted.", refs: ["John 14:13–14","1 John 5:14"] },
  "Matthew 18:20": { title: "Gathered in Jesus’ Name", text: "Jesus promises to be in the midst of two or three gathered in His name. The power of the assembly rests in His presence and authority, not merely in the size of the gathering.", refs: ["Matthew 28:20","1 Corinthians 5:4"] },
  "Matthew 18:21": { title: "Peter Asks How Often to Forgive", text: "Peter asks whether forgiving a brother seven times is enough. He is trying to define a limit, while Jesus is about to teach a more generous spirit of forgiveness.", refs: ["Luke 17:3–4","Colossians 3:13"] },
  "Matthew 18:22": { title: "Forgive Without Keeping Count", text: "Jesus answers with a figure expressing forgiveness far beyond a narrow numerical limit. His point is not arithmetic but a heart ready to forgive repeatedly when repentance is shown.", refs: ["Genesis 4:24","Ephesians 4:32"] },
  "Matthew 18:23": { title: "A King Settles Accounts", text: "Jesus compares the kingdom to a king who begins settling accounts with his servants. The parable teaches that people who receive mercy from God must show mercy to others.", refs: ["Matthew 6:12","Romans 14:12"] },
  "Matthew 18:24": { title: "A Servant Owes a Great Debt", text: "One servant is brought in who owes an enormous sum. The debt illustrates the overwhelming account a person cannot repay by his own resources.", refs: ["Psalm 130:3–4","Romans 3:23–24"] },
  "Matthew 18:25": { title: "The Servant Cannot Pay", text: "Because the servant cannot repay, the king orders that he and his family and possessions be sold. The situation emphasizes the servant’s helplessness under the debt.", refs: ["Luke 7:42","Romans 6:23"] },
  "Matthew 18:26": { title: "The Servant Begs for Patience", text: "The servant falls down and pleads for patience, promising repayment. His promise cannot realistically meet the enormous debt, making the king’s mercy all the more striking.", refs: ["Psalm 51:1","Luke 18:13"] },
  "Matthew 18:27": { title: "The King Forgives the Debt", text: "Moved with compassion, the king releases the servant and forgives the debt. This is a picture of mercy freely granted rather than earned by repayment.", refs: ["Ephesians 1:7","Titus 3:5"] },
  "Matthew 18:28": { title: "The Forgiven Servant Refuses Mercy", text: "The servant finds a fellow servant who owes him a much smaller amount and demands payment harshly. Having received mercy, he fails to extend it to someone else.", refs: ["James 2:13","Matthew 6:14–15"] },
  "Matthew 18:29": { title: "His Fellow Servant Begs", text: "The fellow servant uses the same plea for patience that the first servant had made to the king. The parallel exposes the first servant’s hypocrisy.", refs: ["Matthew 18:26","Proverbs 21:13"] },
  "Matthew 18:30": { title: "He Will Not Forgive", text: "The first servant refuses and has the fellow servant imprisoned until the debt is paid. His lack of compassion contradicts the mercy he himself received.", refs: ["Matthew 5:7","Mark 11:25"] },
  "Matthew 18:31": { title: "Other Servants Are Grieved", text: "The other servants are deeply troubled and report what happened to the king. Cruelty and unforgiveness harm the wider community and are not hidden from judgment.", refs: ["Romans 12:15","1 John 3:17"] },
  "Matthew 18:32": { title: "The King Calls Him Wicked", text: "The king rebukes the servant for failing to show the mercy that had been shown to him. Receiving forgiveness creates a moral obligation to forgive others.", refs: ["Luke 6:36","Ephesians 4:32"] },
  "Matthew 18:33": { title: "Should You Not Have Had Compassion?", text: "The king asks whether the servant should have had compassion on his fellow servant. The question summarizes the moral center of the parable.", refs: ["Matthew 5:7","Colossians 3:12–13"] },
  "Matthew 18:34": { title: "Judgment for Unforgiveness", text: "The angry king delivers the servant to the tormentors until the debt is paid. The severe ending warns that a settled refusal to forgive is incompatible with truly receiving God’s mercy.", refs: ["Matthew 6:15","Hebrews 10:26–27"] },
  "Matthew 18:35": { title: "Forgive from the Heart", text: "Jesus applies the parable: each must forgive a brother from the heart. Biblical forgiveness is not merely polite words; it is a sincere release of vengeance, while accountability and wise boundaries may still be necessary.", refs: ["Mark 11:25","Romans 12:19","Ephesians 4:32"] },

  "Matthew 19:1": { title: "Jesus Departs from Galilee", text: "Jesus finishes these sayings and travels from Galilee into the coasts of Judaea beyond Jordan. The narrative moves toward the final journey to Jerusalem.", refs: ["Mark 10:1","Luke 9:51"] },
  "Matthew 19:2": { title: "The Multitudes Follow and Are Healed", text: "Great multitudes follow Jesus, and He heals them there. His teaching ministry continues alongside acts of compassion.", refs: ["Matthew 4:23","Matthew 14:14"] },
  "Matthew 19:3": { title: "A Question About Divorce", text: "The Pharisees test Jesus by asking whether a man may put away his wife for every cause. Their question seeks controversy, but Jesus directs them back to God’s design in creation.", refs: ["Mark 10:2","Deuteronomy 24:1"] },
  "Matthew 19:4": { title: "Male and Female from the Beginning", text: "Jesus points to the Creator’s making of male and female. Marriage is grounded in God’s creative purpose, not merely in later custom or convenience.", refs: ["Genesis 1:27","Genesis 5:2"] },
  "Matthew 19:5": { title: "One Flesh", text: "Jesus quotes the creation account: a man leaves father and mother and cleaves to his wife, and the two become one flesh. Marriage forms a covenantal union that is not to be treated lightly.", refs: ["Genesis 2:24","Ephesians 5:31"] },
  "Matthew 19:6": { title: "What God Has Joined", text: "Jesus says the two are no longer two but one flesh, and people should not separate what God has joined. His teaching upholds the seriousness and intended permanence of marriage.", refs: ["Malachi 2:14–16","Mark 10:9"] },
  "Matthew 19:7": { title: "Moses and the Writing of Divorce", text: "The Pharisees ask why Moses commanded a writing of divorcement. Jesus distinguishes a concession in the law from God’s original design.", refs: ["Deuteronomy 24:1–4","Mark 10:3–4"] },
  "Matthew 19:8": { title: "Hardness of Heart", text: "Jesus says Moses permitted divorce because of hardness of heart, but it was not so from the beginning. A concession addressing human sin should not be mistaken for the Creator’s ideal.", refs: ["Matthew 5:31–32","Genesis 2:24"] },
  "Matthew 19:9": { title: "Jesus’ Serious Warning on Divorce", text: "Jesus gives a strict warning against divorce and remarriage, with the exception clause concerning fornication. This verse must be read carefully alongside the broader biblical teaching on marriage, sexual faithfulness, and covenant responsibility.", refs: ["Matthew 5:32","Mark 10:11–12","1 Corinthians 7:10–15"] },
  "Matthew 19:10": { title: "The Disciples React", text: "The disciples conclude that if marriage carries such responsibility, it may be better not to marry. Their reaction shows how demanding Jesus’ teaching seemed to them.", refs: ["Mark 10:10–12","1 Corinthians 7:7–9"] },
  "Matthew 19:11": { title: "Not Everyone Receives This Saying", text: "Jesus says not everyone can receive the saying, but those to whom it is given can. He recognizes that people have different callings and capacities regarding marriage and celibacy.", refs: ["1 Corinthians 7:7","1 Corinthians 7:17"] },
  "Matthew 19:12": { title: "Those Who Remain Unmarried for the Kingdom", text: "Jesus describes different reasons some remain unmarried, including choosing a single life for the kingdom’s sake. This is a calling for some, not a command that all must avoid marriage.", refs: ["1 Corinthians 7:32–35","Isaiah 56:4–5"] },
  "Matthew 19:13": { title: "Children Brought to Jesus", text: "People bring little children to Jesus so He can lay hands on them and pray, but the disciples rebuke them. Jesus’ response will correct the idea that children are unworthy of His attention.", refs: ["Mark 10:13","Luke 18:15"] },
  "Matthew 19:14": { title: "Let the Children Come", text: "Jesus commands that the children be allowed to come to Him, for the kingdom of heaven belongs to such as these. He welcomes them and commends the humble posture they illustrate.", refs: ["Matthew 18:3–4","Mark 10:14"] },
  "Matthew 19:15": { title: "Jesus Blesses the Children", text: "Jesus lays His hands on the children and departs. His action confirms that His welcome is real and personal, not merely a lesson in symbolism.", refs: ["Mark 10:16","Luke 18:16"] },
  "Matthew 19:16": { title: "The Rich Young Man Asks About Life", text: "A man asks Jesus what good thing he must do to have eternal life. His question begins a conversation that exposes the difference between outward obedience and wholehearted surrender.", refs: ["Mark 10:17","Luke 18:18"] },
  "Matthew 19:17": { title: "Goodness and God’s Commandments", text: "Jesus directs the man to God’s goodness and the commandments. The response challenges shallow assumptions about goodness and places the questioner under God’s moral standard.", refs: ["Exodus 20:12–16","Romans 3:20"] },
  "Matthew 19:18": { title: "Commandments Concerning Neighbor", text: "Jesus names commandments against murder, adultery, theft, and false witness. These commands concern concrete conduct toward other people.", refs: ["Exodus 20:13–16","Romans 13:9"] },
  "Matthew 19:19": { title: "Honor Parents and Love Your Neighbor", text: "Jesus includes honoring parents and loving one’s neighbor as oneself. Love fulfills the law’s intent but does not turn obedience into a means of boasting.", refs: ["Exodus 20:12","Leviticus 19:18","Romans 13:8–10"] },
  "Matthew 19:20": { title: "The Man Claims to Have Kept the Commands", text: "The young man says he has kept these commandments and asks what he still lacks. Jesus will reveal the deeper allegiance that his self-assessment has not confronted.", refs: ["Luke 18:21","Philippians 3:6–9"] },
  "Matthew 19:21": { title: "Sell, Give, and Follow Jesus", text: "Jesus tells him to sell his possessions, give to the poor, gain treasure in heaven, and follow Him. The command exposes the man’s attachment to wealth and calls him to place Jesus above his possessions.", refs: ["Luke 12:33","Matthew 6:19–21"] },
  "Matthew 19:22": { title: "The Young Man Goes Away Sorrowful", text: "The man leaves grieving because he has great possessions. His sorrow reveals that he is unwilling to surrender what competes with obedience to Jesus.", refs: ["Mark 10:22","Luke 12:15"] },
  "Matthew 19:23": { title: "The Difficulty of the Rich Entering", text: "Jesus says it is difficult for a rich person to enter the kingdom of heaven. Wealth can foster self-reliance and attachment, making surrender to God harder.", refs: ["1 Timothy 6:9–10","James 5:1–3"] },
  "Matthew 19:24": { title: "A Camel Through a Needle’s Eye", text: "Jesus uses an intentionally striking image to show the difficulty of wealth obstructing entry into God’s kingdom. The point is not a clever loophole but the impossibility of relying on riches as a route to life.", refs: ["Mark 10:25","Luke 18:25"] },
  "Matthew 19:25": { title: "Who Then Can Be Saved?", text: "The disciples are astonished and ask who can be saved. They recognize that if wealth and status cannot secure salvation, no one can presume on human advantage.", refs: ["Psalm 49:6–9","Romans 3:23"] },
  "Matthew 19:26": { title: "With God All Things Are Possible", text: "Jesus says that salvation is impossible with people but possible with God. Eternal life is ultimately made possible by God’s saving work, not human achievement or wealth.", refs: ["Jeremiah 32:17","Luke 1:37","Ephesians 2:8–9"] },
  "Matthew 19:27": { title: "Peter Asks About Their Reward", text: "Peter says the disciples have left all to follow Jesus and asks what they will receive. The question raises the cost of discipleship and the hope of God’s promised restoration.", refs: ["Mark 10:28","Luke 18:28"] },
  "Matthew 19:28": { title: "The Regeneration and the Twelve Thrones", text: "Jesus speaks of the regeneration, when the Son of man sits on His glorious throne, and promises the twelve apostles a role in judging the twelve tribes of Israel. The saying points to future kingdom restoration and apostolic responsibility.", refs: ["Luke 22:28–30","Revelation 21:12–14"] },
  "Matthew 19:29": { title: "Reward for Leaving All for Jesus", text: "Those who leave homes, family, or lands for Jesus’ name will receive abundantly and inherit eternal life. Jesus does not teach contempt for family; He teaches that loyalty to Him outranks every earthly claim.", refs: ["Mark 10:29–30","Luke 14:26"] },
  "Matthew 19:30": { title: "The First and the Last", text: "Jesus warns that many who are first will be last and the last first. Kingdom reward overturns worldly ranking and calls for humility rather than entitlement.", refs: ["Matthew 20:16","Luke 13:30"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 20:1": { title: "The Laborers in the Vineyard", text: "Jesus compares the kingdom of heaven to a householder who hires laborers for his vineyard. The parable addresses God's generosity and warns against measuring His goodness by human comparisons.", refs: ["Matthew 19:30","Matthew 20:16"] },
  "Matthew 20:2": { title: "An Agreed Penny", text: "The householder agrees with the first laborers for a penny a day and sends them to work. Their agreement establishes the expectation against which the later payment is judged.", refs: ["Leviticus 19:13","Matthew 20:13"] },
  "Matthew 20:3": { title: "Laborers at the Third Hour", text: "The householder finds others standing idle in the marketplace at the third hour. He continues seeking workers rather than limiting his invitation to the first group.", refs: ["Matthew 9:37–38","John 4:35"] },
  "Matthew 20:4": { title: "A Promise to Pay What Is Right", text: "He tells the later workers to go into the vineyard and promises to give them what is right. Their trust rests on the householder's word rather than a specified wage.", refs: ["Psalm 9:8","Romans 9:14–16"] },
  "Matthew 20:5": { title: "More Workers Are Hired", text: "The householder goes out again at the sixth and ninth hours and does the same. The repeated invitations show his continuing willingness to bring people into the work.", refs: ["Isaiah 55:6","John 6:37"] },
  "Matthew 20:6": { title: "Workers at the Eleventh Hour", text: "Near the end of the day, the householder finds others still standing idle and asks why they have not worked. They explain that no one hired them.", refs: ["Luke 23:39–43","2 Peter 3:9"] },
  "Matthew 20:7": { title: "Go Into the Vineyard", text: "The householder sends them into the vineyard too. The invitation reaches even those who begin late, displaying generosity without suggesting that a person should deliberately delay obedience.", refs: ["Luke 14:21–23","Hebrews 3:15"] },
  "Matthew 20:8": { title: "The Wages Are Paid", text: "At evening, the owner tells his steward to pay the laborers, beginning with the last and ending with the first. The order of payment exposes the attitudes of those who compare their reward with others.", refs: ["Leviticus 19:13","Deuteronomy 24:15"] },
  "Matthew 20:9": { title: "The Last Receive a Penny", text: "Those hired at the eleventh hour each receive a penny. The householder's generosity toward them is the central surprise of the parable.", refs: ["Romans 4:4–5","Titus 3:5–7"] },
  "Matthew 20:10": { title: "The First Expect More", text: "The first laborers assume they will receive more when they see the late workers paid the same amount. Their expectation turns another person's blessing into a reason for resentment.", refs: ["Jonah 4:1–4","Luke 15:28–30"] },
  "Matthew 20:11": { title: "They Complain Against the Householder", text: "After receiving their wages, the first laborers murmur against the householder. Their complaint reveals dissatisfaction with his generosity, despite receiving the wage they had agreed upon.", refs: ["Exodus 16:2–8","1 Corinthians 10:10"] },
  "Matthew 20:12": { title: "The Complaint of Unequal Hours", text: "They complain that those who worked only one hour were paid equally with them despite the day's heat and burden. They judge fairness only by comparison, not by the agreement they received.", refs: ["Luke 15:29–30","Romans 12:15"] },
  "Matthew 20:13": { title: "No Wrong Was Done", text: "The householder answers one of them that he has done no wrong and paid the agreed wage. God's generosity to another person does not mean He has broken His promise to us.", refs: ["Deuteronomy 32:4","Romans 9:14"] },
  "Matthew 20:14": { title: "Take What Is Yours", text: "The householder tells the laborer to take what is his and says he chooses to give the last worker the same. The parable distinguishes justice in keeping a promise from generosity freely extended.", refs: ["Romans 11:6","James 1:17"] },
  "Matthew 20:15": { title: "The Right to Be Generous", text: "The householder asks whether he may do what he wishes with his own and whether the laborer's eye is evil because he is good. Envy resents goodness when it benefits someone else.", refs: ["Deuteronomy 15:9–10","Proverbs 23:6–7"] },
  "Matthew 20:16": { title: "The Last Shall Be First", text: "Jesus concludes that the last will be first and the first last. God's kingdom overturns pride and entitlement; His generosity is not controlled by human rankings.", refs: ["Matthew 19:30","Luke 13:30"] },
  "Matthew 20:17": { title: "Jesus Goes Up to Jerusalem", text: "Jesus takes the twelve disciples aside on the way to Jerusalem. He prepares them for what is coming rather than allowing them to misunderstand His mission as earthly triumph alone.", refs: ["Mark 10:32","Luke 18:31"] },
  "Matthew 20:18": { title: "The Son of Man Will Be Delivered", text: "Jesus says the Son of man will be delivered to the chief priests and scribes and condemned to death. His suffering is foreknown and central to His saving work.", refs: ["Isaiah 53:3–8","Matthew 16:21"] },
  "Matthew 20:19": { title: "Crucifixion and Resurrection Foretold", text: "Jesus says He will be delivered to the Gentiles, mocked, scourged, crucified, and raised on the third day. The prediction joins the humiliation of the cross with the certainty of resurrection.", refs: ["Psalm 22:1–18","Matthew 28:5–6","Luke 24:7"] },
  "Matthew 20:20": { title: "A Request for Her Sons", text: "The mother of Zebedee's sons approaches Jesus with her sons and makes a request. The next exchange reveals that even close followers still misunderstand the nature of kingdom greatness.", refs: ["Mark 10:35","Matthew 18:1"] },
  "Matthew 20:21": { title: "Seats at the Right and Left", text: "She asks that her sons sit at Jesus' right and left in His kingdom. Their ambition seeks honor before they have understood the suffering Jesus has just described.", refs: ["Matthew 19:28","Mark 10:37"] },
  "Matthew 20:22": { title: "Can You Drink the Cup?", text: "Jesus asks whether they can drink the cup He is about to drink. The cup points to suffering; discipleship is not simply a claim to honor but a willingness to remain faithful through hardship.", refs: ["Matthew 26:39","John 18:11"] },
  "Matthew 20:23": { title: "Places of Honor Are Not His to Assign", text: "Jesus says they will share in His cup, but places at His right and left are prepared by the Father. The passage emphasizes that kingdom honor is assigned according to God's purpose, not secured by ambition.", refs: ["Acts 1:7","Mark 10:40"] },
  "Matthew 20:24": { title: "The Ten Are Indignant", text: "The other ten disciples are displeased with the two brothers. Their indignation suggests that rivalry is not confined to the pair who made the request.", refs: ["Luke 22:24","Philippians 2:3"] },
  "Matthew 20:25": { title: "Gentile Rulers Exercise Authority", text: "Jesus contrasts kingdom leadership with rulers who dominate those under them. His followers must not imitate leadership built on oppression and status.", refs: ["Mark 10:42","1 Peter 5:2–3"] },
  "Matthew 20:26": { title: "Greatness Through Service", text: "Jesus says it must not be so among His disciples; whoever would be great must become a servant. Kingdom greatness is measured by service rather than control.", refs: ["Matthew 23:11","John 13:14–15"] },
  "Matthew 20:27": { title: "The First Must Be Servant", text: "Whoever wants to be first must become a servant. Jesus calls His people to put others' needs ahead of self-promotion.", refs: ["Mark 9:35","Romans 12:10"] },
  "Matthew 20:28": { title: "The Son of Man Gives His Life", text: "Jesus says the Son of man came not to be served but to serve and give His life a ransom for many. The sacrifice is His own life freely given for the deliverance of others; the verse does not require describing salvation as one divine person paying another divine person.", refs: ["Isaiah 53:10–12","1 Timothy 2:5–6","John 10:17–18"] },
  "Matthew 20:29": { title: "Two Blind Men Near Jericho", text: "As Jesus and His disciples leave Jericho, a great multitude follows. The setting leads to a public appeal for mercy from two blind men.", refs: ["Mark 10:46","Luke 18:35"] },
  "Matthew 20:30": { title: "Jesus, Son of David, Have Mercy", text: "Two blind men hear that Jesus is passing and cry out to Him as Son of David. Their title recognizes His messianic lineage, and their plea depends on His mercy.", refs: ["Isaiah 35:5","Matthew 9:27"] },
  "Matthew 20:31": { title: "They Cry Out More Earnestly", text: "The crowd rebukes the men and tells them to be quiet, but they cry out even more. They refuse to let public pressure silence their appeal to Jesus.", refs: ["Luke 18:39","Psalm 34:6"] },
  "Matthew 20:32": { title: "Jesus Stops and Asks", text: "Jesus stands still, calls the men, and asks what they want Him to do. He gives them the opportunity to state their need plainly.", refs: ["Mark 10:49–51","Philippians 4:6"] },
  "Matthew 20:33": { title: "Lord, Open Our Eyes", text: "They ask Jesus to open their eyes. Their request is direct and shows confidence that He can restore their sight.", refs: ["Psalm 146:8","Isaiah 42:7"] },
  "Matthew 20:34": { title: "Jesus Has Compassion and Heals", text: "Moved with compassion, Jesus touches their eyes, and immediately they receive sight and follow Him. His healing power is joined with mercy and leads the men into discipleship.", refs: ["Matthew 9:29–30","Mark 10:52"] },

  "Matthew 21:1": { title: "Approaching Jerusalem", text: "Jesus and His disciples come near Jerusalem to Bethphage at the Mount of Olives. The setting prepares for His public entry as the promised King.", refs: ["Zechariah 14:4","Mark 11:1"] },
  "Matthew 21:2": { title: "The Donkey and Her Colt", text: "Jesus sends two disciples to find a donkey tied with her colt and tells them to bring them. The precise instructions show that the entry unfolds according to His direction.", refs: ["Mark 11:2–3","Luke 19:30–31"] },
  "Matthew 21:3": { title: "The Lord Has Need of Them", text: "Jesus tells the disciples what to say if anyone questions them: the Lord has need of them and will send them back. The statement asserts His authority over the arrangements for His entry.", refs: ["Matthew 28:18","Mark 11:3"] },
  "Matthew 21:4": { title: "The Prophet's Word Fulfilled", text: "These events fulfill what was spoken through the prophet. Matthew presents Jesus' entry as the fulfillment of Scripture, not an accidental public scene.", refs: ["Zechariah 9:9","John 12:14–16"] },
  "Matthew 21:5": { title: "The King Comes Meekly", text: "The daughter of Sion is told that her King comes meek, riding on a donkey and a colt. Jesus displays royal identity without the symbols of a conquering military ruler.", refs: ["Zechariah 9:9","Isaiah 62:11"] },
  "Matthew 21:6": { title: "The Disciples Obey", text: "The disciples do as Jesus commanded them. Their simple obedience helps bring the prophetic sign to pass.", refs: ["John 2:5","Matthew 28:19–20"] },
  "Matthew 21:7": { title: "The Animals Are Brought to Jesus", text: "They bring the donkey and colt, place garments on them, and Jesus sits on them. The action gives visible expression to the prophecy of the humble King.", refs: ["Mark 11:7","Luke 19:35"] },
  "Matthew 21:8": { title: "Garments and Branches on the Road", text: "Many spread their garments in the way, while others cut branches and lay them down. The crowd honors Jesus in a manner associated with welcoming a king.", refs: ["2 Kings 9:13","John 12:13"] },
  "Matthew 21:9": { title: "Hosanna to the Son of David", text: "The crowds cry Hosanna to the Son of David and bless the One who comes in the Lord's name. Their words echo the Psalms and proclaim messianic hope.", refs: ["Psalm 118:25–26","Matthew 12:23"] },
  "Matthew 21:10": { title: "Jerusalem Is Stirred", text: "Jesus' entry stirs the whole city, and people ask who He is. His presence demands a response and makes His identity a public question.", refs: ["Matthew 2:3","John 12:19"] },
  "Matthew 21:11": { title: "Jesus the Prophet of Nazareth", text: "The crowds answer that Jesus is the prophet from Nazareth of Galilee. This is true as far as it goes, but Matthew's Gospel has already revealed Him as more than a prophet: the Christ and Son of God.", refs: ["Deuteronomy 18:15","Matthew 16:16"] },
  "Matthew 21:12": { title: "Jesus Cleanses the Temple", text: "Jesus drives out those buying and selling in the temple and overturns the money changers' tables. His action confronts the corruption of worship and asserts the holiness of God's house.", refs: ["Isaiah 56:7","Jeremiah 7:11","John 2:14–16"] },
  "Matthew 21:13": { title: "A House of Prayer Made a Den of Thieves", text: "Jesus cites Scripture to declare that God's house should be called a house of prayer, but they have made it a den of thieves. Worship must honor God's purpose rather than exploit people.", refs: ["Isaiah 56:7","Jeremiah 7:11"] },
  "Matthew 21:14": { title: "The Blind and Lame Come to Jesus", text: "Blind and lame people come to Jesus in the temple, and He heals them. After confronting corruption, He demonstrates the healing mercy that should characterize God's house.", refs: ["Isaiah 35:5–6","Matthew 15:30"] },
  "Matthew 21:15": { title: "Children Cry Hosanna", text: "The chief priests and scribes are displeased by Jesus' works and by children crying Hosanna to the Son of David. Those in authority resent praise that recognizes Jesus' messianic identity.", refs: ["Psalm 8:2","Matthew 21:9"] },
  "Matthew 21:16": { title: "Praise from the Mouths of Children", text: "Jesus quotes Scripture about praise perfected from the mouths of children. He accepts their praise and rebukes the leaders for failing to recognize what Scripture says.", refs: ["Psalm 8:2","Luke 19:40"] },
  "Matthew 21:17": { title: "Jesus Goes to Bethany", text: "Jesus leaves the city and lodges in Bethany. His movements between Bethany and Jerusalem frame the events of the final week.", refs: ["Mark 11:11","John 11:18"] },
  "Matthew 21:18": { title: "Jesus Is Hungry", text: "In the morning Jesus returns to the city and is hungry. The ordinary detail of hunger underscores His real human experience.", refs: ["Matthew 4:2","John 4:6"] },
  "Matthew 21:19": { title: "The Fig Tree Withers", text: "Jesus finds no fruit on a fig tree, speaks judgment upon it, and it withers. The acted parable warns against a show of religious life without the fruit God seeks.", refs: ["Mark 11:12–14","Luke 13:6–9"] },
  "Matthew 21:20": { title: "The Disciples Marvel", text: "The disciples are amazed at how quickly the fig tree withers. Their wonder opens the way for Jesus to teach them about faith and prayer.", refs: ["Mark 11:20–21","Matthew 17:20"] },
  "Matthew 21:21": { title: "Faith Without Doubting", text: "Jesus teaches that faith can accomplish what seems impossible, using the mountain and sea as vivid imagery. This is a call to trust God, not a promise that human desire can command any outcome.", refs: ["Matthew 17:20","James 1:6–7"] },
  "Matthew 21:22": { title: "Ask in Prayer, Believing", text: "Jesus connects prayer with believing. Biblical prayer trusts God's wisdom and will rather than treating faith as a technique to force an answer.", refs: ["1 John 5:14","Mark 11:24"] },
  "Matthew 21:23": { title: "Who Gave You This Authority?", text: "Chief priests and elders challenge Jesus' authority to teach and act in the temple. Their question is institutional, but Jesus exposes their unwillingness to respond honestly to God's witness.", refs: ["Matthew 7:29","Acts 4:7"] },
  "Matthew 21:24": { title: "Jesus Asks a Question in Return", text: "Jesus says He will answer if they first answer His question about John's baptism. Their response to John will reveal whether they are truly seeking truth.", refs: ["Matthew 11:7–11","Luke 20:3–4"] },
  "Matthew 21:25": { title: "The Baptism of John", text: "Jesus asks whether John's baptism came from heaven or from men. The leaders privately weigh the consequences of each answer instead of asking which answer is true.", refs: ["John 1:6–8","Matthew 3:5–6"] },
  "Matthew 21:26": { title: "Fear of the Multitude", text: "They fear the crowd because the people regard John as a prophet. Fear of public opinion prevents them from speaking plainly about God's messenger.", refs: ["Matthew 14:5","John 9:22"] },
  "Matthew 21:27": { title: "We Cannot Tell", text: "The leaders answer that they do not know, so Jesus declines to answer their challenge. Their evasive response reveals that their question was not a sincere search for truth.", refs: ["Proverbs 26:4–5","Luke 20:7–8"] },
  "Matthew 21:28": { title: "A Father and Two Sons", text: "Jesus introduces a parable of a father who tells two sons to work in his vineyard. Their different responses will show that obedience is demonstrated by action, not words alone.", refs: ["Matthew 7:21","Luke 6:46"] },
  "Matthew 21:29": { title: "The Son Who First Refuses", text: "One son says he will not go, but afterward repents and goes. His initial refusal is wrong, yet he ultimately responds with action.", refs: ["Ezekiel 18:21–23","Luke 15:18–20"] },
  "Matthew 21:30": { title: "The Son Who Says Yes", text: "The second son says he will go but does not. A respectful-sounding promise is worthless when it is not followed by obedience.", refs: ["James 1:22","Titus 1:16"] },
  "Matthew 21:31": { title: "Publicans and Harlots Enter First", text: "Jesus says tax collectors and harlots go into the kingdom before the leaders because they believed John, while the leaders did not repent afterward. Responding to God's call matters more than a reputation for religious respectability.", refs: ["Luke 7:29–30","Matthew 3:5–8"] },
  "Matthew 21:32": { title: "John Came in the Way of Righteousness", text: "John came showing the way of righteousness, yet the leaders did not believe him even after seeing sinners respond. Their failure is not lack of evidence but refusal to repent and believe.", refs: ["Matthew 3:1–8","Luke 7:30"] },
  "Matthew 21:33": { title: "The Parable of the Vineyard", text: "Jesus tells of a householder who plants a vineyard, equips it, leases it, and travels away. The imagery echoes Isaiah's vineyard song and prepares an indictment of leaders who reject God's messengers.", refs: ["Isaiah 5:1–7","Mark 12:1"] },
  "Matthew 21:34": { title: "Servants Sent for Fruit", text: "At harvest, the owner sends servants to receive the fruit. The servants represent those sent to call the tenants to fulfill their responsibility.", refs: ["2 Chronicles 36:15–16","Jeremiah 7:25–26"] },
  "Matthew 21:35": { title: "The Servants Are Mistreated", text: "The tenants seize the servants, beat one, kill another, and stone another. The parable recalls the repeated rejection and persecution of God's messengers.", refs: ["Nehemiah 9:26","Hebrews 11:36–38"] },
  "Matthew 21:36": { title: "More Servants Are Sent", text: "The owner sends additional servants, more than before, and they are treated the same way. God's repeated warnings reveal patience, while continued rejection increases accountability.", refs: ["Jeremiah 25:4","Matthew 23:37"] },
  "Matthew 21:37": { title: "The Beloved Son Is Sent", text: "Finally the owner sends his son, expecting the tenants to respect him. In the parable, the son has a unique status that the servants do not share, reflecting Jesus' unique sonship and mission.", refs: ["Hebrews 1:1–2","John 3:16–17"] },
  "Matthew 21:38": { title: "The Heir Is Rejected", text: "The tenants recognize the heir and decide to kill him to seize his inheritance. The parable points to the leaders' rejection of Jesus and exposes the selfish motives behind it.", refs: ["John 11:47–53","Acts 2:23"] },
  "Matthew 21:39": { title: "The Son Is Cast Out and Killed", text: "The tenants cast the son out of the vineyard and kill him. The image foreshadows Jesus' rejection and death outside Jerusalem.", refs: ["Hebrews 13:12","John 19:16–18"] },
  "Matthew 21:40": { title: "The Owner Will Judge the Tenants", text: "Jesus asks what the owner will do when he comes. The question invites the hearers to pronounce judgment on the tenants before recognizing that the parable concerns them.", refs: ["Matthew 21:41","Luke 20:15–16"] },
  "Matthew 21:41": { title: "The Vineyard Given to Others", text: "The hearers answer that the owner will destroy the wicked tenants and lease the vineyard to others who will give him fruit. The answer anticipates judgment on unfaithful leadership and the raising up of a fruitful people.", refs: ["Matthew 8:11–12","Romans 11:17–21"] },
  "Matthew 21:42": { title: "The Rejected Stone Becomes the Head", text: "Jesus cites the Scripture about the stone rejected by builders becoming the chief cornerstone. The rejected Jesus becomes the foundation of God's saving work, as the Lord has done this.", refs: ["Psalm 118:22–23","Acts 4:11","1 Peter 2:6–7"] },
  "Matthew 21:43": { title: "The Kingdom Given to a Fruitful Nation", text: "Jesus says the kingdom will be taken from those who refuse its fruit and given to a nation producing its fruits. The warning is against unbelief and unfaithfulness, not a license for ethnic contempt; all who belong to Christ are called to bear fruit.", refs: ["Galatians 3:28–29","John 15:5–8"] },
  "Matthew 21:44": { title: "The Stone That Breaks and Crushes", text: "Jesus describes the stone as a source of ruin to those who fall upon it and judgment upon those it falls on. Rejecting God's chosen cornerstone carries serious consequences.", refs: ["Isaiah 8:14–15","Daniel 2:34–35"] },
  "Matthew 21:45": { title: "The Leaders Know He Speaks of Them", text: "The chief priests and Pharisees understand that Jesus' parables speak against them. Recognition does not necessarily produce repentance; they respond with hostility.", refs: ["Luke 20:19","John 7:30"] },
  "Matthew 21:46": { title: "They Fear the People", text: "They want to seize Jesus but fear the crowd, which regards Him as a prophet. Their concern is shaped by public reaction rather than submission to the truth.", refs: ["Matthew 14:5","John 11:47–48"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 22:1": { title: "The Parable of the Marriage Feast", text: "Jesus compares the kingdom of heaven to a king who prepares a marriage feast for his son. The feast pictures God's gracious invitation and the honor of the Son.", refs: ["Luke 14:16–17","Revelation 19:7–9"] },
  "Matthew 22:2": { title: "A King Makes a Marriage for His Son", text: "The king prepares a marriage feast for his son. The image centers on the son's honor and the king's desire to share the celebration with invited guests.", refs: ["Psalm 45:6–7","John 3:29"] },
  "Matthew 22:3": { title: "The Invited Guests Refuse", text: "The king sends servants to call those already invited, but they will not come. God's invitation can be refused even when it is graciously and clearly presented.", refs: ["Isaiah 65:2","Luke 14:18"] },
  "Matthew 22:4": { title: "The Invitation Is Repeated", text: "The king sends other servants and describes the prepared meal and feast. The repeated invitation demonstrates patience and the abundance prepared for the guests.", refs: ["Proverbs 9:1–5","Isaiah 25:6"] },
  "Matthew 22:5": { title: "Some Ignore the Invitation", text: "The invited guests make light of the call and go to their own fields or business. Everyday responsibilities become excuses when people refuse to give God His rightful place.", refs: ["Luke 14:18–20","Haggai 1:5–9"] },
  "Matthew 22:6": { title: "The Servants Are Mistreated", text: "Others seize the king's servants, treat them spitefully, and kill them. The parable echoes the rejection of God's messengers and the hostility shown toward His word.", refs: ["Matthew 21:35–36","2 Chronicles 36:15–16"] },
  "Matthew 22:7": { title: "The King Judges the Murderers", text: "The king responds with judgment against the murderers and their city. The parable warns that rejecting God's invitation with violence brings accountability.", refs: ["Luke 19:41–44","Matthew 23:37–38"] },
  "Matthew 22:8": { title: "The Guests Were Not Worthy", text: "The king says those invited were not worthy and orders the feast to continue with others. Their unworthiness is shown by their refusal, not by a lack of generosity from the king.", refs: ["Acts 13:46","Hebrews 2:3"] },
  "Matthew 22:9": { title: "Invite Whomever You Find", text: "The servants are sent to the crossroads to invite everyone they find. God's invitation extends beyond those who first assumed they would attend.", refs: ["Matthew 28:19","Acts 10:34–35"] },
  "Matthew 22:10": { title: "The Wedding Is Filled", text: "The servants gather both bad and good, and the wedding is filled with guests. The invitation reaches people from every kind of background, while the next verses show that responding to the invitation also matters.", refs: ["Luke 14:21–23","Acts 2:39"] },
  "Matthew 22:11": { title: "A Guest Without a Wedding Garment", text: "The king sees a man without a wedding garment. The scene shifts from the invitation being offered to the necessity of being properly prepared for the king's feast.", refs: ["Revelation 19:8","Isaiah 61:10"] },
  "Matthew 22:12": { title: "The Guest Has No Answer", text: "The king asks how the man entered without a wedding garment, and he is speechless. The encounter warns that outward presence among God's people is not a substitute for a fitting response to His grace.", refs: ["Romans 13:14","Colossians 3:12"] },
  "Matthew 22:13": { title: "Cast into Outer Darkness", text: "The king orders the unprepared guest removed into outer darkness, where there is weeping and gnashing of teeth. Jesus uses severe imagery to warn of final judgment.", refs: ["Matthew 8:12","Matthew 13:41–42"] },
  "Matthew 22:14": { title: "Many Are Called, Few Chosen", text: "Jesus concludes that many are called but few are chosen. The parable joins the breadth of God's invitation with the seriousness of truly responding to it.", refs: ["Matthew 7:13–14","2 Peter 1:10"] },
  "Matthew 22:15": { title: "A Plot to Trap Jesus", text: "The Pharisees take counsel about how to entangle Jesus in His words. Their aim is not to learn but to manufacture a reason to accuse Him.", refs: ["Mark 12:13","Psalm 2:1–2"] },
  "Matthew 22:16": { title: "Flattery Before a Question", text: "They send disciples with Herodians who flatter Jesus as truthful and impartial before asking their question. Their praise is manipulative, demonstrating that even accurate words can be spoken with deceitful motives.", refs: ["Luke 20:20","Proverbs 26:24–26"] },
  "Matthew 22:17": { title: "Is It Lawful to Pay Tribute?", text: "They ask whether it is lawful to pay tribute to Caesar. They hope to force Jesus into a politically dangerous answer either way.", refs: ["Romans 13:7","Mark 12:14"] },
  "Matthew 22:18": { title: "Jesus Knows Their Wickedness", text: "Jesus perceives their wickedness and calls them hypocrites. He is not deceived by their respectful approach and exposes the trap behind their question.", refs: ["John 2:24–25","Luke 6:8"] },
  "Matthew 22:19": { title: "Show the Tribute Money", text: "Jesus asks them to show Him the tribute coin. He uses the coin itself to lead them toward the answer rather than accepting their false dilemma.", refs: ["Mark 12:15","Luke 20:24"] },
  "Matthew 22:20": { title: "Whose Image and Superscription?", text: "Jesus asks whose image and inscription are on the coin. The visible mark establishes the point that follows.", refs: ["Genesis 1:26–27","Mark 12:16"] },
  "Matthew 22:21": { title: "Render to Caesar and to God", text: "They answer that the coin bears Caesar's image, and Jesus tells them to render to Caesar what belongs to Caesar and to God what belongs to God. Civic obligations do not cancel God's higher claim upon the whole person, who bears God's image.", refs: ["Romans 13:1–7","Genesis 1:27","Acts 5:29"] },
  "Matthew 22:22": { title: "They Marvel and Depart", text: "The questioners marvel at Jesus' answer and leave. His wisdom defeats their trap without surrendering either truth or proper civic responsibility.", refs: ["Luke 20:26","Proverbs 2:6"] },
  "Matthew 22:23": { title: "The Sadducees Deny the Resurrection", text: "The Sadducees, who deny the resurrection, present Jesus with a hypothetical case about marriage. Their question is designed to make resurrection seem absurd.", refs: ["Acts 23:8","Mark 12:18"] },
  "Matthew 22:24": { title: "Moses' Law About a Brother's Wife", text: "They quote the law requiring a brother to raise up seed for a deceased brother who died childless. The provision addressed family continuity in Israel, but they use it to challenge resurrection.", refs: ["Deuteronomy 25:5–6","Genesis 38:8"] },
  "Matthew 22:25": { title: "Seven Brothers", text: "The hypothetical story begins with seven brothers, the first of whom marries and dies without children. The elaborate example is intended to create a puzzle rather than honestly seek understanding.", refs: ["Mark 12:20","Luke 20:29"] },
  "Matthew 22:26": { title: "The Second and Third Brother", text: "The second and third brothers likewise marry the woman and die. The repeated pattern continues the Sadducees' proposed dilemma.", refs: ["Matthew 22:25","Luke 20:30–31"] },
  "Matthew 22:27": { title: "The Woman Also Dies", text: "After all seven brothers, the woman dies too. The questioners now present the situation as if it invalidates the resurrection.", refs: ["Matthew 22:25–26","Mark 12:22"] },
  "Matthew 22:28": { title: "Whose Wife in the Resurrection?", text: "They ask whose wife she will be in the resurrection, since all seven had married her. Their error is assuming the life to come simply repeats earthly arrangements.", refs: ["Luke 20:33","Matthew 22:30"] },
  "Matthew 22:29": { title: "Mistaken About Scripture and Power", text: "Jesus says they err because they do not know the Scriptures or the power of God. False conclusions often come from limiting God to human assumptions and failing to read His word rightly.", refs: ["2 Timothy 2:15","Ephesians 1:19–20"] },
  "Matthew 22:30": { title: "No Marriage in the Resurrection", text: "Jesus explains that in the resurrection people neither marry nor are given in marriage but are as the angels in heaven in this respect. He does not say redeemed humans become angels; He teaches that resurrection life is not governed by the same marriage arrangements.", refs: ["Luke 20:34–36","1 Corinthians 15:42–44"] },
  "Matthew 22:31": { title: "Have You Not Read About the Resurrection?", text: "Jesus points them back to what God spoke concerning the resurrection. He grounds the answer in Scripture rather than speculative argument.", refs: ["Exodus 3:6","Mark 12:26"] },
  "Matthew 22:32": { title: "God of the Living", text: "God calls Himself the God of Abraham, Isaac, and Jacob; Jesus concludes that God is not the God of the dead but of the living. God's covenant relationship and power overcome the Sadducees' assumption that death ends all hope.", refs: ["Exodus 3:6","Luke 20:37–38","Hebrews 11:16"] },
  "Matthew 22:33": { title: "The Multitude Is Astonished", text: "The multitude is astonished at Jesus' teaching. His answer has shown that the resurrection is consistent with Scripture and God's power.", refs: ["Matthew 7:28–29","Mark 12:27"] },
  "Matthew 22:34": { title: "The Pharisees Gather Together", text: "When the Pharisees hear that Jesus has silenced the Sadducees, they gather. Another group attempts to challenge Him, now with a question about the law's greatest commandment.", refs: ["Mark 12:28","Luke 10:25"] },
  "Matthew 22:35": { title: "A Lawyer Tests Jesus", text: "A lawyer asks a question to test Jesus. The question is about the law, but the motive is adversarial rather than humble inquiry.", refs: ["Luke 10:25","Matthew 19:3"] },
  "Matthew 22:36": { title: "Which Commandment Is Greatest?", text: "The lawyer asks which commandment is greatest in the law. Jesus' answer will show that the whole law's moral purpose is centered on love for God and neighbor.", refs: ["Deuteronomy 6:4–5","Leviticus 19:18"] },
  "Matthew 22:37": { title: "Love the Lord with All Your Being", text: "Jesus commands love for the Lord with all the heart, soul, and mind. True devotion involves the whole person and is grounded in the one Lord Israel confesses.", refs: ["Deuteronomy 6:4–5","Mark 12:29–30"] },
  "Matthew 22:38": { title: "The First and Great Commandment", text: "Jesus calls this the first and great commandment. Every part of life is to be ordered by wholehearted love for God.", refs: ["Deuteronomy 10:12","Joshua 22:5"] },
  "Matthew 22:39": { title: "Love Your Neighbor as Yourself", text: "The second commandment is to love one's neighbor as oneself. Love for God must be expressed in how people treat other people.", refs: ["Leviticus 19:18","Romans 13:9–10"] },
  "Matthew 22:40": { title: "The Law and the Prophets Hang on Love", text: "Jesus says all the law and prophets hang on these two commandments. Love does not abolish God's word; it expresses its central moral purpose and guides faithful obedience.", refs: ["Matthew 7:12","Galatians 5:14"] },
  "Matthew 22:41": { title: "Jesus Questions the Pharisees", text: "While the Pharisees are gathered, Jesus asks them a question about the Christ. He moves the discussion from their tests to the identity of the Messiah.", refs: ["Mark 12:35","Luke 20:41"] },
  "Matthew 22:42": { title: "Whose Son Is the Christ?", text: "Jesus asks whose son the Christ is, and they answer that He is David's son. This is correct but incomplete; the next verses ask how David can call the Christ his Lord.", refs: ["2 Samuel 7:12–16","Isaiah 11:1"] },
  "Matthew 22:43": { title: "David Speaks by the Spirit", text: "Jesus says David spoke in the Spirit when he called the Christ Lord. The Messiah is more than a merely human descendant; Scripture reveals His exalted authority.", refs: ["Psalm 110:1","Acts 2:34–36"] },
  "Matthew 22:44": { title: "The Lord Says to My Lord", text: "Jesus quotes the Psalm in which the Lord tells David's Lord to sit at His right hand until His enemies are made His footstool. The verse distinguishes the speakers in the prophetic scene while revealing the Messiah's exaltation; it should be read with the Bible's wider testimony to the one God and the identity of Jesus.", refs: ["Psalm 110:1","Hebrews 1:13","Acts 2:34–36"] },
  "Matthew 22:45": { title: "How Is the Christ David's Son?", text: "Jesus asks how David can call the Christ Lord if the Christ is only his son. The question presses the hearers to recognize the Messiah's greater status and divine authority.", refs: ["Romans 1:3–4","Revelation 22:16"] },
  "Matthew 22:46": { title: "No One Dares Ask Further", text: "No one can answer Jesus, and from that day no one dares ask Him further questions. Their silence shows that His scriptural reasoning has overturned their challenge.", refs: ["Mark 12:34","Luke 20:40"] },

  "Matthew 23:1": { title: "Jesus Speaks to the Multitude", text: "Jesus addresses the multitudes and His disciples concerning the scribes and Pharisees. He distinguishes public religious authority from the need to live faithfully.", refs: ["Mark 12:38","Luke 20:45"] },
  "Matthew 23:2": { title: "Moses' Seat", text: "The scribes and Pharisees sit in Moses' seat, a position associated with teaching the law. Jesus acknowledges the role while exposing the hypocrisy that follows.", refs: ["Deuteronomy 17:9–11","Romans 2:21"] },
  "Matthew 23:3": { title: "Do What They Teach, Not Their Hypocrisy", text: "Jesus tells the people to observe what they teach from Moses' seat but not imitate their works, because they do not practice what they preach. Truth should be obeyed, while hypocrisy must not be copied.", refs: ["Malachi 2:7–8","James 1:22"] },
  "Matthew 23:4": { title: "Heavy Burdens on Others", text: "The leaders bind heavy burdens and lay them on people's shoulders but will not help carry them. Spiritual leadership should assist people in obedience, not burden them for the sake of control.", refs: ["Luke 11:46","Acts 15:10"] },
  "Matthew 23:5": { title: "Works to Be Seen of Men", text: "They perform religious works to be noticed, enlarging their phylacteries and the borders of their garments. The problem is not the objects alone but using visible religion to seek human praise.", refs: ["Numbers 15:38–40","Matthew 6:1"] },
  "Matthew 23:6": { title: "Chief Seats and Uppermost Rooms", text: "They love the chief places at feasts and the best seats in synagogues. Their pursuit of honor reveals a heart centered on status rather than service.", refs: ["Luke 14:7–11","James 2:1–4"] },
  "Matthew 23:7": { title: "Greetings and Titles in the Market", text: "They enjoy respectful greetings and being called Rabbi. Jesus challenges the craving for religious prestige, not the ordinary courtesy of respectful address.", refs: ["Matthew 6:2","3 John 9"] },
  "Matthew 23:8": { title: "One Master, All Brethren", text: "Jesus tells His disciples not to seek status as masters, because they have one Master and are brethren. Spiritual leadership must not erase the shared dependence of believers on Christ.", refs: ["James 3:1","Ephesians 4:5"] },
  "Matthew 23:9": { title: "One Father in Heaven", text: "Jesus warns against claiming ultimate spiritual fatherhood over others, for one is the heavenly Father. The teaching confronts religious pride and ultimate allegiance; it need not be read as forbidding every ordinary familial use of the word father.", refs: ["Malachi 2:10","Ephesians 4:6"] },
  "Matthew 23:10": { title: "One Master, the Christ", text: "Jesus says not to be called masters, because the Christ is the one Master. The community must look to Him as its final authority rather than elevate human teachers into rivals to His rule.", refs: ["Matthew 28:18","Colossians 1:18"] },
  "Matthew 23:11": { title: "The Greatest Shall Be Servant", text: "The greatest among the disciples must be their servant. Kingdom leadership is measured by humble service, following Jesus' own example.", refs: ["Matthew 20:26–28","John 13:14–15"] },
  "Matthew 23:12": { title: "Humility and Exaltation", text: "Whoever exalts himself will be humbled, and whoever humbles himself will be exalted. God opposes pride and honors genuine humility.", refs: ["Proverbs 29:23","James 4:10","1 Peter 5:6"] },
  "Matthew 23:13": { title: "Woe to Those Who Shut the Kingdom", text: "Jesus rebukes the scribes and Pharisees for shutting the kingdom of heaven against people and refusing to enter themselves. Leaders are accountable when their teaching and conduct obstruct others from coming to God.", refs: ["Luke 11:52","Matthew 18:6"] },
  "Matthew 23:14": { title: "A Manuscript Note on This Verse", text: "Some later manuscript traditions include a woe about devouring widows' houses and making long prayers, while many modern editions omit this verse or place it in a note because it is absent from early witnesses. The same charge appears in Mark and Luke.", refs: ["Mark 12:40","Luke 20:47"] },
  "Matthew 23:15": { title: "Making One a Child of Gehenna", text: "Jesus condemns their zeal to make converts when their teaching produces people even more bound to error. Religious growth is not good if it multiplies hypocrisy and spiritual ruin.", refs: ["Acts 20:30","Galatians 4:17"] },
  "Matthew 23:16": { title: "Blind Guides and Oaths", text: "Jesus calls them blind guides because they make distinctions about which oaths are binding based on the temple and its gold. Their rules obscure the holiness of God and the truthfulness He requires.", refs: ["Matthew 5:33–37","James 5:12"] },
  "Matthew 23:17": { title: "The Temple Sanctifies the Gold", text: "Jesus asks which is greater, the gold or the temple that sanctifies it. Their reasoning reverses the proper order by valuing the gift more than the holy purpose of the temple.", refs: ["Exodus 30:29","Matthew 12:6"] },
  "Matthew 23:18": { title: "The Altar and the Gift", text: "They say an oath by the altar is nothing but an oath by the gift on it is binding. Jesus exposes a system that elevates offerings above the altar's sacred significance.", refs: ["Matthew 5:23–24","Matthew 23:19"] },
  "Matthew 23:19": { title: "The Altar Sanctifies the Gift", text: "Jesus again asks which is greater, the gift or the altar that sanctifies it. The altar's role shows that devotion to God cannot be reduced to the value of a material offering.", refs: ["Exodus 29:37","Matthew 23:17"] },
  "Matthew 23:20": { title: "An Oath by the Altar", text: "Jesus explains that swearing by the altar includes swearing by everything on it. He rejects the artificial distinctions by which people try to manipulate the seriousness of their words.", refs: ["Matthew 5:34–37","James 5:12"] },
  "Matthew 23:21": { title: "An Oath by the Temple", text: "Swearing by the temple also invokes the One who dwells there. Sacred language cannot be separated from the God whose presence gives it meaning.", refs: ["1 Kings 8:10–13","2 Chronicles 6:18"] },
  "Matthew 23:22": { title: "An Oath by Heaven", text: "Jesus says that one who swears by heaven swears by God's throne and the One who sits on it. No verbal formula allows a person to escape accountability before God.", refs: ["Isaiah 66:1","Matthew 5:34"] },
  "Matthew 23:23": { title: "Justice, Mercy, and Faith", text: "Jesus rebukes them for tithing small herbs while neglecting weightier matters of the law: judgment, mercy, and faith. He says the latter should be done without neglecting the former, correcting imbalance rather than praising carelessness.", refs: ["Micah 6:8","Luke 11:42"] },
  "Matthew 23:24": { title: "Straining at a Gnat", text: "Jesus uses the image of straining out a gnat while swallowing a camel to expose their distorted priorities. Small ceremonial details cannot compensate for major moral failures.", refs: ["Matthew 23:23","Luke 11:42"] },
  "Matthew 23:25": { title: "Clean Outside, Unclean Within", text: "They clean the outside of the cup and dish while inside they are full of extortion and excess. Outward religious appearance cannot hide greed and self-indulgence.", refs: ["Mark 7:20–23","Luke 11:39"] },
  "Matthew 23:26": { title: "Clean the Inside First", text: "Jesus tells the blind Pharisee to cleanse the inside of the cup so the outside may also be clean. Genuine reform begins with the heart and then shapes outward conduct.", refs: ["Psalm 51:10","Titus 2:11–12"] },
  "Matthew 23:27": { title: "Whited Sepulchres", text: "Jesus compares them to whitewashed tombs that look beautiful outside but contain uncleanness within. The metaphor exposes a religious image that conceals inward corruption.", refs: ["Luke 11:44","Acts 23:3"] },
  "Matthew 23:28": { title: "Righteous Appearance, Lawlessness Within", text: "They appear righteous to people but inwardly are full of hypocrisy and iniquity. God sees beyond public reputation to the true condition of the heart.", refs: ["1 Samuel 16:7","Luke 16:15"] },
  "Matthew 23:29": { title: "Building the Prophets' Tombs", text: "They build tombs for the prophets and decorate the monuments of the righteous. Honoring past messengers can become hollow when people refuse the truth those messengers proclaimed.", refs: ["Luke 11:47","Acts 7:52"] },
  "Matthew 23:30": { title: "Claiming Not to Share Their Fathers' Deeds", text: "They claim they would not have joined their ancestors in killing the prophets. Jesus will show that their present hostility reveals the same spirit despite their words.", refs: ["Matthew 23:31–32","Acts 7:51"] },
  "Matthew 23:31": { title: "Witnesses Against Themselves", text: "By claiming descent from those who killed the prophets, they testify to their connection with that history. Their conduct will reveal whether they have truly rejected their ancestors' sins.", refs: ["Luke 11:48","John 8:39–40"] },
  "Matthew 23:32": { title: "Fill Up the Measure", text: "Jesus tells them to fill up the measure of their fathers. The phrase warns that their persistent rejection will bring the pattern of rebellion to its full consequence.", refs: ["Genesis 15:16","1 Thessalonians 2:15–16"] },
  "Matthew 23:33": { title: "Serpents and Generation of Vipers", text: "Jesus asks how they can escape the judgment of Gehenna. His severe language confronts hardened hypocrisy and the danger of rejecting God's messengers.", refs: ["Matthew 3:7","Matthew 12:34"] },
  "Matthew 23:34": { title: "Prophets, Wise Men, and Scribes Sent", text: "Jesus says He will send prophets, wise men, and scribes, some of whom will be killed, crucified, scourged, and persecuted. God's mission continues, but the response to His messengers reveals the hearers' hearts.", refs: ["Matthew 10:16–23","Luke 11:49"] },
  "Matthew 23:35": { title: "Righteous Blood from Abel to Zacharias", text: "Jesus speaks of the righteous blood shed from Abel to Zacharias. The phrase gathers the story of Scripture's persecuted righteous and warns that accumulated violence will be judged.", refs: ["Genesis 4:8–10","2 Chronicles 24:20–22"] },
  "Matthew 23:36": { title: "These Things Come on This Generation", text: "Jesus declares that the consequences will come upon that generation. The warning concerns the culmination of persistent rejection and the judgment approaching Jerusalem.", refs: ["Matthew 24:34","Luke 19:43–44"] },
  "Matthew 23:37": { title: "Jesus Laments over Jerusalem", text: "Jesus laments that Jerusalem kills the prophets and stones those sent to her, and He describes His desire to gather her children as a hen gathers her chicks. His words reveal divine compassion and the people's unwillingness to receive it.", refs: ["Luke 13:34","Psalm 91:4"] },
  "Matthew 23:38": { title: "Your House Is Left Desolate", text: "Jesus says their house is left desolate. The temple and city face judgment because the people have rejected the visitation and messengers of God.", refs: ["Jeremiah 22:5","Luke 19:41–44"] },
  "Matthew 23:39": { title: "Until You Say, Blessed Is He", text: "Jesus says they will not see Him again until they say, Blessed is He that comes in the Lord's name. The saying points toward a future recognition of the Messiah and echoes the welcome sung at His entry.", refs: ["Psalm 118:26","Matthew 21:9","Romans 11:25–27"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 24:1": { title: "Jesus Leaves the Temple", text: "Jesus departs from the temple, and His disciples point out its buildings. The scene contrasts the impressive structure with the judgment Jesus is about to announce.", refs: ["Mark 13:1","Luke 21:5–6"] },
  "Matthew 24:2": { title: "Not One Stone Left", text: "Jesus declares that the temple buildings will be thrown down so that not one stone will be left upon another. This points to the coming destruction of Jerusalem and its temple.", refs: ["Luke 19:41–44","Luke 21:20–24"] },
  "Matthew 24:3": { title: "The Disciples Ask About the Future", text: "Privately on the Mount of Olives, the disciples ask about the timing of the temple's destruction and the sign of Jesus' coming and the end of the age. Jesus' answer includes warnings about Jerusalem, the coming of the Son of man, and the need for watchfulness.", refs: ["Mark 13:3–4","Luke 21:7"] },
  "Matthew 24:4": { title: "Take Heed That No One Deceives You", text: "Jesus begins with a warning against deception. Discernment is essential because religious claims and reports about the end can mislead believers.", refs: ["2 Thessalonians 2:3","1 John 4:1"] },
  "Matthew 24:5": { title: "Many Claim to Come in His Name", text: "Many will come using Jesus' name and claiming messianic authority, deceiving many. The warning calls believers to test claims rather than accept a title or slogan as proof.", refs: ["Jeremiah 14:14","Matthew 7:22–23"] },
  "Matthew 24:6": { title: "Wars and Rumors of Wars", text: "Jesus says wars and reports of wars will occur, but the disciples must not be troubled; these things must happen, yet the end is not immediately at hand. Calamity should not be used to set dates or produce panic.", refs: ["Mark 13:7","Luke 21:9"] },
  "Matthew 24:7": { title: "Nation Against Nation", text: "Jesus lists conflict, famines, and earthquakes as the beginning of sorrows. These events are real suffering, but they are not by themselves proof that the final moment has arrived.", refs: ["Isaiah 19:2","Luke 21:10–11"] },
  "Matthew 24:8": { title: "The Beginning of Sorrows", text: "Jesus compares these events to the beginning of birth pains. The image indicates distress preceding what is to come, without giving a calendar for the end.", refs: ["Romans 8:22","1 Thessalonians 5:3"] },
  "Matthew 24:9": { title: "Persecution of Disciples", text: "Jesus warns that His followers will be afflicted, killed, and hated by all nations for His name's sake. Faithfulness may bring suffering, and persecution must not be mistaken for proof that Christ has abandoned His people.", refs: ["John 15:18–20","2 Timothy 3:12"] },
  "Matthew 24:10": { title: "Many Will Be Offended", text: "Many will stumble, betray one another, and hate one another. Pressure reveals hearts and can fracture fellowship, so believers must guard against fear and resentment.", refs: ["Matthew 10:21–22","2 Thessalonians 2:3"] },
  "Matthew 24:11": { title: "False Prophets Arise", text: "Many false prophets will rise and deceive many. Jesus repeats the danger of deceptive religious leadership and calls for testing every teaching by truth.", refs: ["Deuteronomy 13:1–3","1 John 4:1"] },
  "Matthew 24:12": { title: "Love Grows Cold", text: "Because lawlessness increases, the love of many grows cold. Persistent evil can harden people, but disciples are called to preserve sincere love and obedience.", refs: ["2 Timothy 3:1–5","Revelation 2:4–5"] },
  "Matthew 24:13": { title: "Endure to the End", text: "The one who endures to the end will be saved. Jesus calls for persevering faith, not a momentary profession that collapses under pressure.", refs: ["Matthew 10:22","Hebrews 3:14"] },
  "Matthew 24:14": { title: "The Gospel Preached to All Nations", text: "The gospel of the kingdom will be preached in all the world as a witness to all nations, and then the end will come. The mission is to proclaim the good news faithfully rather than speculate about dates.", refs: ["Matthew 28:19–20","Acts 1:8"] },
  "Matthew 24:15": { title: "The Abomination of Desolation", text: "Jesus refers to Daniel's prophecy and warns readers to understand it. The phrase has been interpreted in relation to desecration and the crisis surrounding Jerusalem; the immediate instruction is to recognize danger and act without delay.", refs: ["Daniel 9:27","Daniel 11:31","Daniel 12:11"] },
  "Matthew 24:16": { title: "Flee to the Mountains", text: "Those in Judaea are told to flee to the mountains when the sign appears. Jesus gives practical urgency to His warning rather than inviting people to remain in danger for curiosity's sake.", refs: ["Luke 21:21","Mark 13:14"] },
  "Matthew 24:17": { title: "Do Not Return for Possessions", text: "The person on the housetop must not come down to retrieve belongings. The instruction emphasizes immediate flight when the crisis comes.", refs: ["Luke 17:31","Genesis 19:17"] },
  "Matthew 24:18": { title: "Do Not Return from the Field", text: "The worker in the field must not turn back for a garment. Ordinary possessions must not delay escape from the approaching danger.", refs: ["Luke 17:31–32","Genesis 19:26"] },
  "Matthew 24:19": { title: "Woe to the Pregnant and Nursing", text: "Jesus expresses compassion for pregnant women and those nursing infants because fleeing will be especially difficult for them. His warning recognizes the human cost of the coming distress.", refs: ["Luke 21:23","Matthew 2:18"] },
  "Matthew 24:20": { title: "Pray Your Flight Is Not in Winter or Sabbath", text: "Jesus tells them to pray that their flight not occur in winter or on the Sabbath. He acknowledges practical hardships and the constraints that could make escape more difficult.", refs: ["Mark 13:18","Luke 21:23"] },
  "Matthew 24:21": { title: "Great Tribulation", text: "Jesus describes great tribulation unlike anything before it. The words convey the extraordinary severity of the crisis and should be read with the surrounding instructions and prophetic context.", refs: ["Daniel 12:1","Mark 13:19"] },
  "Matthew 24:22": { title: "The Days Are Shortened", text: "Unless those days were shortened, no flesh would be saved, but for the elect's sake they will be shortened. God limits the time of distress and remembers those who belong to Him.", refs: ["Isaiah 65:8–9","Mark 13:20"] },
  "Matthew 24:23": { title: "Do Not Believe False Messiahs", text: "If anyone says the Christ is here or there, Jesus warns not to believe it. His followers must not be carried away by sensational claims.", refs: ["Matthew 24:5","Luke 17:23"] },
  "Matthew 24:24": { title: "Signs and Wonders Can Deceive", text: "False christs and false prophets will show great signs and wonders to deceive, if possible, even the elect. Miraculous appearance alone is not proof of truth; teaching must be tested against God's word.", refs: ["Deuteronomy 13:1–4","2 Thessalonians 2:9–10"] },
  "Matthew 24:25": { title: "Jesus Has Forewarned Them", text: "Jesus tells His disciples that He has warned them beforehand. Forewarning equips believers to remain steady instead of being surprised into credulity or panic.", refs: ["John 14:29","2 Peter 3:17"] },
  "Matthew 24:26": { title: "Do Not Go Out After Secret Claims", text: "If people say Christ is in the desert or in secret chambers, disciples must not believe them. Jesus rejects secret, localized claims that seek to draw people after false messiahs.", refs: ["Luke 17:23–24","Acts 1:11"] },
  "Matthew 24:27": { title: "The Coming Like Lightning", text: "The coming of the Son of man will be like lightning visible from east to west. Jesus contrasts His coming with secret rumors and hidden claims; it will not depend on a private announcement.", refs: ["Luke 17:24","Revelation 1:7"] },
  "Matthew 24:28": { title: "Where the Carcase Is", text: "Jesus uses the picture of vultures gathering around a carcass. The saying suggests that the signs of judgment will be recognizable where the judgment is taking place.", refs: ["Luke 17:37","Job 39:30"] },
  "Matthew 24:29": { title: "Cosmic Signs After the Tribulation", text: "Jesus describes the sun darkened, the moon without light, stars falling, and heavenly powers shaken. Prophetic language portrays a world-shaking intervention and judgment; interpreters differ on how literally and in what sequence these signs occur.", refs: ["Isaiah 13:10","Joel 2:10","Mark 13:24–25"] },
  "Matthew 24:30": { title: "The Sign of the Son of Man", text: "The sign of the Son of man appears, the tribes mourn, and they see Him coming with power and great glory. The coming is public and majestic, bringing both recognition and judgment.", refs: ["Daniel 7:13–14","Revelation 1:7"] },
  "Matthew 24:31": { title: "The Elect Gathered", text: "The Son of man sends His angels with a great trumpet to gather His elect from the four winds. The image promises that God's people will be gathered and not forgotten.", refs: ["Isaiah 27:13","1 Thessalonians 4:16–17"] },
  "Matthew 24:32": { title: "The Lesson of the Fig Tree", text: "As budding branches indicate that summer is near, Jesus says signs teach observers to recognize nearness. The lesson is discernment, not setting a date beyond what He has revealed.", refs: ["Luke 21:29–31","Matthew 16:2–3"] },
  "Matthew 24:33": { title: "When You See These Things", text: "When the described things occur, the disciples are to know that the event is near. Jesus calls for alertness and readiness in response to the signs He has given.", refs: ["Luke 21:31","James 5:8–9"] },
  "Matthew 24:34": { title: "This Generation Shall Not Pass", text: "Jesus declares that this generation will not pass until all these things are fulfilled. Interpreters understand 'this generation' in different ways, including the generation witnessing the events, the people of Israel, or the kind of people Jesus describes; the verse should be handled carefully in its full context.", refs: ["Matthew 23:36","Matthew 24:3"] },
  "Matthew 24:35": { title: "Jesus' Words Will Not Pass Away", text: "Heaven and earth will pass away, but Jesus' words will not pass away. His teaching is more enduring and reliable than the created order.", refs: ["Isaiah 40:8","Matthew 5:18"] },
  "Matthew 24:36": { title: "No One Knows the Day or Hour", text: "No one knows the day and hour, not even the angels, but the Father only. Jesus forbids date-setting and calls His disciples to humility about what has not been revealed.", refs: ["Acts 1:7","1 Thessalonians 5:1–2"] },
  "Matthew 24:37": { title: "As in the Days of Noah", text: "The coming of the Son of man will be like the days of Noah. People carried on ordinary life without taking the warning seriously until judgment arrived.", refs: ["Genesis 6:5–13","Luke 17:26–27"] },
  "Matthew 24:38": { title: "Eating, Drinking, and Marrying", text: "People ate, drank, and married until the day Noah entered the ark. Ordinary activities are not inherently sinful; the danger is living without regard for God's warning and coming judgment.", refs: ["Genesis 7:7–10","Luke 17:27"] },
  "Matthew 24:39": { title: "They Did Not Know Until the Flood", text: "They did not understand until the flood came and took them away. Sudden judgment overtakes those who ignore God's warning, so Jesus calls for readiness.", refs: ["Genesis 7:21–23","Luke 17:28–30"] },
  "Matthew 24:40": { title: "One Taken and One Left", text: "Two men are in the field; one is taken and the other left. The image emphasizes sudden separation and the need to be ready; the precise meaning of 'taken' is debated in light of the Noah comparison.", refs: ["Luke 17:34–36","Genesis 7:23"] },
  "Matthew 24:41": { title: "Two Women Grinding", text: "Two women are grinding at the mill; one is taken and one left. Even people engaged in the same ordinary task may face different outcomes when the Lord acts.", refs: ["Luke 17:35–36","Matthew 24:40"] },
  "Matthew 24:42": { title: "Watch, for You Do Not Know", text: "Jesus commands His disciples to watch because they do not know the hour of His Lord's coming. Readiness, not prediction, is the proper response to uncertainty.", refs: ["Matthew 25:13","1 Peter 4:7"] },
  "Matthew 24:43": { title: "The Householder and the Thief", text: "If a householder knew when a thief would come, he would watch and prevent the break-in. The illustration urges constant readiness because the time is unknown.", refs: ["Luke 12:39–40","1 Thessalonians 5:2"] },
  "Matthew 24:44": { title: "Be Ready", text: "The Son of man comes at an hour people do not expect, so they must be ready. Readiness means faithful living and obedience rather than anxious speculation.", refs: ["Luke 12:40","Titus 2:11–13"] },
  "Matthew 24:45": { title: "The Faithful and Wise Servant", text: "Jesus asks who the faithful and wise servant is, whom the master appoints to give the household food at the proper time. Leaders are accountable to care for those entrusted to them.", refs: ["Luke 12:42","1 Peter 5:2–4"] },
  "Matthew 24:46": { title: "Blessed Is the Faithful Servant", text: "The servant is blessed if the master finds him faithfully doing his work when he returns. The proper way to await Jesus is to remain diligent in one's responsibility.", refs: ["Luke 12:43","1 Corinthians 4:2"] },
  "Matthew 24:47": { title: "Set Over All the Master's Goods", text: "The master rewards the faithful servant by placing him over all his goods. Faithfulness in present service prepares for greater responsibility in the kingdom.", refs: ["Luke 19:17","Matthew 25:21"] },
  "Matthew 24:48": { title: "The Evil Servant Delays", text: "The evil servant says his master delays his coming. When expectation weakens, he reveals his character by mistreating others and living without restraint.", refs: ["2 Peter 3:3–4","Luke 12:45"] },
  "Matthew 24:49": { title: "Abusing Fellow Servants", text: "The servant begins to beat fellow servants and indulge with the drunken. Claiming that the master is delayed becomes an excuse for cruelty and self-indulgence.", refs: ["Ezekiel 34:2–4","Galatians 5:19–21"] },
  "Matthew 24:50": { title: "The Master Comes Unexpectedly", text: "The master arrives on a day and at an hour the servant does not expect. Delay does not mean absence, and accountability may come suddenly.", refs: ["Luke 12:46","1 Thessalonians 5:3"] },
  "Matthew 24:51": { title: "Judgment for the Hypocritical Servant", text: "The master cuts the servant asunder and assigns him a place with the hypocrites, where there is weeping and gnashing of teeth. Jesus closes with a grave warning that professed service without faithfulness faces judgment.", refs: ["Matthew 25:30","Luke 12:46"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 25:1": { title: "The Ten Virgins", text: "Jesus compares the kingdom of heaven to ten virgins who take their lamps and go to meet the bridegroom. The parable emphasizes readiness for the bridegroom's arrival.", refs: ["Matthew 24:42–44","Revelation 19:7–9"] },
  "Matthew 25:2": { title: "Five Wise and Five Foolish", text: "Five virgins are wise and five are foolish. The distinction is not outward appearance but the preparation that will matter when the bridegroom is delayed.", refs: ["Proverbs  wise","Matthew 7:24–27"] },
  "Matthew 25:3": { title: "The Foolish Take No Extra Oil", text: "The foolish virgins take lamps but no extra oil. They have the appearance of readiness without making adequate provision for the wait.", refs: ["Luke 12:35","Matthew 13:20–21"] },
  "Matthew 25:4": { title: "The Wise Bring Oil", text: "The wise virgins bring oil in their vessels along with their lamps. Their foresight shows readiness that can endure delay.", refs: ["Proverbs 6:6–8","Matthew 24:45–46"] },
  "Matthew 25:5": { title: "The Bridegroom Delays", text: "Because the bridegroom delays, all the virgins become drowsy and sleep. The key difference is not that some grow tired, but that some are prepared when the moment arrives.", refs: ["Matthew 24:48–50","2 Peter 3:9"] },
  "Matthew 25:6": { title: "A Cry at Midnight", text: "At midnight a cry announces that the bridegroom is coming and calls the virgins to go meet him. His arrival comes at an unexpected hour.", refs: ["Matthew 24:44","1 Thessalonians 5:2"] },
  "Matthew 25:7": { title: "They Trim Their Lamps", text: "All the virgins arise and trim their lamps. The arrival forces a moment of decision, revealing whether their preparation is sufficient.", refs: ["Luke 12:35","Matthew 25:8"] },
  "Matthew 25:8": { title: "The Foolish Ask for Oil", text: "The foolish virgins discover that their lamps are going out and ask the wise for oil. Some forms of readiness cannot simply be borrowed at the last moment from another person.", refs: ["Ezekiel 14:14","Romans 14:12"] },
  "Matthew 25:9": { title: "Go to Those Who Sell Oil", text: "The wise refuse to divide their oil lest all lack enough, and direct the others to buy for themselves. The parable is not teaching selfishness in ordinary charity; it shows that personal readiness before God cannot be transferred.", refs: ["Galatians 6:5","Romans 2:6"] },
  "Matthew 25:10": { title: "The Door Is Shut", text: "While the foolish go to buy oil, the bridegroom arrives, the ready enter the marriage, and the door is shut. The warning is that the opportunity to prepare will not remain open indefinitely.", refs: ["Luke 13:25","Matthew 7:21–23"] },
  "Matthew 25:11": { title: "Lord, Lord, Open to Us", text: "The other virgins arrive later and plead for the door to be opened. Their urgent appeal comes after the time of preparation has passed.", refs: ["Matthew 7:21","Luke 13:25"] },
  "Matthew 25:12": { title: "I Know You Not", text: "The bridegroom answers that he does not know them. Mere association with the wedding party does not replace true readiness and relationship.", refs: ["Matthew 7:23","John 10:14"] },
  "Matthew 25:13": { title: "Watch, for You Know Not the Day", text: "Jesus applies the parable by commanding His disciples to watch because they do not know the day or hour. The intended response is steady readiness, not date-setting.", refs: ["Matthew 24:42","1 Thessalonians 5:6"] },
  "Matthew 25:14": { title: "The Parable of the Talents", text: "Jesus compares the kingdom to a man who travels and entrusts his goods to servants. Each servant receives a responsibility to manage faithfully during the master's absence.", refs: ["Luke 19:12–13","1 Corinthians 4:2"] },
  "Matthew 25:15": { title: "According to Each Ability", text: "The master gives different amounts to each servant according to ability and then departs. God does not give every person identical responsibilities, but each is accountable for what is entrusted.", refs: ["Romans 12:6","1 Peter 4:10"] },
  "Matthew 25:16": { title: "The First Servant Trades", text: "The servant given five talents immediately puts them to work and gains five more. Faithfulness is active and productive, using what has been entrusted rather than leaving it unused.", refs: ["Proverbs 10:4","Colossians 3:23"] },
  "Matthew 25:17": { title: "The Second Servant Gains Two", text: "The servant with two talents also gains two more. His faithfulness is equal in principle to the first servant's even though the amount differs.", refs: ["Luke 16:10","Romans 12:6"] },
  "Matthew 25:18": { title: "The Third Servant Hides the Talent", text: "The servant with one talent digs in the earth and hides his master's money. Fear and passivity cause him to neglect the responsibility entrusted to him.", refs: ["Proverbs 26:13–16","James 4:17"] },
  "Matthew 25:19": { title: "The Master Returns to Settle Accounts", text: "After a long time the master returns and settles accounts with the servants. The delay does not cancel accountability; every servant must answer for his stewardship.", refs: ["Romans 14:12","2 Corinthians 5:10"] },
  "Matthew 25:20": { title: "Five Talents Gained", text: "The first servant presents the original five talents and five more, acknowledging that the master entrusted the resources to him. His report demonstrates productive faithfulness.", refs: ["Matthew 25:16","Luke 19:16"] },
  "Matthew 25:21": { title: "Well Done, Good and Faithful Servant", text: "The master commends the servant as good and faithful, promotes him over more, and invites him into his master's joy. Faithfulness in limited responsibility is honored by God.", refs: ["Luke 16:10","1 Corinthians 4:5"] },
  "Matthew 25:22": { title: "The Two-Talent Servant Reports", text: "The servant given two talents reports that he has gained two more. He presents his work honestly and receives the same commendation as the servant with five.", refs: ["Matthew 25:17","Luke 19:18"] },
  "Matthew 25:23": { title: "The Same Commendation", text: "The master gives the two-talent servant the same words of praise and invites him into the master's joy. God's approval is not measured by comparing the size of people's assignments.", refs: ["Matthew 20:12–16","Galatians 6:4"] },
  "Matthew 25:24": { title: "The Servant's Accusation", text: "The one-talent servant describes the master as a hard man who reaps where he has not sown. His words reveal a distorted view of the master and prepare to expose his excuse.", refs: ["Luke 19:20–21","Proverbs 26:13"] },
  "Matthew 25:25": { title: "Fear Leads to Hiding", text: "The servant says he was afraid and hid the talent in the earth. Fear becomes his excuse for doing nothing with what he was given.", refs: ["2 Timothy 1:7","James 1:22"] },
  "Matthew 25:26": { title: "The Master Calls Him Wicked and Slothful", text: "The master calls the servant wicked and lazy. Even on the servant's own stated view, he should have acted responsibly rather than burying the money.", refs: ["Luke 19:22–23","Proverbs 18:9"] },
  "Matthew 25:27": { title: "At Least Deposit the Money", text: "The master says the servant could have placed the money with bankers so it would earn interest. The rebuke shows that the servant's inaction was not unavoidable.", refs: ["Luke 19:23","Ecclesiastes 11:1–2"] },
  "Matthew 25:28": { title: "The Talent Is Taken Away", text: "The master orders the talent taken from the unfaithful servant and given to the one with ten. Entrusted opportunity is not meant to be wasted.", refs: ["Luke 19:24","Matthew 13:12"] },
  "Matthew 25:29": { title: "More Given to the Faithful", text: "Jesus states that the one who has will receive more, while from the one who has not, even what he has will be taken away. Faithful use of God's gifts leads to greater responsibility, while neglect brings loss.", refs: ["Matthew 13:12","Luke 8:18"] },
  "Matthew 25:30": { title: "Outer Darkness", text: "The unprofitable servant is cast into outer darkness, where there is weeping and gnashing of teeth. The severe conclusion warns that empty profession without faithful obedience is dangerous.", refs: ["Matthew 8:12","Matthew 24:51"] },
  "Matthew 25:31": { title: "The Son of Man Comes in Glory", text: "The Son of man comes in His glory with all the holy angels and sits on His glorious throne. Jesus presents Himself as the appointed judge of the nations.", refs: ["Daniel 7:13–14","John 5:22–27"] },
  "Matthew 25:32": { title: "All Nations Gathered", text: "All nations are gathered before Him, and He separates them as a shepherd separates sheep from goats. No nation or person stands outside His authority to judge.", refs: ["Joel 3:2","Ezekiel 34:17"] },
  "Matthew 25:33": { title: "Sheep on the Right, Goats on the Left", text: "The sheep are placed at the right hand and the goats at the left. The separation symbolizes the difference between those who belong to the King and those who do not.", refs: ["Psalm 110:1","Matthew 13:49"] },
  "Matthew 25:34": { title: "Come, Blessed of My Father", text: "The King invites those at His right hand to inherit the kingdom prepared for them from the foundation of the world. Their inheritance is God's gracious purpose, not a reward they can boastfully claim apart from Him.", refs: ["Ephesians 1:4","1 Peter 1:4"] },
  "Matthew 25:35": { title: "Food, Drink, and Welcome", text: "The King recounts that they fed Him when hungry, gave Him drink when thirsty, and welcomed Him as a stranger. Practical mercy toward people in need is treated as service rendered to the King.", refs: ["Isaiah 58:7","Hebrews 13:2"] },
  "Matthew 25:36": { title: "Clothing, Care, and Visiting", text: "The King continues by naming care for the naked, sick, and imprisoned. Genuine faith expresses itself through compassionate action toward people who are vulnerable.", refs: ["James 2:15–17","Hebrews 13:3"] },
  "Matthew 25:37": { title: "The Righteous Ask When", text: "The righteous ask when they saw the King hungry, thirsty, or in need. They have not been performing acts of mercy merely to earn public praise or to calculate a reward.", refs: ["Matthew 6:1–4","Luke 14:13–14"] },
  "Matthew 25:38": { title: "When Did We See You a Stranger?", text: "They ask when they saw Him as a stranger or naked and cared for Him. Their question shows that their service was not based on recognizing the recipient as the King in disguise.", refs: ["Hebrews 13:2","Proverbs 19:17"] },
  "Matthew 25:39": { title: "When Did We Visit You?", text: "They ask when they saw the King sick or in prison and came to Him. The repeated question emphasizes that small acts of care have kingdom significance.", refs: ["Matthew 10:42","Hebrews 13:3"] },
  "Matthew 25:40": { title: "Done to the Least of These", text: "The King says that what they did to one of the least of His brethren, they did to Him. Jesus identifies Himself with those who belong to Him and are vulnerable; the verse calls for serious, practical care.", refs: ["Proverbs 19:17","Matthew 10:40–42"] },
  "Matthew 25:41": { title: "Depart into Everlasting Fire", text: "The King tells those on the left to depart into everlasting fire prepared for the devil and his angels. The warning portrays final judgment as real and grave.", refs: ["Revelation 20:10–15","Jude 7"] },
  "Matthew 25:42": { title: "They Did Not Feed the Hungry", text: "The condemned are judged for failing to feed the hungry and give drink to the thirsty. Their neglect reveals a lack of merciful love, not merely an isolated omission.", refs: ["James 2:15–16","1 John 3:17"] },
  "Matthew 25:43": { title: "They Did Not Welcome or Clothe", text: "The King names their failure to welcome the stranger, clothe the naked, and visit the sick and imprisoned. Indifference toward suffering is incompatible with the mercy God commands.", refs: ["Isaiah 58:6–7","Hebrews 13:2–3"] },
  "Matthew 25:44": { title: "When Did We Fail to Serve You?", text: "The condemned ask when they saw the King in need and did not minister to Him. Their question cannot excuse their neglect; the King has already identified the people whose needs they ignored.", refs: ["Matthew 25:40","Luke 10:29–37"] },
  "Matthew 25:45": { title: "Not Done to the Least", text: "The King answers that what they failed to do for one of the least, they failed to do for Him. The passage warns against separating devotion to Jesus from responsibility toward those He identifies with.", refs: ["1 John 4:20","James 1:27"] },
  "Matthew 25:46": { title: "Everlasting Punishment and Eternal Life", text: "Jesus concludes that the wicked go into everlasting punishment, while the righteous enter eternal life. The verse presents both outcomes as serious and enduring, urging hearers to live in faithful obedience to God.", refs: ["Daniel 12:2","John 5:28–29","Romans 2:6–8"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 26:1": { title: "Jesus Finishes His Teaching", text: "Jesus finishes these sayings and prepares the disciples for the events ahead. His teaching about judgment leads directly into the account of His own suffering.", refs: ["Matthew 24:1–3","Matthew 26:2"] },
  "Matthew 26:2": { title: "The Passover and the Cross", text: "Jesus tells the disciples that the Passover is two days away and that the Son of man will be delivered up to be crucified. He knowingly moves toward His death as part of His saving mission.", refs: ["Exodus 12:1–14","Matthew 20:18–19"] },
  "Matthew 26:3": { title: "The Leaders Gather", text: "The chief priests and elders gather in the palace of the high priest Caiaphas. The leaders' planning stands in contrast to Jesus' willing obedience to the Father's purpose.", refs: ["Psalm 2:1–2","John 11:47–53"] },
  "Matthew 26:4": { title: "They Plot to Take Jesus", text: "They consult together to take Jesus by subtlety and kill Him. Their use of secrecy reveals that they know their plan cannot withstand honest public scrutiny.", refs: ["Matthew 21:46","Mark 14:1"] },
  "Matthew 26:5": { title: "Not During the Feast", text: "They decide not to act during the feast lest there be an uproar among the people. Their concern is political risk rather than justice.", refs: ["Luke 22:2","Matthew 27:24"] },
  "Matthew 26:6": { title: "Jesus in Bethany", text: "Jesus is in Bethany at the house of Simon the leper. The scene provides the setting for an act of devotion shortly before His death.", refs: ["Mark 14:3","John 12:1–3"] },
  "Matthew 26:7": { title: "A Woman Anoints Jesus", text: "A woman brings an alabaster box of very precious ointment and pours it on Jesus' head as He sits at meat. Her costly act expresses honor and devotion to Him.", refs: ["Mark 14:3","John 12:3"] },
  "Matthew 26:8": { title: "The Disciples Object", text: "The disciples are indignant and call the act wasteful. They judge the gift by its financial value without understanding its significance in the moment.", refs: ["John 12:4–6","Mark 14:4"] },
  "Matthew 26:9": { title: "The Ointment Could Have Been Sold", text: "They say the ointment could have been sold for much and given to the poor. Care for the poor is important, but their objection misses the honor being shown to Jesus.", refs: ["Deuteronomy 15:7–11","John 12:5"] },
  "Matthew 26:10": { title: "Jesus Defends the Woman", text: "Jesus knows their complaint and asks why they trouble the woman, for she has done a good work to Him. He recognizes the meaning of her devotion when others do not.", refs: ["Mark 14:6","Luke 7:44–47"] },
  "Matthew 26:11": { title: "The Poor Are Always Present", text: "Jesus says the poor are always present, but He will not always be physically present with them in the same way. His words do not cancel care for the poor; they highlight the unique moment before His death.", refs: ["Deuteronomy 15:11","John 12:8"] },
  "Matthew 26:12": { title: "Prepared for Burial", text: "Jesus says the woman poured the ointment on His body in preparation for burial. Her act becomes a fitting expression of honor in view of His approaching death.", refs: ["Mark 14:8","John 19:39–40"] },
  "Matthew 26:13": { title: "Her Deed Remembered", text: "Jesus says her act will be told wherever the gospel is preached. Her devotion is permanently remembered because it honored Him at a decisive moment.", refs: ["Mark 14:9","Hebrews 6:10"] },
  "Matthew 26:14": { title: "Judas Goes to the Chief Priests", text: "Judas Iscariot goes to the chief priests to arrange Jesus' betrayal. A disciple who had been close to Jesus chooses money and treachery instead of loyalty.", refs: ["Luke 22:3–6","John 13:2"] },
  "Matthew 26:15": { title: "Thirty Pieces of Silver", text: "Judas asks what they will give him to deliver Jesus, and they pay thirty pieces of silver. The price recalls the prophetic imagery of a rejected shepherd and exposes the shameful valuation of Jesus.", refs: ["Zechariah 11:12–13","Exodus 21:32"] },
  "Matthew 26:16": { title: "Judas Looks for an Opportunity", text: "From that time Judas seeks an opportunity to betray Jesus. Sinful intention becomes an active plan when he begins arranging the circumstances.", refs: ["Luke 22:6","John 13:27"] },
  "Matthew 26:17": { title: "Preparing the Passover", text: "The disciples ask where Jesus wants them to prepare the Passover meal. The feast recalls God's deliverance of Israel and frames the meaning of Jesus' coming death.", refs: ["Exodus 12:14","Mark 14:12"] },
  "Matthew 26:18": { title: "The Master Says His Time Is at Hand", text: "Jesus directs the disciples to a certain man and says His time is at hand. Even as events unfold through human choices, Jesus understands that the appointed hour of His mission has arrived.", refs: ["John 13:1","John 17:1"] },
  "Matthew 26:19": { title: "The Disciples Prepare the Meal", text: "The disciples do as Jesus directs and prepare the Passover. Their obedience provides the setting for Jesus' final meal with them before the crucifixion.", refs: ["Luke 22:13","Exodus 12:21–28"] },
  "Matthew 26:20": { title: "Jesus Sits with the Twelve", text: "At evening Jesus sits down with the twelve disciples. The meal is intimate, but betrayal is already present among those gathered.", refs: ["Mark 14:17","John 13:21"] },
  "Matthew 26:21": { title: "One Will Betray Him", text: "As they eat, Jesus says that one of them will betray Him. His knowledge of the coming betrayal does not mean Judas is forced against his will; the account holds together foreknowledge and human responsibility.", refs: ["Psalm 41:9","John 13:18–21"] },
  "Matthew 26:22": { title: "The Disciples Are Sorrowful", text: "Each disciple begins to ask whether he is the one, showing sorrow and uncertainty. The moment calls for self-examination rather than quick confidence in one's own loyalty.", refs: ["1 Corinthians 10:12","2 Corinthians 13:5"] },
  "Matthew 26:23": { title: "The One Who Dips with Jesus", text: "Jesus identifies the betrayer as one who dips his hand with Him in the dish. The shared meal makes the betrayal especially grievous, echoing the pain of betrayal by a close companion.", refs: ["Psalm 41:9","John 13:26"] },
  "Matthew 26:24": { title: "Woe to the Betrayer", text: "The Son of man goes as Scripture has written, yet woe to the man who betrays Him. God's purpose is not an excuse for Judas' wicked choice; the warning affirms his accountability.", refs: ["Acts 2:23","Luke 22:22"] },
  "Matthew 26:25": { title: "Judas Asks, Is It I?", text: "Judas addresses Jesus as Rabbi and asks if he is the betrayer; Jesus answers, 'Thou hast said.' The exchange shows that outward religious language can conceal a divided heart.", refs: ["Matthew 7:21","John 13:27"] },
  "Matthew 26:26": { title: "The Bread and Jesus' Body", text: "Jesus takes bread, blesses and breaks it, gives it to the disciples, and says, 'Take, eat; this is my body.' The bread signifies His body given for them and establishes the memorial meal centered on His sacrifice.", refs: ["Luke 22:19","1 Corinthians 11:23–24"] },
  "Matthew 26:27": { title: "The Cup of Thanksgiving", text: "Jesus takes the cup, gives thanks, and gives it to them to drink. The shared cup prepares for His explanation of the covenant significance of His blood.", refs: ["Mark 14:23","1 Corinthians 10:16"] },
  "Matthew 26:28": { title: "Blood of the New Covenant", text: "Jesus calls the cup His blood of the new covenant, shed for many for the remission of sins. His sacrificial death brings forgiveness and fulfills the covenant promises; God is reconciling the world to Himself through Christ.", refs: ["Jeremiah 31:31–34","Hebrews 9:14–22","2 Corinthians 5:19"] },
  "Matthew 26:29": { title: "Until the Kingdom Comes", text: "Jesus says He will not drink the fruit of the vine again until He drinks it new in His Father's kingdom. The meal points beyond the cross to the coming completion of God's kingdom.", refs: ["Isaiah 25:6","Revelation 19:9"] },
  "Matthew 26:30": { title: "They Sing a Hymn", text: "After singing a hymn, they go to the Mount of Olives. Worship accompanies Jesus as He moves toward the garden and the cross.", refs: ["Psalm 113–118","Mark 14:26"] },
  "Matthew 26:31": { title: "The Disciples Will Be Scattered", text: "Jesus tells them that all will be offended because of Him that night, quoting the prophecy about the shepherd being struck and the sheep scattered. Their coming failure is foreseen, but not the end of their story.", refs: ["Zechariah 13:7","Mark 14:27"] },
  "Matthew 26:32": { title: "Jesus Will Rise and Go Before Them", text: "Jesus says that after He is risen, He will go before them into Galilee. The prediction of resurrection gives hope beyond their scattering and His death.", refs: ["Matthew 28:7","Mark 16:7"] },
  "Matthew 26:33": { title: "Peter Claims Stronger Loyalty", text: "Peter declares that even if all others are offended, he will never be offended. His confidence exceeds his self-knowledge and prepares for the test to come.", refs: ["Proverbs 16:18","Mark 14:29"] },
  "Matthew 26:34": { title: "Peter's Denial Foretold", text: "Jesus tells Peter that before the cock crows, he will deny Him three times. The warning shows Jesus' foreknowledge and Peter's need for humility.", refs: ["Luke 22:34","John 13:38"] },
  "Matthew 26:35": { title: "Peter Insists He Will Not Deny", text: "Peter insists that he would die with Jesus rather than deny Him, and the other disciples say likewise. Sincere resolve alone cannot sustain faithfulness without watchfulness and dependence on God.", refs: ["Matthew 26:41","1 Corinthians 10:12"] },
  "Matthew 26:36": { title: "Gethsemane", text: "Jesus comes with His disciples to Gethsemane and tells them to sit while He goes to pray. The garden becomes the place where His anguish and submission are openly revealed.", refs: ["Mark 14:32","Luke 22:39–40"] },
  "Matthew 26:37": { title: "Jesus Is Sorrowful", text: "Jesus takes Peter and the two sons of Zebedee and begins to be sorrowful and deeply distressed. His human anguish is real, not an illusion, as He faces the suffering of the cross.", refs: ["Isaiah 53:3","Hebrews 5:7"] },
  "Matthew 26:38": { title: "My Soul Is Exceeding Sorrowful", text: "Jesus tells the three that His soul is exceedingly sorrowful, even unto death, and asks them to watch with Him. The verse reveals the depth of His human suffering before His arrest.", refs: ["Psalm 42:5","Mark 14:34"] },
  "Matthew 26:39": { title: "Not My Will, but Thine", text: "Jesus falls on His face and prays that the cup might pass from Him, yet submits to the Father's will. His prayer reveals genuine human will and obedience; in Oneness understanding, this is the incarnate Son's real human experience, not proof of two divine beings.", refs: ["Luke 22:42","John 6:38","Hebrews 5:7–8"] },
  "Matthew 26:40": { title: "The Disciples Sleep", text: "Jesus finds the disciples sleeping and asks Peter whether they could not watch with Him one hour. Their weakness contrasts with Jesus' steadfast prayer.", refs: ["Mark 14:37","Matthew 26:41"] },
  "Matthew 26:41": { title: "Watch and Pray", text: "Jesus commands them to watch and pray lest they enter into temptation; the spirit is willing, but the flesh is weak. Prayerful dependence is necessary when sincere intentions meet human frailty.", refs: ["Luke 22:40","Galatians 5:16–17"] },
  "Matthew 26:42": { title: "Thy Will Be Done", text: "Jesus prays again that if the cup cannot pass unless He drink it, the Father's will be done. His submission is deliberate obedience in the face of suffering.", refs: ["Matthew 6:10","John 18:11"] },
  "Matthew 26:43": { title: "They Sleep Again", text: "Jesus returns and finds the disciples asleep because their eyes are heavy. Their weakness remains even after His warning, illustrating the need for sustained watchfulness.", refs: ["Mark 14:40","Luke 22:45"] },
  "Matthew 26:44": { title: "Jesus Prays a Third Time", text: "Jesus leaves them and prays the third time, saying the same words. Repeated prayer expresses earnest persistence and full submission to God's purpose.", refs: ["2 Corinthians 12:8–9","Luke 18:1"] },
  "Matthew 26:45": { title: "The Hour Has Come", text: "Jesus tells the disciples to sleep on and take their rest, then announces that the hour is at hand and the Son of man is betrayed into sinners' hands. The moment of arrest has arrived.", refs: ["John 12:23","Matthew 20:18"] },
  "Matthew 26:46": { title: "Rise, Let Us Be Going", text: "Jesus tells them to rise because the betrayer is near. He does not flee the appointed hour but meets it with resolve.", refs: ["John 18:4","Mark 14:42"] },
  "Matthew 26:47": { title: "Judas Arrives with a Multitude", text: "Judas comes with a large armed crowd sent by the chief priests and elders. The betrayal is carried out through a coordinated arrest party.", refs: ["John 18:3","Acts 1:16"] },
  "Matthew 26:48": { title: "The Betrayal Sign", text: "Judas has arranged a sign: the one he kisses is Jesus. He uses a sign of affection to identify the one he is betraying.", refs: ["Psalm 55:12–14","Luke 22:47–48"] },
  "Matthew 26:49": { title: "Judas Kisses Jesus", text: "Judas comes straight to Jesus, greets Him as Rabbi, and kisses Him. The contrast between the greeting and the betrayal reveals the hypocrisy of the act.", refs: ["Luke 22:48","Proverbs 27:6"] },
  "Matthew 26:50": { title: "Friend, Wherefore Art Thou Come?", text: "Jesus addresses Judas and allows the arrest to proceed. His calm response shows that He is not surprised and remains in control of His mission.", refs: ["John 18:4–8","Luke 22:48"] },
  "Matthew 26:51": { title: "A Disciple Draws a Sword", text: "One of Jesus' companions draws a sword and strikes the servant of the high priest, cutting off his ear. The disciple attempts to resist by force, but Jesus will reject that path.", refs: ["John 18:10","Luke 22:49–50"] },
  "Matthew 26:52": { title: "Put Up Your Sword", text: "Jesus commands the disciple to put away the sword, warning that those who take the sword will perish by the sword. The kingdom is not advanced by violent retaliation.", refs: ["Genesis 9:6","Romans 12:19","John 18:36"] },
  "Matthew 26:53": { title: "Legions of Angels", text: "Jesus says He could appeal to the Father, who would send more than twelve legions of angels. His submission is voluntary; He is not helpless before the arresting crowd.", refs: ["2 Kings 6:17","Daniel 7:10"] },
  "Matthew 26:54": { title: "The Scriptures Must Be Fulfilled", text: "Jesus asks how the Scriptures would be fulfilled if He resisted. His suffering unfolds in accordance with God's revealed purpose, not because the captors have defeated His authority.", refs: ["Isaiah 53:7–12","Luke 24:44–46"] },
  "Matthew 26:55": { title: "Arrested as a Thief", text: "Jesus asks why they come with swords and staves as though He were a robber, when He had taught openly in the temple. Their secretive arrest contrasts with His public ministry.", refs: ["Luke 22:52–53","John 18:20"] },
  "Matthew 26:56": { title: "The Disciples Flee", text: "All this happens so the Scriptures of the prophets might be fulfilled, and the disciples forsake Jesus and flee. Their failure is real, but God's purpose continues through the events.", refs: ["Zechariah 13:7","Mark 14:50"] },
  "Matthew 26:57": { title: "Jesus Brought to Caiaphas", text: "Those who arrest Jesus bring Him to Caiaphas the high priest, where scribes and elders are assembled. The hearing begins within the leadership that has already plotted His death.", refs: ["Mark 14:53","John 18:24"] },
  "Matthew 26:58": { title: "Peter Follows Afar Off", text: "Peter follows at a distance to the high priest's palace and sits among the servants to see the outcome. His distance foreshadows the fear that will lead to denial.", refs: ["Luke 22:54","Matthew 26:69"] },
  "Matthew 26:59": { title: "False Witnesses Sought", text: "The chief priests and council seek false witness against Jesus in order to put Him to death. The proceedings aim at a verdict already desired rather than impartial justice.", refs: ["Psalm 27:12","Mark 14:55"] },
  "Matthew 26:60": { title: "False Witnesses Do Not Agree", text: "Many false witnesses come, but their testimony does not agree. Their inability to produce consistent evidence exposes the injustice of the proceeding.", refs: ["Deuteronomy 19:15","Mark 14:56"] },
  "Matthew 26:61": { title: "A Saying About the Temple", text: "Some witnesses claim Jesus said He could destroy God's temple and build it in three days. They distort His words, which elsewhere refer to His body and resurrection.", refs: ["John 2:19–21","Mark 14:58"] },
  "Matthew 26:62": { title: "The High Priest Demands an Answer", text: "The high priest rises and asks Jesus whether He has an answer to the accusations. Jesus' silence fulfills the picture of the suffering servant who does not defend Himself through deceit.", refs: ["Isaiah 53:7","Mark 14:60"] },
  "Matthew 26:63": { title: "Jesus Is Put Under Oath", text: "The high priest adjures Jesus by the living God to say whether He is the Christ, the Son of God. Jesus' identity is now placed directly before the council.", refs: ["Leviticus 5:1","Mark 14:61"] },
  "Matthew 26:64": { title: "The Son of Man at God's Right Hand", text: "Jesus answers that they will see the Son of man sitting at the right hand of power and coming in the clouds of heaven. He combines Psalm 110 and Daniel 7 to declare His coming vindication and authority.", refs: ["Psalm 110:1","Daniel 7:13–14","Acts 2:34–36"] },
  "Matthew 26:65": { title: "The High Priest Tears His Clothes", text: "The high priest tears his clothes and accuses Jesus of blasphemy. The reaction shows that the council interprets Jesus' claim as an intolerable assertion of authority.", refs: ["Mark 14:63–64","John 10:33–36"] },
  "Matthew 26:66": { title: "They Declare Him Guilty", text: "The council declares Jesus guilty of death. The verdict is unjust, and the Gospel's narrative makes clear that human judgment does not determine His true identity.", refs: ["Acts 3:13–15","Isaiah 53:8"] },
  "Matthew 26:67": { title: "Jesus Is Struck and Spat Upon", text: "They spit in Jesus' face, strike Him, and buffet Him. The suffering servant endures shame and violence from those who reject Him.", refs: ["Isaiah 50:6","Mark 14:65"] },
  "Matthew 26:68": { title: "Prophesy, Christ", text: "They mock Jesus by telling Him to prophesy who struck Him. Their taunt ridicules His prophetic authority while fulfilling the pattern of abuse against God's righteous servant.", refs: ["Luke 22:64","Isaiah 53:3"] },
  "Matthew 26:69": { title: "Peter Is Accused", text: "Peter sits outside in the palace, and a servant girl says he was with Jesus of Galilee. The test comes in an ordinary conversation, not a formal trial.", refs: ["Mark 14:66–67","Luke 22:56"] },
  "Matthew 26:70": { title: "Peter Denies Jesus", text: "Peter denies before them all that he knows what she is saying. Fear makes him contradict his earlier bold promise.", refs: ["Matthew 26:34–35","Luke 22:57"] },
  "Matthew 26:71": { title: "Another Accusation", text: "Peter moves toward the porch, where another servant girl identifies him as one who was with Jesus of Nazareth. His association with Jesus becomes increasingly difficult to conceal.", refs: ["Mark 14:69","John 18:25"] },
  "Matthew 26:72": { title: "Peter Denies with an Oath", text: "Peter denies again, this time with an oath, saying he does not know the man. His words intensify the denial and show how fear can lead to deeper falsehood.", refs: ["Luke 22:58","Mark 14:70"] },
  "Matthew 26:73": { title: "The Bystanders Recognize Peter's Speech", text: "Those standing nearby say Peter's speech betrays him as one of Jesus' followers. The evidence they notice makes his denial more difficult to maintain.", refs: ["Mark 14:70","Acts 2:7"] },
  "Matthew 26:74": { title: "Peter Curses and Denies", text: "Peter begins to curse and swear that he does not know Jesus, and immediately the cock crows. His denial reaches its most painful point, just as Jesus had foretold.", refs: ["Matthew 26:34","Luke 22:60"] },
  "Matthew 26:75": { title: "Peter Remembers and Weeps", text: "Peter remembers Jesus' words and goes out to weep bitterly. His grief shows the collapse of self-confidence and opens the way for repentance and restoration.", refs: ["Luke 22:61–62","John 21:15–19"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 25:2": { title: "Five Wise and Five Foolish", text: "Five virgins are wise and five are foolish. The distinction is not outward appearance but the preparation that will matter when the bridegroom is delayed.", refs: ["Proverbs 6:6–8","Matthew 7:24–27"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 27:1": { title: "The Council Decides to Put Jesus to Death", text: "At morning, the chief priests and elders consult together against Jesus and decide that He should be put to death. Their verdict is driven by hostility, not a fair examination of His life and teaching.", refs: ["Psalm 2:1–2","Mark 15:1"] },
  "Matthew 27:2": { title: "Jesus Is Delivered to Pilate", text: "They bind Jesus, lead Him away, and deliver Him to Pontius Pilate the governor. Since Roman authority controlled crucifixion, the leaders bring Him before the governing power.", refs: ["John 18:28–32","Luke 23:1"] },
  "Matthew 27:3": { title: "Judas Regrets His Betrayal", text: "Judas sees that Jesus is condemned and is seized with remorse, returning the thirty pieces of silver. His regret acknowledges the terrible outcome of his betrayal.", refs: ["Matthew 26:14–16","Zechariah 11:12–13"] },
  "Matthew 27:4": { title: "I Have Betrayed Innocent Blood", text: "Judas confesses that he has betrayed innocent blood, but the priests and elders refuse responsibility for his guilt. His confession is true, yet remorse alone is not the same as turning to God for restoration.", refs: ["Deuteronomy 27:25","Matthew 27:24"] },
  "Matthew 27:5": { title: "Judas Dies", text: "Judas throws the silver into the temple, departs, and hangs himself. The account records the tragic end of his betrayal; Acts 1 gives a related description of his death and the aftermath.", refs: ["Acts 1:18–19","2 Corinthians 7:10"] },
  "Matthew 27:6": { title: "The Blood Money", text: "The chief priests refuse to put the silver into the treasury because they regard it as blood money. Their concern for ceremonial propriety contrasts sharply with their part in condemning an innocent man.", refs: ["Deuteronomy 23:18","Matthew 23:23"] },
  "Matthew 27:7": { title: "The Potter's Field", text: "They use the money to buy the potter's field as a burial place for strangers. The field becomes associated with the price of betrayal and the consequences of the leaders' actions.", refs: ["Acts 1:19","Zechariah 11:13"] },
  "Matthew 27:8": { title: "The Field of Blood", text: "The field is called the field of blood to that day. The name preserves the memory of the innocent blood involved in Jesus' betrayal and condemnation.", refs: ["Matthew 27:4","Acts 1:19"] },
  "Matthew 27:9": { title: "The Prophet's Words Fulfilled", text: "Matthew connects the thirty pieces of silver and the potter's field with prophetic Scripture. The quotation is traditionally associated with Zechariah's imagery, with wording that also recalls Jeremiah's field and potter passages.", refs: ["Zechariah 11:12–13","Jeremiah 19:1–13","Jeremiah 32:6–9"] },
  "Matthew 27:10": { title: "The Price of the Potter's Field", text: "The silver is used to buy the potter's field as the Lord directed. Matthew presents even this shameful transaction within the larger scriptural story of God's purposes and human responsibility.", refs: ["Zechariah 11:13","Matthew 27:7"] },
  "Matthew 27:11": { title: "Jesus Before the Governor", text: "Jesus stands before Pilate, who asks whether He is the King of the Jews. Jesus answers, 'Thou sayest,' affirming the truth while refusing to conform to the political expectations behind the title.", refs: ["John 18:33–37","1 Timothy 6:13"] },
  "Matthew 27:12": { title: "Jesus Does Not Answer the Accusations", text: "When the chief priests and elders accuse Him, Jesus gives no answer. His silence recalls the suffering servant who does not answer deceit with deceit.", refs: ["Isaiah 53:7","Mark 15:3–5"] },
  "Matthew 27:13": { title: "Pilate Asks About the Charges", text: "Pilate asks whether Jesus hears the many accusations against Him. The question highlights the unusual silence of a defendant who is being charged by powerful opponents.", refs: ["John 19:9–11","Luke 23:9"] },
  "Matthew 27:14": { title: "Pilate Marvels at His Silence", text: "Jesus does not answer even one accusation, and the governor marvels greatly. His silence is not an admission of guilt but a refusal to play the accusers' game.", refs: ["Isaiah 53:7","1 Peter 2:23"] },
  "Matthew 27:15": { title: "A Prisoner Released at the Feast", text: "The governor customarily releases a prisoner chosen by the crowd at the feast. The custom sets the stage for a choice that exposes the crowd's judgment.", refs: ["Mark 15:6","John 18:39"] },
  "Matthew 27:16": { title: "Barabbas", text: "A notorious prisoner named Barabbas is in custody. His presence provides a stark contrast between a guilty prisoner and Jesus, whom the narrative presents as innocent.", refs: ["Mark 15:7","Luke 23:19"] },
  "Matthew 27:17": { title: "Which One Shall I Release?", text: "Pilate asks whether the crowd wants Barabbas or Jesus called Christ released. The question forces the crowd to choose between a violent prisoner and the Messiah.", refs: ["John 18:39–40","Acts 3:14"] },
  "Matthew 27:18": { title: "Pilate Knows Their Envy", text: "Pilate recognizes that the leaders have delivered Jesus because of envy. The governor sees the motive behind the accusation even as he fails to act justly.", refs: ["Mark 15:10","Proverbs 27:4"] },
  "Matthew 27:19": { title: "Pilate's Wife Sends a Warning", text: "While Pilate sits on the judgment seat, his wife sends word that she has suffered in a dream because of this righteous man and urges him to have nothing to do with Him. The warning further confirms Jesus' innocence.", refs: ["Matthew 1:20","Matthew 27:24"] },
  "Matthew 27:20": { title: "The Leaders Persuade the Crowd", text: "The chief priests and elders persuade the multitude to ask for Barabbas and destroy Jesus. Public opinion is manipulated by leaders who seek to eliminate an innocent opponent.", refs: ["Mark 15:11","Luke 23:18–23"] },
  "Matthew 27:21": { title: "The Crowd Chooses Barabbas", text: "Pilate asks which prisoner should be released, and they answer Barabbas. Their choice reveals how a crowd can reject justice under the influence of manipulation and anger.", refs: ["Acts 3:14","John 18:40"] },
  "Matthew 27:22": { title: "What Shall I Do with Jesus?", text: "Pilate asks what he should do with Jesus called Christ, and the crowd cries for crucifixion. The question remains a challenge to every hearer: how will we respond to Jesus?", refs: ["Mark 15:12–13","John 19:6"] },
  "Matthew 27:23": { title: "Pilate Finds No Cause", text: "Pilate asks what evil Jesus has done, but the crowd only cries louder for crucifixion. Their insistence replaces evidence with pressure.", refs: ["Luke 23:22–23","Acts 13:28"] },
  "Matthew 27:24": { title: "Pilate Washes His Hands", text: "Seeing that a tumult is beginning, Pilate washes his hands before the crowd and declares himself innocent of Jesus' blood. The gesture cannot absolve him of the responsibility to administer justice.", refs: ["Deuteronomy 21:6–9","Matthew 27:19","Acts 4:27–28"] },
  "Matthew 27:25": { title: "The Crowd's Answer", text: "The crowd answers that Jesus' blood be on them and their children. This is the speech of that gathered crowd in the narrative, not a warrant for blaming all Jewish people across time; Jesus, His disciples, and the earliest church were themselves Jewish.", refs: ["Acts 2:22–23","Romans 11:1–2"] },
  "Matthew 27:26": { title: "Barabbas Released, Jesus Scourged", text: "Pilate releases Barabbas, has Jesus scourged, and delivers Him to be crucified. The innocent Jesus suffers while the guilty prisoner goes free, a powerful picture of substitution and mercy.", refs: ["Isaiah 53:5","1 Peter 3:18"] },
  "Matthew 27:27": { title: "The Soldiers Take Jesus", text: "The governor's soldiers bring Jesus into the common hall and gather the whole band around Him. The abuse that follows turns the scene into a cruel parody of royal ceremony.", refs: ["Mark 15:16","John 19:2"] },
  "Matthew 27:28": { title: "A Scarlet Robe", text: "They strip Jesus and put a scarlet robe on Him. The garment mocks His kingship even as the Gospel reveals that He truly is the King.", refs: ["John 19:2–3","Isaiah 63:1–3"] },
  "Matthew 27:29": { title: "A Crown of Thorns", text: "The soldiers twist a crown of thorns, put it on His head, place a reed in His hand, and kneel in mock homage. The scene humiliates Jesus, but its symbols unintentionally point to His kingship and the curse He bears.", refs: ["Genesis 3:17–18","John 19:5"] },
  "Matthew 27:30": { title: "They Spit and Strike Him", text: "They spit on Jesus, take the reed, and strike Him on the head. The King endures degrading violence rather than answering evil with retaliation.", refs: ["Isaiah 50:6","1 Peter 2:23"] },
  "Matthew 27:31": { title: "Led Away to Be Crucified", text: "After mocking Jesus, the soldiers remove the robe, put His own clothes on Him, and lead Him away to crucify Him. The mockery gives way to the execution that Jesus had foretold.", refs: ["Matthew 20:18–19","John 19:16"] },
  "Matthew 27:32": { title: "Simon of Cyrene Carries the Cross", text: "On the way, the soldiers compel Simon of Cyrene to carry Jesus' cross. The detail shows the physical burden of the execution and Simon's unexpected involvement in the event.", refs: ["Mark 15:21","Luke 23:26"] },
  "Matthew 27:33": { title: "Golgotha", text: "They arrive at Golgotha, the place of a skull. The place name becomes associated with the central event of Christian proclamation: Jesus' crucifixion.", refs: ["John 19:17","Mark 15:22"] },
  "Matthew 27:34": { title: "Wine Mixed with Gall", text: "Jesus is offered wine mixed with gall, but after tasting it He will not drink. The bitter drink may have been intended to dull pain, yet Jesus faces the suffering with awareness.", refs: ["Psalm 69:21","Mark 15:23"] },
  "Matthew 27:35": { title: "They Crucify Jesus", text: "The soldiers crucify Jesus and divide His garments by casting lots. The action fulfills the Scripture about the righteous sufferer's clothes being divided.", refs: ["Psalm 22:18","John 19:23–24"] },
  "Matthew 27:36": { title: "They Watch Him There", text: "The soldiers sit and watch Jesus as He hangs on the cross. Their duty places them at the scene, though they do not yet understand its full significance.", refs: ["Mark 15:39","Luke 23:47"] },
  "Matthew 27:37": { title: "The Charge Above His Head", text: "A written accusation is placed above Jesus: 'This is Jesus the King of the Jews.' Intended as a charge and mockery, the inscription states a truth the authorities reject.", refs: ["John 19:19–22","Isaiah 9:6–7"] },
  "Matthew 27:38": { title: "Two Thieves Crucified with Him", text: "Two robbers are crucified with Jesus, one on His right and one on His left. He is numbered with transgressors, as the suffering servant prophecy says.", refs: ["Isaiah 53:12","Luke 23:32–33"] },
  "Matthew 27:39": { title: "Passersby Mock Jesus", text: "Those passing by revile Jesus and shake their heads. The ridicule echoes the language of the righteous sufferer in the Psalms.", refs: ["Psalm 22:7–8","Mark 15:29"] },
  "Matthew 27:40": { title: "Save Yourself", text: "They challenge Jesus to come down from the cross if He is the Son of God. They treat deliverance from suffering as proof of divine favor, failing to understand that His mission is to save others through the cross.", refs: ["Matthew 4:3–6","John 12:27–28"] },
  "Matthew 27:41": { title: "The Leaders Mock Him", text: "The chief priests, scribes, and elders mock Jesus together. Their religious authority does not protect them from profound spiritual blindness.", refs: ["Psalm 22:12–13","Luke 23:35"] },
  "Matthew 27:42": { title: "He Saved Others", text: "They say He saved others but cannot save Himself, and challenge Him to come down from the cross. Ironically, He remains on the cross precisely to complete the saving work they mock.", refs: ["John 12:24","Romans 5:8"] },
  "Matthew 27:43": { title: "He Trusted in God", text: "They mock Jesus for trusting in God and claim God should deliver Him if He delights in Him. Their words echo Psalm 22 and reveal the cruelty of testing God's faithfulness by demanding immediate rescue.", refs: ["Psalm 22:8","Wisdom 2:18–20"] },
  "Matthew 27:44": { title: "The Robbers Also Reproach Him", text: "The robbers crucified with Jesus join in the reproach. The scene underscores the depth of His humiliation before the account later records one criminal's change of heart in Luke.", refs: ["Luke 23:39–43","Isaiah 53:3"] },
  "Matthew 27:45": { title: "Darkness Over the Land", text: "Darkness covers the land from the sixth hour to the ninth. The darkness signals the gravity of the crucifixion and recalls prophetic images of the day of the Lord.", refs: ["Amos 8:9–10","Luke 23:44–45"] },
  "Matthew 27:46": { title: "My God, My God, Why Hast Thou Forsaken Me?", text: "Jesus cries out the opening words of Psalm 22. The cry expresses the depth of His suffering and invokes a psalm that moves from anguish toward trust and vindication; in Oneness theology, it is the incarnate Jesus experiencing genuine human anguish, not evidence that God ceased to be one.", refs: ["Psalm 22:1–24","Hebrews 5:7–9"] },
  "Matthew 27:47": { title: "Some Think He Calls Elijah", text: "Some bystanders misunderstand Jesus' cry and think He is calling Elijah. Their confusion shows that the words of His suffering are not understood by everyone present.", refs: ["Mark 15:35","Psalm 22:1"] },
  "Matthew 27:48": { title: "Sour Wine Offered", text: "One person runs to fill a sponge with sour wine and offers it to Jesus on a reed. The act occurs amid the crowd's watchful anticipation and echoes the psalm of suffering.", refs: ["Psalm 69:21","John 19:28–29"] },
  "Matthew 27:49": { title: "Wait to See Whether Elijah Comes", text: "Others say to wait and see whether Elijah will come to save Him. The bystanders continue to misunderstand the moment and look for a dramatic rescue.", refs: ["Malachi 4:5–6","Mark 15:36"] },
  "Matthew 27:50": { title: "Jesus Yields Up His Spirit", text: "Jesus cries again with a loud voice and yields up His spirit. He truly dies in His human life; Scripture does not teach that the eternal Spirit of God ceased to exist, but that Jesus gave His life in the flesh for humanity.", refs: ["John 19:30","Luke 23:46","1 Peter 3:18"] },
  "Matthew 27:51": { title: "The Veil Is Torn", text: "The temple veil is torn from top to bottom, the earth shakes, and rocks split. The torn veil signifies a decisive change in access to God through Jesus' sacrifice.", refs: ["Hebrews 10:19–22","Exodus 26:31–33"] },
  "Matthew 27:52": { title: "Tombs Opened", text: "Tombs are opened and many bodies of sleeping saints are raised. The extraordinary signs point to the life-giving significance of Jesus' death and resurrection.", refs: ["Ezekiel 37:12–14","John 5:25"] },
  "Matthew 27:53": { title: "They Appear After His Resurrection", text: "After Jesus' resurrection, the raised saints come into the holy city and appear to many. Matthew presents this as a sign of God's victory over death connected to Jesus' resurrection.", refs: ["1 Corinthians 15:20–23","Matthew 28:6"] },
  "Matthew 27:54": { title: "The Centurion Confesses", text: "The centurion and those with him see the earthquake and events and confess that Jesus truly was the Son of God. The Roman witnesses recognize something of Jesus' identity through the signs surrounding His death.", refs: ["Mark 15:39","Matthew 16:16"] },
  "Matthew 27:55": { title: "Women Watch from Afar", text: "Many women who had followed Jesus from Galilee to minister to Him watch from a distance. Their faithful presence contrasts with the disciples' earlier flight.", refs: ["Luke 8:1–3","Mark 15:40–41"] },
  "Matthew 27:56": { title: "Mary Magdalene and the Others", text: "Matthew names Mary Magdalene, Mary the mother of James and Joses, and the mother of Zebedee's children. These witnesses remain important in the burial and resurrection accounts.", refs: ["Mark 15:40","Matthew 28:1"] },
  "Matthew 27:57": { title: "Joseph of Arimathaea", text: "A rich man named Joseph of Arimathaea, who was also Jesus' disciple, comes in the evening. His public action will provide Jesus with an honorable burial.", refs: ["Isaiah 53:9","John 19:38"] },
  "Matthew 27:58": { title: "Joseph Requests the Body", text: "Joseph goes to Pilate and asks for Jesus' body, and Pilate orders it to be given to him. The request confirms that Jesus' death is treated as real and allows the burial to proceed.", refs: ["Mark 15:43–45","John 19:38"] },
  "Matthew 27:59": { title: "The Body Wrapped in Clean Linen", text: "Joseph takes the body and wraps it in clean linen. The care taken with the body prepares for its placement in the tomb.", refs: ["John 19:40","Mark 15:46"] },
  "Matthew 27:60": { title: "A New Tomb", text: "Joseph lays Jesus in his own new tomb cut into rock and rolls a great stone to the door. The specific burial place makes the later discovery of the empty tomb meaningful.", refs: ["Isaiah 53:9","John 19:41–42"] },
  "Matthew 27:61": { title: "The Women Sit Opposite the Sepulchre", text: "Mary Magdalene and the other Mary sit opposite the tomb. Their presence gives continuity between Jesus' burial and the first witnesses to the empty tomb.", refs: ["Matthew 28:1","Mark 15:47"] },
  "Matthew 27:62": { title: "The Day After the Preparation", text: "The chief priests and Pharisees gather before Pilate the day after the preparation. Though they have secured Jesus' death, they remain concerned about what His followers might do.", refs: ["John 19:31","Matthew 27:64"] },
  "Matthew 27:63": { title: "They Remember His Prediction", text: "They recall that Jesus said He would rise after three days and call Him a deceiver. Ironically, even His opponents remember His prediction while the disciples are fearful and confused.", refs: ["Matthew 16:21","Matthew 20:19"] },
  "Matthew 27:64": { title: "Secure the Tomb", text: "They ask Pilate to secure the tomb until the third day lest the disciples steal the body and claim resurrection. Their plan provides the context for the guard and seal described next.", refs: ["Matthew 28:11–15","Mark 8:31"] },
  "Matthew 27:65": { title: "A Guard Is Granted", text: "Pilate tells them to use a guard and secure the tomb as they know how. The authorities take steps to prevent tampering, which later makes their explanation of the empty tomb especially significant.", refs: ["Matthew 28:4","Matthew 28:11–15"] },
  "Matthew 27:66": { title: "The Tomb Is Sealed", text: "They secure the tomb by sealing the stone and setting a watch. Matthew closes the chapter with the tomb guarded, preparing for the surprising events of the resurrection morning.", refs: ["Daniel 6:17","Matthew 28:2–6"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 28:1": { title: "The Women Come to the Tomb", text: "After the Sabbath, as the first day of the week begins to dawn, Mary Magdalene and the other Mary come to see the tomb. Their visit sets the scene for the announcement that Jesus has risen.", refs: ["Mark 16:1–2","Luke 24:1–2","John 20:1"] },
  "Matthew 28:2": { title: "An Angel Rolls Away the Stone", text: "A great earthquake occurs, and an angel of the Lord descends and rolls back the stone. The angel's action reveals God's power; the stone is moved to reveal the empty tomb, not to enable the risen Jesus to escape.", refs: ["Matthew 27:60","Matthew 28:6"] },
  "Matthew 28:3": { title: "The Angel's Appearance", text: "The angel's appearance is like lightning and his clothing white as snow. The description communicates heavenly glory and the extraordinary significance of the message he brings.", refs: ["Daniel 10:5–6","Matthew 17:2"] },
  "Matthew 28:4": { title: "The Guards Tremble", text: "The guards shake with fear and become like dead men. The armed watch cannot control the event or withstand the revelation of God's power.", refs: ["Matthew 27:65–66","Psalm 76:7"] },
  "Matthew 28:5": { title: "Fear Not", text: "The angel tells the women not to fear, for he knows they seek Jesus who was crucified. The message acknowledges the crucifixion as real and turns their fear toward the good news.", refs: ["Luke 24:5–6","Mark 16:6"] },
  "Matthew 28:6": { title: "He Is Risen", text: "The angel declares that Jesus is not here because He is risen, as He said, and invites them to see the place where He lay. The resurrection is presented as God's act fulfilling Jesus' own prediction.", refs: ["Matthew 16:21","1 Corinthians 15:3–8"] },
  "Matthew 28:7": { title: "Tell the Disciples", text: "The women are instructed to go quickly and tell the disciples that Jesus is risen and will go before them into Galilee. The first response to the resurrection is to carry its message to others.", refs: ["Matthew 26:32","Matthew 28:10"] },
  "Matthew 28:8": { title: "Fear and Great Joy", text: "The women depart with fear and great joy and run to tell the disciples. Awe and gladness coexist as they respond to news that changes everything.", refs: ["Mark 16:8","Luke 24:9"] },
  "Matthew 28:9": { title: "Jesus Meets the Women", text: "Jesus meets the women, who come and hold Him by the feet and worship Him. Their encounter presents the risen Jesus as truly present, worthy of worship, and not merely an idea or vision.", refs: ["John 20:14–18","Luke 24:39"] },
  "Matthew 28:10": { title: "Go Tell My Brethren", text: "Jesus tells the women not to fear and to tell His brethren to go to Galilee, where they will see Him. He calls the disciples His brethren despite their abandonment of Him, showing mercy and restoration.", refs: ["John 20:17","Hebrews 2:11–12"] },
  "Matthew 28:11": { title: "The Guards Report", text: "Some of the guards go into the city and report what happened to the chief priests. The empty tomb cannot simply be ignored, so the authorities seek a response to the report.", refs: ["Matthew 27:65–66","Matthew 28:4"] },
  "Matthew 28:12": { title: "The Leaders Consult", text: "The chief priests assemble with the elders and agree on a plan, giving the soldiers a large sum of money. Instead of following the evidence, they attempt to suppress the resurrection report.", refs: ["Acts 4:16–18","Matthew 26:3–4"] },
  "Matthew 28:13": { title: "The Stolen Body Story", text: "The leaders instruct the guards to say that Jesus' disciples came by night and stole His body while they slept. The explanation is internally weak because sleeping guards could not reliably know who took the body.", refs: ["Matthew 27:64","Matthew 28:6"] },
  "Matthew 28:14": { title: "A Promise to Protect the Guards", text: "They promise to persuade the governor and keep the soldiers out of trouble if the story reaches him. The arrangement shows the authorities trying to manage appearances rather than acknowledge the report.", refs: ["Matthew 27:24","Acts 5:28"] },
  "Matthew 28:15": { title: "The Report Is Spread", text: "The soldiers take the money and do as instructed, and the story spreads among the Jews. Matthew records the competing explanation so readers can see how the resurrection was challenged from the beginning.", refs: ["Matthew 28:11–14","Acts 2:32"] },
  "Matthew 28:16": { title: "The Eleven Go to Galilee", text: "The eleven disciples go to Galilee, to the mountain Jesus had appointed. The group is smaller than twelve because Judas has betrayed Jesus, yet the risen Lord continues His work through them.", refs: ["Matthew 26:32","Matthew 28:7"] },
  "Matthew 28:17": { title: "They Worship, Some Doubt", text: "When the disciples see Jesus, they worship Him, though some doubt. The verse honestly records both worship and hesitation, and Jesus proceeds to commission them.", refs: ["Luke 24:41","John 20:24–29"] },
  "Matthew 28:18": { title: "All Authority Given to Jesus", text: "Jesus declares that all power or authority in heaven and earth is given to Him. In a Oneness reading, this is the risen Messiah exercising universal authority as the incarnate Son; it should be read alongside the confession that the one God was in Christ reconciling the world to Himself.", refs: ["Daniel 7:13–14","John 5:22–27","2 Corinthians 5:19"] },
  "Matthew 28:19": { title: "Make Disciples and Baptize", text: "Jesus commands the disciples to make disciples of all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost. The text says 'name' in the singular; Acts records the apostles baptizing in the name of Jesus Christ, which Oneness believers understand as the revealed saving name associated with the Father, Son, and Holy Spirit.", refs: ["Acts 2:38","Acts 8:16","Acts 10:48","Acts 19:5"] },
  "Matthew 28:20": { title: "Teach and Remember His Presence", text: "Jesus commands them to teach disciples to observe all He commanded and promises to be with them always, even to the end of the age. The Great Commission joins evangelism, teaching, obedience, and the abiding presence of the risen Lord.", refs: ["Matthew 18:20","Acts 1:8","John 14:18"] }
});

Object.assign(window.verseCommentary, {
  "Mark 1:1": { title: "The Beginning of the Gospel", text: "Mark opens by announcing the gospel of Jesus Christ, the Son of God. The good news is centered on Jesus' identity and saving mission.", refs: ["Romans 1:1–4","John 20:31"] },
  "Mark 1:2": { title: "The Messenger Foretold", text: "Mark joins prophetic words about a messenger preparing the way. God's promised work is not an improvisation; the coming of Jesus belongs to the story foretold in Scripture.", refs: ["Malachi 3:1","Exodus 23:20"] },
  "Mark 1:3": { title: "Prepare the Lord's Way", text: "A voice cries in the wilderness to prepare the Lord's way and make His paths straight. Mark applies Isaiah's prophecy to the ministry that prepares people for Jesus' coming.", refs: ["Isaiah 40:3","Matthew 3:3"] },
  "Mark 1:4": { title: "John Preaches Repentance", text: "John appears in the wilderness preaching a baptism of repentance for the remission of sins. The people are called to turn from sin and prepare for God's coming work.", refs: ["Luke 3:3","Acts 13:24"] },
  "Mark 1:5": { title: "The People Confess Their Sins", text: "People from Judaea and Jerusalem come to John, confess their sins, and are baptized in the Jordan. Their response shows the seriousness of repentance in preparation for the Messiah.", refs: ["Matthew 3:5–6","Acts 19:4"] },
  "Mark 1:6": { title: "John's Clothing and Food", text: "John wears camel's hair with a leather girdle and eats locusts and wild honey. His austere life recalls the prophets and keeps attention on his message rather than luxury or status.", refs: ["2 Kings 1:8","Matthew 11:7–9"] },
  "Mark 1:7": { title: "One Mightier Is Coming", text: "John says one mightier than he is coming, whose sandal strap he is unworthy to stoop down and loosen. John knows his role is preparatory and directs attention to the greater One.", refs: ["John 1:26–27","Acts 13:25"] },
  "Mark 1:8": { title: "Water and the Holy Spirit", text: "John baptizes with water, but the coming One will baptize with the Holy Ghost. John's baptism prepares people; Jesus brings the promised gift of the Spirit.", refs: ["Joel 2:28–29","Acts 1:5","Acts 2:4"] },
  "Mark 1:9": { title: "Jesus Is Baptized", text: "Jesus comes from Nazareth and is baptized by John in the Jordan. His baptism inaugurates His public ministry and identifies Him with the people He came to save, though He Himself is without sin.", refs: ["Matthew 3:13–17","Hebrews 4:15"] },
  "Mark 1:10": { title: "The Heavens Open", text: "As Jesus comes up from the water, He sees the heavens opened and the Spirit descending like a dove upon Him. The sign marks divine anointing for His messianic ministry.", refs: ["Isaiah 11:2","Luke 4:18","John 1:32–34"] },
  "Mark 1:11": { title: "The Beloved Son", text: "A voice from heaven declares Jesus the beloved Son in whom God is well pleased. The language echoes royal and servant prophecies and identifies Jesus as God's chosen Messiah.", refs: ["Psalm 2:7","Isaiah 42:1","Matthew 17:5"] },
  "Mark 1:12": { title: "The Spirit Drives Him into the Wilderness", text: "Immediately the Spirit drives Jesus into the wilderness. The Spirit's leading places the Messiah in a period of testing before His public ministry unfolds.", refs: ["Matthew 4:1","Luke 4:1"] },
  "Mark 1:13": { title: "Forty Days of Temptation", text: "Jesus is in the wilderness forty days, tempted by Satan, with wild beasts around Him and angels ministering to Him. He faces temptation faithfully where humanity has often failed.", refs: ["Deuteronomy 8:2","Hebrews 2:18","Hebrews 4:15"] },
  "Mark 1:14": { title: "Jesus Preaches the Gospel", text: "After John is put in prison, Jesus comes to Galilee preaching the gospel of the kingdom of God. John's imprisonment does not stop God's message; Jesus continues the proclamation.", refs: ["Matthew 4:12–17","Luke 4:14–15"] },
  "Mark 1:15": { title: "Repent and Believe", text: "Jesus announces that the time is fulfilled and the kingdom of God is at hand, commanding people to repent and believe the gospel. God's promised reign is breaking into history through Jesus, demanding a response.", refs: ["Daniel 2:44","Acts 2:38","Romans 1:16"] },
  "Mark 1:16": { title: "Simon and Andrew Called", text: "Walking by the Sea of Galilee, Jesus sees Simon and Andrew casting a net and calls them. His invitation redirects their ordinary work toward the mission of gathering people into God's kingdom.", refs: ["Matthew 4:18–20","Luke 5:10"] },
  "Mark 1:17": { title: "Fishers of Men", text: "Jesus promises to make Simon and Andrew fishers of men. Discipleship involves learning from Jesus and joining His work of calling others to repentance and faith.", refs: ["Jeremiah 16:16","Matthew 28:19"] },
  "Mark 1:18": { title: "They Leave Their Nets", text: "Simon and Andrew immediately leave their nets and follow Jesus. Their response shows the priority of His call over their former occupation.", refs: ["Luke 5:11","Matthew 10:37–39"] },
  "Mark 1:19": { title: "James and John", text: "Jesus sees James and John in a boat mending their nets. The call reaches another pair of working fishermen.", refs: ["Matthew 4:21","Luke 5:10"] },
  "Mark 1:20": { title: "They Leave Their Father", text: "Jesus calls the brothers, and they leave their father Zebedee in the boat with hired servants to follow Him. Following Jesus may require costly changes in familiar responsibilities and relationships.", refs: ["Matthew 10:37","Luke 14:26"] },
  "Mark 1:21": { title: "Teaching in Capernaum", text: "Jesus enters Capernaum and teaches in the synagogue on the Sabbath. His ministry combines teaching, authority, and acts of deliverance.", refs: ["Luke 4:31","Matthew 4:13"] },
  "Mark 1:22": { title: "Teaching with Authority", text: "The people are astonished because Jesus teaches with authority, unlike the scribes. His authority is not merely a repetition of human tradition; His words carry the force of God's truth.", refs: ["Matthew 7:28–29","John 7:46"] },
  "Mark 1:23": { title: "A Man with an Unclean Spirit", text: "A man in the synagogue has an unclean spirit and cries out. The scene shows that spiritual opposition can be present even in a place of worship, and that Jesus has authority over it.", refs: ["Luke 4:33","Ephesians 6:12"] },
  "Mark 1:24": { title: "The Spirit Recognizes Jesus", text: "The unclean spirit asks what Jesus has to do with them and calls Him the Holy One of God. The spirit recognizes Jesus' identity, but its testimony is not the same as faithful discipleship.", refs: ["Luke 4:34","James 2:19"] },
  "Mark 1:25": { title: "Be Quiet and Come Out", text: "Jesus rebukes the spirit and commands it to be quiet and come out of the man. His authority over evil is immediate and requires no ritual contest.", refs: ["Mark 1:34","Luke 4:35"] },
  "Mark 1:26": { title: "The Spirit Leaves the Man", text: "The unclean spirit convulses the man and cries loudly before coming out. The violent departure underscores the conflict, but the spirit cannot resist Jesus' command.", refs: ["Mark 9:26","Luke 4:35"] },
  "Mark 1:27": { title: "A New Teaching with Authority", text: "The people marvel and ask what new teaching this is, noting that Jesus commands even unclean spirits and they obey Him. His authority is demonstrated in both word and deed.", refs: ["Mark 1:22","Luke 4:36"] },
  "Mark 1:28": { title: "The Report Spreads", text: "Jesus' fame spreads throughout the region of Galilee. The report travels because people witness His teaching and power.", refs: ["Matthew 4:24","Luke 4:37"] },
  "Mark 1:29": { title: "Jesus Enters Simon's House", text: "Jesus leaves the synagogue and enters the house of Simon and Andrew with James and John. The narrative moves from public ministry to care for a family in need.", refs: ["Matthew 8:14","Luke 4:38"] },
  "Mark 1:30": { title: "Simon's Mother-in-Law Is Sick", text: "Simon's wife's mother lies sick with a fever, and they tell Jesus about her. They bring the need to Him directly.", refs: ["Matthew 8:14","Luke 4:38"] },
  "Mark 1:31": { title: "Jesus Heals Her", text: "Jesus takes her by the hand and lifts her up; the fever leaves, and she serves them. Her immediate recovery is followed by practical service, not as payment but as a natural response.", refs: ["Matthew 8:15","Luke 4:39"] },
  "Mark 1:32": { title: "The Sick Are Brought at Evening", text: "At evening, after sunset, people bring the sick and demon-possessed to Jesus. The crowd waits until the Sabbath has ended before bringing many needs to Him.", refs: ["Matthew 8:16","Luke 4:40"] },
  "Mark 1:33": { title: "The Whole City at the Door", text: "The whole city gathers at the door. The needs of the community become visible as people come seeking Jesus' help.", refs: ["Luke 4:40","Matthew 4:24"] },
  "Mark 1:34": { title: "Many Healed and Spirits Cast Out", text: "Jesus heals many with various diseases and casts out many demons, not allowing the demons to speak because they know Him. He controls both the healing work and the testimony about His identity.", refs: ["Luke 4:41","Mark 3:11–12"] },
  "Mark 1:35": { title: "Jesus Prays in a Solitary Place", text: "Rising early while it is still dark, Jesus goes to a solitary place to pray. His busy ministry does not replace communion with God.", refs: ["Luke 5:16","Mark 6:46"] },
  "Mark 1:36": { title: "Simon and the Others Search", text: "Simon and those with him search for Jesus. They see the demand for His attention but do not yet understand that He is not bound to one location.", refs: ["Luke 4:42","Mark 1:38"] },
  "Mark 1:37": { title: "Everyone Is Looking for You", text: "They tell Jesus that everyone is seeking Him. Popularity could have kept Him in one place, but His mission is broader than satisfying immediate demand.", refs: ["John 6:26–27","Luke 4:42"] },
  "Mark 1:38": { title: "Preach in the Nearby Towns", text: "Jesus says they should go to the nearby towns so He may preach there also, for this is why He came forth. Proclaiming the kingdom is central to His mission, alongside healing and deliverance.", refs: ["Luke 4:43","Isaiah 61:1"] },
  "Mark 1:39": { title: "Preaching and Casting Out Demons", text: "Jesus travels through Galilee, preaching in synagogues and casting out demons. His ministry confronts spiritual darkness and announces God's reign.", refs: ["Matthew 4:23","Luke 4:44"] },
  "Mark 1:40": { title: "A Leper Begs for Cleansing", text: "A leper comes to Jesus, kneels, and says that if Jesus is willing, He can make him clean. The man trusts Jesus' power and asks for His compassionate will.", refs: ["Matthew 8:2","Luke 5:12"] },
  "Mark 1:41": { title: "Jesus Touches and Cleanses Him", text: "Moved with compassion, Jesus touches the man and says He is willing; the man is cleansed. Jesus' touch crosses the boundary of ritual uncleanness and restores the afflicted man.", refs: ["Leviticus 13:45–46","Matthew 8:3"] },
  "Mark 1:42": { title: "The Leprosy Departs", text: "Immediately the leprosy leaves, and the man is cleansed. The complete healing confirms Jesus' authority and compassion.", refs: ["Luke 5:13","Psalm 103:2–3"] },
  "Mark 1:43": { title: "Jesus Sends Him Away", text: "Jesus sternly charges the man and sends him away. The instruction that follows directs the man to obey the law and avoid turning the healing into a spectacle.", refs: ["Leviticus 14:2–32","Matthew 8:4"] },
  "Mark 1:44": { title: "Show Yourself to the Priest", text: "Jesus tells the man to say nothing to anyone but show himself to the priest and offer what Moses commanded as a testimony. The law's prescribed process would publicly establish his cleansing and restoration.", refs: ["Leviticus 14:1–20","Luke 5:14"] },
  "Mark 1:45": { title: "The News Spreads Everywhere", text: "The man spreads the news so widely that Jesus can no longer openly enter the city and stays in solitary places, while people come from everywhere. Even a joyful report can complicate the mission when it ignores Jesus' instructions.", refs: ["Luke 5:15–16","Mark 7:36"] }
});

Object.assign(window.verseCommentary, {
  "Mark 2:1": { title: "Jesus Returns to Capernaum", text: "After some days Jesus returns to Capernaum, and word spreads that He is in the house. His presence draws people who seek His teaching and help.", refs: ["Mark 1:21","Matthew 9:1"] },
  "Mark 2:2": { title: "The House Is Filled", text: "So many gather that there is no room, even around the door, and Jesus preaches the word to them. The account emphasizes His teaching before the healing miracle.", refs: ["Luke 5:17","Mark 1:38"] },
  "Mark 2:3": { title: "A Paralytic Is Brought", text: "Four people bring a man sick with palsy to Jesus. Their effort shows the practical care and determination of those who seek help for someone unable to come alone.", refs: ["Luke 5:18","Matthew 9:2"] },
  "Mark 2:4": { title: "They Open the Roof", text: "Unable to reach Jesus because of the crowd, they uncover the roof and lower the bed carrying the paralytic. Their persistence overcomes an obstacle without abandoning their purpose.", refs: ["Luke 5:19","Hebrews 10:24"] },
  "Mark 2:5": { title: "Jesus Sees Their Faith", text: "Jesus sees their faith and tells the paralytic that his sins are forgiven. He addresses the man's deepest need first and demonstrates authority to forgive sins.", refs: ["Matthew 9:2","Psalm 103:3"] },
  "Mark 2:6": { title: "Scribes Reason in Their Hearts", text: "Some scribes sit there and reason inwardly about Jesus' words. The conflict is not only about the healing but about who has authority to forgive sins.", refs: ["Luke 5:21","Isaiah 43:25"] },
  "Mark 2:7": { title: "Who Can Forgive Sins but God?", text: "The scribes ask who can forgive sins but God alone, and they consider Jesus' words blasphemous. Their premise that forgiveness belongs to God is sound; the question is whether they recognize God's authority at work in Jesus.", refs: ["Isaiah 43:25","Luke 7:49"] },
  "Mark 2:8": { title: "Jesus Knows Their Thoughts", text: "Jesus immediately perceives their reasoning and asks why they think these things in their hearts. His knowledge exposes the hidden objection and underscores His authority.", refs: ["John 2:24–25","Matthew 12:25"] },
  "Mark 2:9": { title: "Which Is Easier to Say?", text: "Jesus asks whether it is easier to say sins are forgiven or to tell the paralytic to rise, take his bed, and walk. The visible healing will serve as evidence for His authority to pronounce forgiveness.", refs: ["Luke 5:23","John 5:36"] },
  "Mark 2:10": { title: "The Son of Man Has Authority", text: "Jesus declares that the Son of man has authority on earth to forgive sins. He then turns to the paralytic, making the healing a sign of the authority He has just claimed.", refs: ["Daniel 7:13–14","Matthew 9:6","John 5:27"] },
  "Mark 2:11": { title: "Rise, Take Up Your Bed", text: "Jesus commands the man to rise, take up his bed, and go home. His command is direct and demonstrates authority over the man's physical condition.", refs: ["Mark 2:9","John 5:8"] },
  "Mark 2:12": { title: "The Man Walks and the Crowd Glorifies God", text: "The man rises immediately, takes his bed, and leaves before everyone. The crowd marvels and glorifies God, recognizing that they have witnessed something extraordinary.", refs: ["Luke 5:25–26","Matthew 9:8"] },
  "Mark 2:13": { title: "Jesus Teaches by the Sea", text: "Jesus goes out by the sea, and the crowd comes to Him as He teaches. His mission continues in public spaces where people can hear the word.", refs: ["Mark 1:16","Matthew 13:1–2"] },
  "Mark 2:14": { title: "Levi Is Called", text: "Jesus sees Levi, son of Alphaeus, sitting at the receipt of custom and calls him to follow. Levi rises and follows, showing that Jesus' call can redirect a person's whole life.", refs: ["Matthew 9:9","Luke 5:27–28"] },
  "Mark 2:15": { title: "Jesus Eats with Sinners", text: "Jesus eats in Levi's house with many publicans and sinners, along with His disciples. He draws near to people who need repentance rather than keeping distance for the sake of appearances.", refs: ["Luke 5:29","Matthew 9:10"] },
  "Mark 2:16": { title: "Why Does He Eat with Publicans?", text: "Scribes of the Pharisees question why Jesus eats with publicans and sinners. They mistake separation from sinners for holiness and fail to see the purpose of Jesus' mission.", refs: ["Luke 15:1–2","Matthew 9:11"] },
  "Mark 2:17": { title: "The Physician for the Sick", text: "Jesus says the healthy do not need a physician, but the sick do; He came not to call the righteous, but sinners to repentance. His fellowship is a mission of rescue, not approval of sin.", refs: ["Luke 5:31–32","1 Timothy 1:15"] },
  "Mark 2:18": { title: "A Question About Fasting", text: "People ask why John's disciples and the Pharisees fast while Jesus' disciples do not. Jesus answers by explaining that His presence changes the immediate setting for fasting.", refs: ["Matthew 9:14","Luke 5:33"] },
  "Mark 2:19": { title: "The Bridegroom Is Present", text: "Jesus asks whether wedding guests can fast while the bridegroom is with them. His presence is a time of joy, compared to a wedding celebration.", refs: ["John 3:29","Matthew 25:1"] },
  "Mark 2:20": { title: "The Bridegroom Will Be Taken Away", text: "Jesus says days will come when the bridegroom is taken away, and then His disciples will fast. The saying points toward His coming suffering and the changed circumstances after His departure.", refs: ["Isaiah 53:8","John 16:20"] },
  "Mark 2:21": { title: "New Cloth on an Old Garment", text: "No one sews new cloth on an old garment because the patch will pull away and make the tear worse. Jesus' teaching and mission cannot be reduced to a small patch on a system that refuses to be renewed.", refs: ["Luke 5:36","Hebrews 8:13"] },
  "Mark 2:22": { title: "New Wine in New Bottles", text: "New wine must be put into new wineskins or both are ruined. Jesus illustrates that the new era of God's kingdom requires a fitting response, not rigid resistance to what God is doing.", refs: ["Luke 5:37–39","Jeremiah 31:31–34"] },
  "Mark 2:23": { title: "The Disciples Pluck Grain", text: "As Jesus walks through grainfields on the Sabbath, His disciples begin plucking ears of grain. Their action prompts a dispute about the proper understanding of Sabbath law.", refs: ["Matthew 12:1","Luke 6:1"] },
  "Mark 2:24": { title: "The Pharisees Challenge Them", text: "The Pharisees ask why the disciples do what is unlawful on the Sabbath. Their accusation leads Jesus to explain the law's purpose and the authority of the Son of man.", refs: ["Exodus 20:8–11","Matthew 12:2"] },
  "Mark 2:25": { title: "David and the Bread", text: "Jesus asks whether they have read what David did when he and his companions were hungry. Scripture itself shows that human need matters in interpreting ritual provisions.", refs: ["1 Samuel 21:1–6","Matthew 12:3"] },
  "Mark 2:26": { title: "The Bread in Abiathar's Time", text: "Jesus refers to David entering God's house in the days of Abiathar the high priest and eating the showbread, which was normally reserved for priests. The example challenges a rigid reading that ignores mercy and necessity.", refs: ["1 Samuel 21:1–6","Leviticus 24:5–9"] },
  "Mark 2:27": { title: "The Sabbath Made for Man", text: "Jesus says the Sabbath was made for man, not man for the Sabbath. God's gift of rest is intended for human good, not to become a burden that defeats its purpose.", refs: ["Exodus 23:12","Deuteronomy 5:12–15"] },
  "Mark 2:28": { title: "Lord of the Sabbath", text: "Jesus declares that the Son of man is Lord also of the Sabbath. He speaks with authority to interpret the Sabbath in keeping with God's purpose and His messianic identity.", refs: ["Matthew 12:8","Colossians 2:16–17"] }
});

Object.assign(window.verseCommentary, {
  "Mark 3:1": { title: "A Man with a Withered Hand", text: "Jesus enters the synagogue, where a man with a withered hand is present. The scene sets compassion and restoration against a dispute over Sabbath observance.", refs: ["Matthew 12:9–10","Luke 6:6"] },
  "Mark 3:2": { title: "Watching for an Accusation", text: "Some watch Jesus closely to see whether He will heal on the Sabbath so they can accuse Him. Their attention is fixed on finding fault rather than seeking the man's good.", refs: ["Luke 14:1","John 9:16"] },
  "Mark 3:3": { title: "Stand Forth", text: "Jesus tells the man to stand in the midst. He does not hide the need or allow the controversy to prevent a public demonstration of God's mercy.", refs: ["Mark 2:27","Matthew 12:11"] },
  "Mark 3:4": { title: "Doing Good on the Sabbath", text: "Jesus asks whether it is lawful on the Sabbath to do good or evil, to save life or kill. The question exposes the moral failure of treating a day of rest as a reason to withhold help.", refs: ["Luke 6:9","Matthew 12:12"] },
  "Mark 3:5": { title: "The Man Is Healed", text: "Jesus looks around with grief and anger at their hardness of heart, then tells the man to stretch out his hand. The hand is restored; Jesus' anger is directed at stubbornness that resists mercy, not at the suffering man.", refs: ["Ephesians 4:26","Matthew 12:13"] },
  "Mark 3:6": { title: "A Plot Against Jesus", text: "The Pharisees begin conspiring with the Herodians about how to destroy Jesus. Those who condemn Him for healing reveal how far religious opposition can move from God's intention for life.", refs: ["John 5:16","John 11:53"] },
  "Mark 3:7": { title: "Crowds Follow Jesus", text: "Jesus withdraws to the sea with His disciples, and a great multitude follows from Galilee and surrounding regions. His ministry reaches beyond one town and draws people seeking help.", refs: ["Matthew 4:25","Luke 6:17"] },
  "Mark 3:8": { title: "People Come from Many Regions", text: "People from Judea, Jerusalem, Idumea, beyond Jordan, and the areas around Tyre and Sidon hear what Jesus has done and come to Him. The growing response shows the broad reach of His works and teaching.", refs: ["Mark 1:28","Luke 6:17"] },
  "Mark 3:9": { title: "A Boat Ready for the Crowd", text: "Jesus asks His disciples to keep a small ship ready because the crowd presses around Him. Practical arrangements help Him continue ministering amid the crush of people.", refs: ["Mark 4:1","Luke 5:1–3"] },
  "Mark 3:10": { title: "Many Seek to Touch Him", text: "Because Jesus has healed many, those with diseases press toward Him to touch Him. Their actions express urgent hope in His power to heal.", refs: ["Mark 5:27–29","Matthew 14:36"] },
  "Mark 3:11": { title: "Unclean Spirits Recognize Him", text: "When unclean spirits see Jesus, they fall before Him and cry that He is the Son of God. Their recognition does not make them faithful disciples; true response includes obedience to God.", refs: ["Mark 1:24","James 2:19"] },
  "Mark 3:12": { title: "Jesus Commands Silence", text: "Jesus strictly warns the spirits not to make Him known. He controls the disclosure of His identity and will not allow demons to direct the message about His mission.", refs: ["Mark 1:25","Mark 1:34"] },
  "Mark 3:13": { title: "Jesus Calls Whom He Will", text: "Jesus goes up a mountain and calls those He wants, and they come to Him. Discipleship begins with His call and requires a willing response.", refs: ["Luke 6:12–13","John 15:16"] },
  "Mark 3:14": { title: "The Twelve Are Appointed", text: "Jesus appoints twelve to be with Him and to be sent out to preach. Being with Jesus comes before being sent to represent His message.", refs: ["Matthew 10:1–4","Acts 4:13"] },
  "Mark 3:15": { title: "Authority over Unclean Spirits", text: "The Twelve receive authority to heal sicknesses and cast out devils as part of their commission. Their authority is delegated by Jesus, not independent power of their own.", refs: ["Luke 9:1–2","Mark 6:7"] },
  "Mark 3:16": { title: "Simon Is Named Peter", text: "Mark identifies Simon, whom Jesus surnamed Peter, among the Twelve. The new name becomes associated with Simon's place in the apostolic story, though he remains a disciple who must grow.", refs: ["John 1:42","Matthew 16:18"] },
  "Mark 3:17": { title: "James and John", text: "James and John, sons of Zebedee, are called Boanerges, meaning sons of thunder. Jesus knows their temperaments and forms them for service in His mission.", refs: ["Luke 9:54","Mark 10:35–40"] },
  "Mark 3:18": { title: "The Rest of the Twelve", text: "Andrew, Philip, Bartholomew, Matthew, Thomas, James son of Alphaeus, Thaddaeus, and Simon the Canaanite are named. Jesus gathers different people into one mission under His leadership.", refs: ["Luke 6:14–16","Acts 1:13"] },
  "Mark 3:19": { title: "Judas Iscariot", text: "Judas Iscariot is named last, with the note that he later betrayed Jesus. Being included among the Twelve did not remove his responsibility for his own choices.", refs: ["John 6:70–71","Mark 14:10–11"] },
  "Mark 3:20": { title: "The Crowd Gathers Again", text: "The crowd gathers so heavily that Jesus and His disciples cannot even eat bread. The demands of the ministry are intense, and the people continue seeking Him.", refs: ["Mark 6:31","Mark 1:33"] },
  "Mark 3:21": { title: "His Friends Worry", text: "Those associated with Jesus hear of the commotion and go out to lay hold on Him, saying He is beside Himself. Their response shows that even people close to Him do not yet fully understand His mission.", refs: ["John 7:5","Mark 6:4"] },
  "Mark 3:22": { title: "The Charge of Beelzebub", text: "Scribes from Jerusalem claim that Jesus casts out devils by Beelzebub, the prince of devils. Instead of acknowledging God's work, they attribute deliverance to an evil source.", refs: ["Matthew 12:24","Luke 11:15"] },
  "Mark 3:23": { title: "Jesus Answers with a Parable", text: "Jesus calls them and asks how Satan can cast out Satan. His reasoning begins to show that their accusation contradicts itself.", refs: ["Matthew 12:25","Luke 11:17"] },
  "Mark 3:24": { title: "A Divided Kingdom Falls", text: "A kingdom divided against itself cannot stand. Jesus uses a plain principle to expose the implausibility of Satan systematically undoing his own work through Jesus.", refs: ["Matthew 12:25","Luke 11:17"] },
  "Mark 3:25": { title: "A Divided House Falls", text: "A house divided against itself cannot stand either. Unity is essential for a household to remain standing, and the same logic undermines the accusation against Jesus.", refs: ["Mark 3:24","Luke 11:17"] },
  "Mark 3:26": { title: "Satan Cannot Stand Divided", text: "If Satan rises against himself and is divided, he cannot stand and his end has come. Jesus shows that the scribes' explanation does not make sense.", refs: ["Matthew 12:26","Luke 11:18"] },
  "Mark 3:27": { title: "Binding the Strong Man", text: "No one can enter a strong man's house and spoil his goods without first binding the strong man. Jesus portrays His deliverance of the oppressed as evidence that He is overcoming the power that held them.", refs: ["Matthew 12:29","Luke 11:21–22"] },
  "Mark 3:28": { title: "Forgiveness and Sin", text: "Jesus declares that sins and blasphemies can be forgiven unto the sons of men. The verse emphasizes the breadth of God's mercy, while the next verses give a serious warning about persistent blasphemy against the Holy Ghost.", refs: ["Acts 13:38–39","1 John 1:9"] },
  "Mark 3:29": { title: "Warning About Blasphemy Against the Holy Ghost", text: "Jesus warns that blasphemy against the Holy Ghost has no forgiveness and is described as an eternal sin. In context, the warning concerns attributing the work of God's Spirit to an unclean spirit; it is not a casual mistake or an anxious thought.", refs: ["Matthew 12:31–32","Luke 12:10"] },
  "Mark 3:30": { title: "Why Jesus Gives the Warning", text: "Mark explains that Jesus spoke this warning because they were saying He had an unclean spirit. The immediate context is deliberate rejection and evil misrepresentation of God's work.", refs: ["Mark 3:22","Matthew 12:24"] },
  "Mark 3:31": { title: "Jesus' Mother and Brothers Arrive", text: "Jesus' mother and brothers stand outside and send for Him. Mark presents the moment that leads Jesus to clarify the priority of doing God's will.", refs: ["Matthew 12:46","Luke 8:19"] },
  "Mark 3:32": { title: "The Crowd Tells Him", text: "The crowd sitting around Jesus says His mother and brothers are outside seeking Him. Their natural family relationship is real, but Jesus uses the occasion to teach about spiritual kinship.", refs: ["Luke 8:20","Matthew 12:47"] },
  "Mark 3:33": { title: "Who Is My Mother?", text: "Jesus asks who His mother and brothers are. He is not denying His family, but directing attention to the deeper bond formed by responding to God.", refs: ["Matthew 12:48","John 2:4"] },
  "Mark 3:34": { title: "Those Around Him", text: "Jesus looks at those seated around Him and identifies them as His mother and brothers in the sense He is teaching. The family of faith is gathered around Him as they hear and follow God's word.", refs: ["Luke 8:21","Romans 8:14–17"] },
  "Mark 3:35": { title: "Doing God's Will", text: "Whoever does the will of God is Jesus' brother, sister, and mother. Spiritual kinship is not based only on ancestry or proximity, but on a life responsive to God.", refs: ["Matthew 7:21","John 14:15"] },

  "Mark 4:1": { title: "The Parable by the Sea", text: "Jesus begins teaching beside the sea, and such a large crowd gathers that He enters a ship to teach from it. The setting allows the crowd to hear while Jesus uses familiar scenes from everyday life.", refs: ["Matthew 13:1–2","Luke 8:4"] },
  "Mark 4:2": { title: "Teaching in Parables", text: "Jesus teaches many things by parables. These stories use ordinary images to reveal spiritual truth and invite listeners to consider how they respond to God's word.", refs: ["Psalm 78:2","Matthew 13:34"] },
  "Mark 4:3": { title: "The Sower Goes Out", text: "Jesus tells the crowd to listen as a sower goes out to sow. The call to hear is important because the same word can meet different responses in different hearts.", refs: ["Matthew 13:3","Luke 8:5"] },
  "Mark 4:4": { title: "Seed by the Wayside", text: "Some seed falls by the wayside and birds devour it. In Jesus' later explanation, this represents the word being taken away before it takes root in the hearer.", refs: ["Mark 4:15","Matthew 13:4"] },
  "Mark 4:5": { title: "Seed on Stony Ground", text: "Some seed falls on shallow, stony ground where the soil is not deep. It springs up quickly, but its shallow beginning cannot sustain lasting growth.", refs: ["Mark 4:16–17","Matthew 13:5"] },
  "Mark 4:6": { title: "The Sun Scorches the Plant", text: "When the sun rises, the plant is scorched because it has no deep root and withers. Initial enthusiasm without rooted faith can fail under pressure.", refs: ["Mark 4:17","James 1:11–12"] },
  "Mark 4:7": { title: "Seed Among Thorns", text: "Other seed falls among thorns, which grow up and choke it so that it yields no fruit. Competing concerns can crowd out the word and prevent spiritual fruitfulness.", refs: ["Mark 4:18–19","Luke 8:7"] },
  "Mark 4:8": { title: "Seed on Good Ground", text: "Other seed falls into good ground and brings forth fruit in varying amounts. The word bears fruit where it is received and allowed to grow.", refs: ["Mark 4:20","Galatians 5:22–23"] },
  "Mark 4:9": { title: "Let the Hearer Hear", text: "Jesus says that the one who has ears to hear should hear. Hearing in this setting means more than sound reaching the ear; it calls for understanding and response.", refs: ["Revelation 2:7","Luke 8:18"] },
  "Mark 4:10": { title: "The Disciples Ask", text: "When Jesus is alone, those around Him with the Twelve ask Him about the parable. The disciples seek explanation rather than assuming they have understood everything.", refs: ["Matthew 13:10","Luke 8:9"] },
  "Mark 4:11": { title: "The Mystery of the Kingdom", text: "Jesus says the mystery of God's kingdom is given to His disciples, while those outside encounter the teaching in parables. A mystery here is truth God reveals, not a puzzle that human cleverness alone solves.", refs: ["1 Corinthians 2:7–10","Matthew 13:11"] },
  "Mark 4:12": { title: "Seeing and Hearing Without Understanding", text: "Jesus quotes language about seeing without perceiving and hearing without understanding, lest people turn and be forgiven. The passage warns of the hardening that comes when people repeatedly resist truth; it should be read alongside Scripture's invitations to repent and receive mercy.", refs: ["Isaiah 6:9–10","Acts 28:26–27"] },
  "Mark 4:13": { title: "Understanding the Parable", text: "Jesus asks how they will understand the other parables if they do not understand this one. The sower provides a foundation for recognizing the different ways people receive God's word.", refs: ["Matthew 13:18","Luke 8:11"] },
  "Mark 4:14": { title: "The Sower Sows the Word", text: "Jesus explains that the sower sows the word. The focus is the message of God and the varied conditions in which people hear it.", refs: ["Luke 8:11","1 Peter 1:23"] },
  "Mark 4:15": { title: "The Wayside Hearers", text: "Some hear the word, but Satan immediately takes away what was sown in their hearts. The verse describes spiritual opposition to the word before it can take root.", refs: ["Matthew 13:19","2 Corinthians 4:4"] },
  "Mark 4:16": { title: "Receiving the Word with Joy", text: "Stony-ground hearers receive the word immediately with gladness. Their first response is real, but it has not yet developed into deep endurance.", refs: ["Matthew 13:20","Acts 8:13"] },
  "Mark 4:17": { title: "Faith Tested by Trouble", text: "Because these hearers have no deep root, they endure only for a time; trouble or persecution causes them to stumble. Lasting discipleship requires rooted commitment, not enthusiasm alone.", refs: ["Colossians 2:6–7","John 16:1–4"] },
  "Mark 4:18": { title: "The Thorny Ground", text: "Others hear the word but are represented by seed sown among thorns. The danger is not merely refusing the word openly, but allowing other concerns to grow alongside it until they dominate.", refs: ["Matthew 13:22","Luke 8:14"] },
  "Mark 4:19": { title: "Cares, Riches, and Desires", text: "The cares of this world, deceitfulness of riches, and desires for other things choke the word, making it unfruitful. These pressures can quietly displace obedience and trust in God.", refs: ["Matthew 6:24–33","1 Timothy 6:9–10"] },
  "Mark 4:20": { title: "Good Ground Bears Fruit", text: "Those who hear the word, receive it, and bear fruit represent good ground. Fruitfulness varies, but genuine reception leads to a life changed by the word.", refs: ["John 15:5","Colossians 1:10"] },
  "Mark 4:21": { title: "A Lamp Is Not Hidden", text: "A lamp is not brought to be placed under a bushel or bed, but on a stand. Truth received from Jesus is meant to illuminate life, not be concealed as though it has no purpose.", refs: ["Matthew 5:15","Luke 8:16"] },
  "Mark 4:22": { title: "What Is Hidden Will Be Revealed", text: "Jesus teaches that hidden things will be brought to light. God's truth and people's true responses will not remain concealed forever.", refs: ["Luke 8:17","Ecclesiastes 12:14"] },
  "Mark 4:23": { title: "Hear and Take Heed", text: "Jesus again calls those with ears to hear to listen. The repeated appeal emphasizes the responsibility that comes with receiving His teaching.", refs: ["Mark 4:9","Revelation 3:6"] },
  "Mark 4:24": { title: "Take Heed What You Hear", text: "Jesus tells them to consider carefully what they hear; the measure they use will be measured to them, with more given to those who receive. The principle calls for attentive, generous responsiveness to truth.", refs: ["Luke 6:38","Matthew 7:2"] },
  "Mark 4:25": { title: "More to the One Who Has", text: "The one who has will receive more, while the one who has not will lose even what seems to be his. In context, receptive understanding grows, while neglected truth is lost.", refs: ["Matthew 13:12","Luke 19:26"] },
  "Mark 4:26": { title: "The Kingdom Like Seed Growing", text: "Jesus compares God's kingdom to a man scattering seed on the ground. The farmer participates in sowing, but growth unfolds through a process he does not control.", refs: ["Matthew 13:24","1 Corinthians 3:6–7"] },
  "Mark 4:27": { title: "Growth Beyond Human Control", text: "The man sleeps and rises while the seed sprouts and grows, though he does not know how. The image teaches that God's work has a life and process beyond human management.", refs: ["Ecclesiastes 11:5","John 3:8"] },
  "Mark 4:28": { title: "The Earth Brings Forth Fruit", text: "The earth produces first the blade, then the ear, then the full grain. Spiritual growth often unfolds in stages, and maturity should not be confused with the first sign of life.", refs: ["James 5:7","Philippians 1:6"] },
  "Mark 4:29": { title: "The Harvest Comes", text: "When the fruit is ready, the farmer puts in the sickle because harvest has come. God's purposes move toward a proper completion and appointed harvest.", refs: ["Joel 3:13","Matthew 13:39"] },
  "Mark 4:30": { title: "What Is the Kingdom Like?", text: "Jesus asks what comparison can explain God's kingdom. He chooses a small seed to illustrate how God's work may begin modestly and grow beyond its beginning.", refs: ["Matthew 13:31","Luke 13:18"] },
  "Mark 4:31": { title: "The Mustard Seed", text: "The mustard seed is described as very small among seeds sown in the earth. The comparison highlights the contrast between an unimpressive beginning and the growth that follows.", refs: ["Matthew 13:32","Zechariah 4:10"] },
  "Mark 4:32": { title: "A Great Plant from a Small Seed", text: "The mustard plant grows large branches where birds can lodge in its shade. Jesus emphasizes the kingdom's surprising growth from a small beginning; the point is the contrast, not a technical botanical lesson.", refs: ["Ezekiel 17:23","Daniel 4:12"] },
  "Mark 4:33": { title: "Teaching as They Could Hear", text: "Jesus speaks the word through many parables, according to what the people are able to hear. His teaching meets listeners where they are while still calling them toward deeper understanding.", refs: ["John 16:12","Matthew 13:34"] },
  "Mark 4:34": { title: "Jesus Explains to His Disciples", text: "Jesus does not speak to the crowd without parables, but explains matters privately to His disciples. Those who follow Him are invited to seek and receive fuller understanding.", refs: ["Mark 4:10–11","Matthew 13:36"] },
  "Mark 4:35": { title: "Crossing to the Other Side", text: "That same day Jesus tells His disciples to cross to the other side. They obey His direction, but the journey soon tests their confidence in Him.", refs: ["Luke 8:22","Matthew 8:18"] },
  "Mark 4:36": { title: "They Take Jesus in the Ship", text: "The disciples take Jesus as He is in the ship, and other boats are with them. The account moves from teaching about the kingdom to a demonstration of Jesus' authority amid danger.", refs: ["Luke 8:22","Matthew 8:23"] },
  "Mark 4:37": { title: "A Great Storm Arises", text: "A fierce windstorm sends waves into the ship until it is filling with water. Following Jesus does not mean disciples will never face frightening circumstances.", refs: ["Psalm 107:25–29","Matthew 8:24"] },
  "Mark 4:38": { title: "Jesus Sleeps in the Storm", text: "Jesus is asleep in the back of the ship, and the disciples wake Him, asking whether He cares that they are perishing. His sleep shows genuine human weariness; their fear reveals how hard it is to trust while danger feels immediate.", refs: ["Psalm 121:4","Matthew 8:25"] },
  "Mark 4:39": { title: "Peace, Be Still", text: "Jesus rebukes the wind and commands the sea to be still, and the storm becomes calm. The scene displays extraordinary authority over creation, echoing the Old Testament's portrayal of the LORD ruling the sea.", refs: ["Psalm 89:9","Psalm 107:29","Matthew 8:26"] },
  "Mark 4:40": { title: "Why Are You So Fearful?", text: "Jesus asks why they are afraid and whether they still lack faith. He calls them to trust Him even when circumstances seem beyond their control.", refs: ["Matthew 8:26","Isaiah 41:10"] },
  "Mark 4:41": { title: "Who Then Is This?", text: "The disciples fear greatly and ask who Jesus is, since even wind and sea obey Him. Mark leaves the question ringing: His works reveal an authority that calls for deeper recognition of His identity.", refs: ["Psalm 107:29","Job 38:8–11","Mark 1:27"] }
});

Object.assign(window.verseCommentary, {
  "Mark 5:1": { title: "Jesus Comes to the Gadarenes", text: "Jesus and His disciples arrive on the other side of the sea in the country of the Gadarenes. The crossing leads to a meeting with a man in severe spiritual and social distress.", refs: ["Matthew 8:28","Luke 8:26"] },
  "Mark 5:2": { title: "A Man with an Unclean Spirit", text: "As Jesus leaves the ship, a man with an unclean spirit comes from the tombs to meet Him. The man's condition has isolated him among places associated with death.", refs: ["Luke 8:27","Mark 1:23"] },
  "Mark 5:3": { title: "Living Among the Tombs", text: "The man lives among the tombs, and no one can restrain him even with chains. His bondage is beyond ordinary human control, setting the stage for Jesus' authority to deliver him.", refs: ["Mark 5:4","Luke 8:29"] },
  "Mark 5:4": { title: "No Chains Can Hold Him", text: "He has repeatedly broken fetters and chains, and no one has strength to tame him. The account emphasizes the severity of his oppression, not a model for treating troubled people with force.", refs: ["Mark 5:3","Luke 8:29"] },
  "Mark 5:5": { title: "Tormented Day and Night", text: "The man cries out among the mountains and tombs and cuts himself with stones. His misery is extreme; Jesus approaches him to bring restoration rather than leaving him in despair.", refs: ["Luke 8:27","Psalm 107:10–14"] },
  "Mark 5:6": { title: "He Runs to Jesus", text: "Seeing Jesus from afar, the man runs and worships Him. Even amid the disorder described, the encounter brings him directly before the One who has authority to help.", refs: ["Mark 3:11","Matthew 8:2"] },
  "Mark 5:7": { title: "The Spirit Cries Out", text: "The unclean spirit cries out and recognizes Jesus as Son of the most high God, pleading not to be tormented. The spiritual recognition is not the same as willing obedience or saving faith.", refs: ["Mark 1:24","James 2:19"] },
  "Mark 5:8": { title: "Come Out of the Man", text: "Jesus has commanded the unclean spirit to come out of the man. The command shows that the authority belongs to Jesus, not to the spirit that has enslaved the man.", refs: ["Luke 8:29","Mark 1:25"] },
  "Mark 5:9": { title: "My Name Is Legion", text: "Jesus asks the spirit its name, and the reply is Legion because many spirits are involved. The word conveys the scale of the oppression; the man himself remains the person in need of deliverance.", refs: ["Luke 8:30","Matthew 12:43–45"] },
  "Mark 5:10": { title: "A Plea Not to Leave the Region", text: "The spirits beg Jesus not to send them away out of the country. Their plea reveals that they are subject to His authority and cannot dictate the outcome.", refs: ["Luke 8:31","Mark 1:27"] },
  "Mark 5:11": { title: "A Herd of Swine", text: "A large herd of swine is feeding nearby on the mountainside. The detail prepares for the unusual event that follows and shows the setting was outside ordinary Jewish purity practice.", refs: ["Luke 8:32","Matthew 8:30"] },
  "Mark 5:12": { title: "The Spirits Ask to Enter the Swine", text: "The spirits beg Jesus to send them into the swine. Even their request is made to Jesus, showing that they do not act with independent authority over the situation.", refs: ["Luke 8:32","Mark 5:10"] },
  "Mark 5:13": { title: "The Herd Rushes into the Sea", text: "Jesus permits it, and the spirits enter the herd, which rushes down the steep place into the sea and drowns. The event displays the destructive nature of the oppression and the dramatic release of the man; the passage does not give every detail of why this particular outcome was permitted.", refs: ["Matthew 8:32","Luke 8:33"] },
  "Mark 5:14": { title: "The Keepers Report It", text: "Those tending the swine flee and report what happened in the city and countryside. The extraordinary event quickly becomes public news.", refs: ["Luke 8:34","Mark 5:16"] },
  "Mark 5:15": { title: "The Man Is Restored", text: "People see the formerly possessed man sitting, clothed, and in his right mind, and they become afraid. The visible change is a testimony to the deliverance Jesus has brought.", refs: ["Luke 8:35","Isaiah 61:1"] },
  "Mark 5:16": { title: "Witnesses Explain the Event", text: "Those who saw it describe what happened to the man and the swine. The people must decide how they will respond to the evidence before them.", refs: ["Mark 5:14–15","Luke 8:36"] },
  "Mark 5:17": { title: "They Ask Jesus to Leave", text: "The people begin asking Jesus to depart from their borders. Fear or concern over the loss may have shaped their response, but they turn away from the One who restored the man.", refs: ["Luke 8:37","John 3:19–20"] },
  "Mark 5:18": { title: "The Delivered Man Wants to Follow", text: "As Jesus enters the ship, the restored man begs to be with Him. His desire is understandable: the One who has rescued him has become the center of his new life.", refs: ["Luke 8:38","Psalm 116:1–2"] },
  "Mark 5:19": { title: "Go Home and Tell", text: "Jesus does not permit the man to join the boat party, but tells him to go home and tell how great things the Lord has done and shown him mercy. The man is sent to testify in his own community.", refs: ["Luke 8:39","Psalm 66:16"] },
  "Mark 5:20": { title: "He Proclaims Jesus' Work", text: "The man begins proclaiming in Decapolis how great things Jesus has done, and people marvel. Mark's wording connects the Lord's mercy directly with Jesus' action, a significant testimony to Jesus' divine authority.", refs: ["Luke 8:39","Isaiah 35:5–6"] },
  "Mark 5:21": { title: "A Crowd Welcomes Jesus Back", text: "Jesus crosses again by ship, and a great crowd gathers around Him by the sea. The next account shows another desperate request for help.", refs: ["Luke 8:40","Mark 4:35"] },
  "Mark 5:22": { title: "Jairus Comes to Jesus", text: "Jairus, a ruler of the synagogue, falls at Jesus' feet. His position does not keep him from humbly seeking help for his daughter.", refs: ["Luke 8:41","Matthew 9:18"] },
  "Mark 5:23": { title: "A Daughter Near Death", text: "Jairus urgently asks Jesus to come and lay hands on his little daughter so she may be healed and live. His request expresses both desperation and trust in Jesus' ability to help.", refs: ["Luke 8:42","Matthew 9:18"] },
  "Mark 5:24": { title: "Jesus Goes with Jairus", text: "Jesus goes with him, and the crowd presses around Him. Jesus responds to the father's plea even amid the demands of the crowd.", refs: ["Luke 8:42","Mark 2:2"] },
  "Mark 5:25": { title: "A Woman with an Issue of Blood", text: "A woman has suffered from an issue of blood for twelve years. Her long illness has brought ongoing suffering and need.", refs: ["Luke 8:43","Leviticus 15:25"] },
  "Mark 5:26": { title: "Many Physicians, No Relief", text: "She has suffered under many physicians, spent what she had, and grown worse. Mark describes her hardship compassionately, not as a condemnation of all medical care.", refs: ["Luke 8:43","Jeremiah 30:13"] },
  "Mark 5:27": { title: "She Touches Jesus' Garment", text: "Hearing about Jesus, the woman comes in the crowd behind Him and touches His garment. Faith moves her to approach Jesus despite her long suffering.", refs: ["Matthew 9:20","Luke 8:44"] },
  "Mark 5:28": { title: "If I May Touch His Clothes", text: "She believes that even touching His clothes will make her whole. Her confidence is directed toward Jesus, not toward fabric as a magical object.", refs: ["Matthew 9:21","Hebrews 11:6"] },
  "Mark 5:29": { title: "She Is Healed", text: "Immediately the flow of blood stops, and she knows in her body that she is healed. The healing is presented as a real change after years of suffering.", refs: ["Luke 8:44","Mark 5:34"] },
  "Mark 5:30": { title: "Jesus Knows Power Has Gone Out", text: "Jesus perceives that power has gone out from Him and asks who touched His clothes. The question brings the hidden healing into the open so the woman can be personally acknowledged.", refs: ["Luke 8:45–46","Matthew 9:22"] },
  "Mark 5:31": { title: "The Disciples Notice the Crowd", text: "The disciples point out that the crowd is pressing around Jesus and ask how He can ask who touched Him. They see the many physical contacts but do not yet know about the woman's particular act of faith.", refs: ["Luke 8:45","Mark 3:9–10"] },
  "Mark 5:32": { title: "Jesus Looks for the Woman", text: "Jesus looks around to see who has done this. He does not let the healing remain an anonymous incident; He gives the woman an opportunity to come forward.", refs: ["Luke 8:47","Mark 10:49"] },
  "Mark 5:33": { title: "The Woman Tells the Truth", text: "The woman comes trembling, falls before Jesus, and tells Him the whole truth. Her fear gives way to an honest encounter with the One who has healed her.", refs: ["Luke 8:47","Psalm 32:5"] },
  "Mark 5:34": { title: "Daughter, Thy Faith Hath Made Thee Whole", text: "Jesus calls her daughter, tells her to go in peace, and confirms her healing. His words restore dignity as well as health, and the faith praised is trust that brought her to Him.", refs: ["Matthew 9:22","Luke 8:48"] },
  "Mark 5:35": { title: "News of the Daughter's Death", text: "Messengers arrive saying Jairus' daughter is dead and ask why he should trouble Jesus further. Their conclusion assumes that death has ended every possibility of help.", refs: ["Luke 8:49","John 11:21"] },
  "Mark 5:36": { title: "Believe Only", text: "Jesus tells Jairus not to fear, but to believe. He calls the father to trust Him even when the news seems final.", refs: ["Luke 8:50","Isaiah 41:10"] },
  "Mark 5:37": { title: "Only Three Disciples Enter", text: "Jesus allows Peter, James, and John to accompany Him. The smaller group witnesses the coming sign of His authority over death.", refs: ["Mark 9:2","Mark 14:33"] },
  "Mark 5:38": { title: "Mourning at the House", text: "Jesus sees the commotion, those weeping, and those wailing greatly. The grief is real, and the miracle does not treat the family's sorrow as insignificant.", refs: ["Luke 8:52","John 11:33"] },
  "Mark 5:39": { title: "The Child Is Not Dead but Sleeping", text: "Jesus says the child is not dead but sleeping, and the people laugh at Him. He describes death in terms of the restoration He is about to bring, not because the mourners have no reason to grieve.", refs: ["John 11:11–14","Matthew 9:24"] },
  "Mark 5:40": { title: "The Mockers Are Put Out", text: "After the people laugh, Jesus puts them out and takes the child's parents and His three disciples into the room. The miracle is witnessed by a small group rather than staged for the crowd.", refs: ["Luke 8:51","Matthew 9:25"] },
  "Mark 5:41": { title: "Talitha Cumi", text: "Jesus takes the child by the hand and says, 'Talitha cumi,' meaning, 'Damsel, I say unto thee, arise.' His personal command brings life where others believed the situation was beyond hope.", refs: ["Luke 8:54","Acts 9:40"] },
  "Mark 5:42": { title: "The Girl Rises and Walks", text: "The twelve-year-old girl immediately rises and walks, and those present are astonished. Jesus demonstrates authority over death while the girl's age and ordinary action emphasize her full restoration.", refs: ["Matthew 9:25","John 11:43–44"] },
  "Mark 5:43": { title: "Give Her Something to Eat", text: "Jesus strictly charges them not to publicize the event and tells them to give the girl food. Her need for food confirms her return to ordinary life, and Jesus' instruction shows practical care after a miracle.", refs: ["Luke 8:55–56","Mark 1:44"] }
});

Object.assign(window.verseCommentary, {
  "Mark 6:1": { title: "Jesus Returns to His Own Country", text: "Jesus comes to His hometown with His disciples. Familiarity gives the people an opportunity to hear Him, but it also becomes a stumbling block for some.", refs: ["Matthew 13:54","Luke 4:16"] },
  "Mark 6:2": { title: "The Sabbath Teaching", text: "Jesus teaches in the synagogue, and many are astonished by His wisdom and mighty works. Their amazement turns into questions about how someone they know could speak with such authority.", refs: ["Matthew 13:54","John 7:15"] },
  "Mark 6:3": { title: "Is Not This the Carpenter?", text: "Some identify Jesus as the carpenter, Mary's son, and brother of James, Joses, Juda, and Simon, and they mention His sisters. They focus on His ordinary family background and take offense rather than recognizing God's work through Him.", refs: ["Matthew 13:55–57","John 6:42"] },
  "Mark 6:4": { title: "A Prophet Without Honour", text: "Jesus says a prophet is not without honour except in his own country, among relatives, and in his own house. Familiarity can cause people to dismiss truth instead of weighing it honestly.", refs: ["Luke 4:24","John 4:44"] },
  "Mark 6:5": { title: "Few Mighty Works There", text: "Jesus lays hands on a few sick people and heals them, while the town's unbelief is emphasized. The verse does not mean Jesus lacked divine power; Mark describes the limited reception and ministry in that setting.", refs: ["Matthew 13:58","Mark 9:23"] },
  "Mark 6:6": { title: "Jesus Marvels at Unbelief", text: "Jesus marvels at their unbelief and goes through the villages teaching. Their rejection does not stop His mission; He continues taking God's word to others.", refs: ["Matthew 13:58","Luke 4:30–31"] },
  "Mark 6:7": { title: "The Twelve Are Sent Out", text: "Jesus calls the Twelve and sends them out two by two, giving them authority over unclean spirits. Their ministry is delegated and remains dependent on the One who sends them.", refs: ["Matthew 10:1","Luke 9:1–2"] },
  "Mark 6:8": { title: "Travel Light", text: "Jesus instructs them to take little for the journey, allowing a staff but not extra provisions. The mission calls for trust in God's provision rather than reliance on elaborate supplies.", refs: ["Matthew 10:9–10","Luke 9:3"] },
  "Mark 6:9": { title: "Sandals and One Coat", text: "They are to wear sandals and not carry two coats. The details reinforce simplicity and readiness for the work entrusted to them.", refs: ["Luke 9:3","Matthew 10:10"] },
  "Mark 6:10": { title: "Remain in One House", text: "Jesus tells them to stay in the house where they are welcomed until they leave that place. This keeps the mission focused and discourages seeking more comfortable accommodation.", refs: ["Luke 9:4","Matthew 10:11"] },
  "Mark 6:11": { title: "A Witness Against Rejection", text: "Where people refuse to receive them or hear them, the disciples are to depart and shake off the dust from their feet as a testimony. The sign marks responsibility for rejecting the message; it is not permission for personal revenge.", refs: ["Matthew 10:14–15","Acts 13:51"] },
  "Mark 6:12": { title: "They Preach Repentance", text: "The disciples go out preaching that people should repent. Repentance means turning from sin toward God, not merely feeling regret.", refs: ["Matthew 4:17","Acts 2:38"] },
  "Mark 6:13": { title: "Healing and Deliverance", text: "They cast out many devils, anoint many sick people with oil, and heal them. Their acts of ministry point people toward God's mercy and the authority given by Jesus.", refs: ["James 5:14","Luke 9:6"] },
  "Mark 6:14": { title: "Herod Hears of Jesus", text: "King Herod hears of Jesus because His name has become widely known. Different explanations circulate about Jesus' identity, revealing the public uncertainty surrounding His ministry.", refs: ["Matthew 14:1–2","Luke 9:7"] },
  "Mark 6:15": { title: "Various Ideas About Jesus", text: "Some say Jesus is John the Baptist risen from the dead, while others identify Him with Elijah or a prophet. These views recognize that something extraordinary is happening but do not yet identify Him fully.", refs: ["Mark 8:28","Malachi 4:5"] },
  "Mark 6:16": { title: "Herod's Fearful Conclusion", text: "Herod says that John, whom he beheaded, has risen again. His guilty conscience shapes how he interprets the reports about Jesus.", refs: ["Matthew 14:2","Mark 6:27–29"] },
  "Mark 6:17": { title: "John Imprisoned", text: "Mark recounts how Herod had arrested John and imprisoned him because of Herodias, his brother Philip's wife. John's prophetic faithfulness brings him into conflict with the ruler's household.", refs: ["Matthew 14:3","Luke 3:19–20"] },
  "Mark 6:18": { title: "John Rebukes Herod", text: "John had told Herod that it was unlawful for him to have his brother's wife. A prophet's responsibility includes speaking truth to power when conduct violates God's law.", refs: ["Leviticus 18:16","Matthew 14:4"] },
  "Mark 6:19": { title: "Herodias Holds a Grudge", text: "Herodias bears a grudge against John and wants him killed, but cannot immediately carry it out. Her resentment grows from a refusal to accept correction.", refs: ["Matthew 14:5","Proverbs 29:1"] },
  "Mark 6:20": { title: "Herod Fears John", text: "Herod fears John, knows him to be just and holy, and hears him gladly, though he is perplexed. The account shows that recognizing a righteous messenger is not the same as obeying the truth he speaks.", refs: ["Matthew 14:5","James 1:22"] },
  "Mark 6:21": { title: "Herod's Birthday Feast", text: "A convenient day comes when Herod gives a feast for officials and leading men of Galilee. The setting of public celebration becomes the occasion for a destructive promise.", refs: ["Matthew 14:6","Proverbs 23:1–3"] },
  "Mark 6:22": { title: "The Daughter Dances", text: "Herodias' daughter dances and pleases Herod and his guests. Herod makes an extravagant offer before the company, allowing pride and spectacle to shape his judgment.", refs: ["Matthew 14:6–7","Proverbs 29:20"] },
  "Mark 6:23": { title: "An Oath Made Rashly", text: "Herod swears to give the girl whatever she asks, up to half his kingdom. A reckless oath made for public approval becomes a trap rather than a sign of honour.", refs: ["Esther 5:3","Matthew 14:7"] },
  "Mark 6:24": { title: "She Asks Her Mother", text: "The girl asks her mother what she should request, and Herodias tells her to ask for John the Baptist's head. The mother uses the opportunity to pursue vengeance against the prophet.", refs: ["Matthew 14:8","Mark 6:19"] },
  "Mark 6:25": { title: "The Request Is Made", text: "The girl quickly returns and asks for John's head on a charger immediately. The demand exposes the cruelty hidden beneath the feast's outward celebration.", refs: ["Matthew 14:8","Proverbs 1:16"] },
  "Mark 6:26": { title: "Herod Is Exceedingly Sorry", text: "Herod is deeply sorry, yet because of his oath and the guests he does not want to refuse her. He values appearances and his own public word above justice and the life of an innocent man.", refs: ["Matthew 14:9","Proverbs 29:25"] },
  "Mark 6:27": { title: "John Is Beheaded", text: "Herod sends an executioner to behead John in prison. The account records the cost of prophetic faithfulness in a corrupt political setting.", refs: ["Matthew 14:10","Mark 1:14"] },
  "Mark 6:28": { title: "John's Head Is Delivered", text: "The executioner brings John's head on a charger and gives it to the girl, who gives it to her mother. The chilling sequence shows how far Herodias' hatred has gone.", refs: ["Matthew 14:11","Mark 6:24–25"] },
  "Mark 6:29": { title: "John's Disciples Bury Him", text: "When John's disciples hear what happened, they take his body and lay it in a tomb. They honour their teacher in grief, and John's death anticipates the opposition Jesus Himself will face.", refs: ["Matthew 14:12","Mark 1:14"] },
  "Mark 6:30": { title: "The Apostles Return", text: "The apostles gather around Jesus and report what they have done and taught. Ministry includes both serving others and returning to Jesus to account for the work.", refs: ["Luke 9:10","Mark 6:7–13"] },
  "Mark 6:31": { title: "Come Apart and Rest", text: "Because many people are coming and going and the disciples have no leisure even to eat, Jesus invites them to a quiet place to rest. Compassionate service includes recognizing human limits and the need for rest.", refs: ["Matthew 14:13","Mark 3:20"] },
  "Mark 6:32": { title: "They Depart by Ship", text: "Jesus and His disciples leave by ship for a quiet place apart. The attempt to rest is soon interrupted by the needs of the crowd.", refs: ["Luke 9:10","Matthew 14:13"] },
  "Mark 6:33": { title: "The Crowd Runs Ahead", text: "People see them departing and many recognize them; they run on foot and arrive before the boat. The crowd's eagerness makes solitude difficult.", refs: ["Matthew 14:13","John 6:2"] },
  "Mark 6:34": { title: "Sheep Without a Shepherd", text: "Jesus sees the great crowd and is moved with compassion because they are like sheep without a shepherd. He begins teaching them many things, meeting their spiritual need before addressing their hunger.", refs: ["Matthew 9:36","Ezekiel 34:5","John 10:11"] },
  "Mark 6:35": { title: "The Day Grows Late", text: "The disciples point out that the place is solitary and the hour is late. They see a practical problem and expect the people to be sent away.", refs: ["Matthew 14:15","Luke 9:12"] },
  "Mark 6:36": { title: "Send Them Away to Buy Food", text: "The disciples suggest sending the people to nearby villages to buy food. Their proposal is practical, but Jesus will teach them to bring the need to Him.", refs: ["Luke 9:12","John 6:5"] },
  "Mark 6:37": { title: "You Give Them to Eat", text: "Jesus tells the disciples to feed the crowd, and they question the cost of buying bread. His command exposes the limits of their resources and invites them to rely on His provision.", refs: ["John 6:5–7","Matthew 14:16"] },
  "Mark 6:38": { title: "Five Loaves and Two Fishes", text: "Jesus asks what food they have and tells them to look. They report five loaves and two fish, a small supply compared with the need.", refs: ["John 6:8–9","Matthew 14:17"] },
  "Mark 6:39": { title: "Sit Down on the Green Grass", text: "Jesus directs the people to sit in groups on the green grass. Orderly preparation makes it possible to serve the large crowd.", refs: ["Luke 9:14–15","Psalm 23:1–2"] },
  "Mark 6:40": { title: "Groups of Hundreds and Fifties", text: "The people sit in ranks, in groups of hundreds and fifties. The organized crowd is ready to receive what Jesus provides.", refs: ["Luke 9:14","Exodus 18:21"] },
  "Mark 6:41": { title: "Jesus Blesses and Breaks the Bread", text: "Jesus takes the loaves and fish, looks up to heaven, blesses, breaks the loaves, and gives them to the disciples to distribute. His action expresses dependence and thanksgiving to God, while the abundance that follows displays His extraordinary provision.", refs: ["John 6:11","Matthew 14:19"] },
  "Mark 6:42": { title: "All Eat and Are Filled", text: "Everyone eats and is satisfied. Jesus does not merely offer a token meal; the provision meets the crowd's need.", refs: ["Matthew 14:20","Psalm 107:9"] },
  "Mark 6:43": { title: "Twelve Baskets Remain", text: "The disciples gather twelve baskets of fragments and fish. The leftovers testify to the abundance of the provision, not waste or scarcity.", refs: ["John 6:12–13","Matthew 14:20"] },
  "Mark 6:44": { title: "Five Thousand Men Fed", text: "About five thousand men eat the loaves. The scale of the miracle underscores that the result far exceeded the small supply the disciples first identified.", refs: ["Luke 9:14–17","John 6:10"] },
  "Mark 6:45": { title: "Jesus Sends Them Away", text: "Jesus immediately sends His disciples by ship toward Bethsaida while He dismisses the crowd. He directs the next steps of His disciples after the miracle.", refs: ["Matthew 14:22","John 6:16–17"] },
  "Mark 6:46": { title: "Jesus Prays on the Mountain", text: "After dismissing the people, Jesus goes up a mountain to pray. His public ministry is accompanied by private communion with God.", refs: ["Luke 5:16","Matthew 14:23"] },
  "Mark 6:47": { title: "The Ship Is in the Sea", text: "Evening comes, and the ship is in the middle of the sea while Jesus remains alone on land. The disciples are separated from Him as difficult conditions develop.", refs: ["John 6:17","Matthew 14:24"] },
  "Mark 6:48": { title: "Jesus Sees Them Straining", text: "Jesus sees the disciples straining at the oars because the wind is against them, and comes to them walking on the sea. His coming shows authority over the very conditions that trouble them.", refs: ["Matthew 14:25","Job 9:8"] },
  "Mark 6:49": { title: "They Think He Is a Spirit", text: "The disciples see Jesus walking on the sea and suppose He is a spirit, crying out in fear. They misinterpret what they see because terror overwhelms their understanding.", refs: ["Matthew 14:26","Luke 24:37"] },
  "Mark 6:50": { title: "Be of Good Cheer", text: "They are troubled, but Jesus immediately speaks: be of good cheer, it is I; be not afraid. His presence and words answer their fear before the wind is calmed.", refs: ["Matthew 14:27","Isaiah 43:1–2"] },
  "Mark 6:51": { title: "The Wind Ceases", text: "Jesus enters the ship and the wind ceases, leaving the disciples amazed. His authority over the sea echoes Scripture's witness that God rules the waters.", refs: ["Psalm 107:29","Matthew 14:32"] },
  "Mark 6:52": { title: "Their Hearts Were Hardened", text: "The disciples are astonished because they had not understood the miracle of the loaves, their hearts being hardened. They have witnessed provision but still struggle to grasp what Jesus' works reveal about Him.", refs: ["Mark 8:17–21","Mark 4:41"] },
  "Mark 6:53": { title: "They Arrive at Gennesaret", text: "The boat reaches the land of Gennesaret and is brought to shore. The ministry of healing resumes among the people there.", refs: ["Matthew 14:34","John 6:21"] },
  "Mark 6:54": { title: "The People Recognize Jesus", text: "When Jesus and His disciples leave the ship, the people immediately recognize Him. His reputation has spread through the region.", refs: ["Matthew 14:35","Mark 1:28"] },
  "Mark 6:55": { title: "The Sick Are Brought to Him", text: "People run through the whole region and carry the sick on beds to wherever they hear Jesus is. Their effort reflects urgent hope in His healing power.", refs: ["Matthew 14:35","Mark 2:3"] },
  "Mark 6:56": { title: "Those Who Touch His Garment Are Healed", text: "Wherever Jesus enters villages, cities, or countryside, people lay the sick in public places and beg to touch even the border of His garment; those who touch Him are made whole. The garment is not a charm: the narrative presents Jesus as the source of healing.", refs: ["Matthew 14:36","Mark 5:27–34"] }
});

Object.assign(window.verseCommentary, {
  "Mark 7:1": { title: "Pharisees Come from Jerusalem", text: "Pharisees and scribes gather around Jesus. Their challenge concerns traditions about ceremonial washing and what truly defiles a person.", refs: ["Matthew 15:1","Luke 11:37"] },
  "Mark 7:2": { title: "Unwashed Hands", text: "They notice some disciples eating with hands considered ceremonially unwashed. Mark describes a dispute over ritual practice, not a claim that ordinary cleanliness is unimportant.", refs: ["Matthew 15:2","Exodus 30:18–21"] },
  "Mark 7:3": { title: "The Tradition of the Elders", text: "Mark explains that the Pharisees and many Jews observe traditions about washing hands before eating. The issue is whether human traditions are treated as binding commands from God.", refs: ["Matthew 15:2","Galatians 1:14"] },
  "Mark 7:4": { title: "Many Ceremonial Washings", text: "Mark describes washing after coming from the marketplace and inherited practices concerning vessels. The passage distinguishes ceremonial customs from the moral commands God gives.", refs: ["Leviticus 11:32","Colossians 2:20–23"] },
  "Mark 7:5": { title: "Why Not Follow Tradition?", text: "The leaders ask why Jesus' disciples do not walk according to the tradition of the elders. Jesus answers by examining whether their traditions preserve or undermine God's commandments.", refs: ["Matthew 15:2","Isaiah 29:13"] },
  "Mark 7:6": { title: "Honouring God with the Lips", text: "Jesus quotes Isaiah: the people honour God with their lips while their heart is far from Him. Outward religious speech cannot substitute for sincere devotion.", refs: ["Isaiah 29:13","Matthew 15:7–8"] },
  "Mark 7:7": { title: "Teaching Human Commandments", text: "Jesus says worship is vain when people teach human commandments as doctrines. Religious customs must never be elevated above God's revealed word.", refs: ["Matthew 15:9","Colossians 2:22"] },
  "Mark 7:8": { title: "Leaving God's Commandment", text: "Jesus says they leave God's commandment and hold human traditions. Tradition becomes dangerous when it displaces obedience to God.", refs: ["Mark 7:13","Deuteronomy 4:2"] },
  "Mark 7:9": { title: "Rejecting God's Commandment", text: "Jesus says they reject God's commandment in order to keep their own tradition. A custom must be judged by Scripture, not Scripture adjusted to protect a custom.", refs: ["Matthew 15:3","Mark 7:13"] },
  "Mark 7:10": { title: "Honour Father and Mother", text: "Jesus cites the command to honour father and mother and the judgment attached to cursing them. He grounds His argument in the written word of God.", refs: ["Exodus 20:12","Exodus 21:17"] },
  "Mark 7:11": { title: "The Corban Excuse", text: "Some claim that support which could help their parents is Corban, a gift dedicated to God. The religious label is used as an excuse to evade a clear family responsibility.", refs: ["Matthew 15:5","Leviticus 27:28"] },
  "Mark 7:12": { title: "Parents Left Without Help", text: "Under this tradition, a person is no longer allowed to do anything for his parents. Jesus exposes a rule that uses religious language to prevent obedience to God's command.", refs: ["Mark 7:10–11","1 Timothy 5:4"] },
  "Mark 7:13": { title: "Making God's Word of None Effect", text: "Jesus says they make God's word ineffective through their tradition and do many similar things. Religious teaching should be tested by whether it leads people to honour what God commanded.", refs: ["Matthew 15:6","Isaiah 8:20"] },
  "Mark 7:14": { title: "Hear and Understand", text: "Jesus calls the crowd to hear and understand. He shifts the question from external ritual status to the moral and spiritual condition of the heart.", refs: ["Matthew 15:10","Mark 4:9"] },
  "Mark 7:15": { title: "What Defiles a Person", text: "Jesus teaches that what enters from outside does not defile the heart; what comes out from within does. In context He challenges the idea that ritual food contact is the root of moral uncleanness.", refs: ["Matthew 15:11","Acts 10:15"] },
  "Mark 7:16": { title: "A Call to Hear", text: "This verse appears in some later manuscripts but is omitted from many modern critical-text editions. Its familiar call to hear reinforces the passage's emphasis on attentive understanding.", refs: ["Mark 4:9","Mark 7:14"] },
  "Mark 7:17": { title: "The Disciples Ask Privately", text: "Away from the crowd, the disciples ask Jesus about the saying. Even close followers need instruction to understand His teaching.", refs: ["Matthew 15:15","Mark 4:10"] },
  "Mark 7:18": { title: "Food Does Not Enter the Heart", text: "Jesus explains that food entering from outside does not enter the heart. He distinguishes physical digestion from the moral source of sin.", refs: ["Matthew 15:16–17","1 Corinthians 8:8"] },
  "Mark 7:19": { title: "The Body and the Heart", text: "Food passes through the digestive system rather than the heart; Mark adds that Jesus thereby declared all foods clean. The statement concerns ceremonial food distinctions, while Scripture continues to condemn greed and other sins of the heart.", refs: ["Acts 10:15","Romans 14:14","1 Timothy 4:4–5"] },
  "Mark 7:20": { title: "What Comes from Within", text: "Jesus says that what comes out of a person is what defiles. The core problem is not merely external contact but sinful thoughts and actions arising from within.", refs: ["Matthew 15:18","Jeremiah 17:9"] },
  "Mark 7:21": { title: "Evil Thoughts", text: "Jesus lists evil thoughts and sexual sins among the things that proceed from the heart. His diagnosis reaches the inner source of wrongdoing, not only its visible effects.", refs: ["Matthew 15:19","Genesis 6:5"] },
  "Mark 7:22": { title: "Sins of Desire and Speech", text: "Jesus lists thefts, covetousness, wickedness, deceit, envy, blasphemy, pride, and foolishness. The list shows how many forms of sin grow from a heart not submitted to God.", refs: ["Galatians 5:19–21","Romans 1:29–31"] },
  "Mark 7:23": { title: "These Things Defile", text: "Jesus concludes that evil things come from within and defile the person. True cleansing requires more than external religious observance; it calls for a heart transformed by God.", refs: ["Psalm 51:10","Ezekiel 36:26"] },
  "Mark 7:24": { title: "Jesus Goes to Tyre", text: "Jesus travels to the region of Tyre and enters a house, wishing that no one know He is there, but He cannot remain hidden. His mission crosses familiar boundaries as people seek Him.", refs: ["Matthew 15:21","Luke 6:17"] },
  "Mark 7:25": { title: "A Mother Seeks Jesus", text: "A woman whose young daughter has an unclean spirit hears about Jesus and comes to Him. A mother's concern brings her to seek help from the One she believes can deliver her child.", refs: ["Matthew 15:22","Mark 5:22"] },
  "Mark 7:26": { title: "A Greek Woman of Syrophenicia", text: "The woman is a Gentile from Syrophenicia and begs Jesus to cast the devil out of her daughter. The encounter raises Israel's priority in the messianic mission and the mercy that reaches beyond Israel.", refs: ["Matthew 15:22","Isaiah 49:6"] },
  "Mark 7:27": { title: "The Children's Bread", text: "Jesus speaks of the children being fed first and says it is not right to take their bread and cast it to dogs. The saying expresses the order of His earthly mission to Israel, not a denial that Gentiles can receive God's mercy.", refs: ["Matthew 15:24–26","Romans 1:16"] },
  "Mark 7:28": { title: "Even the Dogs Eat Crumbs", text: "The woman answers that even the dogs under the table eat the children's crumbs. She humbly persists and trusts that Jesus' abundance is sufficient even for those outside Israel's covenant priority.", refs: ["Matthew 15:27","Ephesians 2:12–13"] },
  "Mark 7:29": { title: "Her Daughter Is Delivered", text: "Jesus tells her to go her way because the devil has gone out of her daughter. Her persistent faith meets Jesus' authority, and deliverance is granted.", refs: ["Matthew 15:28","John 4:50–53"] },
  "Mark 7:30": { title: "The Child Found Well", text: "The woman returns home and finds her daughter lying on the bed, with the devil gone. The result confirms the effectiveness of Jesus' word even at a distance.", refs: ["Matthew 15:28","Mark 1:27"] },
  "Mark 7:31": { title: "Through Decapolis", text: "Jesus leaves Tyre, travels through Sidon, and comes to the Sea of Galilee through Decapolis. Mark traces His movement through predominantly Gentile territory.", refs: ["Matthew 15:29","Mark 5:20"] },
  "Mark 7:32": { title: "A Deaf Man with a Speech Difficulty", text: "People bring Jesus a man who is deaf and has difficulty speaking, asking Him to lay His hand on him. They appeal to Jesus as the one able to help.", refs: ["Matthew 9:32–33","Isaiah 35:5–6"] },
  "Mark 7:33": { title: "Jesus Takes Him Aside", text: "Jesus takes the man aside privately, touches his ears and tongue. These personal gestures communicate what Jesus is addressing rather than functioning as a ritual others can mechanically copy.", refs: ["Mark 8:23","John 9:6"] },
  "Mark 7:34": { title: "Ephphatha", text: "Jesus looks up to heaven, sighs, and says, 'Ephphatha,' meaning, 'Be opened.' His upward look expresses dependence on God, and His command brings healing.", refs: ["John 11:41","Isaiah 35:5"] },
  "Mark 7:35": { title: "His Hearing and Speech Restored", text: "Immediately the man's ears are opened, his speech impediment is loosed, and he speaks plainly. The healing recalls the prophetic picture of the deaf hearing and the mute singing.", refs: ["Isaiah 35:5–6","Matthew 15:31"] },
  "Mark 7:36": { title: "Jesus Charges Them to Tell No One", text: "Jesus instructs the people not to publicize the event, but the more He charges them, the more widely they proclaim it. Their amazement overflows the limit He sets.", refs: ["Mark 1:44–45","Matthew 9:30–31"] },
  "Mark 7:37": { title: "He Hath Done All Things Well", text: "The people are astonished and say Jesus has done all things well, making the deaf hear and the mute speak. Their words echo the goodness of God's restoring work and point to Jesus' remarkable authority.", refs: ["Genesis 1:31","Isaiah 35:5–6"] }
});

Object.assign(window.verseCommentary, {
  "Mark 8:1": { title: "Another Great Crowd", text: "Another large crowd gathers, and the people have nothing to eat. Jesus notices their need and prepares to provide for them.", refs: ["Matthew 15:32","Mark 6:34"] },
  "Mark 8:2": { title: "Compassion for the Hungry", text: "Jesus says He has compassion on the crowd because they have been with Him three days and have nothing to eat. His concern includes bodily need as well as spiritual teaching.", refs: ["Matthew 15:32","Mark 6:34"] },
  "Mark 8:3": { title: "They May Faint on the Way", text: "Jesus considers that sending them away hungry could cause some to faint, especially those who came from far away. Compassion considers what people will face after they leave.", refs: ["Matthew 15:32","Isaiah 40:29"] },
  "Mark 8:4": { title: "Where Can Bread Be Found?", text: "The disciples ask how anyone can provide enough bread in a wilderness place. They face the need with limited resources and have not yet learned fully from the earlier feeding.", refs: ["Mark 6:37","John 6:5–7"] },
  "Mark 8:5": { title: "Seven Loaves", text: "Jesus asks how many loaves they have, and they answer seven. He begins with what is available rather than requiring the disciples to produce what they do not possess.", refs: ["Matthew 15:34","Mark 6:38"] },
  "Mark 8:6": { title: "Jesus Gives Thanks", text: "Jesus commands the people to sit, takes the seven loaves, gives thanks, breaks them, and gives them to His disciples to distribute. The disciples serve as intermediaries while provision comes through Jesus.", refs: ["Matthew 15:35–36","Mark 6:41"] },
  "Mark 8:7": { title: "A Few Small Fish", text: "They also have a few small fish, and Jesus blesses them and commands that these be distributed too. The small additional supply is included in the meal He provides.", refs: ["Matthew 15:36","Mark 6:41"] },
  "Mark 8:8": { title: "Four Thousand Are Fed", text: "The people eat and are filled, and seven baskets of leftovers are gathered. The miracle meets the crowd's need with abundance.", refs: ["Matthew 15:37–38","Psalm 107:9"] },
  "Mark 8:9": { title: "About Four Thousand People", text: "About four thousand people are present, and Jesus sends them away after they have eaten. This account is distinct from the earlier feeding of the five thousand.", refs: ["Matthew 15:38–39","Mark 6:44"] },
  "Mark 8:10": { title: "Jesus Comes to Dalmanutha", text: "Jesus enters a ship with His disciples and comes to the region of Dalmanutha. The setting changes, but opposition to His ministry continues.", refs: ["Matthew 15:39","Mark 7:31"] },
  "Mark 8:11": { title: "The Pharisees Demand a Sign", text: "The Pharisees dispute with Jesus and ask for a sign from heaven to test Him. Their demand is a challenge meant to put Him to the test, not an open search for truth.", refs: ["Matthew 16:1","Luke 11:16"] },
  "Mark 8:12": { title: "Jesus Sighs Deeply", text: "Jesus sighs deeply and says no sign will be given to that generation. He refuses to perform a sign on demand for hardened challengers, not because His ministry lacks evidence of God's work.", refs: ["Matthew 16:4","Mark 6:2"] },
  "Mark 8:13": { title: "He Leaves Them", text: "Jesus leaves the challengers, enters the ship again, and departs to the other side. He does not allow their demands to dictate His mission.", refs: ["Matthew 16:4","John 6:15"] },
  "Mark 8:14": { title: "The Disciples Have One Loaf", text: "The disciples have forgotten to bring bread and have only one loaf in the ship. Their attention turns to their immediate shortage.", refs: ["Matthew 16:5","Mark 6:38"] },
  "Mark 8:15": { title: "Beware of Leaven", text: "Jesus warns them to beware of the leaven of the Pharisees and the leaven of Herod. The image points to the corrupting influence of unbelief, hypocrisy, and opposition rather than literal bread.", refs: ["Matthew 16:6","Luke 12:1"] },
  "Mark 8:16": { title: "They Reason About Bread", text: "The disciples think Jesus is speaking because they have no bread. They interpret His spiritual warning at a purely material level.", refs: ["Matthew 16:7","John 6:26–27"] },
  "Mark 8:17": { title: "Do You Not Yet Understand?", text: "Jesus asks why they reason about having no bread and whether their hearts are still hardened. They have seen His provision repeatedly, yet anxiety obscures the lesson.", refs: ["Mark 6:52","Mark 4:40"] },
  "Mark 8:18": { title: "Eyes and Ears Yet No Understanding", text: "Jesus asks whether they have eyes but do not see and ears but do not hear, and whether they remember. Spiritual perception requires learning from what God has shown.", refs: ["Jeremiah 5:21","Mark 4:12"] },
  "Mark 8:19": { title: "Remember the Five Loaves", text: "Jesus asks how many baskets remained after the five thousand ate, and the disciples answer twelve. He reminds them of the earlier miracle so they will not panic over their present shortage.", refs: ["Mark 6:41–43","Matthew 16:9"] },
  "Mark 8:20": { title: "Remember the Seven Loaves", text: "Jesus asks how many baskets remained after the four thousand ate, and they answer seven. The second feeding should further teach them to trust His provision.", refs: ["Mark 8:6–9","Matthew 16:10"] },
  "Mark 8:21": { title: "How Is It You Do Not Understand?", text: "Jesus asks how the disciples still fail to understand. His question exposes how easily they forget the meaning of the works they have witnessed.", refs: ["Mark 8:17–20","John 14:9"] },
  "Mark 8:22": { title: "A Blind Man at Bethsaida", text: "People bring a blind man to Jesus and beg Him to touch him. They seek the same compassionate power that has restored many others.", refs: ["Matthew 11:5","Mark 7:32"] },
  "Mark 8:23": { title: "Jesus Leads Him Outside", text: "Jesus takes the blind man by the hand and leads him outside the town, then puts saliva on his eyes and lays hands on him. The personal actions precede a healing that unfolds in stages.", refs: ["Mark 7:33","John 9:6"] },
  "Mark 8:24": { title: "I See Men as Trees Walking", text: "The man begins to see but his sight is not yet clear; people look like trees walking. This partial recovery shows that the healing is occurring in stages in this account.", refs: ["Mark 8:25","John 9:7"] },
  "Mark 8:25": { title: "His Sight Is Fully Restored", text: "Jesus lays His hands on the man's eyes again, and his sight is restored so that he sees everyone clearly. The two-stage healing reminds readers not to mistake an incomplete stage for the final outcome.", refs: ["Mark 8:23–24","Psalm 146:8"] },
  "Mark 8:26": { title: "Return Home", text: "Jesus sends the man home and tells him not to enter the town or tell anyone there. As elsewhere in Mark, Jesus controls how His works are publicized.", refs: ["Mark 1:44","Mark 7:36"] },
  "Mark 8:27": { title: "Who Do Men Say I Am?", text: "Jesus and His disciples travel toward Caesarea Philippi, and He asks what people say about Him. The question moves toward the disciples' own understanding of His identity.", refs: ["Matthew 16:13","Luke 9:18"] },
  "Mark 8:28": { title: "The People's Answers", text: "The disciples report that some say John the Baptist, others Elijah, and others one of the prophets. The answers show respect for Jesus but stop short of the confession He is drawing out.", refs: ["Mark 6:14–15","Malachi 4:5"] },
  "Mark 8:29": { title: "Thou Art the Christ", text: "Peter answers that Jesus is the Christ, the Messiah. This is a decisive confession, though Peter still needs to understand the kind of mission the Messiah must fulfill.", refs: ["Matthew 16:16","John 20:31"] },
  "Mark 8:30": { title: "Do Not Publicize It Yet", text: "Jesus charges them not to tell anyone about Him at that time. Their understanding is still incomplete, especially concerning His suffering and resurrection.", refs: ["Matthew 16:20","Mark 9:9"] },
  "Mark 8:31": { title: "The Son of Man Must Suffer", text: "Jesus teaches that the Son of man must suffer, be rejected, be killed, and rise again after three days. His messianic mission includes the cross and resurrection, not merely public triumph.", refs: ["Isaiah 53:3–12","Luke 24:7"] },
  "Mark 8:32": { title: "Peter Rebukes Jesus", text: "Jesus speaks openly about His coming suffering, and Peter takes Him aside and begins to rebuke Him. Peter's expectations do not yet align with God's saving purpose through the cross.", refs: ["Matthew 16:22","John 18:10–11"] },
  "Mark 8:33": { title: "Get Thee Behind Me, Satan", text: "Jesus rebukes Peter because Peter is setting his mind on human concerns rather than God's. The severe words identify the temptation to reject the cross as contrary to God's purpose, not that Peter is literally Satan.", refs: ["Matthew 16:23","Isaiah 55:8–9"] },
  "Mark 8:34": { title: "Take Up the Cross", text: "Jesus calls the crowd and disciples to deny themselves, take up their cross, and follow Him. Discipleship requires surrender of self-rule and faithful allegiance even when it costs dearly.", refs: ["Luke 9:23","Galatians 2:20"] },
  "Mark 8:35": { title: "Lose Life to Save It", text: "Whoever tries to save life at all costs will lose it, but whoever loses life for Jesus and the gospel will save it. Jesus reverses worldly ideas of security and calls for faithfulness above self-preservation.", refs: ["Matthew 10:39","John 12:25"] },
  "Mark 8:36": { title: "Gain the World, Lose the Soul", text: "The whole world is no profit if a person loses his own soul. No earthly achievement can compensate for losing one's life with God.", refs: ["Matthew 16:26","Psalm 49:7–8"] },
  "Mark 8:37": { title: "What Can a Person Give in Exchange?", text: "Jesus asks what a person could give in exchange for his soul. The question underscores the incomparable value of eternal life and the limits of worldly wealth.", refs: ["Psalm 49:8","Matthew 16:26"] },
  "Mark 8:38": { title: "Not Ashamed of Jesus", text: "Jesus warns against being ashamed of Him and His words in a sinful generation, saying the Son of man will come in the glory of His Father with the holy angels. Present allegiance matters in light of future divine judgment and glory.", refs: ["Matthew 10:32–33","Luke 9:26","Daniel 7:13–14"] }
});

Object.assign(window.verseCommentary, {
  "Mark 9:1": { title: "The Kingdom Comes with Power", text: "Jesus says some standing there will not taste death until they see God's kingdom come with power. The saying points to a near demonstration of kingdom glory, anticipated immediately by the transfiguration and seen further in Jesus' resurrection and the apostolic mission.", refs: ["Matthew 16:28","Acts 1:8"] },
  "Mark 9:2": { title: "Jesus Is Transfigured", text: "Six days later Jesus takes Peter, James, and John up a high mountain and is transfigured before them. His appearance reveals glory beyond what they ordinarily see.", refs: ["Matthew 17:1–2","2 Peter 1:16–18"] },
  "Mark 9:3": { title: "Garments of Dazzling White", text: "Jesus' garments become exceedingly white, beyond what any earthly process could produce. The scene reveals heavenly glory and confirms His unique identity.", refs: ["Matthew 17:2","Daniel 7:9"] },
  "Mark 9:4": { title: "Moses and Elijah Appear", text: "Moses and Elijah appear and speak with Jesus. Their presence connects the Law and the Prophets with the fulfillment of God's saving purpose in Christ.", refs: ["Luke 9:30–31","Malachi 4:4–5"] },
  "Mark 9:5": { title: "Peter Offers to Make Tents", text: "Peter addresses Jesus as Master and suggests making three tabernacles for Jesus, Moses, and Elijah. His proposal shows reverence but does not yet grasp the unique place of Jesus.", refs: ["Matthew 17:4","Mark 8:29"] },
  "Mark 9:6": { title: "Peter Does Not Know What to Say", text: "Peter is afraid and speaks without understanding what to say. The glory of the moment overwhelms the disciples.", refs: ["Luke 9:33","Job 40:4"] },
  "Mark 9:7": { title: "The Beloved Son", text: "A cloud overshadows them, and a voice declares Jesus to be the beloved Son and commands, 'hear him.' The heavenly voice directs the disciples to listen to Jesus above all competing expectations.", refs: ["Deuteronomy 18:15","Matthew 17:5"] },
  "Mark 9:8": { title: "Jesus Alone", text: "Suddenly the disciples see no one with them except Jesus. Moses and Elijah are not equal alternatives to Him; the focus returns to Jesus as the one they must follow.", refs: ["Hebrews 1:1–2","John 1:17"] },
  "Mark 9:9": { title: "Wait Until the Resurrection", text: "As they descend the mountain, Jesus tells them not to tell what they have seen until the Son of man rises from the dead. The resurrection will clarify the meaning of His glory and mission.", refs: ["Matthew 17:9","Mark 8:31"] },
  "Mark 9:10": { title: "What Does Rising from the Dead Mean?", text: "They keep the saying but discuss among themselves what rising from the dead could mean. They have heard Jesus predict His resurrection but do not yet understand it.", refs: ["Luke 18:34","John 20:9"] },
  "Mark 9:11": { title: "Why Must Elijah Come First?", text: "The disciples ask why the scribes say Elijah must come first. They are trying to reconcile the promised forerunner with what they have just witnessed.", refs: ["Malachi 4:5–6","Matthew 17:10"] },
  "Mark 9:12": { title: "The Son of Man Must Suffer", text: "Jesus confirms that Elijah comes first to restore things, but asks why Scripture says the Son of man must suffer and be treated with contempt. The Messiah's glory does not cancel the prophetic testimony about His suffering.", refs: ["Isaiah 53:3","Luke 24:26"] },
  "Mark 9:13": { title: "Elijah Has Come", text: "Jesus says Elijah has come and people have treated him as they wished, as Scripture indicated. This points to John the Baptist's forerunner ministry and the rejection he endured.", refs: ["Matthew 17:12–13","Luke 1:17"] },
  "Mark 9:14": { title: "A Crowd and Disputing Scribes", text: "Jesus returns to the other disciples and sees a crowd around them and scribes disputing with them. The scene contrasts the mountain's revelation with the confusion and need below.", refs: ["Luke 9:37","Mark 8:33"] },
  "Mark 9:15": { title: "The Crowd Runs to Jesus", text: "The people are amazed when they see Jesus and run to greet Him. His arrival shifts attention toward the one who can address the crisis.", refs: ["Matthew 17:14","Mark 6:54"] },
  "Mark 9:16": { title: "What Are You Disputing About?", text: "Jesus asks the scribes what they are questioning the disciples about. He brings the argument into the open rather than letting dispute replace ministry.", refs: ["Mark 9:14","Luke 9:40"] },
  "Mark 9:17": { title: "A Father Brings His Son", text: "A man explains that he brought his son, who has a spirit that prevents him from speaking. The father seeks help after the disciples have been unable to resolve the problem.", refs: ["Matthew 17:14–15","Luke 9:38"] },
  "Mark 9:18": { title: "The Boy Suffers Terribly", text: "The spirit seizes the boy, causing convulsions, foaming, and physical danger. The father describes a devastating condition and asks for help; the passage should not be used to label every illness as demonic.", refs: ["Matthew 17:15","Mark 5:5"] },
  "Mark 9:19": { title: "O Faithless Generation", text: "Jesus laments the unbelief around Him and tells them to bring the boy. His words rebuke the failure of faith while His willingness to help remains clear.", refs: ["Matthew 17:17","Luke 9:41"] },
  "Mark 9:20": { title: "The Spirit Reacts to Jesus", text: "When the boy is brought, the spirit throws him into convulsions. The crisis is severe, but it does not place the boy beyond Jesus' authority.", refs: ["Luke 9:42","Mark 1:26"] },
  "Mark 9:21": { title: "Since Childhood", text: "Jesus asks the father how long this has happened, and the father says since childhood. Jesus listens to the details of the family's long suffering.", refs: ["Matthew 17:15","Mark 5:25"] },
  "Mark 9:22": { title: "If Thou Canst Do Anything", text: "The father says the spirit has often tried to destroy the boy and pleads for compassion and help. His desperate request expresses both grief and a fragile hope.", refs: ["Luke 9:42","Psalm 34:17"] },
  "Mark 9:23": { title: "All Things Are Possible to Him That Believeth", text: "Jesus answers the father's 'if thou canst' by calling attention to belief. This is not a guarantee that human wishes will always occur, but an invitation to trust God's power rather than surrender to despair.", refs: ["Matthew 17:20","Hebrews 11:6"] },
  "Mark 9:24": { title: "Help Thou Mine Unbelief", text: "The father cries out that he believes and asks Jesus to help his unbelief. Honest faith can acknowledge weakness while still turning to Jesus for help.", refs: ["Luke 17:5","Psalm 73:26"] },
  "Mark 9:25": { title: "Jesus Rebukes the Unclean Spirit", text: "Jesus commands the deaf and dumb spirit to come out and never enter the boy again. His command is direct and authoritative, bringing the destructive oppression to an end.", refs: ["Mark 1:25–27","Luke 9:42"] },
  "Mark 9:26": { title: "The Boy Lies as One Dead", text: "The spirit cries out, convulses the boy, and leaves him appearing dead, so that many say he is dead. The final violent episode does not prevent Jesus from completing the deliverance.", refs: ["Matthew 17:18","Mark 5:41–42"] },
  "Mark 9:27": { title: "Jesus Takes Him by the Hand", text: "Jesus takes the boy by the hand and lifts him up, and he rises. The simple action highlights Jesus' restoring care after the frightening ordeal.", refs: ["Matthew 17:18","Acts 3:7"] },
  "Mark 9:28": { title: "Why Could We Not Cast It Out?", text: "In the house, the disciples ask privately why they could not cast the spirit out. They seek instruction about their failure rather than pretending they succeeded.", refs: ["Matthew 17:19","Luke 9:40"] },
  "Mark 9:29": { title: "Prayer and Dependence on God", text: "Jesus says this kind can come forth only through prayer; some manuscripts add fasting. The emphasis is dependence on God, not a mechanical formula that guarantees results.", refs: ["Matthew 17:21","Ephesians 6:18"] },
  "Mark 9:30": { title: "Passing Through Galilee", text: "Jesus and His disciples pass through Galilee, and He does not want the journey widely known. He continues preparing the disciples for His coming suffering.", refs: ["Matthew 17:22","Mark 8:31"] },
  "Mark 9:31": { title: "The Son of Man Will Be Delivered", text: "Jesus teaches that the Son of man will be delivered into human hands, killed, and rise on the third day. The cross is not an accident but part of the mission Jesus knowingly fulfills.", refs: ["Mark 8:31","Luke 9:44"] },
  "Mark 9:32": { title: "They Do Not Understand", text: "The disciples do not understand the saying and are afraid to ask Him. Their fear and confusion show how difficult it is for them to accept a suffering Messiah.", refs: ["Luke 9:45","John 16:17–18"] },
  "Mark 9:33": { title: "Who Is the Greatest?", text: "At Capernaum, Jesus asks what they argued about on the road. Their silence exposes that their discussion of status conflicts with the path of humble service He teaches.", refs: ["Matthew 18:1","Luke 9:46"] },
  "Mark 9:34": { title: "They Had Disputed About Greatness", text: "The disciples had argued about which of them was greatest. Even those closest to Jesus can be tempted by ambition and comparison.", refs: ["Luke 22:24","Matthew 20:20–24"] },
  "Mark 9:35": { title: "Last of All and Servant of All", text: "Jesus sits, calls the Twelve, and teaches that anyone who wants to be first must be last of all and servant of all. In His kingdom, greatness is measured by humble service rather than rank.", refs: ["Matthew 20:26–28","John 13:14–15"] },
  "Mark 9:36": { title: "Jesus Sets a Child in Their Midst", text: "Jesus takes a child and sets the child among them, embracing the child. The example gives visible form to His teaching about humility and welcoming those without status.", refs: ["Matthew 18:2","Luke 9:47"] },
  "Mark 9:37": { title: "Receiving in Jesus' Name", text: "Whoever receives a child in Jesus' name receives Him, and whoever receives Him receives the One who sent Him. The verse connects care for the lowly with receiving Jesus and, through Him, God who sent Him.", refs: ["Matthew 18:5","John 12:44–45"] },
  "Mark 9:38": { title: "Someone Casting Out Devils", text: "John says they saw someone casting out devils in Jesus' name and tried to stop him because he did not follow their group. The disciples confuse their own circle with the full reach of Jesus' authority.", refs: ["Luke 9:49","Numbers 11:27–29"] },
  "Mark 9:39": { title: "Do Not Forbid Him", text: "Jesus tells them not to forbid the man, noting that one who performs a mighty work in His name is unlikely immediately to speak evil of Him. The disciples must not treat sincere work done in Jesus' name as a threat to their status.", refs: ["Luke 9:50","1 Corinthians 12:3"] },
  "Mark 9:40": { title: "Not Against Us Is for Us", text: "Jesus says that whoever is not against them is on their side. The saying corrects needless rivalry while not removing the need to test teaching and conduct by truth.", refs: ["Luke 9:50","Philippians 1:18"] },
  "Mark 9:41": { title: "A Cup of Water in His Name", text: "Even giving a cup of water because the disciples belong to Christ will not lose its reward. Small acts of kindness done for Jesus' sake matter to God.", refs: ["Matthew 10:42","Hebrews 6:10"] },
  "Mark 9:42": { title: "Do Not Cause Little Ones to Stumble", text: "Jesus gives a severe warning against causing those who believe in Him to stumble. His words demand special care for vulnerable believers and accountability for those who harm their faith.", refs: ["Matthew 18:6","Luke 17:1–2"] },
  "Mark 9:43": { title: "Deal Seriously with Sin", text: "Jesus uses the image of cutting off a hand rather than being cast into hell to teach the seriousness of sin. The language is forceful illustration, not a command to mutilate the body; disciples must remove occasions of sin decisively.", refs: ["Matthew 5:30","Colossians 3:5"] },
  "Mark 9:44": { title: "The Warning of Gehenna", text: "This verse repeats the warning that their worm does not die and the fire is not quenched, but it is omitted in many early manuscripts and translations. The warning is present in the surrounding verses and must be read with their call to take sin seriously.", refs: ["Isaiah 66:24","Mark 9:48"] },
  "Mark 9:45": { title: "Deal Seriously with Sin", text: "Jesus repeats the warning using the foot as an illustration: it is better to enter life maimed than to be cast into hell. He calls for decisive rejection of sin rather than literal self-harm.", refs: ["Matthew 18:8","Romans 8:13"] },
  "Mark 9:46": { title: "The Warning Repeated", text: "This verse repeats the image of the undying worm and unquenched fire, but is absent from many early manuscripts. Mark's next verse preserves the warning, so the central teaching remains clear.", refs: ["Mark 9:48","Isaiah 66:24"] },
  "Mark 9:47": { title: "Enter the Kingdom of God", text: "Jesus uses the eye as another illustration: it is better to enter God's kingdom with one eye than to be cast into hell. The point is to guard what one allows to shape the heart and life.", refs: ["Matthew 5:29","Matthew 18:9"] },
  "Mark 9:48": { title: "The Worm and the Fire", text: "Jesus cites the image of the worm that does not die and the fire that is not quenched. The solemn image warns of judgment and calls listeners to turn from sin.", refs: ["Isaiah 66:24","Mark 9:43–47"] },
  "Mark 9:49": { title: "Salted with Fire", text: "Jesus says everyone will be salted with fire. The saying is difficult and has been interpreted in several ways; in context it may connect testing and judgment with the need for purified discipleship. It should not be used to build a doctrine without considering the surrounding verses.", refs: ["1 Corinthians 3:13–15","Leviticus 2:13"] },
  "Mark 9:50": { title: "Have Salt in Yourselves", text: "Salt is good, but if it loses its savour it is useless; Jesus tells the disciples to have salt in themselves and be at peace with one another. Faithful discipleship requires integrity and peace rather than rivalry.", refs: ["Matthew 5:13","Colossians 4:6","Romans 12:18"] }
});

Object.assign(window.verseCommentary, {
  "Mark 10:1": { title: "Jesus Teaches Beyond Jordan", text: "Jesus travels into Judea and beyond Jordan, and crowds gather again. As was His custom, He teaches them.", refs: ["Matthew 19:1–2","Luke 9:51"] },
  "Mark 10:2": { title: "A Question About Divorce", text: "Pharisees ask whether it is lawful for a man to put away his wife, testing Jesus. He answers by returning to God's purpose in creation rather than letting a trap control the conversation.", refs: ["Matthew 19:3","Deuteronomy 24:1"] },
  "Mark 10:3": { title: "What Did Moses Command?", text: "Jesus asks what Moses commanded them. He directs the questioners to the Scripture they claim to uphold.", refs: ["Matthew 19:7","Mark 7:9"] },
  "Mark 10:4": { title: "Moses' Provision", text: "They answer that Moses permitted a writing of divorcement and putting away. Jesus distinguishes a concession addressing human hardness from God's original intention.", refs: ["Deuteronomy 24:1–4","Matthew 19:7"] },
  "Mark 10:5": { title: "Hardness of Heart", text: "Jesus says Moses wrote this precept because of their hardness of heart. A legal provision addressing human sin should not be mistaken for God's ideal established at creation.", refs: ["Matthew 19:8","Jeremiah 4:4"] },
  "Mark 10:6": { title: "From the Beginning", text: "Jesus points to creation: God made humanity male and female. He grounds marriage teaching in the Creator's design rather than changing social customs.", refs: ["Genesis 1:27","Matthew 19:4"] },
  "Mark 10:7": { title: "A Man Leaves Father and Mother", text: "Jesus cites the teaching that a man leaves father and mother and cleaves to his wife. Marriage establishes a new family bond with real responsibilities.", refs: ["Genesis 2:24","Ephesians 5:31"] },
  "Mark 10:8": { title: "The Two Become One Flesh", text: "The two become one flesh, so they are no longer two but one. Jesus emphasizes the unity and seriousness of the marital covenant.", refs: ["Genesis 2:24","Matthew 19:5–6"] },
  "Mark 10:9": { title: "What God Has Joined", text: "Jesus says what God has joined together, no person should separate. The teaching calls married people to honour the covenant rather than treat it as disposable.", refs: ["Matthew 19:6","Malachi 2:14–16"] },
  "Mark 10:10": { title: "The Disciples Ask at Home", text: "In the house, the disciples ask Jesus further about the matter. They seek clarification on a difficult teaching rather than leaving it unexplored.", refs: ["Matthew 19:10","Mark 4:10"] },
  "Mark 10:11": { title: "Adultery and Divorce", text: "Jesus warns that a man who divorces his wife and marries another commits adultery against her. The verse underscores marital faithfulness; related passages should be studied together when considering cases of abandonment or sexual immorality.", refs: ["Matthew 19:9","Luke 16:18"] },
  "Mark 10:12": { title: "A Wife Who Divorces Her Husband", text: "Jesus also addresses a wife who divorces her husband and marries another. His teaching affirms mutual responsibility for fidelity rather than placing accountability on only one sex.", refs: ["Matthew 5:32","Romans 7:2–3"] },
  "Mark 10:13": { title: "Children Are Brought to Jesus", text: "People bring young children to Jesus so He might touch them, but the disciples rebuke them. Jesus' response shows children are not distractions from His mission.", refs: ["Matthew 19:13","Luke 18:15"] },
  "Mark 10:14": { title: "Suffer the Little Children", text: "Jesus is displeased and tells the disciples to let the children come to Him, for God's kingdom belongs to such as these. He welcomes those often overlooked and models a receptive posture toward God.", refs: ["Matthew 19:14","Luke 18:16"] },
  "Mark 10:15": { title: "Receive the Kingdom as a Child", text: "Whoever does not receive God's kingdom as a little child will not enter it. The point is humble dependence and receptivity, not that children are automatically sinless.", refs: ["Luke 18:17","Matthew 18:3"] },
  "Mark 10:16": { title: "Jesus Blesses the Children", text: "Jesus takes the children in His arms, lays His hands on them, and blesses them. His personal care confirms the value He places on them.", refs: ["Matthew 19:15","Mark 9:36–37"] },
  "Mark 10:17": { title: "The Rich Man Runs to Jesus", text: "A man runs to Jesus, kneels, and asks what he must do to inherit eternal life. His question is earnest, and Jesus will expose what competes with full obedience.", refs: ["Matthew 19:16","Luke 18:18"] },
  "Mark 10:18": { title: "Why Call Me Good?", text: "Jesus asks why the man calls Him good, since none is good but God. He challenges the man to consider the full implication of calling Him good and to understand God's unique goodness; this is not a denial of Jesus' divine identity.", refs: ["Matthew 19:17","John 10:11"] },
  "Mark 10:19": { title: "The Commandments", text: "Jesus names commandments concerning murder, adultery, theft, false witness, fraud, and honouring parents. The commandments provide a moral standard by which the man should examine his life.", refs: ["Exodus 20:12–16","Deuteronomy 5:16–20"] },
  "Mark 10:20": { title: "I Have Kept These", text: "The man says he has observed these commandments from his youth. Jesus will show that outward rule-keeping has not freed him from the hold of his possessions.", refs: ["Matthew 19:20","Philippians 3:6"] },
  "Mark 10:21": { title: "One Thing Thou Lackest", text: "Jesus looks at him with love and tells him to sell what he has, give to the poor, take up the cross, and follow Him. The command identifies the man's particular obstacle: wealth has become a rival to wholehearted discipleship.", refs: ["Matthew 19:21","Luke 12:33"] },
  "Mark 10:22": { title: "He Goes Away Sorrowful", text: "The man is saddened and goes away grieving because he has great possessions. His sorrow reveals the cost of surrendering what he loves more than following Jesus.", refs: ["Matthew 19:22","Luke 18:23"] },
  "Mark 10:23": { title: "How Hard for the Rich", text: "Jesus says how difficult it is for those who have riches to enter God's kingdom. Wealth can create false security and make surrender harder, though riches alone do not automatically exclude a person.", refs: ["1 Timothy 6:17–19","Luke 12:15"] },
  "Mark 10:24": { title: "Trusting in Riches", text: "The disciples are astonished, and Jesus repeats the difficulty of entering the kingdom. Some translations include 'for them that trust in riches'; the context warns against allowing wealth to govern the heart.", refs: ["Matthew 19:23","Proverbs 11:28"] },
  "Mark 10:25": { title: "A Camel Through a Needle's Eye", text: "Jesus uses the picture of a camel passing through a needle's eye to illustrate the impossibility of self-saving reliance on wealth. The image drives home how desperately people need God's grace.", refs: ["Matthew 19:24","Luke 18:25"] },
  "Mark 10:26": { title: "Who Then Can Be Saved?", text: "The disciples are astonished and ask who can be saved. If even the apparently blessed seem unable, salvation cannot rest on human status or achievement.", refs: ["Matthew 19:25","Psalm 49:6–8"] }
});

Object.assign(window.verseCommentary, {
  "Mark 10:27": { title: "With God All Things Are Possible", text: "Jesus says what is impossible with people is possible with God. Salvation depends on God's power and grace, not human wealth or merit.", refs: ["Matthew 19:26","Ephesians 2:8–9"] },
  "Mark 10:28": { title: "We Have Left All", text: "Peter says the disciples have left everything to follow Jesus. His question implies concern about what discipleship means for their future.", refs: ["Matthew 19:27","Luke 18:28"] },
  "Mark 10:29": { title: "Leaving for Jesus and the Gospel", text: "Jesus speaks of those who leave home or family for His sake and the gospel. He acknowledges real sacrifice in discipleship rather than pretending following Him costs nothing.", refs: ["Matthew 19:29","Luke 14:26"] },
  "Mark 10:30": { title: "A Hundredfold with Persecutions", text: "Jesus promises a hundredfold in this present time, along with persecutions, and eternal life in the world to come. The promise includes the new family and community of faith, not a guarantee of material luxury.", refs: ["Matthew 19:29","Acts 2:44–47"] },
  "Mark 10:31": { title: "First and Last", text: "Many who are first will be last, and the last first. God's kingdom overturns ordinary rankings of status and reward.", refs: ["Matthew 20:16","Luke 13:30"] },
  "Mark 10:32": { title: "Going Up to Jerusalem", text: "Jesus leads the way toward Jerusalem, and the disciples are amazed while others are afraid. He takes the lead even as the path toward suffering becomes clearer.", refs: ["Luke 18:31","Mark 8:31"] },
  "Mark 10:33": { title: "The Son of Man Will Be Delivered", text: "Jesus tells the Twelve that He will be handed to the chief priests and scribes, condemned, and delivered to the Gentiles. He knows the events ahead and continues willingly toward His purpose.", refs: ["Matthew 20:18–19","Isaiah 53:3"] },
  "Mark 10:34": { title: "Mocked, Scourged, and Raised", text: "Jesus foretells that He will be mocked, scourged, spat upon, killed, and rise on the third day. His suffering and resurrection are central to the gospel, not incidental events.", refs: ["Luke 18:32–33","Mark 8:31"] },
  "Mark 10:35": { title: "James and John Ask a Favour", text: "James and John ask Jesus to grant whatever they request. Their approach shows that even after hearing about His suffering, they are still thinking in terms of personal honour.", refs: ["Matthew 20:20","Mark 9:34"] },
  "Mark 10:36": { title: "What Would You Have Me Do?", text: "Jesus asks what they want Him to do for them. He draws out their request rather than letting their ambition remain vague.", refs: ["Matthew 20:21","Mark 10:35"] },
  "Mark 10:37": { title: "Places of Honour", text: "They ask to sit at Jesus' right and left in His glory. They understand that His kingdom is coming but misunderstand the suffering and service associated with it.", refs: ["Matthew 20:21","Luke 22:24–27"] },
  "Mark 10:38": { title: "The Cup and the Baptism", text: "Jesus asks whether they can drink His cup and be baptized with His baptism. These images point to sharing the suffering ahead, not merely receiving honour.", refs: ["Matthew 20:22","Psalm 75:8"] },
  "Mark 10:39": { title: "You Shall Share the Cup", text: "James and John say they can, and Jesus says they will share His cup and baptism of suffering. Yet the places of honour are not His to assign independently of the Father's prepared purpose.", refs: ["Acts 12:2","Revelation 1:9"] },
  "Mark 10:40": { title: "Places Prepared by God", text: "Jesus says the places at His right and left are for those for whom they are prepared. Kingdom honour is not secured by ambition or bargaining.", refs: ["Matthew 20:23","Daniel 7:9–10"] }
});

Object.assign(window.verseCommentary, {
  "Mark 10:41": { title: "The Ten Are Displeased", text: "The other ten disciples become indignant with James and John. Their reaction suggests rivalry over status affects the whole group, not just the two who asked.", refs: ["Matthew 20:24","Mark 9:34"] },
  "Mark 10:42": { title: "Rulers Exercise Authority", text: "Jesus notes that Gentile rulers lord it over people and exercise authority over them. He describes the worldly model in order to reject it as the pattern for His followers.", refs: ["Matthew 20:25","Luke 22:25"] },
  "Mark 10:43": { title: "Greatness Through Service", text: "Jesus says it must not be so among His disciples; whoever wants to be great must be a servant. Christian leadership is measured by service, not domination.", refs: ["Matthew 20:26","1 Peter 5:2–3"] },
  "Mark 10:44": { title: "First Must Be Servant of All", text: "Whoever wants to be first must be servant of all. Jesus calls His followers to a form of greatness that willingly places others' needs ahead of status.", refs: ["Matthew 20:27","John 13:14"] },
  "Mark 10:45": { title: "The Son of Man Gives His Life", text: "The Son of man came not to be served but to serve and give His life a ransom for many. Jesus' mission defines Christian service and presents His death as the costly means of deliverance.", refs: ["Isaiah 53:10–12","1 Timothy 2:5–6"] },
  "Mark 10:46": { title: "Bartimaeus at Jericho", text: "Jesus and His disciples come to Jericho, where blind Bartimaeus sits by the roadside begging. The healing follows the disciples' struggle to see what Jesus' mission means.", refs: ["Matthew 20:29–30","Luke 18:35"] },
  "Mark 10:47": { title: "Jesus, Son of David", text: "Bartimaeus hears that Jesus of Nazareth is passing and cries out, calling Him Son of David and asking for mercy. His confession recognizes Jesus as the promised Davidic Messiah.", refs: ["Isaiah 11:1","Matthew 21:9"] },
  "Mark 10:48": { title: "He Cries Out More", text: "Many rebuke Bartimaeus and tell him to be quiet, but he cries out even more. His persistence is not silenced by the crowd's disapproval.", refs: ["Luke 18:39","Psalm 34:6"] },
  "Mark 10:49": { title: "Jesus Calls Him", text: "Jesus stops and commands that Bartimaeus be called. The crowd then encourages him, showing how quickly people can change when Jesus gives attention to someone they had dismissed.", refs: ["Luke 18:40","Mark 5:32"] },
  "Mark 10:50": { title: "He Casts Away His Garment", text: "Bartimaeus throws aside his garment, rises, and comes to Jesus. His immediate response displays eagerness to receive the opportunity Jesus has given him.", refs: ["Luke 18:40","Hebrews 12:1"] },
  "Mark 10:51": { title: "What Wilt Thou That I Should Do?", text: "Jesus asks what Bartimaeus wants, and he asks to receive his sight. Jesus allows him to state his need plainly.", refs: ["Luke 18:41","Mark 5:30"] },
  "Mark 10:52": { title: "Thy Faith Hath Made Thee Whole", text: "Jesus tells Bartimaeus to go, saying his faith has made him whole; immediately he receives sight and follows Jesus in the way. The healing becomes a picture of physical restoration and discipleship.", refs: ["Luke 18:42–43","Isaiah 35:5"] }
});

Object.assign(window.verseCommentary, {
  "Mark 11:1": { title: "Approaching Jerusalem", text: "Jesus and His disciples draw near to Jerusalem, reaching Bethphage and Bethany at the Mount of Olives. The approach prepares for His public entry as King.", refs: ["Matthew 21:1","Zechariah 14:4"] },
  "Mark 11:2": { title: "Find a Colt", text: "Jesus sends two disciples into the village to find a colt that has never been ridden. His specific instructions show deliberate preparation for the entry.", refs: ["Matthew 21:2","Luke 19:30"] },
  "Mark 11:3": { title: "The Lord Has Need of It", text: "If anyone asks why they are taking the colt, they are to say that the Lord has need of it and will send it back. The mission is carried out with Jesus' authority and with a stated return.", refs: ["Luke 19:31","Matthew 21:3"] },
  "Mark 11:4": { title: "The Colt Is Found", text: "The disciples find the colt tied outside by a doorway and begin to loose it. Events unfold as Jesus described.", refs: ["Matthew 21:6","Luke 19:32"] },
  "Mark 11:5": { title: "A Question from Bystanders", text: "Some standing there ask why the disciples are loosing the colt. Their question creates the moment for the explanation Jesus instructed them to give.", refs: ["Mark 11:3","Luke 19:33"] },
  "Mark 11:6": { title: "They Are Allowed to Take It", text: "The disciples answer as Jesus commanded, and the people let them go. Their obedience proceeds without a dispute.", refs: ["Matthew 21:6","Mark 11:3"] },
  "Mark 11:7": { title: "Jesus Rides the Colt", text: "The disciples bring the colt, place their garments on it, and Jesus sits upon it. His entry fulfills the prophetic picture of a humble king.", refs: ["Zechariah 9:9","Matthew 21:7"] },
  "Mark 11:8": { title: "Garments and Branches on the Road", text: "Many spread garments and branches on the road before Jesus. The crowd honours Him publicly, though not all will understand the kind of King He is.", refs: ["John 12:13","2 Kings 9:13"] },
  "Mark 11:9": { title: "Hosanna", text: "People ahead and behind cry, 'Hosanna,' blessing the One who comes in the name of the Lord. Their words draw from Scripture and express hope for God's promised salvation.", refs: ["Psalm 118:25–26","Matthew 21:9"] },
  "Mark 11:10": { title: "Blessed Is the Coming Kingdom", text: "The crowd blesses the coming kingdom of their father David and cries Hosanna in the highest. They associate Jesus with Davidic hope, though the kingdom will not arrive in the political form many expect.", refs: ["2 Samuel 7:12–16","Luke 1:32–33"] },
  "Mark 11:11": { title: "Jesus Enters the Temple", text: "Jesus enters Jerusalem and the temple, looks around at everything, and then leaves for Bethany with the Twelve because it is late. His inspection precedes the prophetic action that follows.", refs: ["Matthew 21:12","Malachi 3:1"] },
  "Mark 11:12": { title: "Jesus Is Hungry", text: "The next day Jesus is hungry as He leaves Bethany. Mark's detail underscores Jesus' genuine human experience and introduces the fig-tree sign.", refs: ["Matthew 21:18","Hebrews 4:15"] },
  "Mark 11:13": { title: "A Fig Tree with Leaves", text: "Jesus sees a fig tree with leaves and looks for fruit, but finds none. The scene will become a prophetic sign concerning fruitfulness rather than a general lesson about ordinary trees.", refs: ["Matthew 21:19","Micah 7:1"] },
  "Mark 11:14": { title: "The Fig Tree Is Cursed", text: "Jesus says no one will eat fruit from the tree hereafter, and the disciples hear Him. The acted parable anticipates the temple judgment and warns against outward appearance without fruit.", refs: ["Luke 13:6–9","Jeremiah 8:13"] },
  "Mark 11:15": { title: "Cleansing the Temple", text: "Jesus enters the temple and drives out those buying and selling, overturning the tables of money changers and seats of sellers of doves. His action confronts the corruption of worship and the exploitation of people seeking God.", refs: ["Matthew 21:12","John 2:14–16"] },
  "Mark 11:16": { title: "No Vessels Through the Temple", text: "Jesus does not allow anyone to carry a vessel through the temple. His authority interrupts the misuse of sacred space and underscores the seriousness of restoring proper worship.", refs: ["Mark 11:15","Malachi 3:1–3"] },
  "Mark 11:17": { title: "A House of Prayer for All Nations", text: "Jesus cites Scripture that God's house should be called a house of prayer for all nations, but they have made it a den of thieves. The temple's purpose is prayer and worship, not exploitation.", refs: ["Isaiah 56:7","Jeremiah 7:11"] },
  "Mark 11:18": { title: "Leaders Seek to Destroy Him", text: "Chief priests and scribes hear of Jesus' action and seek a way to destroy Him, while the people are astonished at His teaching. His public challenge to corruption intensifies the conflict.", refs: ["Luke 19:47","John 11:53"] },
  "Mark 11:19": { title: "Jesus Leaves the City", text: "When evening comes, Jesus and His disciples go out of the city. The narrative continues the next morning with the fig tree and teaching about faith.", refs: ["Matthew 21:17","Mark 11:11"] },
  "Mark 11:20": { title: "The Fig Tree Is Withered", text: "In the morning, the disciples see the fig tree dried up from the roots. The visible result confirms the significance of Jesus' prophetic act.", refs: ["Matthew 21:20","Mark 11:14"] },
  "Mark 11:21": { title: "Peter Remembers", text: "Peter recalls the tree Jesus cursed and points out that it has withered. The disciples are invited to consider what this sign teaches.", refs: ["Matthew 21:20","Mark 11:14"] },
  "Mark 11:22": { title: "Have Faith in God", text: "Jesus tells them to have faith in God. The foundation is trust in God Himself, not confidence in one's own ability to command outcomes.", refs: ["Hebrews 11:6","Psalm 62:8"] },
  "Mark 11:23": { title: "Faith and the Mountain", text: "Jesus uses the image of a mountain being cast into the sea to describe confident prayer that does not doubt God's power. This is not a blank cheque for selfish wishes; prayer must be understood with God's will and the wider teaching of Scripture.", refs: ["Matthew 21:21","James 4:3"] },
  "Mark 11:24": { title: "Believe You Have Received", text: "Jesus encourages prayer offered in faith, trusting God to hear. The promise should be read alongside Scripture's teaching to pray according to God's will and to persevere faithfully.", refs: ["1 John 5:14–15","James 1:6–7"] },
  "Mark 11:25": { title: "Forgive When You Pray", text: "When standing in prayer, the disciples must forgive others so that their heavenly Father may forgive them. A life of prayer cannot be separated from mercy toward others.", refs: ["Matthew 6:14–15","Ephesians 4:32"] },
  "Mark 11:26": { title: "A Textual Note on Forgiveness", text: "This verse appears in the traditional KJV but is absent from many early manuscripts, with similar wording found in Matthew 6:15. The teaching that forgiveness matters is firmly present elsewhere in Scripture.", refs: ["Matthew 6:15","Mark 11:25"] },
  "Mark 11:27": { title: "A Challenge to Jesus' Authority", text: "Jesus returns to Jerusalem and walks in the temple when chief priests, scribes, and elders approach Him. They challenge His authority after His public actions.", refs: ["Matthew 21:23","Luke 20:1"] },
  "Mark 11:28": { title: "Who Gave Thee This Authority?", text: "The leaders ask by what authority Jesus does these things and who gave Him that authority. Their question challenges His right to teach and act as He has.", refs: ["John 2:18","Acts 4:7"] },
  "Mark 11:29": { title: "Jesus Asks a Question", text: "Jesus says He will ask them one question, and if they answer, He will tell them His authority. He exposes whether they are willing to reason honestly about God's work.", refs: ["Matthew 21:24","Luke 20:3"] },
  "Mark 11:30": { title: "The Baptism of John", text: "Jesus asks whether John's baptism was from heaven or from men. John's ministry is the test case: if the leaders answer honestly, their response to Jesus' authority is exposed.", refs: ["Matthew 21:25","John 1:6–7"] },
  "Mark 11:31": { title: "They Reason Among Themselves", text: "The leaders privately reason that saying 'from heaven' would raise the question why they did not believe John. Their concern is political and reputational rather than a sincere search for truth.", refs: ["Matthew 21:25","Luke 20:5"] },
  "Mark 11:32": { title: "Fear of the People", text: "They fear the crowd because the people regard John as a prophet. Their decision is governed by public opinion instead of conviction about God's message.", refs: ["Matthew 21:26","Mark 6:20"] },
  "Mark 11:33": { title: "Neither Will I Tell You", text: "They answer that they do not know, and Jesus declines to tell them by what authority He acts. Their evasive answer reveals unwillingness to face the evidence honestly.", refs: ["Matthew 21:27","Luke 20:8"] }
});

Object.assign(window.verseCommentary, {
  "Mark 12:1": { title: "The Parable of the Vineyard", text: "Jesus tells a parable about a man who plants a vineyard, builds a hedge and winepress, and leases it to tenants. The imagery draws on Israel as God's vineyard and prepares a warning about rejecting God's messengers.", refs: ["Isaiah 5:1–7","Matthew 21:33"] },
  "Mark 12:2": { title: "The Owner Sends a Servant", text: "At harvest time the owner sends a servant to receive fruit from the tenants. The vineyard belongs to the owner, and the tenants are accountable for what has been entrusted to them.", refs: ["Matthew 21:34","Isaiah 5:7"] },
  "Mark 12:3": { title: "The Servant Is Beaten", text: "The tenants seize the servant, beat him, and send him away empty. Their response illustrates the mistreatment of those sent to call God's people back to faithfulness.", refs: ["Jeremiah 7:25–26","2 Chronicles 36:15–16"] },
  "Mark 12:4": { title: "Another Servant Is Wounded", text: "The owner sends another servant, whom the tenants wound in the head and treat shamefully. The repeated rejection shows deliberate rebellion rather than a misunderstanding.", refs: ["Matthew 21:35","Nehemiah 9:26"] },
  "Mark 12:5": { title: "More Servants Are Rejected", text: "The owner sends another servant, whom the tenants kill, and many others are beaten or killed. The parable recalls the long history of rejecting God's messengers.", refs: ["Hebrews 11:36–38","Luke 13:34"] },
  "Mark 12:6": { title: "The Beloved Son", text: "At last the owner sends his beloved son, reasoning that they will respect him. The son represents Jesus, uniquely sent and beloved, and the story moves toward the leaders' rejection of Him.", refs: ["Mark 1:11","John 3:16"] },
  "Mark 12:7": { title: "Let Us Kill the Heir", text: "The tenants decide to kill the heir and seize his inheritance. Their calculation reveals greed and a desire to take what belongs to the owner.", refs: ["Matthew 21:38","John 11:53"] },
  "Mark 12:8": { title: "The Son Is Killed", text: "They kill the son and cast him out of the vineyard. Jesus foreshadows His own rejection and death outside the structures that should have welcomed God's messenger.", refs: ["Hebrews 13:12","Acts 2:23"] },
  "Mark 12:9": { title: "The Owner Will Judge", text: "Jesus asks what the owner will do and answers that he will destroy the tenants and give the vineyard to others. Privilege does not remove accountability; persistent rejection brings judgment.", refs: ["Matthew 21:41","Romans 11:17–21"] },
  "Mark 12:10": { title: "The Rejected Stone", text: "Jesus cites Scripture about the stone rejected by builders becoming the head of the corner. God's purpose vindicates the one human authorities reject.", refs: ["Psalm 118:22–23","Acts 4:11"] },
  "Mark 12:11": { title: "The Lord Has Done This", text: "The exaltation of the rejected stone is the Lord's doing and is marvellous in human eyes. Jesus presents Scripture as revealing God's reversal of human judgment.", refs: ["Psalm 118:23","1 Peter 2:7"] },
  "Mark 12:12": { title: "They Know the Parable Is Against Them", text: "The leaders seek to seize Jesus but fear the crowd, recognizing that the parable is directed against them. They leave, yet their response confirms the warning about rejecting God's messenger.", refs: ["Matthew 21:45–46","John 7:30"] },
  "Mark 12:13": { title: "A Trap About Taxes", text: "Some Pharisees and Herodians are sent to catch Jesus in His words. Their cooperation shows that opposition to Jesus can unite groups that otherwise disagree.", refs: ["Matthew 22:15–16","Luke 20:20"] },
  "Mark 12:14": { title: "Is It Lawful to Pay Tribute?", text: "They flatter Jesus as truthful and impartial, then ask whether tribute should be paid to Caesar. The question is designed to trap Him politically, not to learn sincerely.", refs: ["Matthew 22:16–17","Proverbs 29:5"] },
  "Mark 12:15": { title: "Show Me a Penny", text: "Jesus recognizes their hypocrisy and asks for a coin. He brings their abstract trap into a concrete example they can inspect.", refs: ["Matthew 22:18–19","Luke 20:23–24"] },
  "Mark 12:16": { title: "Whose Image and Superscription?", text: "They show Him a coin and acknowledge Caesar's image and inscription. Their answer prepares Jesus to distinguish obligations to civil authority from obligations to God.", refs: ["Matthew 22:20","Genesis 1:27"] },
  "Mark 12:17": { title: "Render to Caesar and to God", text: "Jesus says to render to Caesar what belongs to Caesar and to God what belongs to God. Civil duties have a place, but God's claim is ultimate because humanity bears His image and owes Him worship and obedience.", refs: ["Matthew 22:21","Romans 13:7","Genesis 1:27"] },
  "Mark 12:18": { title: "The Sadducees Ask About Resurrection", text: "Sadducees, who deny the resurrection, present a case about marriage after death. Their question is intended to ridicule resurrection belief.", refs: ["Matthew 22:23","Acts 23:8"] },
  "Mark 12:19": { title: "Moses' Law About a Brother", text: "They cite the law requiring a man to raise up seed for a deceased brother who left no child. Their question relies on a real legal provision but misunderstands the life to come.", refs: ["Deuteronomy 25:5–6","Luke 20:28"] },
  "Mark 12:20": { title: "Seven Brothers", text: "They describe seven brothers, the first of whom marries and dies without children. The hypothetical is designed to make resurrection seem absurd.", refs: ["Matthew 22:25","Luke 20:29"] },
  "Mark 12:21": { title: "The Second Brother", text: "The second brother marries the widow and dies without children, and then the third does likewise. The repeated deaths extend the hypothetical without addressing the nature of resurrected life.", refs: ["Luke 20:30","Mark 12:20"] },
  "Mark 12:22": { title: "The Woman Also Dies", text: "All seven brothers die without children, and finally the woman dies. The Sadducees set up a dilemma based on earthly marriage arrangements.", refs: ["Matthew 22:26–27","Luke 20:32"] }
});

Object.assign(window.verseCommentary, {
  "Mark 12:23": { title: "Whose Wife Will She Be?", text: "The Sadducees ask whose wife the woman will be in the resurrection, since all seven married her. Their question assumes that resurrected life simply repeats present earthly arrangements.", refs: ["Matthew 22:28","Luke 20:33"] },
  "Mark 12:24": { title: "You Do Not Know the Scriptures", text: "Jesus says their error comes from not knowing the Scriptures or God's power. Sound doctrine requires both careful reading of God's word and confidence in His ability to do what He promises.", refs: ["Matthew 22:29","2 Timothy 2:15"] },
  "Mark 12:25": { title: "Like the Angels in Heaven", text: "Jesus explains that resurrected people do not marry or give in marriage as they do in this age, but are like the angels in heaven in this respect. He teaches a transformed order of life, not that resurrected humans become angels.", refs: ["Matthew 22:30","Luke 20:35–36"] },
  "Mark 12:26": { title: "The God of Abraham", text: "Jesus appeals to the account of the bush, where God identifies Himself as the God of Abraham, Isaac, and Jacob. God's covenant relationship with the patriarchs supports the truth that death does not defeat His promise.", refs: ["Exodus 3:6","Matthew 22:31–32"] },
  "Mark 12:27": { title: "Not the God of the Dead", text: "Jesus says God is not the God of the dead, but of the living, and concludes that the Sadducees greatly err. God's power and covenant faithfulness make resurrection hope reasonable.", refs: ["Luke 20:38","Romans 4:17"] },
  "Mark 12:28": { title: "The First Commandment", text: "A scribe hears the discussion and asks which commandment is first of all. Unlike the previous challengers, his question leads to a direct statement of the heart of God's law.", refs: ["Matthew 22:34–36","Luke 10:25"] },
  "Mark 12:29": { title: "The Lord Our God Is One Lord", text: "Jesus begins with Israel's confession: the Lord our God is one Lord. This central declaration affirms the oneness of God and forms the foundation for wholehearted love and worship.", refs: ["Deuteronomy 6:4","Isaiah 45:5"] },
  "Mark 12:30": { title: "Love God with All Your Being", text: "Jesus commands love for God with all the heart, soul, mind, and strength. True devotion involves the whole person rather than a merely outward religious identity.", refs: ["Deuteronomy 6:5","Joshua 22:5"] },
  "Mark 12:31": { title: "Love Your Neighbour", text: "The second commandment is to love one's neighbour as oneself. Love for God must be expressed in practical concern for other people; no commandment is greater than these.", refs: ["Leviticus 19:18","Romans 13:9–10"] },
  "Mark 12:32": { title: "The Scribe Agrees", text: "The scribe affirms that God is one and there is none other but He, and that loving God and neighbour matters more than offerings alone. He recognizes that worship without obedience and love misses the law's purpose.", refs: ["Deuteronomy 6:4","1 Samuel 15:22"] },
  "Mark 12:33": { title: "Love Above Sacrifices", text: "The scribe says love for God and neighbour is more than all whole burnt offerings and sacrifices. Ritual has its place in Scripture, but God never intended it to replace a heart of love and obedience.", refs: ["Hosea 6:6","Micah 6:6–8"] },
  "Mark 12:34": { title: "Not Far from the Kingdom", text: "Jesus sees that the scribe answers wisely and says he is not far from God's kingdom. Understanding the truth is important, but a person must also respond to it in faith and obedience.", refs: ["Matthew 7:21","James 1:22"] },
  "Mark 12:35": { title: "How Is the Christ David's Son?", text: "While teaching in the temple, Jesus asks how the scribes can say the Christ is David's son. He leads them to consider a Scripture that reveals the Messiah's greater status.", refs: ["Matthew 22:41–42","Psalm 110:1"] },
  "Mark 12:36": { title: "David Speaks by the Holy Ghost", text: "Jesus quotes David's words: the Lord says to David's Lord to sit at His right hand until his enemies are made a footstool. The passage presents the Messiah as greater than an ordinary descendant of David.", refs: ["Psalm 110:1","Acts 2:34–36"] },
  "Mark 12:37": { title: "David Calls Him Lord", text: "Jesus asks how the Christ can be David's son if David calls Him Lord. The question does not deny the Messiah's human descent from David; it presses the crowd to recognize His exalted identity.", refs: ["Matthew 22:45","Romans 1:3–4"] },
  "Mark 12:38": { title: "Beware of the Scribes", text: "Jesus warns the people against scribes who love public displays of status, greetings, and prominent seats. Religious titles and appearances can conceal pride rather than genuine service.", refs: ["Luke 20:46","Matthew 23:5–7"] },
  "Mark 12:39": { title: "Seats of Honour", text: "Jesus continues describing their desire for the chief seats in synagogues and places of honour at feasts. The warning challenges leaders to seek faithfulness rather than recognition.", refs: ["Luke 14:7–11","Matthew 23:6"] },
  "Mark 12:40": { title: "Devouring Widows' Houses", text: "Jesus condemns those who devour widows' houses while making long prayers for appearance. Religious performance cannot excuse exploitation, and Jesus warns that such hypocrisy brings greater judgment.", refs: ["Isaiah 10:1–2","Luke 20:47"] },
  "Mark 12:41": { title: "Jesus Watches the Treasury", text: "Jesus sits opposite the treasury and watches people putting money into it. He observes not only the amount given but the heart and circumstances of the giver.", refs: ["Luke 21:1","1 Samuel 16:7"] },
  "Mark 12:42": { title: "A Poor Widow Gives Two Mites", text: "A poor widow puts in two small coins, worth very little in monetary terms. Her gift is small in amount but significant in what it costs her.", refs: ["Luke 21:2","2 Corinthians 8:12"] },
  "Mark 12:43": { title: "The Widow Gave More", text: "Jesus calls His disciples and says the poor widow gave more than all the others. God's evaluation differs from a simple comparison of totals.", refs: ["Luke 21:3","1 Samuel 16:7"] },
  "Mark 12:44": { title: "She Gave All She Had", text: "The others gave from their abundance, but the widow gave all she had to live on. Jesus commends her costly devotion; the passage should not be used to excuse leaders who pressure poor people into giving beyond their means.", refs: ["Luke 21:4","2 Corinthians 9:7"] }
});

Object.assign(window.verseCommentary, {
  "Mark 13:1": { title: "The Temple's Great Stones", text: "As Jesus leaves the temple, a disciple marvels at its great stones and buildings. Jesus redirects attention from impressive structures to the coming judgment.", refs: ["Matthew 24:1","Luke 21:5"] },
  "Mark 13:2": { title: "Not One Stone Left", text: "Jesus says the temple buildings will be thrown down, with not one stone left upon another. The prediction warns that even sacred and impressive institutions are not immune from judgment.", refs: ["Luke 21:6","Matthew 24:2"] },
  "Mark 13:3": { title: "The Disciples Ask Privately", text: "On the Mount of Olives, Peter, James, John, and Andrew ask Jesus privately about the prediction. They want to understand the timing and signs of what He has said.", refs: ["Matthew 24:3","Zechariah 14:4"] },
  "Mark 13:4": { title: "When Shall These Things Be?", text: "They ask when these things will happen and what sign will show that they are about to be fulfilled. Jesus' answer addresses both their question and the need for spiritual readiness.", refs: ["Matthew 24:3","Luke 21:7"] },
  "Mark 13:5": { title: "Take Heed That No One Deceive You", text: "Jesus begins by warning them not to be deceived. Discernment is essential when people claim authority or announce dramatic events.", refs: ["Matthew 24:4","Ephesians 5:6"] },
  "Mark 13:6": { title: "Many Will Come in My Name", text: "Many will claim to come in Jesus' name and say they are the Christ, deceiving many. The disciples must remain loyal to Jesus rather than follow counterfeit messiahs.", refs: ["Matthew 24:5","1 John 2:18"] },
  "Mark 13:7": { title: "Wars and Rumours of Wars", text: "Reports of wars and rumours of wars will arise, but the disciples must not be troubled because the end is not yet. Turmoil alone does not authorize people to declare the final hour.", refs: ["Matthew 24:6","Luke 21:9"] },
  "Mark 13:8": { title: "Nation Against Nation", text: "Jesus names wars, earthquakes, and famines as the beginning of sorrows. These events are grievous, but they are not by themselves proof that the end has arrived.", refs: ["Matthew 24:7–8","Romans 8:22"] },
  "Mark 13:9": { title: "Watch Yourselves", text: "The disciples will face councils, beatings, and testimony before rulers for Jesus' sake. Persecution becomes an opportunity to bear witness, not a reason to abandon faith.", refs: ["Matthew 10:17–18","Acts 5:40–42"] },
  "Mark 13:10": { title: "The Gospel Must First Be Published", text: "The gospel must first be preached among all nations. The mission of witness continues amid opposition and forms part of God's purpose.", refs: ["Matthew 24:14","Acts 1:8"] },
  "Mark 13:11": { title: "The Holy Ghost Will Help You Speak", text: "When brought before authorities, the disciples are not to be consumed with anxiety over what to say; the Holy Ghost will help them speak. This promise gives courage for persecution and should not be used as an excuse to neglect preparation in ordinary teaching.", refs: ["Matthew 10:19–20","Luke 12:11–12"] },
  "Mark 13:12": { title: "Family Betrayal", text: "Jesus warns that betrayal may divide even families, with some being put to death. Loyalty to God may be tested by the closest human relationships.", refs: ["Matthew 10:21","Micah 7:6"] },
  "Mark 13:13": { title: "Endure to the End", text: "The disciples will be hated for Jesus' name, but the one who endures to the end will be saved. Endurance is steadfast faithfulness through hardship, not a way to earn salvation by human effort.", refs: ["Matthew 24:13","Hebrews 10:36"] },
  "Mark 13:14": { title: "The Abomination of Desolation", text: "Jesus refers to the abomination of desolation standing where it ought not and tells the reader to understand. The language recalls Daniel's prophecy; the precise fulfilment is debated, and the warning calls people to discernment and urgent action in a time of crisis.", refs: ["Daniel 9:27","Daniel 11:31","Matthew 24:15"] },
  "Mark 13:15": { title: "Do Not Go Back Inside", text: "When the crisis comes, the person on the housetop must not go back into the house to collect possessions. The urgency of Jesus' warning requires readiness rather than attachment to material goods.", refs: ["Luke 17:31","Matthew 24:17"] },
  "Mark 13:16": { title: "Do Not Return for a Garment", text: "The person in the field must not turn back to retrieve a garment. The instruction emphasizes swift response when danger comes.", refs: ["Matthew 24:18","Genesis 19:17"] },
  "Mark 13:17": { title: "Woe to the Vulnerable", text: "Jesus laments the hardship for pregnant women and nursing mothers in those days. He recognizes the particular vulnerability of those caring for infants during flight and crisis.", refs: ["Luke 21:23","Matthew 24:19"] },
  "Mark 13:18": { title: "Pray It Be Not in Winter", text: "Jesus tells them to pray that the flight does not occur in winter, when travel would be especially difficult. Prayer and practical concern belong together.", refs: ["Matthew 24:20","Luke 21:36"] },
  "Mark 13:19": { title: "Great Tribulation", text: "Jesus describes distress unlike anything from the beginning of creation until then. The language conveys the severity of the coming crisis and echoes prophetic judgment language.", refs: ["Daniel 12:1","Matthew 24:21"] },
  "Mark 13:20": { title: "The Days Are Shortened", text: "The Lord shortens the days for the sake of the elect, otherwise no flesh would be saved. The verse emphasizes God's sovereignty and mercy even in severe judgment.", refs: ["Matthew 24:22","Isaiah 65:8–9"] },
  "Mark 13:21": { title: "Do Not Believe False Christs", text: "If anyone says the Christ is here or there, the disciples must not believe it. Jesus warns against sensational claims that seek to draw people away from His words.", refs: ["Matthew 24:23","Luke 17:23"] },
  "Mark 13:22": { title: "False Christs and Prophets", text: "False messiahs and prophets will show signs and wonders to deceive, if possible, even the elect. Miraculous claims alone are not a sufficient test of truth; everything must be judged by God's word.", refs: ["Deuteronomy 13:1–3","Matthew 24:24"] },
  "Mark 13:23": { title: "I Have Told You Beforehand", text: "Jesus warns His disciples in advance. His teaching prepares them to remain watchful rather than be taken by surprise by deception.", refs: ["Matthew 24:25","John 16:4"] },
  "Mark 13:24": { title: "The Sun Shall Be Darkened", text: "Jesus describes the sun darkening and the moon withholding its light after the tribulation. Such cosmic language is common in prophetic descriptions of divine judgment and may also point to the final consummation.", refs: ["Isaiah 13:10","Joel 2:10","Matthew 24:29"] },
  "Mark 13:25": { title: "The Powers of Heaven Shaken", text: "The stars fall and the powers in heaven are shaken. The imagery communicates upheaval on a scale beyond ordinary political change.", refs: ["Isaiah 34:4","Luke 21:26"] },
  "Mark 13:26": { title: "The Son of Man Comes in Glory", text: "People will see the Son of man coming in clouds with great power and glory. The image draws on Daniel's vision and points to divine authority and public vindication.", refs: ["Daniel 7:13–14","Matthew 24:30"] },
  "Mark 13:27": { title: "The Elect Are Gathered", text: "The Son of man sends angels to gather His elect from the ends of the earth and heaven. God's people will not be forgotten when He brings His purpose to completion.", refs: ["Matthew 24:31","Deuteronomy 30:4"] },
  "Mark 13:28": { title: "Learn from the Fig Tree", text: "When the fig tree's branch becomes tender and leaves appear, people know summer is near. Jesus uses a familiar seasonal sign to teach attentive observation.", refs: ["Matthew 24:32","Luke 21:29–30"] },
  "Mark 13:29": { title: "Recognize the Nearness", text: "In the same way, when the described events occur, the disciples are to recognize that the time is near. The illustration calls for watchfulness, not date-setting beyond what Jesus reveals.", refs: ["Matthew 24:33","Luke 21:31"] },
  "Mark 13:30": { title: "This Generation", text: "Jesus says this generation will not pass until these things are done. Christians interpret 'this generation' in different ways, including the contemporaries who witnessed Jerusalem's judgment or the generation associated with the final signs; the text should be handled carefully rather than forced into one timeline.", refs: ["Matthew 24:34","Mark 13:2"] },
  "Mark 13:31": { title: "My Words Shall Not Pass Away", text: "Heaven and earth will pass away, but Jesus' words will not pass away. His teaching has enduring authority beyond the present created order.", refs: ["Matthew 24:35","Isaiah 40:8"] },
  "Mark 13:32": { title: "No One Knows the Day or Hour", text: "No one knows that day or hour, not angels or the Son, but the Father. The verse warns against claiming knowledge of the timetable that God has not disclosed.", refs: ["Matthew 24:36","Acts 1:7"] },
  "Mark 13:33": { title: "Take Heed and Watch", text: "Because the time is unknown, the disciples must take heed, watch, and pray. Uncertainty about timing is meant to produce readiness, not speculation.", refs: ["Matthew 24:42","Luke 21:36"] },
  "Mark 13:34": { title: "A Man Leaves His House", text: "Jesus compares the situation to a man who travels, leaves authority with his servants, assigns each work, and commands the doorkeeper to watch. Each servant has a responsibility during the master's absence.", refs: ["Matthew 25:14–15","Luke 12:35–36"] },
  "Mark 13:35": { title: "Watch for the Master", text: "The disciples do not know whether the master will come at evening, midnight, cockcrow, or morning. Readiness must continue through every possible hour.", refs: ["Matthew 24:42–44","1 Thessalonians 5:6"] },
  "Mark 13:36": { title: "Lest He Find You Sleeping", text: "Jesus warns that the master might arrive suddenly and find the servants asleep. Spiritual carelessness is the danger, not ordinary physical sleep.", refs: ["Luke 21:34–36","Romans 13:11"] },
  "Mark 13:37": { title: "What I Say to All: Watch", text: "Jesus concludes that what He says to the disciples, He says to all: watch. The call extends to every generation of believers as a summons to faithful readiness.", refs: ["Matthew 24:42","Revelation 16:15"] }
});

Object.assign(window.verseCommentary, {
  "Mark 14:1": { title: "The Passover Approaches", text: "The Passover and feast of unleavened bread are two days away, and chief priests and scribes seek a way to take Jesus by craft and kill Him. Their plans move toward the sacrifice Jesus has already foretold.", refs: ["Matthew 26:2–4","Exodus 12:1–14"] },
  "Mark 14:2": { title: "Not During the Feast", text: "The leaders say they should not act during the feast lest there be an uproar among the people. Their concern is public reaction, not justice.", refs: ["Matthew 26:5","Luke 22:2"] },
  "Mark 14:3": { title: "Anointing at Bethany", text: "While Jesus is at Bethany in the house of Simon the leper, a woman brings an alabaster box of costly ointment and pours it on His head. Her costly act of devotion stands in contrast to the leaders' plot.", refs: ["Matthew 26:6–7","John 12:1–3"] },
  "Mark 14:4": { title: "Some Are Indignant", text: "Some present are indignant and ask why the ointment was wasted. They evaluate the act only by its sale value and miss its meaning in the moment before Jesus' death.", refs: ["John 12:4–5","Matthew 26:8"] },
  "Mark 14:5": { title: "The Poor Could Have Been Helped", text: "They say the ointment could have been sold for more than three hundred pence and given to the poor, and they criticize the woman. Concern for the poor can be sincere, but it can also be used to condemn an act of genuine devotion.", refs: ["John 12:5–6","Deuteronomy 15:11"] },
  "Mark 14:6": { title: "Let Her Alone", text: "Jesus tells them to leave her alone and not trouble her, saying she has done a good work for Him. He defends the woman's act against an unfair accusation.", refs: ["Matthew 26:10","John 12:7"] },
  "Mark 14:7": { title: "The Poor Are Always There", text: "Jesus says the poor are always present and can be helped, but His own presence with them is limited. He is not dismissing care for the poor; He is identifying the unique moment of His approaching death.", refs: ["Deuteronomy 15:11","Matthew 26:11"] },
  "Mark 14:8": { title: "She Has Done What She Could", text: "Jesus says the woman has done what she could and anointed His body beforehand for burial. Her act, whether or not she understood every detail, honours Him before His suffering.", refs: ["John 12:7","Mark 16:1"] },
  "Mark 14:9": { title: "A Memorial Wherever the Gospel Is Preached", text: "Jesus declares that wherever the gospel is preached throughout the world, what the woman has done will be told in remembrance of her. Her quiet devotion becomes part of the gospel story.", refs: ["Matthew 26:13","Hebrews 6:10"] },
  "Mark 14:10": { title: "Judas Goes to the Chief Priests", text: "Judas Iscariot, one of the Twelve, goes to the chief priests to betray Jesus. His position among the disciples makes the betrayal especially painful.", refs: ["Matthew 26:14","Luke 22:3–4"] },
  "Mark 14:11": { title: "They Promise Money", text: "The chief priests are glad and promise to give Judas money, and he looks for an opportunity to betray Jesus. Greed and calculated betrayal advance the plot toward the arrest.", refs: ["Matthew 26:15–16","Zechariah 11:12"] },
  "Mark 14:12": { title: "Preparing the Passover", text: "On the first day of unleavened bread, when the Passover lamb is sacrificed, the disciples ask where Jesus wants them to prepare the meal. The Passover setting connects His coming death with Israel's story of deliverance.", refs: ["Exodus 12:6","Matthew 26:17"] },
  "Mark 14:13": { title: "Follow the Man Carrying Water", text: "Jesus sends two disciples into the city to follow a man carrying a pitcher of water. His detailed instructions guide them to the place He has prepared.", refs: ["Luke 22:10","Matthew 26:18"] },
  "Mark 14:14": { title: "The Guest Chamber", text: "They are to ask the householder where the guest chamber is in which Jesus may eat the Passover with His disciples. The meal is prepared through this arrangement.", refs: ["Luke 22:11","Mark 14:13"] },
  "Mark 14:15": { title: "A Large Upper Room", text: "The householder will show them a large upper room furnished and prepared. The disciples are to make ready there.", refs: ["Luke 22:12","Acts 1:13"] },
  "Mark 14:16": { title: "They Prepare the Passover", text: "The disciples go into the city, find everything as Jesus said, and prepare the Passover. Their obedience confirms His instructions.", refs: ["Matthew 26:19","Luke 22:13"] },
  "Mark 14:17": { title: "Jesus Comes with the Twelve", text: "In the evening Jesus comes with the Twelve. The meal begins with the full group, though betrayal is already near.", refs: ["Matthew 26:20","Luke 22:14"] },
  "Mark 14:18": { title: "One of You Will Betray Me", text: "As they sit and eat, Jesus says one of them who eats with Him will betray Him. The warning brings the hidden betrayal into the open.", refs: ["Psalm 41:9","Matthew 26:21"] },
  "Mark 14:19": { title: "Is It I?", text: "The disciples become sorrowful and ask one by one whether it is they. Their questions express distress and uncertainty as Jesus' words unsettle the group.", refs: ["Matthew 26:22","Luke 22:23"] },
  "Mark 14:20": { title: "One of the Twelve", text: "Jesus identifies the betrayer as one of the Twelve, one who dips with Him in the dish. The betrayal comes from within the circle of close fellowship.", refs: ["Matthew 26:23","Psalm 41:9"] },
  "Mark 14:21": { title: "The Son of Man Goes as Written", text: "Jesus says the Son of man goes as it is written of Him, but woe to the betrayer. God's foreknowledge and purpose do not erase the betrayer's responsibility for his action.", refs: ["Luke 22:22","Acts 2:23"] },
  "Mark 14:22": { title: "Take, Eat: This Is My Body", text: "As they eat, Jesus takes bread, blesses, breaks it, and gives it to them, saying, 'Take, eat: this is my body.' The bread becomes the memorial sign of His body given for them.", refs: ["Matthew 26:26","1 Corinthians 11:23–24"] },
  "Mark 14:23": { title: "The Cup of Thanksgiving", text: "Jesus takes the cup, gives thanks, and gives it to them, and they all drink of it. The cup will be explained as connected with His covenant blood.", refs: ["Matthew 26:27","1 Corinthians 10:16"] },
  "Mark 14:24": { title: "My Blood of the New Testament", text: "Jesus calls the cup His blood of the new covenant, shed for many. His death establishes the promised covenant forgiveness through the sacrifice He willingly offers.", refs: ["Jeremiah 31:31–34","Matthew 26:28","Hebrews 9:14–15"] },
  "Mark 14:25": { title: "Until the Kingdom Comes", text: "Jesus says He will not drink again of the fruit of the vine until He drinks it new in God's kingdom. The meal looks forward to the fulfilment of God's reign beyond the coming suffering.", refs: ["Matthew 26:29","Luke 22:18"] },
  "Mark 14:26": { title: "They Sing a Hymn", text: "After singing a hymn, they go out to the Mount of Olives. Worship continues even as Jesus moves toward the place of His arrest.", refs: ["Matthew 26:30","Psalm 113–118"] },
  "Mark 14:27": { title: "The Shepherd Will Be Smitten", text: "Jesus tells the disciples that they will all be offended because Scripture says the shepherd will be smitten and the sheep scattered. He foretells their failure without abandoning His care for them.", refs: ["Zechariah 13:7","Matthew 26:31"] },
  "Mark 14:28": { title: "After I Am Risen", text: "Jesus promises that after He is risen, He will go before them into Galilee. Resurrection will restore the relationship that their coming failure will strain.", refs: ["Matthew 26:32","Mark 16:7"] },
  "Mark 14:29": { title: "Peter's Confidence", text: "Peter declares that even if all others are offended, he will not be. His confidence is sincere but overestimates his own strength.", refs: ["Matthew 26:33","Proverbs 16:18"] },
  "Mark 14:30": { title: "Before the Cock Crows Twice", text: "Jesus tells Peter that before the cock crows twice, Peter will deny Him three times. Jesus knows Peter's coming weakness before Peter recognizes it himself.", refs: ["Matthew 26:34","Luke 22:34"] },
  "Mark 14:31": { title: "Peter Insists He Will Not Deny Him", text: "Peter speaks more vehemently that he would die with Jesus rather than deny Him, and the others say likewise. Their courage is real in intention but will be tested by fear.", refs: ["Matthew 26:35","John 13:37"] },
  "Mark 14:32": { title: "Gethsemane", text: "They come to Gethsemane, and Jesus tells His disciples to sit while He prays. The garden becomes the setting for His anguish and submission before the arrest.", refs: ["Matthew 26:36","Luke 22:39"] },
  "Mark 14:33": { title: "Peter, James, and John", text: "Jesus takes Peter, James, and John with Him and begins to be deeply troubled and distressed. Mark presents the genuine emotional weight of the suffering Jesus faces.", refs: ["Matthew 26:37","Hebrews 5:7"] },
  "Mark 14:34": { title: "My Soul Is Exceeding Sorrowful", text: "Jesus tells them His soul is exceedingly sorrowful, even unto death, and asks them to remain and watch. His anguish is real; He does not face the cross as though human suffering were an illusion.", refs: ["Psalm 42:5","Matthew 26:38"] },
  "Mark 14:35": { title: "He Falls to the Ground", text: "Jesus goes a little farther, falls to the ground, and prays that, if possible, the hour might pass from Him. His prayer expresses the full weight of the suffering before Him.", refs: ["Matthew 26:39","Luke 22:41"] },
  "Mark 14:36": { title: "Not My Will, but Thine", text: "Jesus addresses God as Abba, Father, acknowledges that all things are possible to Him, and submits: not what I will, but what Thou wilt. In the Oneness understanding, this reveals Jesus' genuine human will and obedient human life submitted to the Father, not two competing divine beings.", refs: ["Luke 22:42","John 6:38","Philippians 2:8"] }
});

Object.assign(window.verseCommentary, {
  "Mark 14:37": { title: "Could You Not Watch One Hour?", text: "Jesus returns and finds the disciples sleeping, and He asks Peter whether he could not watch one hour. The disciples' weakness contrasts with Jesus' alertness in prayer.", refs: ["Matthew 26:40","Luke 22:45"] },
  "Mark 14:38": { title: "Watch and Pray", text: "Jesus tells them to watch and pray lest they enter into temptation; the spirit is willing, but the flesh is weak. Prayer prepares disciples to stand when sincere intentions meet human weakness.", refs: ["Matthew 26:41","Galatians 5:17"] },
  "Mark 14:39": { title: "Jesus Prays Again", text: "Jesus goes away and prays again, speaking the same words. His repeated prayer reveals persevering submission in anguish.", refs: ["Matthew 26:42","Luke 22:44"] },
  "Mark 14:40": { title: "Their Eyes Are Heavy", text: "When Jesus returns, the disciples are asleep again and do not know what to answer Him. They are overwhelmed by sorrow and unable to give the support He asked for.", refs: ["Matthew 26:43","Luke 22:45"] },
  "Mark 14:41": { title: "The Hour Has Come", text: "Jesus returns a third time and tells them to sleep on if they can, then announces that the hour has come and the Son of man is betrayed into the hands of sinners. The moment of arrest is now at hand.", refs: ["Matthew 26:45","John 12:27"] },
  "Mark 14:42": { title: "Rise, Let Us Go", text: "Jesus tells the disciples to rise because His betrayer is near. He does not flee the appointed encounter but faces it knowingly.", refs: ["Matthew 26:46","John 18:4"] },
  "Mark 14:43": { title: "Judas Arrives with a Crowd", text: "While Jesus is speaking, Judas arrives with a crowd armed with swords and staves, sent by the religious authorities. The arrest comes through a coordinated action, not a spontaneous misunderstanding.", refs: ["Matthew 26:47","Luke 22:47"] },
  "Mark 14:44": { title: "The Betrayal Sign", text: "Judas has arranged a signal: the one he kisses is Jesus, whom they should seize and take away safely. A gesture of affection is turned into a means of betrayal.", refs: ["Matthew 26:48","Psalm 41:9"] },
  "Mark 14:45": { title: "Judas Kisses Jesus", text: "Judas approaches Jesus, calls Him Master, and kisses Him. The betrayal is personal because it comes through a sign of closeness.", refs: ["Matthew 26:49","Luke 22:48"] },
  "Mark 14:46": { title: "They Lay Hands on Jesus", text: "The crowd seizes Jesus and takes Him. The arrest begins the sequence of unjust treatment that He has already foretold.", refs: ["Matthew 26:50","John 18:12"] },
  "Mark 14:47": { title: "A Sword Is Drawn", text: "One standing by draws a sword and strikes the servant of the high priest, cutting off his ear. The disciples' attempt to resist by violence does not represent the way Jesus' kingdom is advanced.", refs: ["Matthew 26:51","John 18:10"] },
  "Mark 14:48": { title: "As Against a Robber", text: "Jesus asks whether they have come with swords and staves to take Him as a robber. He exposes the absurdity of treating Him as a violent criminal after His public teaching.", refs: ["Matthew 26:55","Luke 22:52"] },
  "Mark 14:49": { title: "Daily Teaching in the Temple", text: "Jesus reminds them that He taught daily in the temple and they did not arrest Him then. Their action takes place in darkness, but the events fulfil Scripture.", refs: ["Luke 19:47","John 18:20"] },
  "Mark 14:50": { title: "All Forsake Him", text: "All the disciples forsake Jesus and flee. Their failure fulfils His warning and shows the depth of human fear under pressure.", refs: ["Matthew 26:56","Zechariah 13:7"] },
  "Mark 14:51": { title: "A Young Man Flees", text: "A young man following Jesus, wearing a linen cloth, is seized but escapes naked when the cloth is left behind. Mark records the confusion and panic surrounding the arrest; the young man's identity is not stated.", refs: ["Mark 14:50","Amos 2:16"] },
  "Mark 14:52": { title: "He Flees Naked", text: "The young man leaves the linen cloth and flees. The brief detail reinforces the complete scattering and fear of that night.", refs: ["Mark 14:50–51","Matthew 26:56"] },
  "Mark 14:53": { title: "Jesus Before the High Priest", text: "Jesus is led to the high priest, where chief priests, elders, and scribes gather. The religious authorities assemble to pursue a case against Him.", refs: ["Matthew 26:57","John 18:13"] },
  "Mark 14:54": { title: "Peter Follows at a Distance", text: "Peter follows Jesus at a distance into the high priest's courtyard and sits with the servants, warming himself. He has not fully abandoned Jesus, but fear keeps him at a distance.", refs: ["Matthew 26:58","Luke 22:54"] },
  "Mark 14:55": { title: "Seeking Witness Against Jesus", text: "The chief priests and council seek testimony to put Jesus to death but find none sufficient. The process is driven toward a desired verdict rather than an impartial search for truth.", refs: ["Matthew 26:59","Psalm 27:12"] }
});

Object.assign(window.verseCommentary, {
  "Mark 14:56": { title: "False Witnesses Disagree", text: "Many bear false witness against Jesus, but their testimonies do not agree. The failed testimony exposes the injustice of the proceedings.", refs: ["Matthew 26:60","Psalm 35:11"] },
  "Mark 14:57": { title: "Another False Witness", text: "Some rise and give false testimony against Jesus. The authorities continue seeking grounds for condemnation rather than responding honestly to His teaching and works.", refs: ["Matthew 26:60–61","Deuteronomy 19:16–19"] },
  "Mark 14:58": { title: "Destroying and Rebuilding the Temple", text: "Witnesses claim Jesus said He would destroy the temple made with hands and build another made without hands in three days. Their words distort His teaching about the temple of His body and His resurrection.", refs: ["John 2:19–21","Matthew 26:61"] },
  "Mark 14:59": { title: "Their Testimony Does Not Agree", text: "Even on this claim, their testimony does not agree. The inability to establish consistent evidence highlights the injustice of the trial.", refs: ["Mark 14:56","Deuteronomy 19:15"] },
  "Mark 14:60": { title: "The High Priest Questions Jesus", text: "The high priest stands in the midst and asks Jesus whether He answers the accusations. Jesus does not attempt to make false witnesses agree.", refs: ["Matthew 26:62","Isaiah 53:7"] },
  "Mark 14:61": { title: "Are You the Christ?", text: "Jesus remains silent until the high priest asks whether He is the Christ, the Son of the Blessed. The question demands a direct answer about His identity.", refs: ["Matthew 26:63","Isaiah 53:7"] },
  "Mark 14:62": { title: "I Am", text: "Jesus answers, 'I am,' and speaks of the Son of man seated at the right hand of power and coming with the clouds of heaven. He applies the exalted imagery of Psalm 110 and Daniel 7 to Himself, declaring messianic authority and future vindication.", refs: ["Psalm 110:1","Daniel 7:13–14","Matthew 26:64"] },
  "Mark 14:63": { title: "The High Priest Tears His Clothes", text: "The high priest tears his clothes and declares that they need no further witnesses. He treats Jesus' answer as blasphemy rather than examining the scriptural claim Jesus has made.", refs: ["Matthew 26:65","Leviticus 24:16"] },
  "Mark 14:64": { title: "They Condemn Him", text: "The council judges Jesus worthy of death. Their verdict shows the leaders' rejection of His claim and prepares for His delivery to the Roman authorities.", refs: ["Matthew 26:66","John 19:7"] },
  "Mark 14:65": { title: "Mocked and Beaten", text: "Some spit on Jesus, blindfold Him, strike Him, and mock Him to prophesy; the officers also strike Him. The abuse fulfils the pattern of the suffering servant who is rejected and humiliated.", refs: ["Isaiah 50:6","Matthew 26:67–68"] },
  "Mark 14:66": { title: "Peter in the Courtyard", text: "As Peter is below in the courtyard, one of the high priest's servant girls comes by. The scene shifts from Jesus' trial to Peter's predicted denial.", refs: ["Matthew 26:69","Luke 22:55–56"] },
  "Mark 14:67": { title: "You Were with Jesus", text: "The servant girl sees Peter warming himself and says he was with Jesus of Nazareth. Peter faces the first direct challenge to his association with Jesus.", refs: ["Matthew 26:69","John 18:17"] },
  "Mark 14:68": { title: "Peter Denies Him", text: "Peter denies knowing or understanding what she means and moves toward the porch; the cock crows. Fear begins to overcome his earlier confident promise.", refs: ["Matthew 26:70","Luke 22:57"] },
  "Mark 14:69": { title: "Another Accusation", text: "The servant girl sees Peter again and tells those standing nearby that he is one of them. Peter's presence and speech continue to draw attention.", refs: ["Matthew 26:71","John 18:25"] },
  "Mark 14:70": { title: "Peter Denies Again", text: "Peter denies it again, and after a little while the bystanders say he must be one of Jesus' followers because he is a Galilean. His effort to conceal his identity becomes harder to maintain.", refs: ["Matthew 26:72–73","Luke 22:58"] },
  "Mark 14:71": { title: "Peter Swears He Does Not Know Jesus", text: "Peter begins to curse and swear that he does not know the man they speak of. His denial is serious, but it is not the end of his story; Jesus will later restore him.", refs: ["Matthew 26:74","John 21:15–17"] },
  "Mark 14:72": { title: "Peter Remembers and Weeps", text: "The cock crows a second time, and Peter remembers Jesus' words and weeps. His grief shows that he recognizes his failure, preparing for the later work of repentance and restoration.", refs: ["Matthew 26:75","Luke 22:61–62"] }
});

Object.assign(window.verseCommentary, {
  "Mark 15:1": { title: "Jesus Before Pilate", text: "Early in the morning, the chief priests consult with elders, scribes, and the council, bind Jesus, and deliver Him to Pilate. The religious leaders bring the case to Roman authority.", refs: ["Matthew 27:1–2","Luke 23:1"] },
  "Mark 15:2": { title: "Art Thou the King of the Jews?", text: "Pilate asks whether Jesus is the King of the Jews, and Jesus answers, 'Thou sayest it.' His response acknowledges the title while leaving Pilate to confront its meaning.", refs: ["Matthew 27:11","John 18:33–37"] },
  "Mark 15:3": { title: "Many Accusations", text: "The chief priests accuse Jesus of many things. The multiplicity of accusations contrasts with His restrained response.", refs: ["Matthew 27:12","Luke 23:2"] },
  "Mark 15:4": { title: "Pilate Questions Jesus Again", text: "Pilate asks whether Jesus answers the accusations, but Jesus remains silent. His silence recalls the suffering servant who does not answer every false charge.", refs: ["Isaiah 53:7","Matthew 27:13"] },
  "Mark 15:5": { title: "Pilate Marvels", text: "Jesus gives no further answer, and Pilate marvels. The governor is surprised by His composure before the accusations.", refs: ["Matthew 27:14","John 19:9"] },
  "Mark 15:6": { title: "The Passover Release Custom", text: "At the feast, Pilate customarily releases a prisoner chosen by the people. The custom becomes the setting for a choice between Jesus and Barabbas.", refs: ["Matthew 27:15","Luke 23:17"] },
  "Mark 15:7": { title: "Barabbas", text: "Barabbas is imprisoned with rebels who committed murder in an insurrection. He represents a guilty prisoner who will be released while Jesus, whom Pilate finds no valid cause to condemn, is sentenced.", refs: ["Luke 23:19","John 18:40"] },
  "Mark 15:8": { title: "The Crowd Asks for the Custom", text: "The crowd begins asking Pilate to do as he has usually done. Their request sets the decision before the governor.", refs: ["Matthew 27:20","John 18:39"] },
  "Mark 15:9": { title: "Shall I Release the King?", text: "Pilate asks whether they want him to release the King of the Jews. He recognizes the title attached to Jesus but attempts to manage the crowd's response.", refs: ["Matthew 27:17","John 18:39"] },
  "Mark 15:10": { title: "Pilate Knows Their Motive", text: "Pilate knows the chief priests have delivered Jesus because of envy. He sees that the accusation is not simply a sincere concern for justice.", refs: ["Matthew 27:18","Genesis 37:11"] },
  "Mark 15:11": { title: "The Crowd Chooses Barabbas", text: "The chief priests stir up the crowd to ask for Barabbas instead. The leaders manipulate public opinion to secure their desired outcome.", refs: ["Matthew 27:20","Acts 3:14"] },
  "Mark 15:12": { title: "What Shall I Do with Jesus?", text: "Pilate asks what he should do with the one they call King of the Jews. The question places responsibility for the decision before the crowd and the governor.", refs: ["Matthew 27:22","John 19:14"] },
  "Mark 15:13": { title: "Crucify Him", text: "The crowd cries out for Jesus to be crucified. The demand for execution overwhelms the call for a just verdict.", refs: ["Luke 23:21","John 19:6"] },
  "Mark 15:14": { title: "What Evil Has He Done?", text: "Pilate asks what evil Jesus has done, but the crowd cries out even more for crucifixion. Their insistence is not supported by a demonstrated crime.", refs: ["Matthew 27:23","Luke 23:22"] },
  "Mark 15:15": { title: "Pilate Delivers Jesus", text: "Wanting to satisfy the crowd, Pilate releases Barabbas and has Jesus scourged and delivered to be crucified. Political expediency wins over justice.", refs: ["John 19:1","Matthew 27:26"] },
  "Mark 15:16": { title: "The Soldiers Gather", text: "The soldiers lead Jesus into the palace courtyard and gather the whole band. The Roman soldiers prepare to mock the one condemned to crucifixion.", refs: ["Matthew 27:27","John 19:2"] },
  "Mark 15:17": { title: "A Crown of Thorns", text: "They clothe Jesus in purple and twist together a crown of thorns. The soldiers parody royal symbols, unknowingly highlighting the suffering of the true King.", refs: ["Matthew 27:28–29","John 19:2"] },
  "Mark 15:18": { title: "Hail, King of the Jews", text: "They begin saluting Jesus as King of the Jews. Their mockery contrasts with the truth of His kingship.", refs: ["Matthew 27:29","John 19:3"] },
  "Mark 15:19": { title: "They Strike and Spit on Him", text: "The soldiers strike Jesus on the head, spit on Him, and bow in mock homage. He endures humiliation without retaliating.", refs: ["Isaiah 50:6","Matthew 27:30"] },
  "Mark 15:20": { title: "Led Away to Crucifixion", text: "After mocking Him, they remove the purple robe, put His own clothes back on Him, and lead Him out to crucify Him. The public humiliation gives way to the execution.", refs: ["Matthew 27:31","John 19:16"] },
  "Mark 15:21": { title: "Simon of Cyrene Carries the Cross", text: "Simon of Cyrene, father of Alexander and Rufus, is compelled to carry Jesus' cross. The detail names a witness associated with the early Christian community.", refs: ["Matthew 27:32","Luke 23:26"] },
  "Mark 15:22": { title: "Golgotha", text: "They bring Jesus to Golgotha, meaning the place of a skull. The location becomes the place of His sacrificial death.", refs: ["Matthew 27:33","John 19:17"] },
  "Mark 15:23": { title: "Wine Mingled with Myrrh", text: "They offer Jesus wine mixed with myrrh, but He does not take it. The narrative records His refusal without explaining every reason for it.", refs: ["Matthew 27:34","Psalm 69:21"] },
  "Mark 15:24": { title: "They Crucify Him", text: "The soldiers crucify Jesus and divide His garments by casting lots. The terrible act fulfils the scriptural picture of the righteous sufferer whose clothing is divided.", refs: ["Psalm 22:18","John 19:23–24"] },
  "Mark 15:25": { title: "The Third Hour", text: "Mark notes that it was the third hour when they crucified Jesus. The detail places the execution within the day's timeline.", refs: ["John 19:14–16","Matthew 27:35"] },
  "Mark 15:26": { title: "The Charge Above Him", text: "The inscription states the accusation, 'THE KING OF THE JEWS.' Intended as a charge, the title also declares the identity that the mockers refuse to honour.", refs: ["Matthew 27:37","John 19:19–22"] }
});

Object.assign(window.verseCommentary, {
  "Mark 15:27": { title: "Two Robbers Crucified with Him", text: "Two robbers are crucified with Jesus, one on His right and one on His left. He is numbered among transgressors, as Scripture foretold.", refs: ["Isaiah 53:12","Matthew 27:38"] },
  "Mark 15:28": { title: "A Textual Note", text: "This verse, stating that Scripture was fulfilled by Jesus being numbered with transgressors, appears in the traditional KJV but is omitted from many early Greek manuscripts. The same prophecy is explicitly cited in Luke 22:37.", refs: ["Isaiah 53:12","Luke 22:37"] },
  "Mark 15:29": { title: "Mocked by Passersby", text: "Those passing by wag their heads and mock Jesus, repeating the accusation about destroying the temple and rebuilding it in three days. Their words echo the distorted testimony used at His trial.", refs: ["Psalm 22:7","Matthew 27:39–40"] },
  "Mark 15:30": { title: "Save Thyself", text: "The mockers challenge Jesus to come down from the cross and save Himself. They misunderstand that His saving mission requires Him to remain and give His life.", refs: ["Matthew 27:40","John 12:27"] },
  "Mark 15:31": { title: "Chief Priests Mock Him", text: "The chief priests and scribes mock Jesus among themselves, saying He saved others but cannot save Himself. Their taunt unintentionally points toward the sacrificial purpose of His death for others.", refs: ["Matthew 27:41–42","John 11:50–52"] },
  "Mark 15:32": { title: "Let Christ Come Down", text: "They challenge Christ, the King of Israel, to come down from the cross so they may believe. The two crucified men also revile Him, according to Mark's account; the scene shows how suffering becomes a target for mockery.", refs: ["Matthew 27:42–44","Luke 23:39–43"] },
  "Mark 15:33": { title: "Darkness over the Land", text: "At the sixth hour darkness comes over the whole land until the ninth hour. The darkness marks the gravity of Jesus' death and recalls prophetic imagery of the day of the Lord.", refs: ["Amos 8:9","Matthew 27:45"] },
  "Mark 15:34": { title: "My God, My God, Why Hast Thou Forsaken Me?", text: "At the ninth hour Jesus cries the opening words of Psalm 22. He voices the anguish of the righteous sufferer and invokes a psalm that moves from affliction toward God's vindication. In the Oneness view, this is Jesus' genuine human experience of suffering and prayer, not proof of two separate divine persons.", refs: ["Psalm 22:1","Matthew 27:46","Hebrews 5:7"] },
  "Mark 15:35": { title: "They Think He Calls Elijah", text: "Some bystanders misunderstand Jesus' cry and think He is calling Elijah. Their reaction shows that they do not grasp the Scripture He is invoking.", refs: ["Matthew 27:47","Psalm 22:1"] },
  "Mark 15:36": { title: "A Sponge of Vinegar", text: "Someone offers Jesus vinegar on a sponge and tells others to wait and see whether Elijah will come to take Him down. The onlookers continue watching rather than understanding the significance of His suffering.", refs: ["Psalm 69:21","Matthew 27:48–49"] },
  "Mark 15:37": { title: "Jesus Gives Up the Ghost", text: "Jesus cries with a loud voice and dies. The Gospels present His death as real, the necessary offering of His human life for the redemption of humanity.", refs: ["John 19:30","Hebrews 2:14","1 Peter 3:18"] },
  "Mark 15:38": { title: "The Veil of the Temple Is Torn", text: "The temple veil is torn in two from top to bottom. The sign points to a decisive change in access to God through Jesus' death, not a human achievement.", refs: ["Matthew 27:51","Hebrews 10:19–22"] },
  "Mark 15:39": { title: "The Centurion's Confession", text: "The centurion standing opposite Jesus sees how He dies and says truly this man was the Son of God. A Gentile soldier recognizes something extraordinary in Jesus' death, while the precise force of the title is understood in the Gospel's larger context.", refs: ["Matthew 27:54","Mark 1:1"] },
  "Mark 15:40": { title: "Women Watching from Afar", text: "Women, including Mary Magdalene, Mary the mother of James the Less and Joses, and Salome, watch from a distance. They are among the faithful witnesses who remain connected to Jesus through His death.", refs: ["Matthew 27:55–56","Luke 8:2–3"] },
  "Mark 15:41": { title: "They Had Followed and Ministered", text: "These women had followed Jesus in Galilee and ministered to Him, along with many others who came to Jerusalem. Mark records their faithful service and presence as witnesses.", refs: ["Luke 8:1–3","Matthew 27:55"] },
  "Mark 15:42": { title: "The Preparation Day", text: "Because it is the preparation day before the Sabbath, evening is approaching. The timing creates urgency for burial before the Sabbath begins.", refs: ["Luke 23:54","John 19:31"] },
  "Mark 15:43": { title: "Joseph of Arimathaea", text: "Joseph, an honourable counsellor who waits for God's kingdom, boldly asks Pilate for Jesus' body. His request is a courageous public act of allegiance at a dangerous moment.", refs: ["Matthew 27:57–58","John 19:38"] },
  "Mark 15:44": { title: "Pilate Confirms the Death", text: "Pilate marvels that Jesus is already dead and calls the centurion to confirm it. The detail emphasizes that Jesus' death is verified, not merely assumed.", refs: ["John 19:33–34","Mark 15:37"] },
  "Mark 15:45": { title: "The Body Is Given to Joseph", text: "After receiving confirmation from the centurion, Pilate grants Jesus' body to Joseph. The burial arrangements can proceed before the Sabbath.", refs: ["Matthew 27:58","John 19:38"] },
  "Mark 15:46": { title: "Jesus Is Buried", text: "Joseph buys linen, takes Jesus down, wraps Him, and lays Him in a tomb hewn from rock, then rolls a stone to the entrance. The burial confirms the reality of Jesus' death and prepares for the resurrection account.", refs: ["Isaiah 53:9","Matthew 27:59–60"] },
  "Mark 15:47": { title: "The Women See the Tomb", text: "Mary Magdalene and Mary the mother of Joses observe where Jesus is laid. Their witness helps establish the location of the tomb before the resurrection is announced.", refs: ["Matthew 27:61","Mark 16:1–6"] }
});

Object.assign(window.verseCommentary, {
  "Mark 16:1": { title: "The Women Bring Spices", text: "After the Sabbath, Mary Magdalene, Mary the mother of James, and Salome buy spices to anoint Jesus. Their plan shows that they expect to honour a dead teacher, not yet that He has risen.", refs: ["Luke 23:56","Matthew 28:1"] },
  "Mark 16:2": { title: "Very Early on the First Day", text: "They come to the tomb very early on the first day of the week, at sunrise. The timing sets the scene for the discovery that changes the disciples' understanding.", refs: ["Matthew 28:1","John 20:1"] },
  "Mark 16:3": { title: "Who Will Roll Away the Stone?", text: "The women wonder who will roll away the heavy stone from the tomb entrance. They are thinking about a practical obstacle while approaching the place where Jesus was buried.", refs: ["Mark 15:46","Luke 24:2"] },
  "Mark 16:4": { title: "The Stone Is Rolled Away", text: "They look and see that the stone has already been rolled away, though it was very large. The obstacle they worried about has been removed before they arrive.", refs: ["Matthew 28:2","John 20:1"] },
  "Mark 16:5": { title: "A Young Man in White", text: "Entering the tomb, they see a young man in a white garment sitting on the right, and they are frightened. The heavenly messenger prepares them to hear that Jesus is not there.", refs: ["Matthew 28:3–5","Luke 24:4"] },
  "Mark 16:6": { title: "He Is Risen", text: "The messenger tells them not to be afraid: Jesus of Nazareth, who was crucified, is risen and is not here. The empty tomb announces God's victory over death and confirms Jesus' promise.", refs: ["Matthew 28:5–6","1 Corinthians 15:3–4"] },
  "Mark 16:7": { title: "Tell His Disciples and Peter", text: "They are told to tell the disciples and Peter that Jesus goes before them into Galilee, as He said. Naming Peter personally offers hope to the disciple who had denied Jesus.", refs: ["Mark 14:28","John 21:15–17"] },
  "Mark 16:8": { title: "Fear and Astonishment", text: "The women flee from the tomb trembling and astonished, and initially say nothing to anyone because they are afraid. The verse ends the earliest widely attested form of Mark abruptly; the fear reflects the overwhelming news, not a denial of the resurrection.", refs: ["Matthew 28:8","Luke 24:9"] },
  "Mark 16:9": { title: "Jesus Appears to Mary Magdalene", text: "The longer ending of Mark begins by saying the risen Jesus appeared first to Mary Magdalene, from whom He had cast out seven devils. Mark 16:9–20 is absent from some of the earliest manuscripts, so readers should know the textual note while comparing the resurrection accounts.", refs: ["John 20:11–18","Luke 8:2"] },
  "Mark 16:10": { title: "Mary Tells the Disciples", text: "Mary goes and tells those who had been with Jesus while they mourn and weep. The first response to the resurrection report is grief and difficulty believing.", refs: ["John 20:18","Luke 24:10–11"] },
  "Mark 16:11": { title: "They Do Not Believe", text: "When the disciples hear that Jesus is alive and Mary has seen Him, they do not believe. The Gospels portray the disciples as needing convincing witnesses, not as inventing a story they already expected.", refs: ["Luke 24:11","John 20:24–25"] },
  "Mark 16:12": { title: "Jesus Appears to Two", text: "Afterward Jesus appears in another form to two disciples as they walk into the country. This corresponds generally to the account of disciples on the road, though Mark gives few details here.", refs: ["Luke 24:13–32","1 Corinthians 15:5"] },
  "Mark 16:13": { title: "They Report It", text: "The two return and tell the others, but their report is not believed either. Repeated testimony meets continued doubt among the disciples.", refs: ["Luke 24:33–35","Mark 16:11"] },
  "Mark 16:14": { title: "Jesus Rebukes Their Unbelief", text: "Jesus appears to the Eleven as they eat and rebukes their unbelief and hardness of heart because they did not believe those who had seen Him risen. His correction leads into the commission to proclaim the gospel.", refs: ["Luke 24:36–43","John 20:26–29"] },
  "Mark 16:15": { title: "Go into All the World", text: "Jesus commands the disciples to go into all the world and preach the gospel to every creature. The resurrection launches a worldwide mission rather than a message restricted to one nation.", refs: ["Matthew 28:19–20","Acts 1:8"] },
  "Mark 16:16": { title: "Believe and Be Baptized", text: "The verse connects belief and baptism with salvation and warns against unbelief. Read with Acts and the rest of the New Testament, it calls for a believing response to the gospel, including baptism, while identifying unbelief as condemnation's ground.", refs: ["Acts 2:38","Acts 8:36–38","John 3:18"] },
  "Mark 16:17": { title: "Signs Following Believers", text: "The passage describes signs associated with believers, including casting out devils and speaking with new tongues. Signs in Scripture serve God's mission and should never be used to manipulate people or test God recklessly.", refs: ["Acts 2:4","Acts 8:7","1 Corinthians 12:7–11"] },
  "Mark 16:18": { title: "God's Protection and Healing", text: "The longer ending speaks of protection from serpents and poison and of laying hands on the sick. These words must not be turned into a command to handle dangerous animals or drink poison; Scripture forbids tempting God, and healing remains under His sovereignty.", refs: ["Luke 10:19","Acts 28:3–6","James 5:14–15"] },
  "Mark 16:19": { title: "Jesus Is Received into Heaven", text: "After speaking to them, the Lord Jesus is received up into heaven and sits at the right hand of God. The language expresses His exaltation and completed earthly mission.", refs: ["Luke 24:50–53","Acts 1:9–11","Psalm 110:1"] },
  "Mark 16:20": { title: "They Preach Everywhere", text: "The disciples go out preaching everywhere, while the Lord works with them and confirms the word with signs. The Gospel closes with the continuing mission of proclaiming what God has done through Jesus.", refs: ["Acts 2:43","Hebrews 2:3–4","Matthew 28:20"] }
});

Object.assign(window.verseCommentary, {
  "Luke 1:1": { title: "An Ordered Account", text: "Luke explains that many had undertaken to set forth an account of the events fulfilled among them. His opening presents the Gospel as a careful account of God's work in history.", refs: ["Acts 1:1","John 20:30–31"] },
  "Luke 1:2": { title: "Eyewitnesses and Ministers of the Word", text: "Luke received information from those who were eyewitnesses and ministers of the word from the beginning. The Gospel is rooted in testimony about real events, not merely private speculation.", refs: ["2 Peter 1:16","1 John 1:1–3"] },
  "Luke 1:3": { title: "Carefully Traced from the Beginning", text: "Luke says he has carefully investigated everything from the beginning and decided to write an orderly account to Theophilus. His aim is clarity and reliability for the reader.", refs: ["Acts 1:1","Luke 1:4"] },
  "Luke 1:4": { title: "Certainty About the Teaching", text: "Luke writes so Theophilus may know the certainty of the things in which he has been instructed. Faith is not opposed to careful examination of trustworthy testimony.", refs: ["John 20:31","2 Timothy 3:14"] },
  "Luke 1:5": { title: "Zacharias and Elisabeth", text: "In the days of Herod, Zacharias is a priest of the course of Abia, and his wife Elisabeth is of Aaron's daughters. Luke locates the events in a specific historical setting and a priestly family.", refs: ["1 Chronicles 24:10","Luke 1:8"] },
  "Luke 1:6": { title: "Righteous Before God", text: "Zacharias and Elisabeth are righteous before God, walking blamelessly in the Lord's commandments and ordinances. Their blamelessness describes sincere covenant faithfulness, not absolute sinlessness.", refs: ["Genesis 6:9","Philippians 3:6"] },
  "Luke 1:7": { title: "They Have No Child", text: "They have no child because Elisabeth is barren, and both are advanced in years. Their long-standing sorrow sets the stage for God's unexpected intervention.", refs: ["Genesis 18:11","1 Samuel 1:5–6"] },
  "Luke 1:8": { title: "Zacharias Serves as Priest", text: "Zacharias performs his priestly service before God according to the order of his course. The ordinary rhythm of worship becomes the setting for an extraordinary message.", refs: ["1 Chronicles 24:10","Exodus 28:1"] },
  "Luke 1:9": { title: "The Lot to Burn Incense", text: "According to priestly custom, the lot falls to Zacharias to burn incense in the temple. The detail shows him carrying out a familiar duty when the angel appears.", refs: ["Exodus 30:7–8","Revelation 8:3"] },
  "Luke 1:10": { title: "The People Pray Outside", text: "A multitude of people are praying outside at the time of incense. The scene links the temple service with the prayers of God's people.", refs: ["Psalm 141:2","Revelation 8:3–4"] },
  "Luke 1:11": { title: "An Angel Appears", text: "An angel of the Lord appears to Zacharias, standing on the right side of the altar of incense. God's message comes into the midst of ordinary priestly service.", refs: ["Daniel 9:21","Luke 1:19"] },
  "Luke 1:12": { title: "Zacharias Is Troubled", text: "Zacharias sees the angel and is troubled, and fear falls upon him. The reaction is a common response to an overwhelming heavenly encounter.", refs: ["Daniel 10:8–9","Luke 2:9"] },
  "Luke 1:13": { title: "Fear Not: Your Prayer Is Heard", text: "The angel tells Zacharias not to fear, because his prayer is heard and Elisabeth will bear a son named John. The name is given by God's messenger and signals the child's appointed role.", refs: ["Genesis 17:19","Luke 1:60–63"] },
  "Luke 1:14": { title: "Joy and Gladness", text: "John's birth will bring joy and gladness, and many will rejoice. His life will matter beyond the household because he prepares people for the Lord.", refs: ["Luke 1:58","Malachi 4:5–6"] },
  "Luke 1:15": { title: "Great Before the Lord", text: "John will be great before the Lord, will abstain from wine and strong drink, and will be filled with the Holy Ghost from his mother's womb. His consecrated life is set apart for a prophetic mission.", refs: ["Numbers 6:2–3","Jeremiah 1:5"] },
  "Luke 1:16": { title: "Turning Israel to the Lord", text: "John will turn many of the children of Israel to the Lord their God. His preaching will call people away from sin and back to covenant faithfulness.", refs: ["Malachi 4:6","Matthew 3:1–2"] },
  "Luke 1:17": { title: "In the Spirit and Power of Elijah", text: "John will go before the Lord in the spirit and power of Elijah, turning hearts and preparing a people. This fulfils the prophetic expectation of a forerunner, without claiming John is literally Elijah returned as the same person.", refs: ["Malachi 4:5–6","Matthew 11:14"] },
  "Luke 1:18": { title: "How Shall I Know This?", text: "Zacharias asks how he can know the promise, pointing to his age and Elisabeth's. His question contrasts with Mary's later question, which seeks understanding rather than demanding proof, as the angel's response makes clear.", refs: ["Genesis 17:17","Luke 1:34"] },
  "Luke 1:19": { title: "Gabriel Stands Before God", text: "The angel identifies himself as Gabriel, who stands in God's presence and was sent to speak this good news. The message comes with heavenly authority.", refs: ["Daniel 8:16","Daniel 9:21"] },
  "Luke 1:20": { title: "Zacharias Becomes Mute", text: "Because Zacharias did not believe the words that will be fulfilled in their season, he becomes unable to speak until the promise is accomplished. The sign both corrects his unbelief and confirms the certainty of God's word.", refs: ["Luke 1:62–64","Numbers 20:12"] },
  "Luke 1:21": { title: "The People Wait", text: "The people wait for Zacharias and wonder at his delay in the temple. His unusual absence raises questions among those gathered outside.", refs: ["Luke 1:10","Leviticus 16:17"] },
  "Luke 1:22": { title: "He Cannot Speak", text: "When Zacharias comes out unable to speak, the people realize he has seen a vision. He communicates by signs, and his experience becomes publicly evident.", refs: ["Luke 1:20","Daniel 10:15"] },
  "Luke 1:23": { title: "His Service Is Finished", text: "When the days of his service are complete, Zacharias returns home. The extraordinary message does not erase the ordinary responsibilities he completes.", refs: ["Luke 1:8","1 Chronicles 24:10"] },
  "Luke 1:24": { title: "Elisabeth Conceives", text: "After these days Elisabeth conceives and remains secluded for five months. The promise begins to be fulfilled, and she reflects on God's kindness.", refs: ["Genesis 21:1–2","1 Samuel 1:19–20"] },
  "Luke 1:25": { title: "The Lord Has Looked Upon Me", text: "Elisabeth says the Lord has looked on her to take away her reproach among people. Her words express gratitude for God's mercy after years of barrenness and social shame.", refs: ["Genesis 30:23","1 Samuel 1:6"] },
  "Luke 1:26": { title: "Gabriel Is Sent to Nazareth", text: "In the sixth month of Elisabeth's pregnancy, Gabriel is sent by God to Nazareth in Galilee. Luke connects the two miraculous birth announcements in God's unfolding plan.", refs: ["Luke 1:36","Matthew 2:23"] },
  "Luke 1:27": { title: "Mary, a Virgin Betrothed to Joseph", text: "Gabriel comes to Mary, a virgin betrothed to Joseph, a descendant of David. The details establish Mary's virginity and the Davidic line through Joseph's family.", refs: ["Matthew 1:18","Isaiah 7:14"] },
  "Luke 1:28": { title: "Hail, Thou That Art Highly Favoured", text: "The angel greets Mary as highly favoured and says the Lord is with her. Her favour is God's gracious choice, not a claim that she is herself divine.", refs: ["Luke 1:30","Ephesians 1:6"] },
  "Luke 1:29": { title: "Mary Wonders at the Greeting", text: "Mary is troubled by the greeting and considers what kind of salutation it is. Her response is thoughtful and humble before the unexpected message.", refs: ["Luke 1:12","Luke 1:34"] },
  "Luke 1:30": { title: "Fear Not, Mary", text: "The angel tells Mary not to fear because she has found favour with God. The announcement begins with divine grace and reassurance.", refs: ["Luke 1:28","Genesis 6:8"] },
  "Luke 1:31": { title: "Thou Shalt Call His Name Jesus", text: "Mary will conceive and bear a son, and she is to call His name Jesus. The name means the Lord saves and is fitting for the child who will save His people from their sins.", refs: ["Matthew 1:21","Acts 4:12"] },
  "Luke 1:32": { title: "The Son of the Highest", text: "The child will be great, called the Son of the Highest, and given the throne of David. His identity and kingship fulfil God's promises to David and point beyond an ordinary earthly ruler.", refs: ["2 Samuel 7:12–16","Isaiah 9:6–7"] },
  "Luke 1:33": { title: "His Kingdom Has No End", text: "He will reign over the house of Jacob forever, and His kingdom will have no end. The promise describes the enduring reign of the Messiah.", refs: ["Daniel 7:14","Revelation 11:15"] },
  "Luke 1:34": { title: "How Shall This Be?", text: "Mary asks how this will happen since she has not known a man. Her question seeks the manner of fulfilment, and the angel will explain God's miraculous action.", refs: ["Matthew 1:18","Luke 1:18"] },
  "Luke 1:35": { title: "The Holy Ghost Shall Come Upon Thee", text: "The angel explains that the Holy Ghost will come upon Mary and the power of the Highest will overshadow her; therefore the holy child will be called the Son of God. In the Oneness understanding, this describes the miraculous conception by God's Spirit, not a second divine person biologically fathering Jesus.", refs: ["Matthew 1:20","Isaiah 7:14","2 Corinthians 5:19"] },
  "Luke 1:36": { title: "Elisabeth Also Conceived", text: "Gabriel tells Mary that Elisabeth, her relative, has also conceived a son in old age and is now in her sixth month. The sign encourages Mary by showing God's power at work in another impossible situation.", refs: ["Luke 1:24","Genesis 18:14"] },
  "Luke 1:37": { title: "Nothing Is Impossible with God", text: "The angel declares that no word from God shall be impossible. God's promise is not limited by human inability or natural expectation.", refs: ["Genesis 18:14","Matthew 19:26"] },
  "Luke 1:38": { title: "Be It unto Me According to Thy Word", text: "Mary submits herself as the Lord's servant and accepts the word spoken to her. Her response is a model of humble trust and willingness to participate in God's purpose.", refs: ["1 Samuel 3:10","Luke 11:27–28"] },
  "Luke 1:39": { title: "Mary Visits Elisabeth", text: "Mary rises and travels quickly to a city in the hill country of Judah. Her visit brings the two women together during their unusual pregnancies.", refs: ["Luke 1:56","Joshua 21:9–11"] },
  "Luke 1:40": { title: "Mary Greets Elisabeth", text: "Mary enters Zacharias' house and greets Elisabeth. The greeting becomes the occasion for the child in Elisabeth's womb to leap and for Elisabeth to speak by the Spirit.", refs: ["Luke 1:41","Luke 1:44"] }
});

Object.assign(window.verseCommentary, {
  "Luke 1:41": { title: "The Baby Leaps", text: "When Elisabeth hears Mary's greeting, the baby leaps in her womb, and Elisabeth is filled with the Holy Ghost. The unborn John responds to the presence of the promised Messiah.", refs: ["Luke 1:15","Luke 1:44"] },
  "Luke 1:42": { title: "Blessed Art Thou Among Women", text: "Elisabeth cries out that Mary is blessed among women and that the fruit of her womb is blessed. Her words honour God's work in Mary without making Mary the source of the blessing.", refs: ["Luke 1:28","Luke 11:27–28"] },
  "Luke 1:43": { title: "The Mother of My Lord", text: "Elisabeth wonders why the mother of her Lord should come to her. Her Spirit-inspired greeting recognizes the significance of the child Mary carries.", refs: ["Psalm 110:1","Luke 2:11"] },
  "Luke 1:44": { title: "The Baby Leaped for Joy", text: "Elisabeth says the baby leaped for joy when Mary's greeting reached her ears. The joy anticipates John's future role in pointing Israel to Jesus.", refs: ["Luke 1:41","Malachi 4:5–6"] },
  "Luke 1:45": { title: "Blessed Is She That Believed", text: "Elisabeth calls Mary blessed because she believed that the Lord's words would be fulfilled. Faith receives God's promise before all its details are visible.", refs: ["Genesis 15:6","Hebrews 11:11"] },
  "Luke 1:46": { title: "My Soul Doth Magnify the Lord", text: "Mary begins a song of praise, magnifying the Lord rather than herself. Her worship directs attention to God's greatness and mercy.", refs: ["1 Samuel 2:1","Psalm 34:3"] },
  "Luke 1:47": { title: "My Spirit Hath Rejoiced in God My Saviour", text: "Mary rejoices in God her Saviour. Her words show that she too depends on God's saving mercy, even as she is chosen for a unique role in the incarnation.", refs: ["Habakkuk 3:18","Titus 3:4–6"] },
  "Luke 1:48": { title: "He Hath Regarded His Low Estate", text: "Mary says God has looked upon the low estate of His handmaiden, and future generations will call her blessed. The honour comes from God's gracious choice, not self-exaltation.", refs: ["1 Samuel 1:11","Luke 11:27–28"] },
  "Luke 1:49": { title: "The Mighty One Has Done Great Things", text: "Mary praises the Mighty One for doing great things for her, declaring His name holy. Her testimony celebrates God's power and holiness.", refs: ["Psalm 111:9","Psalm 126:2–3"] },
  "Luke 1:50": { title: "Mercy to Them That Fear Him", text: "God's mercy extends from generation to generation to those who fear Him. Reverent trust in God is met by His enduring covenant mercy.", refs: ["Psalm 103:17","Exodus 20:6"] },
  "Luke 1:51": { title: "He Scatters the Proud", text: "Mary says God has shown strength with His arm and scattered the proud in the imagination of their hearts. God's action overturns arrogant self-reliance.", refs: ["Psalm 89:10","Isaiah 2:11–12"] },
  "Luke 1:52": { title: "The Mighty Are Put Down", text: "God brings down the mighty from their seats and exalts those of low degree. The song celebrates God's justice and reversal of human pride.", refs: ["1 Samuel 2:7–8","Job 5:11"] },
  "Luke 1:53": { title: "The Hungry Are Filled", text: "God fills the hungry with good things and sends the rich away empty. The words challenge complacency and announce God's concern for the humble and needy.", refs: ["Psalm 107:9","Luke 6:21"] },
  "Luke 1:54": { title: "He Has Helped Israel", text: "God has helped His servant Israel in remembrance of His mercy. The coming of Jesus is tied to God's faithfulness to His covenant people.", refs: ["Isaiah 41:8–9","Psalm 98:3"] },
  "Luke 1:55": { title: "The Promise to Abraham", text: "Mary recalls God's promise to Abraham and his seed forever. The Messiah's coming fulfils the ancient covenant and opens blessing to the nations.", refs: ["Genesis 12:3","Genesis 17:7","Galatians 3:16"] },
  "Luke 1:56": { title: "Mary Returns Home", text: "Mary remains with Elisabeth about three months and then returns to her own house. The visit has provided fellowship and confirmation during a remarkable season.", refs: ["Luke 1:39","Luke 1:24"] },
  "Luke 1:57": { title: "Elisabeth Gives Birth", text: "Elisabeth's full time comes, and she gives birth to a son. God's promise is fulfilled after the long years of waiting.", refs: ["Luke 1:13","Genesis 21:1–2"] },
  "Luke 1:58": { title: "Neighbours Rejoice", text: "Neighbours and relatives hear of the Lord's great mercy to Elisabeth and rejoice with her. A personal blessing becomes a shared occasion of praise.", refs: ["Luke 1:14","Psalm 126:2–3"] },
  "Luke 1:59": { title: "The Child Is to Be Circumcised", text: "On the eighth day, they come to circumcise the child and plan to name him after his father. The family follows covenant custom but does not yet know the name God has commanded.", refs: ["Genesis 17:12","Leviticus 12:3"] },
  "Luke 1:60": { title: "His Name Shall Be John", text: "Elisabeth says the child will be called John. She confirms the instruction given by the angel rather than following the family's expected naming tradition.", refs: ["Luke 1:13","Luke 1:63"] },
  "Luke 1:61": { title: "No Relative Has That Name", text: "The people object that none of their relatives is called John. Their objection reflects ordinary custom, but God's instruction takes precedence.", refs: ["Luke 1:60","Acts 5:29"] },
  "Luke 1:62": { title: "They Ask Zacharias by Signs", text: "They make signs to Zacharias to learn what he wants the child called. His inability to speak continues until the promise is fulfilled.", refs: ["Luke 1:20","Luke 1:22"] },
  "Luke 1:63": { title: "His Name Is John", text: "Zacharias asks for a writing tablet and writes, 'His name is John.' The people marvel because he confirms the name announced by the angel.", refs: ["Luke 1:13","Luke 1:60"] },
  "Luke 1:64": { title: "Zacharias Speaks and Praises God", text: "Immediately Zacharias' mouth is opened and his tongue loosed, and he speaks and praises God. The sign promised by Gabriel ends when Zacharias obeys the revealed word.", refs: ["Luke 1:20","Luke 1:22"] },
  "Luke 1:65": { title: "Fear Comes on the Neighbours", text: "Fear comes upon the neighbours, and the events are discussed throughout the hill country of Judea. The birth is recognized as a sign of God's unusual activity.", refs: ["Luke 1:12","Luke 2:18"] },
  "Luke 1:66": { title: "What Manner of Child Shall This Be?", text: "Those who hear the news lay it up in their hearts and ask what the child will become, because the Lord's hand is with him. The question anticipates John's prophetic calling.", refs: ["Luke 2:19","Acts 11:21"] },
  "Luke 1:67": { title: "Zacharias Is Filled with the Holy Ghost", text: "Zacharias is filled with the Holy Ghost and prophesies. His song interprets the births in the light of God's covenant and saving purpose.", refs: ["Luke 1:41","2 Peter 1:21"] },
  "Luke 1:68": { title: "Blessed Be the Lord God of Israel", text: "Zacharias blesses the Lord God of Israel because He has visited and redeemed His people. God's saving action is arriving in history through the Messiah.", refs: ["Psalm 72:18","Luke 7:16"] },
  "Luke 1:69": { title: "A Horn of Salvation", text: "God has raised up a horn of salvation in the house of David. The image speaks of strength and victory through the promised Davidic Messiah.", refs: ["Psalm 18:2","2 Samuel 7:12–16"] },
  "Luke 1:70": { title: "As the Prophets Spoke", text: "This salvation was promised through God's holy prophets from ancient times. The coming of Jesus fulfils a long scriptural story rather than appearing without preparation.", refs: ["Acts 3:21","Romans 1:2"] },
  "Luke 1:71": { title: "Salvation from Enemies", text: "God's promise includes salvation from enemies and those who hate His people. The deliverance is ultimately deeper than political victory, reaching sin and death through the Messiah.", refs: ["Psalm 106:10","Titus 2:14"] },
  "Luke 1:72": { title: "Remembering the Holy Covenant", text: "God shows mercy promised to the fathers and remembers His holy covenant. His faithfulness is the basis of Israel's hope.", refs: ["Genesis 17:7","Psalm 105:8–10"] },
  "Luke 1:73": { title: "The Oath to Abraham", text: "Zacharias recalls the oath God swore to Abraham. God's promise is dependable because it rests on His own faithfulness.", refs: ["Genesis 22:16–18","Hebrews 6:13–18"] },
  "Luke 1:74": { title: "Serving Without Fear", text: "God's purpose is to deliver His people so they may serve Him without fear. Salvation brings people into faithful worship and service, not simply escape from danger.", refs: ["Exodus 7:16","Romans 6:18"] },
  "Luke 1:75": { title: "Holiness and Righteousness", text: "The people are to serve God in holiness and righteousness all their days. Grace leads to a changed life of devotion and obedience.", refs: ["Ephesians 4:24","Titus 2:11–12"] },
  "Luke 1:76": { title: "Prophet of the Highest", text: "Zacharias addresses John as prophet of the Highest, who will go before the Lord to prepare His ways. John is the forerunner who prepares hearts for God's coming in salvation.", refs: ["Isaiah 40:3","Malachi 3:1"] },
  "Luke 1:77": { title: "Knowledge of Salvation by Forgiveness", text: "John will give knowledge of salvation to God's people through the remission of their sins. The central need is forgiveness and reconciliation with God.", refs: ["Jeremiah 31:34","Acts 13:38"] },
  "Luke 1:78": { title: "The Dayspring from on High", text: "Because of God's tender mercy, the dayspring from on high visits His people. The image speaks of dawn and light breaking into spiritual darkness through the Messiah.", refs: ["Malachi 4:2","Isaiah 9:2"] },
  "Luke 1:79": { title: "Light to Those in Darkness", text: "The coming light gives light to those in darkness and guides their feet into the way of peace. Jesus brings God's saving illumination and reconciliation.", refs: ["Isaiah 42:6–7","John 8:12"] },
  "Luke 1:80": { title: "John Grows in the Wilderness", text: "The child grows and becomes strong in spirit, living in the deserts until the day of his public appearance to Israel. God prepares His messenger away from the public stage before his ministry begins.", refs: ["Matthew 3:1–4","Luke 3:2–3"] }
});

Object.assign(window.verseCommentary, {
  "Luke 2:1": { title: "A Decree from Caesar Augustus", text: "A decree from Caesar Augustus orders a census throughout the Roman world. Luke sets Jesus' birth within public history and the rule of the empire.", refs: ["Matthew 2:1","Micah 5:2"] },
  "Luke 2:2": { title: "The First Census", text: "Luke identifies the census with the time of Cyrenius governing Syria. Scholars discuss the chronology of this detail, but Luke's purpose is to locate the birth in a historical setting.", refs: ["Acts 5:37","Luke 3:1"] },
  "Luke 2:3": { title: "Each Goes to His Own City", text: "Everyone goes to be registered, each to his own city. The census brings Joseph and Mary to Bethlehem, in keeping with the Davidic setting of the Messiah's birth.", refs: ["Luke 2:4","Micah 5:2"] },
  "Luke 2:4": { title: "Joseph Goes to Bethlehem", text: "Joseph travels from Nazareth to Bethlehem because he is of the house and lineage of David. The birthplace connects Jesus with God's promise concerning David's royal line.", refs: ["2 Samuel 7:12–16","Matthew 1:1"] },
  "Luke 2:5": { title: "Mary Is with Child", text: "Mary travels with Joseph while expecting the child. Luke emphasizes the real circumstances surrounding the birth of Jesus.", refs: ["Luke 1:31","Matthew 1:18"] },
  "Luke 2:6": { title: "The Days Are Accomplished", text: "While Joseph and Mary are in Bethlehem, the time comes for her to give birth. God's promise unfolds in an ordinary town and under humble circumstances.", refs: ["Galatians 4:4","Micah 5:2"] },
  "Luke 2:7": { title: "She Brings Forth Her Firstborn Son", text: "Mary gives birth to her firstborn son, wraps Him in swaddling clothes, and lays Him in a manger because there is no room for them in the inn. The promised King enters the world without earthly display or privilege.", refs: ["Matthew 1:25","Isaiah 9:6"] },
  "Luke 2:8": { title: "Shepherds in the Fields", text: "Shepherds are living in the fields nearby, keeping watch over their flock at night. The first announcement will come to ordinary working people rather than the powerful.", refs: ["Luke 2:15","Psalm 23:1"] },
  "Luke 2:9": { title: "The Glory of the Lord Shines", text: "An angel appears and the glory of the Lord shines around the shepherds, causing great fear. God's glory interrupts the ordinary night with a message of salvation.", refs: ["Luke 1:11–12","Exodus 16:10"] },
  "Luke 2:10": { title: "Good Tidings of Great Joy", text: "The angel tells them not to fear and announces good news of great joy for all people. The birth of Jesus is a message meant to reach beyond one household or social class.", refs: ["Isaiah 52:7","Luke 1:14"] },
  "Luke 2:11": { title: "A Saviour Is Born", text: "A Saviour, Christ the Lord, is born in David's city. The titles identify Jesus as deliverer, Messiah, and Lord, fulfilling Israel's hope.", refs: ["Isaiah 9:6","Matthew 1:21"] },
  "Luke 2:12": { title: "The Sign of the Manger", text: "The sign is a baby wrapped in swaddling clothes and lying in a manger. God's promised Saviour is identified through a humble, unmistakable sign rather than royal splendour.", refs: ["Luke 2:7","Isaiah 7:14"] },
  "Luke 2:13": { title: "A Multitude of the Heavenly Host", text: "Suddenly a multitude of the heavenly host appears with the angel, praising God. Heaven itself responds to the arrival of the Saviour.", refs: ["Daniel 7:10","Revelation 5:11–12"] },
  "Luke 2:14": { title: "Glory to God in the Highest", text: "The heavenly host praises God and announces peace and goodwill in the wording of the traditional KJV. The song celebrates God's glory and the peace His saving work brings to those who receive His favour.", refs: ["Isaiah 9:6–7","Romans 5:1"] },
  "Luke 2:15": { title: "Let Us Go to Bethlehem", text: "When the angels depart, the shepherds decide to go to Bethlehem and see what the Lord has made known. Their response to revelation is immediate action.", refs: ["Luke 2:20","Matthew 2:1–2"] },
  "Luke 2:16": { title: "They Find Mary, Joseph, and the Baby", text: "The shepherds come quickly and find Mary, Joseph, and the baby lying in a manger, just as the angel said. The sign is confirmed by what they see.", refs: ["Luke 2:12","Luke 2:7"] },
  "Luke 2:17": { title: "They Make the Saying Known", text: "After seeing the child, the shepherds spread the message they had been told about Him. Witness naturally follows their encounter with the promised Saviour.", refs: ["Luke 2:10–11","Acts 4:20"] },
  "Luke 2:18": { title: "People Wonder at the Report", text: "Those who hear the shepherds' report marvel. The news invites wonder and reflection about God's action.", refs: ["Luke 2:33","Luke 1:65"] },
  "Luke 2:19": { title: "Mary Keeps These Things", text: "Mary keeps these things and ponders them in her heart. She reflects deeply on events whose full meaning will become clearer over time.", refs: ["Luke 2:51","Genesis 37:11"] },
  "Luke 2:20": { title: "The Shepherds Glorify God", text: "The shepherds return glorifying and praising God for all they have heard and seen. Their worship is grounded in the confirmation of God's word.", refs: ["Luke 1:68","Psalm 103:1–2"] },
  "Luke 2:21": { title: "The Child Is Named Jesus", text: "On the eighth day, the child is circumcised and named Jesus, the name given by the angel before His conception. The family obeys the covenant custom while fulfilling the revealed name.", refs: ["Luke 1:31","Genesis 17:12"] },
  "Luke 2:22": { title: "The Days of Purification", text: "When the days of purification are complete according to the law of Moses, Mary and Joseph bring Jesus to Jerusalem. Luke shows the family observing the law while God's promise is being fulfilled.", refs: ["Leviticus 12:2–8","Galatians 4:4"] },
  "Luke 2:23": { title: "Every Firstborn Is Holy to the Lord", text: "They present Jesus in accordance with the law that every male opening the womb is called holy to the Lord. The act recalls God's claim on Israel's firstborn and the redemption from Egypt.", refs: ["Exodus 13:2","Exodus 13:12"] },
  "Luke 2:24": { title: "A Pair of Turtledoves", text: "They offer the sacrifice permitted for those who could not afford a lamb. The offering shows the family's humble means and faithful observance.", refs: ["Leviticus 12:8","Luke 2:7"] },
  "Luke 2:25": { title: "Simeon Waits for Consolation", text: "Simeon is just and devout, waiting for the consolation of Israel, and the Holy Ghost is upon him. He represents faithful people who continue hoping for God's promised redemption.", refs: ["Isaiah 40:1","Isaiah 49:13"] },
  "Luke 2:26": { title: "He Will See the Lord's Christ", text: "The Holy Ghost has revealed to Simeon that he will not die before seeing the Lord's Christ. God's promise sustains his hope until the appointed moment.", refs: ["Luke 2:29–30","Psalm 27:13"] },
  "Luke 2:27": { title: "Simeon Comes into the Temple", text: "Simeon comes into the temple by the Spirit as the parents bring in the child Jesus to fulfil the law. God's timing brings the faithful elder and the Messiah together.", refs: ["Luke 2:22","Luke 2:25"] },
  "Luke 2:28": { title: "Simeon Takes Jesus in His Arms", text: "Simeon takes the child in his arms and blesses God. His response is worship because he recognizes God's promise being fulfilled.", refs: ["Luke 2:30","Psalm 98:3"] },
  "Luke 2:29": { title: "Now Let Thy Servant Depart in Peace", text: "Simeon says the Lord can now let His servant depart in peace according to His word. Having seen the promised Saviour, he can face death with confidence in God's faithfulness.", refs: ["Philippians 1:23","2 Timothy 4:7–8"] },
  "Luke 2:30": { title: "Mine Eyes Have Seen Thy Salvation", text: "Simeon declares that his eyes have seen God's salvation. Salvation is presented not merely as an abstract plan but as God's work revealed in Jesus.", refs: ["Isaiah 52:10","Luke 3:6"] },
  "Luke 2:31": { title: "Prepared Before All People", text: "This salvation has been prepared in the sight of all peoples. God's purpose extends beyond a hidden private blessing and is intended for public witness.", refs: ["Psalm 98:2","Acts 28:28"] },
  "Luke 2:32": { title: "Light to the Gentiles", text: "Jesus is a light to lighten the Gentiles and the glory of God's people Israel. The Messiah fulfils Israel's calling and brings God's saving light to the nations.", refs: ["Isaiah 42:6","Isaiah 49:6","Acts 13:47"] },
  "Luke 2:33": { title: "Joseph and Mary Marvel", text: "Joseph and Jesus' mother marvel at the things spoken about Him. The testimony of Simeon deepens their awareness of the child's mission.", refs: ["Luke 2:18","Luke 2:19"] },
  "Luke 2:34": { title: "A Sign Spoken Against", text: "Simeon blesses them and tells Mary that the child is appointed for the fall and rising of many in Israel and as a sign spoken against. Jesus will expose hearts and provoke both faith and opposition.", refs: ["Isaiah 8:14","1 Peter 2:7–8"] },
  "Luke 2:35": { title: "A Sword Shall Pierce Mary's Soul", text: "Simeon says a sword will pierce Mary's own soul also, as the thoughts of many hearts are revealed. She will share in the sorrow of witnessing her son's rejection and suffering.", refs: ["John 19:25","Luke 23:27"] },
  "Luke 2:36": { title: "Anna the Prophetess", text: "Anna, a prophetess of the tribe of Asher, is advanced in years and has lived faithfully after being widowed. Luke honours her as a witness who serves God in the temple.", refs: ["1 Timothy 5:5","Acts 21:9"] },
  "Luke 2:37": { title: "Serving with Fasting and Prayer", text: "Anna does not depart from the temple but serves God with fastings and prayers night and day. Her long devotion prepares her to recognize the significance of Jesus.", refs: ["Luke 18:1","1 Thessalonians 5:17"] },
  "Luke 2:38": { title: "She Gives Thanks and Speaks of Redemption", text: "Anna comes at that moment, gives thanks to God, and speaks about Jesus to those looking for redemption in Jerusalem. Her testimony joins Simeon's in announcing that God's promised deliverance has arrived.", refs: ["Isaiah 52:9","Luke 2:25"] },
  "Luke 2:39": { title: "They Return to Nazareth", text: "After completing everything required by the law, Joseph and Mary return to Galilee, to Nazareth. Luke summarizes the family's return and Jesus' growth.", refs: ["Matthew 2:23","Luke 2:4"] },
  "Luke 2:40": { title: "The Child Grows Strong", text: "Jesus grows and becomes strong in spirit, filled with wisdom, and God's grace is upon Him. Luke emphasizes His genuine human development and divine favour.", refs: ["Luke 2:52","Isaiah 11:2"] },
  "Luke 2:41": { title: "The Family Goes to Jerusalem", text: "Jesus' parents go to Jerusalem every year at the feast of the Passover. Their regular observance situates Jesus within Israel's worship and covenant life.", refs: ["Exodus 23:14–17","Deuteronomy 16:1–8"] },
  "Luke 2:42": { title: "Jesus Is Twelve Years Old", text: "When Jesus is twelve, they go up to Jerusalem according to the feast's custom. The episode begins to reveal His unusual understanding of His relationship to the Father.", refs: ["Luke 2:49","Luke 2:52"] },
  "Luke 2:43": { title: "Jesus Remains in Jerusalem", text: "When the feast days are complete, Jesus stays behind in Jerusalem, while His parents do not know it. His absence is not immediately noticed among the travelling company.", refs: ["Luke 2:44","Luke 2:46"] },
  "Luke 2:44": { title: "They Seek Him Among Relatives", text: "They assume Jesus is among their travelling companions and search for Him among relatives and acquaintances. Their assumption is understandable in a large group, but they soon realize He is missing.", refs: ["Luke 2:45","Luke 2:43"] },
  "Luke 2:45": { title: "They Return to Jerusalem", text: "When they do not find Him, they return to Jerusalem seeking Him. The search shows their concern for the child entrusted to them.", refs: ["Luke 2:46","Luke 2:48"] },
  "Luke 2:46": { title: "Jesus Among the Teachers", text: "After three days they find Jesus in the temple, sitting among teachers, listening and asking questions. He is not merely showing off knowledge; He is engaged seriously with the things of God.", refs: ["Luke 2:47","Malachi 3:1"] },
  "Luke 2:47": { title: "All Are Astonished at His Understanding", text: "Those who hear Jesus are amazed at His understanding and answers. His wisdom is remarkable even at a young age.", refs: ["Matthew 13:54","Luke 4:22"] },
  "Luke 2:48": { title: "His Mother Asks Why", text: "Mary tells Jesus that she and Joseph have sought Him sorrowing. Her words express parental anxiety after the distressing search.", refs: ["Luke 2:44–45","Luke 2:35"] },
  "Luke 2:49": { title: "About My Father's Business", text: "Jesus asks why they sought Him and whether they knew He must be about His Father's business, or in His Father's house. Even as a boy, He understands His life in relation to God the Father and His unique mission.", refs: ["John 2:16","John 5:17"] },
  "Luke 2:50": { title: "They Do Not Understand the Saying", text: "His parents do not understand what He means. The significance of Jesus' identity and mission unfolds gradually even to those closest to Him.", refs: ["Luke 2:19","Luke 2:51"] },
  "Luke 2:51": { title: "Jesus Is Subject to His Parents", text: "Jesus returns to Nazareth and is subject to Mary and Joseph, while Mary keeps these sayings in her heart. His divine mission does not prevent Him from fulfilling ordinary family obedience.", refs: ["Luke 2:19","Ephesians 6:1–2"] },
  "Luke 2:52": { title: "Jesus Increases in Wisdom and Favour", text: "Jesus increases in wisdom, stature, and favour with God and man. Luke affirms His genuine human development while the Gospel as a whole reveals His unique identity as God manifested in flesh.", refs: ["1 Samuel 2:26","Luke 2:40","John 1:14"] }
});

Object.assign(window.verseCommentary, {
  "Luke 3:1": { title: "The Historical Setting", text: "Luke names Tiberius Caesar, Pontius Pilate, Herod, Philip, Lysanias, and the high priests to locate John's ministry in public history. God's saving work enters a real political and religious world.", refs: ["Luke 1:5","Acts 4:27"] },
  "Luke 3:2": { title: "The Word of God Comes to John", text: "The word of God comes to John in the wilderness during the high priesthood of Annas and Caiaphas. John is called directly into his prophetic mission away from the centres of power.", refs: ["Luke 1:80","Jeremiah 1:2"] },
  "Luke 3:3": { title: "A Baptism of Repentance", text: "John travels through the region around Jordan, preaching baptism of repentance for the remission of sins. His message calls people to turn from sin in preparation for the Lord.", refs: ["Mark 1:4","Acts 19:4"] },
  "Luke 3:4": { title: "Prepare the Way of the Lord", text: "Luke cites Isaiah's prophecy of a voice crying in the wilderness to prepare the Lord's way. John's ministry prepares the people for God's saving visitation in Jesus.", refs: ["Isaiah 40:3","Matthew 3:3"] },
  "Luke 3:5": { title: "Every Valley Shall Be Filled", text: "The prophecy pictures valleys filled, mountains brought low, and crooked paths made straight. It portrays the removal of obstacles as God prepares His people for salvation.", refs: ["Isaiah 40:4","Luke 1:52"] },
  "Luke 3:6": { title: "All Flesh Shall See God's Salvation", text: "Luke concludes the quotation with the promise that all flesh shall see God's salvation. The gospel's reach extends beyond one people to the nations.", refs: ["Isaiah 40:5","Acts 28:28"] },
  "Luke 3:7": { title: "Who Warned You to Flee?", text: "John challenges the crowds who come for baptism, calling them a generation of vipers and asking who warned them to flee coming wrath. Religious attendance without repentance is not enough.", refs: ["Matthew 3:7","Romans 2:4–5"] },
  "Luke 3:8": { title: "Bring Forth Fruits Worthy of Repentance", text: "John calls for fruit that matches repentance and warns against trusting in Abrahamic ancestry. True turning to God produces visible changes in conduct.", refs: ["Matthew 3:8–9","James 2:17"] },
  "Luke 3:9": { title: "The Axe at the Root", text: "The axe is laid to the root of the trees, and every tree without good fruit is cut down. John warns that judgment is near and that fruitlessness has consequences.", refs: ["Matthew 7:19","John 15:2"] },
  "Luke 3:10": { title: "What Shall We Do?", text: "The crowd asks John what they should do. Genuine conviction moves people beyond emotion to seek practical obedience.", refs: ["Acts 2:37","Luke 19:8"] },
  "Luke 3:11": { title: "Share Clothing and Food", text: "John tells the person with two coats to share with someone who has none, and the one with food to do likewise. Repentance includes generosity toward people in need.", refs: ["Isaiah 58:7","James 2:15–16"] },
  "Luke 3:12": { title: "Publicans Ask for Direction", text: "Tax collectors come to be baptized and ask what they should do. John does not tell them that their occupation alone makes repentance impossible; he gives ethical instruction.", refs: ["Luke 19:2–9","Luke 5:27–32"] },
  "Luke 3:13": { title: "Collect No More Than Appointed", text: "John tells the tax collectors not to collect more than they are authorized to collect. Repentance requires honesty and refusing to exploit a position for personal gain.", refs: ["Leviticus 19:11","Luke 19:8"] },
  "Luke 3:14": { title: "Be Content with Your Wages", text: "Soldiers are told not to extort money, falsely accuse anyone, or use threats, and to be content with their wages. Repentance changes how power is exercised and how people treat others.", refs: ["Exodus 20:16","Micah 6:8"] },
  "Luke 3:15": { title: "Is John the Christ?", text: "The people are in expectation and wonder whether John might be the Christ. John's impact creates messianic anticipation, but he will clearly point away from himself.", refs: ["John 1:19–20","Malachi 3:1"] },
  "Luke 3:16": { title: "One Mightier Than I", text: "John says one mightier than he is coming, whose sandals he is unworthy to unloose. The coming one will baptize with the Holy Ghost and fire, revealing a work beyond John's water baptism.", refs: ["Matthew 3:11","Acts 1:5","Acts 2:3–4"] },
  "Luke 3:17": { title: "The Winnowing Fan", text: "The coming one has a winnowing fan to separate wheat from chaff, gathering wheat and burning chaff with unquenchable fire. The image warns of a real division between those who respond to God and those who persist in rejecting Him.", refs: ["Matthew 13:30","Malachi 4:1"] },
  "Luke 3:18": { title: "Good News and Exhortation", text: "With many other exhortations John preaches good news to the people. His message includes both warning and the hopeful announcement of God's approaching salvation.", refs: ["Mark 1:4","Isaiah 40:9"] },
  "Luke 3:19": { title: "John Rebukes Herod", text: "John rebukes Herod the tetrarch for his relationship with Herodias and for other evils. Faithful prophetic ministry speaks truth even when it challenges rulers.", refs: ["Mark 6:17–18","Leviticus 18:16"] },
  "Luke 3:20": { title: "John Is Imprisoned", text: "Herod adds imprisonment to his other wrongs by shutting John in prison. The rejection of John's message anticipates the opposition Jesus will face.", refs: ["Matthew 14:3–4","Luke 9:9"] },
  "Luke 3:21": { title: "Jesus Is Baptized", text: "When the people are baptized, Jesus also is baptized and prays, and heaven opens. Jesus identifies with the people He came to save while remaining without sin.", refs: ["Matthew 3:13–17","Hebrews 4:15"] },
  "Luke 3:22": { title: "The Spirit Descends", text: "The Holy Ghost descends in bodily form like a dove, and a voice from heaven declares Jesus the beloved Son. The passage reveals Jesus' messianic identity and God's approval; in Oneness theology, the heavenly voice and Spirit's descent are manifestations of the one God, not proof of three separate gods.", refs: ["Isaiah 42:1","Matthew 3:16–17","John 1:32–34"] },
  "Luke 3:23": { title: "Jesus Begins His Ministry", text: "Jesus is about thirty years old when He begins His ministry, and He is regarded as the son of Joseph. Luke then gives a genealogy that traces Jesus' human lineage.", refs: ["Numbers 4:3","Luke 4:14"] },
  "Luke 3:24": { title: "The Genealogy Continues", text: "Luke continues the genealogy through Heli and earlier ancestors. The list situates Jesus within human family history and the wider story of God's people.", refs: ["Matthew 1:1–16","Romans 1:3"] },
  "Luke 3:25": { title: "Ancestors Before David", text: "The genealogy continues through Matthat, Levi, Melchi, Janna, and Joseph. Luke's list differs in places from Matthew's, and readers should recognize that ancient genealogies can serve distinct purposes.", refs: ["Matthew 1:1–17","1 Chronicles 3:1–9"] },
  "Luke 3:26": { title: "The Family Line Continues", text: "Luke names Mattathias, Amos, Naum, Esli, and Nagge among Jesus' ancestors. The long list underscores the continuity of Jesus' human descent.", refs: ["Luke 3:23–38","Romans 9:5"] },
  "Luke 3:27": { title: "From Zerubbabel Backward", text: "The genealogy names Joanan, Rhesa, Zerubbabel, and Salathiel. Zerubbabel connects the family line with the return from exile and the restoration period.", refs: ["Ezra 3:2","Haggai 1:1"] },
  "Luke 3:28": { title: "The Genealogy Through Earlier Generations", text: "Luke continues through Neri, Melchi, Addi, Cosam, and Elmodam. These names preserve the line through generations not otherwise widely described in Scripture.", refs: ["Luke 3:23–38","1 Chronicles 3:17–19"] },
  "Luke 3:29": { title: "The Line Before the Exile", text: "The genealogy proceeds through Jose, Eliezer, Jorim, Matthat, and Levi. Luke's purpose is to trace Jesus' human ancestry beyond the immediate royal line.", refs: ["Luke 3:23–38","Romans 1:3"] },
  "Luke 3:30": { title: "Ancestors Toward David", text: "Luke lists Simeon, Juda, Joseph, Jonan, and Eliakim. The genealogy moves toward David and the covenant history of Israel.", refs: ["Luke 3:23–38","2 Samuel 7:12–16"] },
  "Luke 3:31": { title: "David and Nathan", text: "The genealogy traces Jesus through Nathan, a son of David, rather than through Solomon as Matthew's genealogy does. This is one reason the two genealogies differ and has led to several explanations among interpreters.", refs: ["2 Samuel 5:14","1 Chronicles 3:5"] },
  "Luke 3:32": { title: "From David to Jesse", text: "Luke names David, Jesse, Obed, Booz, and Salmon. The line connects Jesus with David and the family associated with Bethlehem.", refs: ["Ruth 4:17–22","Matthew 1:5–6"] },
  "Luke 3:33": { title: "Judah and the Patriarchs", text: "The genealogy continues through Naasson, Aminadab, Aram, Esrom, and Phares, connecting Jesus' ancestry to Judah. God's promises unfold through the history of Israel's tribes.", refs: ["Genesis 38:29","Genesis 49:10"] },
  "Luke 3:34": { title: "Isaac and Abraham", text: "Luke names Jacob, Isaac, Abraham, Thara, and Nachor. The genealogy reaches the patriarchs through whom God made covenant promises.", refs: ["Genesis 12:1–3","Genesis 17:7"] },
  "Luke 3:35": { title: "The Line Before Abraham", text: "The genealogy continues through Saruch, Ragau, Phalec, Heber, and Sala. Luke carries the ancestry further back through generations before Abraham.", refs: ["Genesis 11:10–20","Luke 3:23–38"] },
  "Luke 3:36": { title: "Noah and the Flood Generation", text: "Luke names Cainan, Arphaxad, Sem, Noah, and Lamech. The genealogy connects Jesus' human line with the generations before and after the flood.", refs: ["Genesis 5:28–32","Genesis 10:22–24"] },
  "Luke 3:37": { title: "Back to the Earliest Generations", text: "The genealogy proceeds through Mathusala, Enoch, Jared, Maleleel, and Cainan. These names link Jesus' ancestry with the early biblical history of humanity.", refs: ["Genesis 5:12–27","Hebrews 11:5"] },
  "Luke 3:38": { title: "Adam, the Son of God", text: "Luke traces the line back to Adam, who is called the son of God as God's created human. The genealogy places Jesus within the story of all humanity, not Israel alone.", refs: ["Genesis 1:26–27","Acts 17:26","Romans 5:14"] }
});

Object.assign(window.verseCommentary, {
  "Luke 4:1": { title: "Jesus Is Led into the Wilderness", text: "Jesus, full of the Holy Ghost, returns from Jordan and is led by the Spirit into the wilderness. His testing follows the public affirmation at His baptism.", refs: ["Matthew 4:1","Deuteronomy 8:2"] },
  "Luke 4:2": { title: "Forty Days of Temptation", text: "For forty days Jesus is tempted by the devil and eats nothing, becoming hungry afterward. He experiences real human weakness without yielding to sin.", refs: ["Matthew 4:2","Hebrews 4:15"] },
  "Luke 4:3": { title: "Command This Stone to Become Bread", text: "The devil challenges Jesus to prove His identity by turning a stone into bread. The temptation is to use power apart from obedient trust in God's word.", refs: ["Matthew 4:3","Deuteronomy 8:3"] },
  "Luke 4:4": { title: "Man Shall Not Live by Bread Alone", text: "Jesus answers from Scripture that life depends on more than bread. Physical needs are real, but obedience to God is foundational.", refs: ["Deuteronomy 8:3","Matthew 4:4"] },
  "Luke 4:5": { title: "The Kingdoms of the World", text: "The devil shows Jesus the kingdoms of the world in a moment of time. The temptation offers authority without the path of suffering and obedience.", refs: ["Matthew 4:8","John 18:36"] },
  "Luke 4:6": { title: "Authority Offered by the Tempter", text: "The devil claims authority to give the kingdoms to whomever he will. His offer is a temptation to grasp rule through compromise rather than fulfil God's purpose.", refs: ["John 12:31","Daniel 7:14"] },
  "Luke 4:7": { title: "Worship Me", text: "The devil demands worship in exchange for the kingdoms. Jesus will not exchange the worship due to God for any worldly power.", refs: ["Deuteronomy 6:13","Matthew 4:9"] },
  "Luke 4:8": { title: "Worship the Lord Thy God", text: "Jesus answers that the Lord God alone is to be worshipped and served. Scripture defines the boundary that no promise of power can cross.", refs: ["Deuteronomy 6:13","Matthew 4:10"] },
  "Luke 4:9": { title: "The Pinnacle of the Temple", text: "The devil brings Jesus to Jerusalem and sets Him on the temple's pinnacle. The temptation now uses a sacred place to encourage a reckless demand for proof.", refs: ["Matthew 4:5","Psalm 91:11–12"] },
  "Luke 4:10": { title: "Angels Will Keep Thee", text: "The devil quotes Scripture about angels guarding God's servant. Even a true passage can be misused when taken out of its purpose.", refs: ["Psalm 91:11","2 Peter 3:16"] },
  "Luke 4:11": { title: "Lest Thou Dash Thy Foot", text: "The quotation continues that angels will bear Jesus up. Jesus will not manipulate God's promise into a test of divine protection.", refs: ["Psalm 91:12","Deuteronomy 6:16"] },
  "Luke 4:12": { title: "Thou Shalt Not Tempt the Lord", text: "Jesus answers that people must not tempt the Lord their God. Faith trusts God; it does not demand that He prove Himself through reckless acts.", refs: ["Deuteronomy 6:16","Matthew 4:7"] },
  "Luke 4:13": { title: "The Devil Departs for a Season", text: "After finishing the temptation, the devil departs from Jesus for a season. The victory does not mean temptation will never return, but Jesus has remained faithful.", refs: ["Matthew 4:11","Hebrews 2:18"] },
  "Luke 4:14": { title: "Jesus Returns in the Spirit's Power", text: "Jesus returns to Galilee in the power of the Spirit, and His fame spreads through the region. His public ministry proceeds in the power and direction of God's Spirit.", refs: ["Luke 4:1","Acts 10:38"] },
  "Luke 4:15": { title: "Teaching in the Synagogues", text: "Jesus teaches in the synagogues and is glorified by all. His ministry begins with Scripture teaching and public recognition.", refs: ["Matthew 4:23","Luke 4:22"] },
  "Luke 4:16": { title: "Jesus Comes to Nazareth", text: "Jesus comes to Nazareth, where He was brought up, and enters the synagogue on the Sabbath as was His custom. He stands to read the Scripture, placing God's word at the centre of the moment.", refs: ["Matthew 13:54","Acts 17:2"] },
  "Luke 4:17": { title: "The Book of Isaiah", text: "The scroll of Isaiah is delivered to Jesus, and He finds the passage written about the Spirit-anointed messenger. His reading identifies His mission with the prophetic promises.", refs: ["Isaiah 61:1–2","Luke 3:22"] },
  "Luke 4:18": { title: "The Spirit of the Lord Is Upon Me", text: "Jesus reads that the Spirit of the Lord has anointed Him to preach good news to the poor, heal the brokenhearted, proclaim deliverance, and give sight to the blind. His mission brings God's salvation to the needy and oppressed.", refs: ["Isaiah 61:1","Isaiah 42:7","Acts 10:38"] },
  "Luke 4:19": { title: "The Acceptable Year of the Lord", text: "The passage announces the acceptable year of the Lord, echoing the language of Jubilee and divine favour. Jesus declares the arrival of God's saving opportunity.", refs: ["Leviticus 25:10","Isaiah 61:2"] },
  "Luke 4:20": { title: "All Eyes Are Fixed on Jesus", text: "Jesus closes the book, returns it to the attendant, and sits, while everyone in the synagogue looks at Him. The room waits to hear how He will apply the prophecy.", refs: ["Luke 4:21","Nehemiah 8:5"] },
  "Luke 4:21": { title: "This Scripture Is Fulfilled Today", text: "Jesus declares that the Scripture is fulfilled in their hearing. He presents Himself as the one through whom Isaiah's promise of God's saving work is arriving.", refs: ["Isaiah 61:1–2","Matthew 5:17"] },
  "Luke 4:22": { title: "Gracious Words and Familiarity", text: "The people marvel at His gracious words but ask whether He is Joseph's son. They admire His speech yet struggle to reconcile His message with their familiarity with His family.", refs: ["Matthew 13:54–55","John 6:42"] },
  "Luke 4:23": { title: "Physician, Heal Thyself", text: "Jesus anticipates their proverb and their demand that He do in His hometown what they heard He did in Capernaum. He exposes their expectation that familiar ties should entitle them to special signs.", refs: ["Matthew 13:58","Luke 23:35"] },
  "Luke 4:24": { title: "No Prophet Is Accepted in His Own Country", text: "Jesus says no prophet is accepted in his own country. Familiarity and pride can cause people to reject a message they would otherwise recognize as true.", refs: ["Mark 6:4","John 4:44"] }
});

Object.assign(window.verseCommentary, {
  "Luke 4:25": { title: "Elijah and the Widow", text: "Jesus reminds them that there were many widows in Israel during Elijah's days, when a great famine came over the land for three and a half years. God's prophets were not always sent only to those who considered themselves entitled to them.", refs: ["1 Kings 17:1","James 5:17"] },
  "Luke 4:26": { title: "A Widow in Sarepta", text: "Elijah was sent to a widow in Sarepta of Sidon, outside Israel. Jesus uses the example to show that God's mercy can reach beyond the boundaries people expect.", refs: ["1 Kings 17:8–16","Acts 10:34–35"] },
  "Luke 4:27": { title: "Naaman the Syrian", text: "There were many lepers in Israel in Elisha's time, but Naaman the Syrian was cleansed. The example challenges national pride and reminds the hearers that receiving God's mercy requires humility.", refs: ["2 Kings 5:1–14","Matthew 8:10"] },
  "Luke 4:28": { title: "The Synagogue Is Filled with Wrath", text: "The listeners are filled with anger when they hear Jesus' examples. Their response reveals how quickly pride can turn admiration into hostility.", refs: ["Luke 4:22","Acts 7:54"] },
  "Luke 4:29": { title: "They Try to Cast Him Down", text: "They rise, thrust Jesus out of the city, and lead Him to the brow of the hill to cast Him down. Their rejection becomes an attempt at violence.", refs: ["John 8:59","John 10:31"] },
  "Luke 4:30": { title: "Jesus Passes Through Them", text: "Jesus passes through the midst of them and goes His way. His mission continues because the time and manner of His death are not determined by the crowd's anger.", refs: ["John 7:30","John 8:20"] },
  "Luke 4:31": { title: "Jesus Teaches in Capernaum", text: "Jesus goes down to Capernaum in Galilee and teaches on the Sabbath days. The people encounter His teaching with a different response from Nazareth.", refs: ["Matthew 4:13","Mark 1:21"] },
  "Luke 4:32": { title: "His Word Has Authority", text: "The people are astonished because His word is with power and authority. Jesus teaches not as a mere repeater of tradition but as one whose message carries divine authority.", refs: ["Mark 1:22","Matthew 7:28–29"] },
  "Luke 4:33": { title: "A Man with an Unclean Spirit", text: "A man in the synagogue has an unclean spirit and cries out loudly. The confrontation shows that spiritual oppression is not hidden from Jesus' authority.", refs: ["Mark 1:23","Luke 8:27"] },
  "Luke 4:34": { title: "The Spirit Recognizes Jesus", text: "The spirit cries out asking what Jesus has to do with it and calls Him Jesus of Nazareth, the Holy One of God. Demonic recognition of His identity is not the same as faithful submission.", refs: ["Mark 1:24","James 2:19"] },
  "Luke 4:35": { title: "Be Silent and Come Out", text: "Jesus rebukes the spirit and commands it to come out, and it leaves the man without harming him. His authority delivers the man and prevents the spirit from controlling the outcome.", refs: ["Mark 1:25–26","Luke 8:29"] },
  "Luke 4:36": { title: "A New Teaching with Authority", text: "The people are amazed and ask what word this is, since Jesus commands unclean spirits with authority and power. His teaching and works together reveal His authority.", refs: ["Luke 4:32","Mark 1:27"] },
  "Luke 4:37": { title: "His Fame Spreads", text: "Reports of Jesus spread into every place in the surrounding region. His works prompt public discussion and draw more people to seek Him.", refs: ["Mark 1:28","Luke 5:15"] },
  "Luke 4:38": { title: "Simon's Mother-in-Law", text: "Jesus leaves the synagogue and enters Simon's house, where Simon's mother-in-law is suffering from a great fever. The people ask Jesus to help her.", refs: ["Matthew 8:14","Mark 1:29–30"] },
  "Luke 4:39": { title: "The Fever Leaves Her", text: "Jesus stands over her and rebukes the fever, which leaves her; she immediately rises and serves them. Her recovery is complete enough for her to return to ordinary activity.", refs: ["Matthew 8:15","Mark 1:31"] },
  "Luke 4:40": { title: "Jesus Heals Many at Sunset", text: "At sunset, people bring those with various diseases, and Jesus lays His hands on each one and heals them. His care is personal and extends to many kinds of suffering.", refs: ["Matthew 8:16","Mark 1:32–34"] },
  "Luke 4:41": { title: "Demons Declare Him the Christ", text: "Demons come out of many, crying that Jesus is the Christ, the Son of God, but He rebukes them and does not allow them to speak. Jesus will not let unclean spirits control the testimony about His identity.", refs: ["Mark 1:34","Luke 4:34"] },
  "Luke 4:42": { title: "Jesus Seeks a Solitary Place", text: "When day comes, Jesus goes to a solitary place, but the crowds seek Him and try to keep Him from leaving. Even amid great demand, Jesus remains directed by His mission.", refs: ["Mark 1:35–37","Luke 5:16"] },
  "Luke 4:43": { title: "I Must Preach the Kingdom", text: "Jesus says He must preach the kingdom of God to other cities also, because He was sent for this purpose. His mission is wider than the wishes of one town.", refs: ["Mark 1:38","Isaiah 61:1"] },
  "Luke 4:44": { title: "He Preaches in the Synagogues", text: "Jesus continues preaching in the synagogues of Galilee. His teaching ministry remains central alongside His works of healing and deliverance.", refs: ["Matthew 4:23","Luke 4:15"] }
});

Object.assign(window.verseCommentary, {
  "Luke 5:1": { title: "The Crowd Hears God's Word", text: "The crowd presses around Jesus by the lake of Gennesaret to hear the word of God. His teaching draws people, and He uses the setting by the water to address them.", refs: ["Mark 4:1","Matthew 13:1–2"] },
  "Luke 5:2": { title: "Empty Boats and Washed Nets", text: "Jesus sees two boats by the lake while the fishermen have left them and are washing their nets. The ordinary workday setting prepares for a call that will change their lives.", refs: ["Matthew 4:18","Mark 1:16"] },
  "Luke 5:3": { title: "Jesus Teaches from Simon's Boat", text: "Jesus enters Simon's boat and asks him to push out a little from the land, then teaches the crowd. Simon lends his boat to serve the word.", refs: ["Mark 4:1","John 21:3"] },
  "Luke 5:4": { title: "Launch Out into the Deep", text: "When Jesus finishes speaking, He tells Simon to launch into the deep and let down the nets. The command asks experienced fishermen to act on His word despite their recent failure.", refs: ["John 21:6","Psalm 107:23–24"] },
  "Luke 5:5": { title: "Nevertheless at Thy Word", text: "Simon says they have laboured all night without catching anything, yet he will let down the net at Jesus' word. His response shows the beginning of trust that obeys beyond visible evidence.", refs: ["John 21:3–6","Proverbs 3:5–6"] },
  "Luke 5:6": { title: "A Great Catch of Fish", text: "The fishermen catch such a great multitude of fish that their net begins to break. Jesus' word produces what their own labour could not accomplish that night.", refs: ["John 21:6","Psalm 127:1"] },
  "Luke 5:7": { title: "Partners Help with the Catch", text: "They signal their partners in the other boat, and both boats are filled so heavily that they begin to sink. The abundance is too much for one crew to handle alone.", refs: ["Mark 1:19–20","John 21:8"] },
  "Luke 5:8": { title: "Depart from Me, for I Am a Sinner", text: "Simon Peter falls at Jesus' knees and asks Him to depart because he is a sinful man. The miracle reveals not only Jesus' power but Peter's awareness of his own unworthiness.", refs: ["Isaiah 6:5","Luke 18:13"] },
  "Luke 5:9": { title: "Astonishment at the Catch", text: "Peter and all with him are astonished at the catch of fish. The event marks a decisive revelation of Jesus' authority in the midst of ordinary life.", refs: ["Luke 5:6–8","John 21:7"] },
  "Luke 5:10": { title: "From Now on, Catch Men", text: "James and John, partners with Simon, share his astonishment, and Jesus tells Simon not to fear: from now on he will catch people. The call redirects their abilities toward gathering people into God's kingdom.", refs: ["Matthew 4:19","Mark 1:17"] },
  "Luke 5:11": { title: "They Forsake All and Follow Him", text: "They bring their boats to land, leave everything, and follow Jesus. Their response shows the priority of discipleship over the livelihood that had defined them.", refs: ["Matthew 4:20–22","Luke 14:33"] },
  "Luke 5:12": { title: "A Man Full of Leprosy", text: "A man full of leprosy sees Jesus, falls on his face, and asks to be cleansed if Jesus is willing. He believes Jesus has power and places the decision in His hands.", refs: ["Matthew 8:2","Mark 1:40"] },
  "Luke 5:13": { title: "I Will: Be Thou Clean", text: "Jesus touches the man and says He is willing; immediately the leprosy departs. His touch and command bring cleansing where the disease had caused separation.", refs: ["Matthew 8:3","Leviticus 14:1–7"] },
  "Luke 5:14": { title: "Show Thyself to the Priest", text: "Jesus tells the man to tell no one but show himself to the priest and offer what Moses commanded as a testimony. The healing is to be verified according to the law.", refs: ["Leviticus 14:2–32","Matthew 8:4"] },
  "Luke 5:15": { title: "The Crowds Grow", text: "Reports of Jesus spread further, and great multitudes gather to hear Him and be healed. The demand grows as people seek both His teaching and help.", refs: ["Mark 1:45","Luke 4:37"] },
  "Luke 5:16": { title: "Jesus Withdraws to Pray", text: "Jesus often withdraws into the wilderness and prays. His public ministry is sustained by private communion with God.", refs: ["Mark 1:35","Luke 6:12"] },
  "Luke 5:17": { title: "Power to Heal", text: "As Jesus teaches, Pharisees and teachers of the law sit nearby, having come from many towns, and the power of the Lord is present to heal. The next event confronts both physical need and the authority to forgive sins.", refs: ["Mark 2:1–2","Luke 6:19"] },
  "Luke 5:18": { title: "A Man Who Is Paralyzed", text: "Men carry a paralyzed man on a bed and seek to bring him inside before Jesus. Their effort shows determined care for someone unable to reach Jesus alone.", refs: ["Mark 2:3","Matthew 9:2"] },
  "Luke 5:19": { title: "They Lower Him Through the Roof", text: "Unable to find a way through the crowd, they go onto the roof and lower the man through the tiles before Jesus. Their faith is active and resourceful.", refs: ["Mark 2:4","Matthew 9:2"] },
  "Luke 5:20": { title: "Man, Thy Sins Are Forgiven", text: "Jesus sees their faith and tells the man his sins are forgiven. He addresses the deepest human need first and prepares to demonstrate His authority to forgive.", refs: ["Mark 2:5","Psalm 103:3"] },
  "Luke 5:21": { title: "Who Can Forgive Sins but God?", text: "Scribes and Pharisees reason that blasphemy is being spoken, because only God can forgive sins. Their premise recognizes God's unique authority, but they fail to recognize God's saving presence in Jesus.", refs: ["Mark 2:7","Isaiah 43:25"] },
  "Luke 5:22": { title: "Jesus Knows Their Thoughts", text: "Jesus perceives their reasoning and asks why they question in their hearts. His knowledge of their inner thoughts is part of the sign of His extraordinary authority.", refs: ["John 2:24–25","Mark 2:8"] },
  "Luke 5:23": { title: "Which Is Easier to Say?", text: "Jesus asks whether it is easier to say sins are forgiven or to say rise and walk. Since forgiveness cannot be visually verified in the same way, He provides a visible healing as confirmation of His authority.", refs: ["Matthew 9:5","Mark 2:9"] },
  "Luke 5:24": { title: "The Son of Man Has Authority", text: "Jesus declares that the Son of man has authority on earth to forgive sins and tells the paralyzed man to rise, take his bed, and go home. The healing publicly demonstrates the authority He has claimed.", refs: ["Daniel 7:13–14","Mark 2:10–12"] },
  "Luke 5:25": { title: "He Rises Immediately", text: "The man immediately rises before them, takes the bed he had lain on, and goes home glorifying God. His restored body becomes public evidence of God's work.", refs: ["Mark 2:12","Acts 3:8"] },
  "Luke 5:26": { title: "We Have Seen Strange Things Today", text: "The people are amazed, glorify God, and say they have seen remarkable things. The miracle leaves them with awe at the authority displayed.", refs: ["Luke 7:16","Mark 2:12"] },
  "Luke 5:27": { title: "Levi Is Called", text: "Jesus sees a tax collector named Levi sitting at the receipt of custom and tells him to follow. Jesus calls a man viewed with suspicion by many into discipleship.", refs: ["Mark 2:14","Matthew 9:9"] },
  "Luke 5:28": { title: "Levi Leaves All", text: "Levi leaves everything, rises, and follows Jesus. His response is decisive and parallels the fishermen's call.", refs: ["Luke 5:11","Philippians 3:7–8"] },
  "Luke 5:29": { title: "A Great Feast for Jesus", text: "Levi makes a great feast in his house, with many tax collectors and others present. His new allegiance becomes an occasion to bring others into contact with Jesus.", refs: ["Mark 2:15","Matthew 9:10"] },
  "Luke 5:30": { title: "Why Eat with Sinners?", text: "Pharisees and scribes complain to Jesus' disciples that they eat and drink with tax collectors and sinners. They see the fellowship as contamination rather than an opportunity for repentance.", refs: ["Mark 2:16","Luke 15:1–2"] },
  "Luke 5:31": { title: "The Physician and the Sick", text: "Jesus answers that those who are well do not need a physician, but those who are sick do. His ministry intentionally reaches people who know they need spiritual healing.", refs: ["Mark 2:17","Matthew 9:12"] },
  "Luke 5:32": { title: "Call Sinners to Repentance", text: "Jesus says He has not come to call the righteous but sinners to repentance. He does not endorse sin; He comes to bring sinners to turn from it.", refs: ["1 Timothy 1:15","Acts 3:19"] },
  "Luke 5:33": { title: "A Question About Fasting", text: "People ask why John's disciples and the Pharisees fast, while Jesus' disciples eat and drink. Jesus explains that His presence marks a time of joy, though fasting will have its place.", refs: ["Mark 2:18","Matthew 9:14"] },
  "Luke 5:34": { title: "The Bridegroom Is Present", text: "Jesus asks whether wedding guests can be made to fast while the bridegroom is with them. His presence is compared to a wedding celebration.", refs: ["Mark 2:19","John 3:29"] },
  "Luke 5:35": { title: "The Bridegroom Will Be Taken Away", text: "Jesus says days will come when the bridegroom is taken away, and then His disciples will fast. The saying points ahead to His suffering and departure.", refs: ["Mark 2:20","John 16:20"] },
  "Luke 5:36": { title: "New Cloth and Old Garment", text: "Jesus gives the picture of a new patch tearing an old garment. His teaching and mission cannot be reduced to a small addition to a system unwilling to be renewed.", refs: ["Mark 2:21","Matthew 9:16"] },
  "Luke 5:37": { title: "New Wine and Old Bottles", text: "New wine put into old wineskins bursts them and is lost. The illustration calls for a fitting response to what God is doing through Jesus.", refs: ["Mark 2:22","Matthew 9:17"] },
  "Luke 5:38": { title: "New Wine in New Bottles", text: "New wine must be put into new wineskins. Jesus emphasizes the need for a renewed response, not rigid resistance to the new work of God's kingdom.", refs: ["Mark 2:22","Jeremiah 31:31–34"] },
  "Luke 5:39": { title: "The Old Wine Seems Better", text: "Jesus notes that a person accustomed to old wine may say it is better. The saying recognizes how attachment to familiar patterns can make people reluctant to embrace change.", refs: ["Luke 5:36–38","Hebrews 8:13"] }
});

Object.assign(window.verseCommentary, {
  "Luke 6:1": { title: "Grain Plucked on the Sabbath", text: "On a Sabbath, Jesus and His disciples walk through grainfields, and the disciples pluck and eat grain. Their action leads to a dispute about the Sabbath's purpose.", refs: ["Mark 2:23","Matthew 12:1"] },
  "Luke 6:2": { title: "A Challenge from the Pharisees", text: "Some Pharisees ask why the disciples do what is not lawful on the Sabbath. Jesus answers by showing that the law must be understood according to God's purpose and mercy.", refs: ["Matthew 12:2","Exodus 20:8–11"] },
  "Luke 6:3": { title: "Have You Not Read About David?", text: "Jesus asks whether they have read what David did when he and his companions were hungry. Scripture itself records a case where human need intersected with a ceremonial rule.", refs: ["1 Samuel 21:1–6","Mark 2:25"] },
  "Luke 6:4": { title: "The Showbread", text: "David entered God's house and ate the showbread, which was ordinarily reserved for priests, and shared it with his companions. Jesus uses the account to challenge a rigid reading that ignores mercy and necessity.", refs: ["Leviticus 24:5–9","Matthew 12:4"] },
  "Luke 6:5": { title: "The Son of Man Is Lord of the Sabbath", text: "Jesus declares that the Son of man is Lord also of the Sabbath. He speaks with authority to interpret the Sabbath in keeping with God's purpose.", refs: ["Mark 2:28","Matthew 12:8"] },
  "Luke 6:6": { title: "A Man with a Withered Hand", text: "On another Sabbath Jesus teaches in a synagogue, where a man with a withered right hand is present. The need for healing becomes the focus of a conflict about mercy.", refs: ["Mark 3:1","Matthew 12:9"] },
  "Luke 6:7": { title: "They Watch Him", text: "Scribes and Pharisees watch Jesus to see whether He will heal on the Sabbath, hoping to find a charge against Him. Their scrutiny seeks condemnation rather than the man's restoration.", refs: ["Mark 3:2","Luke 14:1"] },
  "Luke 6:8": { title: "Stand in the Midst", text: "Jesus knows their thoughts and tells the man to rise and stand in the middle. He brings the need into view instead of allowing silent hostility to govern the moment.", refs: ["Mark 3:3","John 2:24–25"] },
  "Luke 6:9": { title: "To Save Life or Destroy It", text: "Jesus asks whether it is lawful on the Sabbath to do good or evil, to save life or destroy it. His question reveals the moral contradiction in withholding good under the guise of religious strictness.", refs: ["Mark 3:4","Matthew 12:12"] },
  "Luke 6:10": { title: "The Hand Is Restored", text: "Jesus looks around and tells the man to stretch out his hand, and it is restored. The healing demonstrates the goodness of God's work despite the leaders' opposition.", refs: ["Mark 3:5","Matthew 12:13"] },
  "Luke 6:11": { title: "They Are Filled with Rage", text: "The scribes and Pharisees are filled with rage and discuss what they might do to Jesus. Their response to a healing exposes how far hostility has taken them from mercy.", refs: ["Mark 3:6","John 5:16"] },
  "Luke 6:12": { title: "Jesus Prays All Night", text: "Jesus goes to a mountain to pray and continues all night in prayer to God. Before choosing the Twelve, He spends extended time in communion with God.", refs: ["Mark 1:35","Luke 5:16"] },
  "Luke 6:13": { title: "He Chooses the Twelve", text: "At daybreak Jesus calls His disciples and chooses twelve, whom He names apostles. Their appointment prepares them for a particular role in the mission.", refs: ["Matthew 10:1–4","Acts 1:2"] },
  "Luke 6:14": { title: "Simon, Andrew, James, and John", text: "Luke begins naming the apostles, including Simon whom Jesus calls Peter, Andrew, James, and John. The group includes people with different backgrounds united by Jesus' call.", refs: ["Mark 3:16–17","Acts 1:13"] },
  "Luke 6:15": { title: "The Other Apostles", text: "Philip, Bartholomew, Matthew, Thomas, James son of Alphaeus, and Simon called Zelotes are named. Each becomes part of the apostolic witness to Jesus.", refs: ["Matthew 10:3–4","Acts 1:13"] },
  "Luke 6:16": { title: "Judas Iscariot", text: "Judas the brother of James and Judas Iscariot, who became a traitor, complete the list. The mention anticipates the betrayal that will come from within the Twelve.", refs: ["Mark 3:19","John 6:70–71"] },
  "Luke 6:17": { title: "A Great Crowd Comes", text: "Jesus comes down with the apostles and stands on a level place with a large crowd of disciples and people from many regions. They come to hear Him and to be healed.", refs: ["Matthew 4:25","Luke 5:15"] },
  "Luke 6:18": { title: "Healing and Deliverance", text: "Those troubled by unclean spirits are healed, and the crowd seeks both teaching and relief from suffering. Jesus' authority addresses spiritual and physical need.", refs: ["Mark 1:34","Luke 4:40–41"] },
  "Luke 6:19": { title: "Power Goes Out from Jesus", text: "The crowd tries to touch Jesus because power goes out from Him and heals them all. The narrative emphasizes His extraordinary healing authority.", refs: ["Mark 5:30","Matthew 14:36"] },
  "Luke 6:20": { title: "Blessed Are the Poor", text: "Jesus looks at His disciples and calls the poor blessed, for theirs is God's kingdom. Luke highlights God's concern for people who lack worldly status and security.", refs: ["Matthew 5:3","James 2:5"] },
  "Luke 6:21": { title: "Hungry and Weeping", text: "Jesus blesses those who hunger now, promising they will be filled, and those who weep, promising they will laugh. God's kingdom brings future reversal and hope to those who suffer now.", refs: ["Matthew 5:4–6","Psalm 126:5–6"] },
  "Luke 6:22": { title: "Hated for the Son of Man", text: "Jesus calls His disciples blessed when people hate, separate, reproach, and reject them for the Son of man's sake. Faithfulness to Him may bring social rejection, but God sees and values it.", refs: ["Matthew 5:11","John 15:18–20"] },
  "Luke 6:23": { title: "Rejoice in That Day", text: "Jesus tells them to rejoice when persecuted for His sake because their reward is great in heaven, recalling how prophets were treated. Their suffering places them in the company of faithful witnesses.", refs: ["Matthew 5:12","Hebrews 11:32–38"] },
  "Luke 6:24": { title: "Woe to the Rich", text: "Jesus pronounces woe on the rich who have already received their consolation. The warning concerns false security and complacency, not the claim that every person with resources is condemned.", refs: ["James 5:1–5","Luke 12:16–21"] },
  "Luke 6:25": { title: "Woe to the Satisfied and Laughing", text: "Jesus warns those who are full now that they will hunger and those who laugh now that they will mourn. Self-satisfaction that ignores God and neighbour will be overturned.", refs: ["Amos 6:1–7","Luke 16:19–25"] },
  "Luke 6:26": { title: "Woe When All Speak Well", text: "Jesus warns when everyone speaks well of His disciples, recalling false prophets who were praised. Faithfulness to God is not measured by universal popularity.", refs: ["Jeremiah 5:31","John 15:19"] },
  "Luke 6:27": { title: "Love Your Enemies", text: "Jesus commands His hearers to love their enemies and do good to those who hate them. Kingdom love moves beyond reciprocal kindness and reflects God's mercy.", refs: ["Matthew 5:44","Romans 12:20"] },
  "Luke 6:28": { title: "Bless and Pray", text: "Disciples are to bless those who curse them and pray for those who mistreat them. Prayer changes the response from retaliation to seeking God's good.", refs: ["Matthew 5:44","1 Peter 3:9"] },
  "Luke 6:29": { title: "Do Not Repay Evil with Evil", text: "Jesus uses striking examples of refusing retaliation when insulted or deprived. The teaching calls disciples away from revenge, not to enable ongoing abuse or deny lawful protection.", refs: ["Matthew 5:39–40","Romans 12:17–19"] },
  "Luke 6:30": { title: "Give and Do Not Demand Back", text: "Jesus teaches generosity toward those who ask and warns against grasping at repayment. The principle calls for an open-handed heart, exercised with wisdom rather than enabling harm.", refs: ["Matthew 5:42","Deuteronomy 15:7–8"] },
  "Luke 6:31": { title: "Do to Others as You Would Have Them Do", text: "Jesus gives the positive rule of treating others as one would wish to be treated. Love becomes practical by imagining the other person's needs and dignity.", refs: ["Matthew 7:12","Leviticus 19:18"] },
  "Luke 6:32": { title: "Love Beyond Reciprocity", text: "Loving only those who love you earns no special distinction, since sinners do the same. Jesus calls His followers to a love shaped by God's character rather than mutual advantage.", refs: ["Matthew 5:46","Romans 5:8"] },
  "Luke 6:33": { title: "Do Good Beyond Your Circle", text: "Doing good only to those who do good to you is ordinary reciprocity. Jesus calls disciples to extend goodness even when there is no expectation of return.", refs: ["Matthew 5:47","Galatians 6:10"] },
  "Luke 6:34": { title: "Lending Without Expecting Return", text: "Lending only to those expected to repay offers no distinctive witness. Kingdom generosity seeks the good of others without making personal profit its controlling motive.", refs: ["Deuteronomy 15:8–10","Matthew 5:42"] },
  "Luke 6:35": { title: "Love Your Enemies and Lend", text: "Jesus repeats the call to love enemies, do good, and lend without despairing, promising reward and calling His disciples children of the Highest. God is kind even to the unthankful and evil.", refs: ["Matthew 5:44–45","Romans 2:4"] },
  "Luke 6:36": { title: "Be Merciful", text: "Disciples are to be merciful as their Father is merciful. God's mercy becomes the pattern for how they treat others.", refs: ["Matthew 5:48","Ephesians 4:32"] },
  "Luke 6:37": { title: "Judge Not, Condemn Not, Forgive", text: "Jesus warns against a condemning spirit and calls for forgiveness. This does not forbid all discernment, since Scripture also commands testing teaching and confronting sin with care.", refs: ["Matthew 7:1–5","John 7:24","Galatians 6:1"] },
  "Luke 6:38": { title: "Give and It Shall Be Given", text: "Jesus uses the picture of a generous measure pressed down and overflowing to teach that the measure people use will be measured back to them. The principle concerns generosity and mercy, not a guaranteed financial return.", refs: ["Matthew 7:2","2 Corinthians 9:6–8"] },
  "Luke 6:39": { title: "The Blind Leading the Blind", text: "Jesus asks whether the blind can lead the blind without both falling into a ditch. Teachers must see clearly themselves before they can guide others safely.", refs: ["Matthew 15:14","Romans 2:19–21"] },
  "Luke 6:40": { title: "The Disciple and the Master", text: "A disciple is not above his master, but everyone fully trained will be like his master. The aim of discipleship is to become formed by Jesus' teaching and character.", refs: ["Matthew 10:24–25","Ephesians 4:13"] },
  "Luke 6:41": { title: "The Mote and the Beam", text: "Jesus asks why someone notices a speck in a brother's eye while ignoring a beam in his own. Self-examination must come before fault-finding.", refs: ["Matthew 7:3","Romans 2:1"] },
  "Luke 6:42": { title: "First Remove the Beam", text: "Jesus calls the hypocrite to remove the beam from his own eye before helping his brother with the speck. Correction is appropriate when offered humbly after honest self-examination.", refs: ["Matthew 7:4–5","Galatians 6:1"] },
  "Luke 6:43": { title: "Good Trees and Corrupt Trees", text: "A good tree does not bring forth corrupt fruit, nor a corrupt tree good fruit. Jesus connects a person's inner character with the life that emerges from it.", refs: ["Matthew 7:17","James 3:12"] },
  "Luke 6:44": { title: "Known by Its Fruit", text: "Every tree is known by its own fruit; people do not gather figs from thorns or grapes from a bramble. Conduct over time reveals the nature of a person's teaching and character.", refs: ["Matthew 7:16","Galatians 5:22–23"] },
  "Luke 6:45": { title: "Out of the Heart the Mouth Speaks", text: "A good person brings good out of the heart's treasure, while an evil person brings evil; the mouth speaks from what fills the heart. Speech reveals inner priorities and the need for heart transformation.", refs: ["Matthew 12:34–35","Proverbs 4:23"] },
  "Luke 6:46": { title: "Why Call Me Lord?", text: "Jesus asks why people call Him Lord but do not do what He says. Confession must be joined with obedience.", refs: ["Matthew 7:21","John 14:15"] },
  "Luke 6:47": { title: "Coming, Hearing, and Doing", text: "Jesus describes the person who comes to Him, hears His sayings, and does them. True discipleship includes listening and putting His teaching into practice.", refs: ["James 1:22","Matthew 7:24"] },
  "Luke 6:48": { title: "A House on a Foundation", text: "Such a person is like one building a house who digs deep and lays a foundation on rock. When the flood comes, the house stands because it was well founded.", refs: ["Matthew 7:24–25","1 Corinthians 3:11"] },
  "Luke 6:49": { title: "A House Without a Foundation", text: "The person who hears but does not obey is like one who builds without a foundation; when the flood strikes, the house collapses greatly. Hearing Jesus' words without living them leaves a life unprepared for testing.", refs: ["Matthew 7:26–27","James 1:23–25"] }
});

Object.assign(window.verseCommentary, {
  "Luke 7:1": { title: "Jesus Enters Capernaum", text: "After finishing His sayings in the hearing of the people, Jesus enters Capernaum. His teaching is followed by another encounter that displays His authority and compassion.", refs: ["Matthew 8:5","Luke 4:31"] },
  "Luke 7:2": { title: "A Centurion's Sick Servant", text: "A centurion has a servant who is dear to him and is near death. The officer's concern for his servant becomes the reason he seeks Jesus' help.", refs: ["Matthew 8:5–6","John 4:46–47"] },
  "Luke 7:3": { title: "The Centurion Sends Elders", text: "Hearing about Jesus, the centurion sends Jewish elders to ask Him to come and heal his servant. His request shows both concern and confidence that Jesus can help.", refs: ["Matthew 8:5","Luke 7:6"] },
  "Luke 7:4": { title: "He Is Worthy", text: "The elders earnestly ask Jesus to help, saying the centurion is worthy of this favour. They point to his character and support for the people.", refs: ["Luke 7:5","Acts 10:2"] },
  "Luke 7:5": { title: "He Loves Our Nation", text: "The elders explain that the centurion loves their nation and has built them a synagogue. His actions show unusual goodwill across social and national boundaries.", refs: ["Acts 10:1–2","Luke 7:9"] },
  "Luke 7:6": { title: "The Centurion Sends Friends", text: "As Jesus approaches, the centurion sends friends to say He need not come under his roof because he is not worthy. His humility contrasts with the elders' description of his worthiness.", refs: ["Matthew 8:8","Luke 18:13"] },
  "Luke 7:7": { title: "Speak the Word Only", text: "The centurion says he did not consider himself worthy to come to Jesus and asks Him to speak the word so his servant may be healed. He recognizes that Jesus' authority is not limited by physical distance.", refs: ["Matthew 8:8","Psalm 107:20"] },
  "Luke 7:8": { title: "Authority Under Authority", text: "The centurion understands authority because he is under authority and has soldiers under him. He reasons that Jesus can command sickness as he commands soldiers.", refs: ["Matthew 8:9","Mark 1:27"] },
  "Luke 7:9": { title: "Jesus Marvels at His Faith", text: "Jesus marvels at the centurion and tells the crowd He has not found such great faith even in Israel. The man's trust is remarkable because he relies on Jesus' word without demanding a visible sign.", refs: ["Matthew 8:10","Hebrews 11:6"] },
  "Luke 7:10": { title: "The Servant Is Healed", text: "The messengers return to the house and find the servant well. Jesus' word has accomplished the healing at a distance.", refs: ["Matthew 8:13","John 4:50–53"] },
  "Luke 7:11": { title: "Jesus Goes to Nain", text: "Jesus travels to a city called Nain, accompanied by His disciples and a great crowd. There He encounters a funeral procession.", refs: ["Luke 8:1","1 Kings 17:10"] },
  "Luke 7:12": { title: "A Widow's Only Son", text: "As Jesus approaches the city gate, a dead man is being carried out, the only son of a widow. The widow's loss is especially grievous because she has lost both her child and a key source of family support.", refs: ["1 Kings 17:17–18","Luke 8:42"] },
  "Luke 7:13": { title: "The Lord Has Compassion", text: "The Lord sees the widow and is moved with compassion, telling her not to weep. His response begins with mercy before any request is made.", refs: ["Matthew 9:36","Lamentations 3:22"] },
  "Luke 7:14": { title: "Young Man, Arise", text: "Jesus touches the bier and commands the young man to arise. The one who has authority over life speaks directly to the dead.", refs: ["1 Kings 17:21–22","Mark 5:41"] },
  "Luke 7:15": { title: "The Dead Man Sits Up", text: "The dead man sits up and begins to speak, and Jesus gives him to his mother. The miracle restores both life to the son and hope to the grieving widow.", refs: ["1 Kings 17:23","Luke 8:55"] },
  "Luke 7:16": { title: "God Has Visited His People", text: "Fear and praise spread through the crowd, who say a great prophet has risen and God has visited His people. They recognize God's activity, though Jesus' full identity will become clearer.", refs: ["Luke 1:68","John 6:14"] },
  "Luke 7:17": { title: "The Report Spreads", text: "The report of Jesus spreads throughout Judea and the surrounding region. His works of compassion become widely known.", refs: ["Luke 4:37","Matthew 9:26"] },
  "Luke 7:18": { title: "John's Disciples Report", text: "John's disciples tell him about all these things. John is in prison, and the reports of Jesus' ministry lead to a question about His identity.", refs: ["Matthew 11:2","Luke 3:20"] },
  "Luke 7:19": { title: "Art Thou He That Should Come?", text: "John sends two disciples to ask Jesus whether He is the promised one or whether they should look for another. The question may reflect John's struggle to reconcile Jesus' ministry with his expectations of judgment.", refs: ["Matthew 11:3","Malachi 3:1"] },
  "Luke 7:20": { title: "The Question Is Repeated", text: "The messengers stand before Jesus and repeat John's question about the one who should come. Jesus will answer by pointing to the works that fulfil prophecy.", refs: ["Matthew 11:3","Isaiah 35:5–6"] },
  "Luke 7:21": { title: "Jesus Heals Many", text: "At that hour Jesus heals many of diseases, plagues, and evil spirits and gives sight to many who are blind. His actions supply evidence that God's promised restoration is taking place.", refs: ["Isaiah 61:1","Matthew 11:4"] },
  "Luke 7:22": { title: "Tell John What You Have Seen", text: "Jesus tells the messengers to report that the blind see, the lame walk, lepers are cleansed, the deaf hear, the dead are raised, and the poor hear the gospel. These works echo prophetic promises about the coming salvation.", refs: ["Isaiah 35:5–6","Isaiah 61:1","Matthew 11:5"] },
  "Luke 7:23": { title: "Blessed Is He Not Offended in Me", text: "Jesus calls blessed the one who is not offended in Him. His mission may challenge expectations, but those who trust Him must receive God's work as it truly comes.", refs: ["Matthew 11:6","John 6:60–68"] },
  "Luke 7:24": { title: "A Reed Shaken by the Wind?", text: "After John's messengers leave, Jesus asks the crowd what they went into the wilderness to see. He reminds them that John was not a wavering person seeking comfort or public approval.", refs: ["Matthew 11:7","Ephesians 4:14"] },
  "Luke 7:25": { title: "Soft Clothing in Palaces", text: "Jesus asks whether they went to see someone dressed in fine clothing, noting that such people live in royal palaces. John was a prophet of austere courage, not a court flatterer.", refs: ["Matthew 11:8","Mark 1:6"] }
});
